window.SIYER_CONTENT_V2={"version":2,"title":"Siyer Yolculuğu","subtitle":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) hayatını öğreniyoruz","audience":"Ortaokul • 10–14 yaş","minutesPerLesson":10,"totalMinutes":600,"modules":["Dünya, Mekke ve çocukluk","Gençlik, aile ve güven","İlk vahiy ve davet","Zorluklar ve yeni umutlar","Hicret ve Medine","Medine’yi korumak","Barış ve yeni ufuklar","Mekke’ye dönüş","Son yıllar ve veda","Hayatımıza taşıyalım"],"lessons":[{"id":1,"module":1,"title":"Yolculuğun haritası: Arabistan","date":"6. yüzyıl","objective":"Siyer olaylarının geçtiği bölgeyi ve şehirlerin önemini tanır.","hook":{"question":"Mekke'den Yesrib'e giden eski bir kervanı anlamak için önce neye bakardın?","options":["Şehirlerin konumuna ve su kaynaklarına","Yalnız yolculuğun başladığı tarihe","Yalnız taşınan malların sayısına"],"note":"Henüz doğru cevap ilan etmeyin. Harita açılınca her seçimin hangi bilgiyi sağladığını karşılaştırın."},"frames":[{"title":"Önce büyük haritayı okuyalım","kind":"map","labels":["Arabistan","Hicaz","Kızıldeniz","Mekke"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem)'in hayatının geçtiği Arabistan, Asya'nın güneybatısındaki büyük bir yarımadadır. Bu derslerde özellikle batı kesimindeki Hicaz bölgesine bakacağız. Haritada Kızıldeniz'i bulup doğusundaki kara parçasını izleyelim. Böylece şehir adlarını ezberlemek yerine birbirleriyle ilişkilerini görmeye başlarız. Ekrandaki çizim yönleri öğrenmek içindir; gerçek uzaklıkları ölçmek için ölçekli bir harita gerekir."},{"title":"Üç şehir, farklı özellikler","kind":"map","labels":["Mekke: Kâbe","Yesrib: sonraki Medine","Tâif: yüksek kesim"],"narration":"Mekke, Kâbe'nin bulunduğu şehir olarak yolculuğumuzun başlangıcındadır. Yesrib, Mekke'nin kuzeyinde yer alır; hicretten sonraki derslerde bu şehri Medine adıyla daha sık duyacağız. Tâif ise Mekke'nin doğusundaki yüksek kesimdedir. Haritadaki üç noktaya dokun. Aynı şehir olmadıklarını ve her birinin siyerin farklı olaylarında karşımıza çıkacağını kendi cümlenle açıkla. İsimleri doğru yerleştirmek olayları karıştırmamızı önler."},{"title":"Yol yalnızca çizgi değildir","kind":"route","labels":["Kervan","Su","Konaklama","Haberleşme"],"narration":"Şehirleri birbirine bağlayan yollar üzerinde kervanlar ilerliyordu. Kervanlar mal taşıdığı gibi insanlar arasında haber ve bilgi dolaşımına da katkı sağlıyordu. Kurak bölgelerde yolculuk; suyu, dinlenmeyi ve güvenliği düşünmeyi gerektirirdi. Haritadaki bir çizginin arkasında emek ve hazırlık olduğunu fark edelim. Bugünün araçları ve yollarını aynen geçmişe taşımadan, dönemin şartlarını göz önünde tutalım."},{"title":"Mekân bilgisi olayları aydınlatır","kind":"journey","labels":["Nerede?","Hangi yön?","Hangi ihtiyaç?","Hangi kaynak?"],"narration":"Bir siyer olayını okurken önce gerçekleştiği yeri belirleyebiliriz. Ardından yolculuk varsa başlangıcı ve varışı işaretleriz. Mekke ile Yesrib'i tanımak ileride hicreti anlamamıza yardım edecek. Ancak harita tek başına olayın sebebini söylemez; bunun için güvenilir anlatımı da okumalıyız. Şimdi şehirleri bulurken hem coğrafya bilgisini hem de kaynak okuma alışkanlığını birlikte kullanacağız."}],"game":{"kind":"match","title":"Haritanın anahtarları","prompt":"Yerleri, bu derste öğrendiğin doğru açıklamalarıyla eşleştir.","pairs":[{"left":"Mekke","right":"Kâbe'nin bulunduğu şehir","explanation":"Yolculuğun doğum ve ilk davet dönemleri Mekke'de başlayacak."},{"left":"Yesrib","right":"Daha sonra Medine adıyla tanınan şehir","explanation":"İki adın farklı dönemlerde aynı şehri işaret edebildiğini hatırla."},{"left":"Tâif","right":"Mekke'nin doğusundaki yüksek kesimdeki şehir","explanation":"Tâif'i Yesrib ile karıştırmamak için yönlere bak."},{"left":"Kızıldeniz","right":"Arabistan'ın batısındaki deniz","explanation":"Deniz, Hicaz'ın haritadaki yerini bulmamıza yardım eder."}]},"decision":{"question":"Bir arkadaşın şematik haritada iki şehir arasını cetvelle ölçüp yolculuğun kesin kilometresini yazıyor. En uygun düzeltme hangisi?","options":["Yönleri bu çizimden, mesafeyi ölçekli haritadan kontrol edelim.","Şehir adları doğruysa her çizimden kesin mesafe bulunur.","Yolculuk süresini kilometreyle aynı sayı olarak yazalım."],"answer":0,"explanations":["Doğru: şema ilişkiyi gösterir; kesin mesafe için ölçek ve uygun kaynak gerekir.","Şehir adlarının doğruluğu çizimin ölçekli olduğu anlamına gelmez.","Süre; yol, araç ve duraklara bağlıdır, mesafe ile aynı değildir."]},"quiz":[{"question":"Yesrib ve Medine adlarını iki ayrı şehir sanan biri hangi bilgiyi gözden kaçırmıştır?","options":["Bir şehrin farklı adlarla anılabildiğini","Kervanların yalnız denizden gittiğini","Tâif'in Mekke'nin eski adı olduğunu"],"answer":0,"explanation":"Yesrib, hicret sonrasında Medine olarak anılan şehrin önceki adıdır."},{"question":"Mekke'den Yesrib'e gidişi haritada ararken hangi yön yardımcı olur?","options":["Doğu","Kuzey","Güney"],"answer":1,"explanation":"Yesrib, Mekke'nin kuzeyindedir; Tâif ise doğudaki yüksek kesimdedir."},{"question":"Kervan yolculuğunu açıklarken hangi iki bilgi birlikte daha yararlıdır?","options":["Yalnız şehirlerin adları ve bugünkü nüfusları","Yalnız yola çıkılan gün ve taşınan yükün rengi","Güzergâh ile su ve konaklama imkânları"],"answer":2,"explanation":"Yolun nereden geçtiğini ve ihtiyaçların nasıl karşılandığını birlikte düşünmek dönemi anlamayı sağlar."}],"teacher":{"misconception":"Şematik haritayı ölçekli coğrafya haritası gibi okutmayın; Yesrib ve Medine'nin iki şehir olmadığını vurgulayın.","differentiation":"5–6. sınıf üç şehri bulsun; 7–8. sınıf konum ile yolculuk ihtiyacı arasında iki gerekçeli bağ kursun.","exit":"Mekke, Yesrib ve Tâif'i göster; haritanın anlattığı bir bilgiyi ve tek başına anlatamadığı bir bilgiyi söyle."},"sources":[{"title":"TDV — Mekke","url":"https://islamansiklopedisi.org.tr/mekke"}]},{"id":2,"module":1,"title":"Mekke, Kâbe ve toplum","date":"Peygamberlik öncesi","objective":"Mekke'nin dinî ve toplumsal yapısını temel özellikleriyle açıklar.","hook":{"question":"Bir şehri tanımak için hangi iki alana birlikte bakmak gerekir?","options":["Yalnız binalarına ve sokaklarına","İnanç hayatına ve insanların ilişkilerine","Yalnız yöneticilerin adlarına"],"note":"Öğrencilerin okul/mahalle örneklerinden hareketle şehir hayatının birden çok boyutu olduğunu sezdirin."},"frames":[{"title":"Şehrin merkezindeki Kâbe","kind":"city","labels":["Mekke","Kâbe","Ziyaret","Hizmet"],"narration":"Mekke'nin önemini anlamak için Kâbe'nin şehir hayatındaki yerine bakarız. Kâbe, ziyaretçilerin yöneldiği dinî merkezdi. Ziyaretçilere su ve yiyecek sağlama gibi hizmetler de şehirde sorumluluk paylaşımını etkiliyordu. Bir yapının çevresinde ibadet, yolculuk ve insanların ihtiyaçları birleşebiliyordu. Bu nedenle Mekke'yi yalnız evlerden oluşan bir yer olarak değil, ilişkileri olan bir şehir olarak inceleyeceğiz."},{"title":"Kureyş ve ticaret hayatı","kind":"market","labels":["Kureyş","Kervan","Alışveriş","Güven"],"narration":"Kureyş, Mekke'de etkili olan kabileydi. Çevrenin tarıma elverişsiz oluşu ticaretin önemini artırmıştı. Kervanlarla farklı bölgelere gidiliyor, getirilen mallar alınıp satılıyordu. Alışverişte ölçü, ödeme ve verilen sözler insanlar arasındaki güveni etkiler. Böyle bir ortamı tanımak, ileride güvenilirlik ve haksızlığa karşı dayanışma olaylarını anlamamızı kolaylaştırır. Ticaret kelimesini yalnız para kazanmakla sınırlamayalım."},{"title":"Aynı toplumda farklı davranışlar","kind":"community","labels":["Misafirperverlik","Dayanışma","Haksızlık","Sorumluluk"],"narration":"Peygamberlik öncesi Mekke toplumunda misafiri ağırlamak ve yakınlarına yardım etmek gibi değer verilen davranışlar vardı. Bunun yanında güçlülerin zayıfları ezmesi ve kabile desteği olmayanların haklarını korumakta zorlanması gibi sorunlar da görülüyordu. Geçmişteki herkesi tek bir davranışla tanımlamak doğru değildir. İyi örnekleri ve haksızlıkları birlikte görmek, değişimin neden gerekli olduğunu daha iyi anlamamızı sağlar."},{"title":"İnanç ortamını doğru ayıralım","kind":"values","labels":["Kâbe","Putperestlik","Tevhid","Davet"],"narration":"Kâbe'nin bulunduğu Mekke'de peygamberlik öncesinde putperestlik yaygındı; Allahü teâlânın birliğine inanan kimseler de bulunuyordu. Bu iki bilgiyi birbirine karıştırmayalım: Kâbe'nin kutsallığı, toplumdaki her inanç ve davranışın doğru olduğu anlamına gelmez. Peygamber Efendimiz (sallallahü aleyhi ve sellem) ile başlayan davetin hangi ortamda gerçekleştiğini öğrenirken inançları, ekonomik hayatı ve toplumsal ilişkileri ayrı ayrı inceleyip sonra ilişkilendiririz."}],"game":{"kind":"classify","title":"Toplumu iki pencereden oku","prompt":"Kartın anlattığı şey bir dayanışma örneği mi, düzeltilmesi gereken bir haksızlık mı?","groups":["Dayanışma örneği","Haksızlık"],"items":[{"text":"Yolculuktan gelen misafire su sunmak","group":0,"explanation":"İhtiyacı karşılamak toplumsal yardımlaşmadır."},{"text":"Satın aldığı malın parasını gücüne güvenerek vermemek","group":1,"explanation":"Güçlü olmak başkasının hakkını ortadan kaldırmaz."},{"text":"Zor durumdaki yakının yiyecek ihtiyacına yardım etmek","group":0,"explanation":"Yakınları gözetmek dayanışmadır."},{"text":"Yabancı olduğu için bir tüccarın şikâyetini dinlememek","group":1,"explanation":"Hak arama imkânını kökene göre daraltmak haksızlıktır."},{"text":"Ziyaretçilerin su ihtiyacı için sorumluluk almak","group":0,"explanation":"Şehirde ihtiyaçların karşılanmasına katkı sağlar."},{"text":"Aynı kabileden diye haksız kişiyi korumak","group":1,"explanation":"Dayanışma, haksız davranışı savunmaya dönüşmemelidir."}]},"decision":{"question":"Bir öğrenci 'Mekke'de haksızlıklar vardı; demek ki hiç kimse kimseye yardım etmiyordu' diyor. Kaynaklara uygun cevap hangisi?","options":["Yardımlaşma varsa toplumda haksızlık bulunamaz.","Haksızlık örnekleriyle yardımlaşma örneklerini birlikte incelemeliyiz.","Toplumu yalnız en zengin ailesine bakarak değerlendirmeliyiz."],"answer":1,"explanations":["Bir toplumda yararlı davranışlarla sorunlar aynı dönemde bulunabilir.","Doğru: farklı örnekleri birlikte incelemek genellemeyi önler.","Bir ailenin hayatı bütün toplumun hayatını göstermez."]},"quiz":[{"question":"Mekke'de ticaretin önemli olmasını açıklayan etken hangisidir?","options":["Çevrenin tarım için sınırlı imkân sunması","Şehirde bütün ihtiyaçların tarımla karşılanması","Ziyaretçilerin şehre hiç gelmemesi"],"answer":0,"explanation":"Tarım imkânlarının sınırlılığı ve şehirler arası ilişkiler ticaretin önemini artırıyordu."},{"question":"Ziyaretçilere su sağlama hangi iki alanı birbirine bağlar?","options":["Yalnız savaş ve yönetim","Dinî ziyaret ve toplumsal hizmet","Yalnız tarım ve madencilik"],"answer":1,"explanation":"Kâbe ziyareti insanların ihtiyaçlarını karşılamaya dönük hizmetlerle birlikte düşünülür."},{"question":"Toplumla ilgili en dikkatli sonuç hangisidir?","options":["Aynı şehirde herkes aynı davranır.","Misafirperverlik bütün haksızlıkları kendiliğinden çözer.","İyi gelenekler bulunurken haksızlıklar da yaşanabilir."],"answer":2,"explanation":"Siyer öğrenirken toplumun farklı yönlerini birlikte değerlendiririz."}],"teacher":{"misconception":"Câhiliye kavramını 'hiçbir bilgi ve iyi davranış yoktu' biçiminde açıklamayın; dinî ve ahlâkî sorunlar ile olumlu davranışları ayırın.","differentiation":"Küçük sınıflar davranışları ayırsın; büyük sınıflar kabile dayanışmasının hangi durumda haksızlığa dönüşebileceğini gerekçelendirsin.","exit":"Mekke'nin dinî, ekonomik ve toplumsal hayatından birer bağlantı kur."},"sources":[{"title":"TDV — Mekke","url":"https://islamansiklopedisi.org.tr/mekke"}]},{"id":3,"module":1,"title":"Mekke'de bir doğum","date":"Fil Yılı; yaygın tarihle yaklaşık 571","objective":"Doğum yerini ve yakın aileyi tanır.","hook":{"question":"Bir hayat hikâyesinin başlangıcını araştırırken hangi bilgileri ayrı kutulara yazarsın?","options":["Yer, zaman ve aile","Yalnız kesin doğum günü","Yalnız sonraki yolculuklar"],"note":"Üç bilgi türünü ayırın; tartışmalı günü tahmin ettiren yarışma yapmayın."},"frames":[{"title":"Doğumun şehri","kind":"city","labels":["Mekke","Hicaz","Kâbe çevresi"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) Mekke'de dünyaya geldi. Önceki derslerde tanıdığımız şehir şimdi hayat yolculuğunun başlangıç noktası oluyor. Haritada Mekke'yi yeniden bulalım ve doğum bilgisiyle eşleştirelim. Sonraki yıllarda gidilen başka bir şehri doğum yeri sanmamak için olay ile mekânı birlikte kaydetmek önemlidir. Bu dersin ilk kesin ayrımı yer bilgisidir: başlangıç şehri Mekke'dir."},{"title":"Yakın aile bağları","kind":"family","labels":["Anne: Âmine","Baba: Abdullah","Dede: Abdülmuttalib"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem)'in annesi Âmine, babası Abdullah'tır. Abdullah doğumdan önce vefat etmişti. Dede Abdülmuttalib de yakın aile çevresinde önemli bir yere sahipti. Aile şemasındaki çizgiler kişilerin görevlerini karıştırmamamız için kullanılır; anne, baba ve dede farklı bağları anlatır. Şemayı okurken yalnız adları tekrar etmek yerine her adın hangi bağla yer aldığını açıklayalım."},{"title":"Fil Yılı neyi anlatır?","kind":"timeline","labels":["Fil Yılı","Doğum","Yaklaşık 571","Farklı hesaplamalar"],"narration":"Doğum, siyer kaynaklarında Fil Yılı ile ilişkilendirilir. Miladî takvimde yaygın olarak yaklaşık 571 yılı verilir; farklı hesaplamalar da bulunduğunu bilmeliyiz. Bir olayın yılı hakkında farklı görüş bulunması, olayla ilgili bütün bilgilerin belirsiz olduğu anlamına gelmez. Mekke bilgisiyle tarih hesaplamasını ayrı tutarız. Zaman çizgisine kesin gün yazmak yerine kullanılan kaynakta belirtilen açıklamayı ekleriz."},{"title":"Bilgiye saygı, insana özen","kind":"book","labels":["Bilinen bilgi","Yaklaşık tarih","Kaynak notu","Özenli anlatım"],"narration":"Bu başlangıcı öğrenirken hem bilgiyi doğru aktarır hem de aile kaybı gibi konuları incelikle konuşuruz. Bir arkadaşımızın kendi ailesini anlatması gerekmez. Kaynakta bulunmayan ayrıntıları hikâyeyi heyecanlı kılmak için eklemeyiz. Defterimizde yer, aile bağı ve tarih için ayrı alanlar açabiliriz. Böylece bildiğimizle tahmin ettiğimizi ayıran, saygılı bir siyer öğrenme alışkanlığı kazanırız."}],"game":{"kind":"match","title":"Başlangıç dosyasını tamamla","prompt":"Her bilgi kartını uygun başlıkla eşleştir.","pairs":[{"left":"Mekke","right":"Doğum yeri","explanation":"Sonraki hayat durakları doğum yerini değiştirmez."},{"left":"Âmine","right":"Anne","explanation":"Aile şemasındaki anne bağıdır."},{"left":"Abdullah","right":"Baba","explanation":"Doğumdan önce vefat ettiği bilgisi aynı kartta tutulur."},{"left":"Abdülmuttalib","right":"Dede","explanation":"Baba ile dede bağları farklıdır."}]},"decision":{"question":"Sınıf afişinde 'Doğum tarihi tartışmasız şu gündür' yazıyor; kullanılan kaynak ise farklı hesaplamalar olduğunu belirtiyor. Ne yapmalıyız?","options":["Afiş daha kesin görünsün diye kaynak notunu silelim.","Mekke bilgisini de silelim; hiçbir şey bilinmiyor diyelim.","Yaklaşık yılı yazıp tarih hesabındaki farklılığı belirtelim."],"answer":2,"explanations":["Kesin görünmek, kaynakta olmayan kesinlik eklemeyi haklı çıkarmaz.","Tarih hesabındaki farklılık, doğum yerini belirsiz yapmaz.","Doğru: kaynağın verdiği kesinlik düzeyini koruyoruz."]},"quiz":[{"question":"Mekke ile yaklaşık 571 bilgileri hangi iki soruyu cevaplar?","options":["Kim ve neden?","Nerede ve ne zaman?","Nasıl ve kimle?"],"answer":1,"explanation":"Mekke yer, yaklaşık 571 zaman bilgisidir."},{"question":"Abdullah ile Abdülmuttalib'i doğru ayıran seçenek hangisidir?","options":["Abdullah baba, Abdülmuttalib dede","Abdullah dede, Abdülmuttalib amca","İkisi de süt aile üyeleri"],"answer":0,"explanation":"Aile şeması adları farklı bağlarla yerleştirir."},{"question":"'Yaklaşık' ifadesi bu derste neden kullanılıyor?","options":["Şehir adı bilinmediği için","Aile bağları bilinmediği için","Miladî tarih hesabında farklı görüşler bulunduğu için"],"answer":2,"explanation":"Yaklaşık ifadesi hangi bilginin ne ölçüde kesin olduğunu dürüstçe gösterir."}],"teacher":{"misconception":"Fil Yılı ile bir miladî günün tartışmasız eşit olduğunu söylemeyin; bu bölümde doğum mucizeleri üzerine doğrulanmamış ayrıntı eklemeyin.","differentiation":"5–6. sınıf üç aile bağını eşlesin; 7–8. sınıf kesin yer bilgisi ile yaklaşık zaman bilgisini ayırsın.","exit":"Doğum yerini, anne-baba adlarını ve tarihin nasıl yazılması gerektiğini birer cümleyle açıkla."},"sources":[{"title":"TDV — Siyer: hayat ve kronoloji","url":"https://islamansiklopedisi.org.tr/muhammed#1-hayati"}]},{"id":4,"module":1,"title":"Hazret-i Halîme'nin yanında","date":"Çocukluğun ilk yılları","objective":"Sütanne geleneğini ve Hazret-i Halîme'nin hayat hikâyesindeki yerini öğrenir.","hook":{"question":"Bir çocuğun bakımında anne-baba dışında kimler destek olabilir?","options":["Aile yakınları ve bakım veren kişiler","Yalnız aynı evde doğan kardeşler","Yalnız okul çağından sonraki öğretmenler"],"note":"Kendi aile durumlarını anlatmaya zorlamadan, bakımın farklı kişilerce desteklenebileceğini konuşun."},"frames":[{"title":"Bir dönemin bakım geleneği","kind":"home","labels":["Mekke","Sütanne","Şehir dışı çevre"],"narration":"Bazı Mekkeli aileler küçük çocuklarını bir süre şehir dışında yaşayan sütannelerin bakımına veriyordu. Bu, dönemin hayat şartları içinde karşılaşılan bir uygulamaydı. Her aile ve her dönem için tek bir bakım biçimi varmış gibi düşünmeyelim. Tarihî geleneği anlamak, bugünkü aileleri onunla karşılaştırıp yargılamak değildir. Önce uygulamanın ne olduğunu öğrenir, sonra hayat hikâyesindeki yerini belirleriz."},{"title":"Hazret-i Halîme'nin yeri","kind":"family","labels":["Hazret-i Halîme","Sütannelik","Bakım","Çocukluk"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) çocukluğunun bir bölümünü sütanne Hazret-i Halîme'nin yanında geçirdi. Hazret-i Halîme, Sa'doğulları çevresinden geliyordu. Bu ad aile şemamızda anneden farklı bir bağ olan sütanneliği gösterir. Âmine'nin anne oluşu ile Hazret-i Halîme'nin sütanne oluşu birbiriyle çelişmez. Her kişinin hayat hikâyesine hangi bağla katıldığını doğru adlandırmak, yakın çevreyi anlamamızı sağlar."},{"title":"Bakım birden çok emek ister","kind":"community","labels":["Beslenme","Koruma","İlgi","Süt aile"],"narration":"Hazret-i Halîme ve aile çevresi, çocukluk döneminin bakım halkalarından biridir. Bir çocuğun büyümesinde yalnız yiyecek değil, korunma ve ilgi de önem taşır. Bu cümlelerimiz olaydan hareketle kurduğumuz eğitim bağlantısıdır; kaynakta aktarılmayan günlük konuşmaları gerçekmiş gibi anlatmayız. Ekrandaki bakım kartlarını inceleyip hangi ihtiyacı karşıladıklarını söyleyelim. Böylece aile bağlarının yanında verilen emeği de fark ederiz."},{"title":"Teşekkürün somut karşılığı","kind":"values","labels":["Fark etmek","Teşekkür etmek","Destek olmak"],"narration":"Bu dersten günlük hayatımıza taşıyacağımız soru şudur: Bana verilen emeği nasıl fark edebilirim? İsim ve özel bilgi paylaşmadan bir bakım örneği düşünebiliriz. Düzenli yemek hazırlamak, güvenli bir yere götürmek veya dikkatle dinlemek farklı emeklerdir. Teşekkür ederken yalnız güzel bir söz söylemekle kalmayıp yaşımıza uygun bir sorumluluk üstlenebiliriz. Tarih bilgisini bugünkü davranışla ilişkilendirirken iki dönemi birbirine karıştırmayız."}],"game":{"kind":"classify","title":"Bağ mı, bakım davranışı mı?","prompt":"Kartları aile bağı ve bakım örneği olarak ayır.","groups":["Aile ve süt aile bağı","Bakım davranışı"],"items":[{"text":"Âmine'nin anne oluşu","group":0,"explanation":"Bu, kişinin aile içindeki bağını belirtir."},{"text":"Hazret-i Halîme'nin sütanneliği","group":0,"explanation":"Sütannelik özel bir bakım ve yakınlık bağıdır."},{"text":"Abdülmuttalib'in dedeliği","group":0,"explanation":"Dede, aile bağıdır; bir davranışın adı değildir."},{"text":"Küçük bir çocuğun beslenmesiyle ilgilenmek","group":1,"explanation":"Bu kart ihtiyaç karşılayan bir işi anlatır."},{"text":"Çocuğun güvenliğini gözetmek","group":1,"explanation":"Koruma bir bakım davranışıdır."},{"text":"Bir ihtiyacı dikkatle dinlemek","group":1,"explanation":"İlgi göstermek bakımın davranış boyutudur."}]},"decision":{"question":"Bir öğrenci aile şemasında Âmine'yi silip yerine Hazret-i Halîme yazıyor. En uygun açıklama hangisi?","options":["Sütanne ve anne farklı bağlardır; ikisi de kendi başlığıyla kalmalı.","Sütanne adı varsa anne adı artık kullanılmaz.","İki ad benzer işi anlattığı için tek kişide birleştirilebilir."],"answer":0,"explanations":["Doğru: farklı kişileri ve bağları ayrı gösteriyoruz.","Bakım desteği, anne bağını ortadan kaldırmaz.","İki farklı kişiyi tek kişi gibi göstermek tarih bilgisini bozar."]},"quiz":[{"question":"Hazret-i Halîme'nin bu bölümdeki temel bağı nedir?","options":["Dede ailesinden hala","Sütanne","Mekke'nin yöneticisi"],"answer":1,"explanation":"Hazret-i Halîme çocukluk döneminde sütanne olarak bakım sağlamıştır."},{"question":"Bu eski geleneği öğrenirken hangi yaklaşım uygundur?","options":["Bütün ailelerin aynı uygulamayı yaptığını varsaymak","Bugünkü her aileye aynı modeli zorunlu saymak","Dönemin şartlarını ve kaynakta anlatılan örneği incelemek"],"answer":2,"explanation":"Tarihî bir uygulamayı kendi bağlamında öğreniriz; her aileye genellemeyiz."},{"question":"Hangisi tarihî bilgiyle bugünkü eğitim bağlantısını doğru ayırır?","options":["Sütannelik tarihî bilgidir; bakım verenlere teşekkür planı bizim uygulamamızdır.","Yazdığımız teşekkür cümlesi tarihî bir konuşmadır.","Bugünkü bakım örnekleri Hazret-i Halîme'nin bütün günlük işlerini kanıtlar."],"answer":0,"explanation":"Özgün uygulamayı kaynakta aktarılan tarihî söz veya olay gibi sunmayız."}],"teacher":{"misconception":"Sütanneliği annenin yerine geçip anne bağını yok eden bir durum gibi açıklamayın; özel aile bilgisi istemeyin.","differentiation":"Küçük sınıflar iki bağı ayırsın; büyük sınıflar tarihî bilgi ile bugünkü çıkarımı farklı renklerde işaretlesin.","exit":"Hazret-i Halîme'nin bağını doğru adlandır ve bakım emeği için somut bir teşekkür örneği ver."},"sources":[{"title":"TDV — Hazret-i Halîme","url":"https://islamansiklopedisi.org.tr/halime"}]},{"id":5,"module":1,"title":"Âmine ve Hazret-i Ümmü Eymen","date":"Yaklaşık altı yaşındayken","objective":"Annenin vefatından sonra sağlanan desteği tanır.","hook":{"question":"Üzüntülü bir yolculukta küçük bir çocuğa yardım etmek neyi gerektirir?","options":["Yalnız yolun adını bilmek","Güvenli dönüşü ve bakım ihtiyacını birlikte gözetmek","Kendi kararlarını tek başına vermesini beklemek"],"note":"Kişisel kayıp deneyimi istemeyin. Hikâyeyi canlandırmadan güzergâh ve bakım sorumluluğu üzerinden ilerleyin."},"frames":[{"title":"Mekke'den Yesrib'e ziyaret","kind":"route","labels":["Mekke","Yesrib","Âmine","Hazret-i Ümmü Eymen"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) yaklaşık altı yaşındayken annesi Âmine ile Yesrib'e bir ziyarette bulundu. Yolculukta Hazret-i Ümmü Eymen de vardı. Haritada başlangıç ve ziyaret yerini işaretleyelim. Bu ziyaret, yıllar sonra gerçekleşecek hicretle aynı olay değildir. Aynı şehir hayat hikâyesinde farklı zamanlarda yeniden karşımıza çıkabilir; olayın tarihini ve yolculuğun amacını birlikte okumamız gerekir."},{"title":"Dönüş yolundaki kayıp","kind":"journey","labels":["Yesrib'den dönüş","Ebvâ","Âmine'nin vefatı"],"narration":"Ziyaretten dönüş sırasında Âmine, Mekke ile Yesrib arasındaki Ebvâ'da vefat etti. Bu bilgi, çocukluk dönemindeki önemli bir kaybı anlatır. Olayı öğrenirken ayrıntılı üzüntü tasvirleri yapmaya gerek yoktur. Haritada Ebvâ'yı iki şehir arasındaki yol üzerinde düşünelim. Bir kişinin vefat ettiği yer ile yolculuğun başladığı ya da bittiği şehir aynı olmak zorunda değildir."},{"title":"Hazret-i Ümmü Eymen'in desteği","kind":"community","labels":["Bakım","Güvenli dönüş","Mekke","Aile büyükleri"],"narration":"Hazret-i Ümmü Eymen, Peygamber Efendimiz (sallallahü aleyhi ve sellem) ile Mekke'ye dönerek aile büyüklerine ulaşılmasına yardımcı oldu. Burada öğrenmemiz gereken yalnız bir isim değildir: zor bir durumda bakım sorumluluğu sürdürülmüş, güvenli dönüş sağlanmıştır. Kaynakta anlatılan bu desteği, yolculuk çizgisiyle birlikte okuyalım. Yolun tamamlanması ile bir çocuğun gözetilmesi aynı olayın birbirini tamamlayan iki yönüdür."},{"title":"Destek verirken incelik","kind":"values","labels":["Dinle","Yanında ol","Güvenilir yetişkin","Zorlama"],"narration":"Bu bölümden bugüne kuracağımız bağ, üzüntü yaşayan kişiye özen göstermektir. Böyle bir arkadaşımıza konuşmak isteyip istemediğini sorabilir, dinleyebilir ve gerektiğinde güvenilir bir yetişkinden destek isteyebiliriz. Yaşadıklarını sınıfta anlatmaya zorlamak doğru olmaz. Bunlar tarihî olayın yeni ayrıntıları değil, bizim bugünkü davranış önerilerimizdir. Yardımın yalnız sözle değil, güvenlik ve bakım ihtiyacını gözetmekle de ilgili olduğunu hatırlayalım."}],"game":{"kind":"sequence","title":"Ziyaret ve dönüş çizgisi","prompt":"Bu çocukluk yolculuğunun olaylarını doğru sıraya koy.","items":[{"text":"Âmine ve Hazret-i Ümmü Eymen ile Mekke'den ayrılış","explanation":"Yolculuğun başlangıç şehri Mekke'dir."},{"text":"Yesrib'de ziyaret","explanation":"Bu ziyaret yıllar sonraki hicret değildir."},{"text":"Dönüş yolunda Ebvâ'da Âmine'nin vefatı","explanation":"Ebvâ, dönüşte yaşanan kaybın yeridir."},{"text":"Hazret-i Ümmü Eymen'in desteğiyle Mekke'ye dönüş","explanation":"Bakım ve güvenli dönüş sorumluluğu sürdürülür."}]},"decision":{"question":"Sınıfta bu konuyu işlerken bir arkadaşın sessizleşiyor. Hangi yaklaşım daha özenli?","options":["Herkesin önünde kendi kaybını ayrıntılı anlatmasını istemek","Konuşmak isterse dinlemek ve gerekirse öğretmenden destek istemek","Konu bitsin diye üzülecek bir şey olmadığını söylemek"],"answer":1,"explanations":["Kişisel kaybı anlatmaya zorlamak arkadaşını daha fazla zorlayabilir.","Doğru: seçim hakkını, dinlemeyi ve güvenilir yetişkin desteğini birlikte gözetir.","Duyguyu küçümsemek destek olmak değildir."]},"quiz":[{"question":"Çocuklukta yapılan Yesrib ziyaretiyle hicreti ayırmak için hangi bilgi gerekir?","options":["Şehrin bugünkü nüfusu","Yol üzerindeki bütün dağların adı","Olayın zamanı ve yolculuğun amacı"],"answer":2,"explanation":"Aynı şehre farklı yıllarda farklı amaçlarla gidilebilir."},{"question":"Âmine'nin vefat ettiği yer hangisidir?","options":["Ebvâ","Mekke","Tâif"],"answer":0,"explanation":"Vefat, Yesrib ziyaretinden dönüşte Ebvâ'da gerçekleşmiştir."},{"question":"Hazret-i Ümmü Eymen'in katkısını en iyi açıklayan ifade hangisidir?","options":["Ziyaret şehrini yeniden adlandırmak","Bakımı sürdürerek Mekke'ye güvenli dönüşe destek olmak","Hicret için Medine'de yeni toplum kurmak"],"answer":1,"explanation":"Bu bölüm çocukluk yolculuğundaki bakım ve dönüş desteğini anlatır."}],"teacher":{"misconception":"Altı yaş çevresindeki Yesrib ziyaretiyle 622 hicretini karıştırmayın. Yas yaşayan öğrenciye kişisel anlatım zorunluluğu getirmeyin.","differentiation":"5–6. sınıf dört olay kartını sıralasın; 7–8. sınıf aynı mekânın iki farklı olayda geçmesini zaman çizgisiyle açıklasın.","exit":"Mekke, Yesrib ve Ebvâ'nın bu yolculuktaki işlevlerini birer kelimeyle söyle."},"sources":[{"title":"TDV — Âmine","url":"https://islamansiklopedisi.org.tr/amine"},{"title":"TDV — Ebvâ","url":"https://islamansiklopedisi.org.tr/ebva"},{"title":"TDV — Siyer: hayat ve kronoloji","url":"https://islamansiklopedisi.org.tr/muhammed#1-hayati"}]},{"id":6,"module":1,"title":"Dede ve amca himayesinde","date":"Yaklaşık altı–sekiz yaş ve sonrası","objective":"Çocukluk dönemindeki bakım ve destek zincirini sıralar.","hook":{"question":"Bir aile şemasında 'dede' ve 'amca' bağlarını nasıl ayırırsın?","options":["İki sözcüğü aynı kişi için kullanırım","Ailedeki ilişkiye ve olayların sırasına bakarım","Yalnız adların benzemesine bakarım"],"note":"Abdülmuttalib ve Ebû Tâlib adlarını gösterin; cevabı şemadan gerekçelendirmelerini isteyin."},"frames":[{"title":"Önce dede himayesi","kind":"family","labels":["Âmine'nin vefatı","Abdülmuttalib","Yaklaşık altı yaş"],"narration":"Âmine'nin vefatından sonra Peygamber Efendimiz (sallallahü aleyhi ve sellem)'in bakımını dede Abdülmuttalib üstlendi. Çocukluk çizgisinde artık yeni bir bakım halkası görüyoruz. Aynı hayatın içinde destek veren kişiler değişebilir; olayları karıştırmamak için değişimin hangi olaydan sonra gerçekleştiğine bakarız. Dede kartını annenin vefatından sonraki yere yerleştir. Bu sıralama, kişilerin önemini yarıştırmaz; bakım sorumluluğunun nasıl sürdüğünü gösterir."},{"title":"Ardından amca himayesi","kind":"timeline","labels":["Abdülmuttalib'in vefatı","Yaklaşık sekiz yaş","Ebû Tâlib"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) yaklaşık sekiz yaşındayken Abdülmuttalib vefat etti. Bundan sonra amca Ebû Tâlib'in yanında yaşamaya başladı. Ebû Tâlib, baba Abdullah'ın kardeşiydi. Aile şemasındaki amca çizgisini şimdi takip edelim. Zaman çizgisiyle aile şeması farklı soruları cevaplar: biri olayın sırasını, diğeri yakınlık bağını gösterir. İkisini birlikte okuyunca adlar daha anlamlı hale gelir."},{"title":"Bir evde paylaşılan bakım","kind":"home","labels":["Ebû Tâlib'in evi","Hazret-i Fâtıma bint Esed","Bakım","Yakınlık"],"narration":"Ebû Tâlib'in eşi Hazret-i Fâtıma bint Esed de bakım ve destek sağlayan aile çevresindeydi. Bir evin sorumluluğu yalnız bir kişinin adıyla sınırlı kalmaz; farklı kişiler farklı katkılar sunar. Burada kaynakta aktarılan bağı öğreniyoruz, günlük hayatın bilinmeyen konuşmalarını uydurmuyoruz. Şemada aynı ev çevresine yerleştirilen adlar, herkesin aynı akrabalık bağına sahip olduğu anlamına gelmez."},{"title":"Bakım zinciri ne öğretir?","kind":"community","labels":["Sorumluluk","Süreklilik","Yakınları gözetmek"],"narration":"Çocukluk dönemini yalnız kayıpların listesi olarak okumayalım. Aynı zamanda bakımın kimler tarafından sürdürüldüğünü fark edelim. Dede, amca ve diğer aile yakınlarının desteği hayat çizgisindeki önemli halkalardır. Bugün de yardıma ihtiyaç duyan birinin sorumluluğunu paylaşmak, yalnız güzel söz söylemekten daha fazlasını gerektirir. Dersin sonunda bir aile bağı ile bir bakım davranışını birbirinden ayırarak açıklayacağız."}],"game":{"kind":"sequence","title":"Bakım halkalarını sırala","prompt":"Çocukluk dönemindeki geçişleri önce-sonra ilişkisiyle yerleştir.","items":[{"text":"Âmine ile çocukluk dönemi","explanation":"Anne bağı ve bakımın başlangıç halkalarından biridir."},{"text":"Âmine'nin vefatından sonra Abdülmuttalib'in himayesi","explanation":"Dede himayesi amca himayesinden önce gelir."},{"text":"Yaklaşık sekiz yaşında Abdülmuttalib'in vefatı","explanation":"Bakım sorumluluğunda yeni bir geçiş yaşanır."},{"text":"Ebû Tâlib'in evinde bakımın sürmesi","explanation":"Amca ve aile çevresi destek sağlamayı sürdürür."}]},"decision":{"question":"Bir öğrenci 'Ebû Tâlib, Abdülmuttalib'in diğer adıdır' diyor. Hangi iki kanıt düzeltmeye yardımcı olur?","options":["Farklı aile bağları ve farklı zamanlarda üstlenilen bakım","İki adın bazı seslerinin benzemesi","Aynı şehirde yaşamış olmaları"],"answer":0,"explanations":["Doğru: biri dede, diğeri amcadır; himaye dönemleri de birbirini izler.","Adların benzemesi kişilerin aynı olduğunu göstermez.","Aynı şehirde yaşamak farklı kişileri tek kişiye dönüştürmez."]},"quiz":[{"question":"Bakım sırası hangi seçenekte doğrudur?","options":["Ebû Tâlib, ardından Abdülmuttalib","Abdülmuttalib, ardından Ebû Tâlib","Hazret-i Fâtıma bint Esed, ardından Âmine"],"answer":1,"explanation":"Annenin vefatından sonra dede, dedenin vefatından sonra amca himayesi gelir."},{"question":"Ebû Tâlib'in aile bağı hangisidir?","options":["Anne tarafından dede","Süt kardeş","Baba Abdullah'ın kardeşi olan amca"],"answer":2,"explanation":"Aile şemasında Abdullah ile Ebû Tâlib kardeş bağıyla yer alır."},{"question":"Aile şemasıyla zaman çizgisini birlikte okumak ne sağlar?","options":["Yakınlık bağını ve bakımın sırasını birlikte anlamayı","Kaynakta olmayan konuşmaları tamamlamayı","Bütün kişilerin aynı görevi yaptığını göstermeyi"],"answer":0,"explanation":"İki gösterim farklı ama birbirini tamamlayan bilgileri taşır."}],"teacher":{"misconception":"Abdülmuttalib ile Ebû Tâlib'i veya Hazret-i Fâtıma bint Esed ile kız evlat Hazret-i Fâtıma'yı birleştirmeyin.","differentiation":"Küçük sınıflarda iki aşamalı sıra; büyük sınıflarda aynı bilgiyi aile şeması ve zaman çizgisiyle iki biçimde açıklama.","exit":"Dede ile amcayı adlarıyla ayır; bakımın hangi olaydan sonra değiştiğini söyle."},"sources":[{"title":"TDV — Ebû Tâlib","url":"https://islamansiklopedisi.org.tr/ebu-talib"}]},{"id":7,"module":2,"title":"Emek ve sorumluluk","date":"Çocukluk ve gençlik yılları","objective":"Çalışmanın ve yaşa uygun görevlerin önemini fark eder.","hook":{"question":"Bir sorumluluğu iyi yapmak için hangisi daha önemlidir?","options":["İşe yalnız hızlı başlamak","İşin adını bilmek","İhtiyacı gözetip işi düzenli takip etmek"],"note":"Günlük küçük görevlerden örnek alın; çobanlık ile bugünkü çocuk emeğini aynı şartlarda değerlendirmeyin."},"frames":[{"title":"Çocuklukta emek","kind":"journey","labels":["Çobanlık","Mekke çevresi","Emek","Sorumluluk"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) küçük yaşlarda çobanlık yaptı. Bu bilgi, hayat hikâyesinde emek ve sorumluluğun yerini görmemize yardım eder. Çobanlık yalnız hayvanların yanında durmak değildir; onların ihtiyaçlarını ve güvenliğini takip etmeyi gerektiren bir iştir. Ekrandaki görev kartlarını inceleyelim. Burada günlük ayrıntıları tarihî olay diye eklemek yerine, öğrenilen işi ve gerektirdiği dikkati anlamaya çalışıyoruz."},{"title":"Aile hayatına katkı","kind":"home","labels":["Ebû Tâlib'in ailesi","Katkı","Düzen","Görev"],"narration":"Çobanlık, Peygamber Efendimiz (sallallahü aleyhi ve sellem)'in yanında yaşadığı Ebû Tâlib'in ailesine de destek sağlıyordu. Aile içinde bir işe katkı sunmak, herkesin bütün işleri tek başına üstlenmesi demek değildir. Görevin yaşa, güce ve şartlara uygun olması gerekir. Tarihî dönemdeki çalışma biçimini öğrenirken bugün çocukların güvenliğini, eğitimini ve dinlenmesini gözeten sorumluluklarla bağlantı kurarız; ağır iş yükünü övmeyiz."},{"title":"İşin gerektirdiği dikkat","kind":"values","labels":["İhtiyacı fark et","Takip et","Aksaklığı bildir"],"narration":"Bir işi üstlenmekle o işin gereğini yerine getirmek aynı şey değildir. Çobanlık örneği üzerinden dikkatin ve sürekliliğin önemini düşünelim. Bir canlıyı gözetmek, ihtiyaç ortaya çıkınca fark etmeyi ve gerektiğinde yardım istemeyi gerektirir. Bu açıklama bizim eğitim bağlantımızdır; kaynakta anlatılmamış tek bir güne ait olay kurmuyoruz. Sorumluluğu sonuçlarıyla birlikte düşünmek, verilen görevi daha bilinçli yapmamıza yardım eder."},{"title":"Bugün hangi görevi üstlenebilirim?","kind":"community","labels":["Yaşa uygun görev","Zaman belirle","Yardım iste","Kontrol et"],"narration":"Şimdi tarihî örnekten kendi hayatımıza geçelim. Sınıf kitaplığını düzenlemek veya evde güvenli bir küçük işe yardım etmek gibi bir görev seçebiliriz. Görevin ne olduğunu, ne zaman yapılacağını ve tamamlandığını nasıl anlayacağımızı belirleyelim. Yapamadığımız yerde durumu saklamak yerine yardım istemek sorumluluğun parçasıdır. Düzenli küçük bir katkı, yalnız bir kere büyük bir söz vermekten daha anlaşılır bir plandır."}],"game":{"kind":"classify","title":"Sorumluluk planını kontrol et","prompt":"Örnekleri sorumluluğu sürdüren ve yeniden düzenlenmesi gereken davranışlar olarak ayır.","groups":["Sorumluluğu sürdürüyor","Planı düzeltmeli"],"items":[{"text":"Kitaplık görevinin gününü belirleyip uygulamak","group":0,"explanation":"Görev ve zaman nettir; düzenli takip mümkündür."},{"text":"Görev zorlaşınca öğretmenden yardım istemek","group":0,"explanation":"Yardım istemek görevi önemsemenin bir yoludur."},{"text":"Sınıf bitkisine verilen suyu kontrol etmek","group":0,"explanation":"Canlının ihtiyacı takip edilir; yalnız yapılmış görünmesi yetmez."},{"text":"Yapamadığı görevi tamamlanmış gibi bildirmek","group":1,"explanation":"Eksikliği saklamak çözüm bulunmasını engeller."},{"text":"Güvenli olmayan ağır bir işi tek başına denemek","group":1,"explanation":"Görev yaşa ve güvenliğe uygun olmalıdır."},{"text":"Görevi üstlenip ne zaman yapacağını hiç planlamamak","group":1,"explanation":"Niyetin yanında uygulanabilir bir zaman ve takip gerekir."}]},"decision":{"question":"Bir arkadaşın 'Sorumluluk sahibi kişi hiç yardım istemez' diyor. Bu dersin yaklaşımı hangisidir?","options":["Yardım istememek görevin doğru yapıldığını kanıtlar.","Gerektiğinde yardım isteyerek işi güvenli ve doğru sürdürür.","Yardım gerekiyorsa görevi haber vermeden bırakır."],"answer":1,"explanations":["Tek başına kalmak doğru sonuç garantisi değildir.","Doğru: sorumluluk, kendi sınırını ve ihtiyacı fark etmeyi de kapsar.","Görevi haber vermeden bırakmak başkalarının planını ve ihtiyacı etkiler."]},"quiz":[{"question":"Bu bölümde öğrenilen çalışma hangisidir?","options":["Medine'de elçilik","Mekke döneminde çobanlık","Kâbe onarımında hakemlik"],"answer":1,"explanation":"Çobanlık çocukluk ve gençlikte emek konusuyla ele alınır; diğer olaylar farklı derslerdedir."},{"question":"Tarihî örneği bugüne taşırken hangi sınır korunmalıdır?","options":["Çocuklara her ağır işi vermek","Eğitim ve dinlenmeyi gereksiz görmek","Görevin yaşa ve güvenliğe uygun olması"],"answer":2,"explanation":"Emek değerini öğrenmek, çocukların güvenliğini ve eğitimini ihmal etmek değildir."},{"question":"Hangi plan daha izlenebilirdir?","options":["Her salı kitapları sayıp eksikleri öğretmene bildireceğim.","Bundan sonra her işi kusursuz yapacağım.","Bir gün kitaplığa yardım edebilirim."],"answer":0,"explanation":"Somut görev, zaman ve kontrol ölçütü planı uygulanabilir kılar."}],"teacher":{"misconception":"Çobanlıkla ilgili kaynakta bulunmayan maceralar eklemeyin; modern çocuk emeğini normalleştiren sonuçlar çıkarmayın.","differentiation":"5–6. sınıf bir güvenli görev seçsin; 7–8. sınıf görev-zaman-kontrol ölçütü içeren plan hazırlasın.","exit":"Öğrendiğin tarihî çalışma ile bugün üstlenebileceğin güvenli görevi ayrı cümlelerde söyle."},"sources":[{"title":"TDV — Siyer: hayat ve kronoloji","url":"https://islamansiklopedisi.org.tr/muhammed#1-hayati"}]},{"id":8,"module":2,"title":"Güvenilirlik: el-Emîn","date":"Gençlik yılları","objective":"El-Emîn unvanını dürüstlük ve güvenilirlikle açıklar.","hook":{"question":"Ödünç verdiğin bir eşyayı kime daha rahat teslim edersin?","options":["Eşyayı koruyup sözünü yerine getirene","En yüksek sesle güven sözü verene","Eşyayı en uzun süre kendinde tutana"],"note":"Öğrencilerin kişi adı vermeden davranış gerekçesi sunmasını isteyin."},"frames":[{"title":"El-Emîn ne demektir?","kind":"values","labels":["el-Emîn","Güvenilirlik","Doğruluk","Emanet"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) insanlar arasında doğruluk ve güvenilirlikle tanındı; el-Emîn unvanı bu güvenilirliği ifade eder. Bir unvanın anlamını öğrenmek yalnız kelime karşılığını söylemek değildir. Hangi davranışların böyle bir güven oluşturduğunu düşünmek gerekir. Verilen söze sadık kalmak, doğru bilgi vermek ve emanetin hakkını gözetmek aynı değerin farklı yönleridir. Şimdi bu yönleri örneklerle birbirinden ayıracağız."},{"title":"Ticarette güvenin yeri","kind":"market","labels":["Mal","Ödeme","Doğru bilgi","Söz"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) gençlik yıllarında ticaretle uğraştı. Ticaret, malın el değiştirmesinin yanında insanlar arasında güven gerektirir. Malı doğru tanıtmak, üzerinde anlaşılan koşulları korumak ve hakkı sahibine vermek bunun parçalarıdır. Bu genel ilişkiyi anlamak, güvenilirliğin neden günlük hayatta görülen bir özellik olduğunu gösterir. Kaynakta anlatılmayan bir pazarlık konuşmasını tarihî diyalog gibi kurmayacağız."},{"title":"Emanet, izinle korunur","kind":"agreement","labels":["Sahibi","İzin","Koruma","Teslim"],"narration":"Emanet, korunması için bize bırakılan şey olabilir. Bir eşyayı elinde tutmak ona istediğin gibi davranma hakkı vermez. Sahibinin iznini ve teslim şartını gözetmek gerekir. Bu dersteki kitap örneği bugüne ait bir uygulamadır: kitabı korumak, zamanında vermek ve bir zarar oluştuysa dürüstçe açıklamak güveni sürdürür. Hatanın hiç yaşanmaması değil, yaşananın saklanmaması da önemlidir."},{"title":"Güven davranışlarla büyür","kind":"community","labels":["Söz","Davranış","Açıklık","Süreklilik"],"narration":"Bir kere doğru davranmak değerlidir; fakat güven zaman içinde benzer davranışlarla güçlenir. Söylediğimizle yaptığımızın uyuşmasına bakabiliriz. Sınıf çalışmasında payımıza düşeni yapmak, yanlış bilgi verdiğimizi fark edince düzeltmek ve başkasının eşyasını izinsiz kullanmamak birbirinden farklı örneklerdir. Bunları el-Emîn kavramıyla ilişkilendirirken tarihî unvan ile bizim günlük uygulamalarımız arasındaki ayrımı koruyalım. Amaç güvenilirliği somut davranışa çevirmektir."}],"game":{"kind":"match","title":"Güvenin dört davranışı","prompt":"Davranışı açıkladığı güven ilkesiyle eşleştir.","pairs":[{"left":"Ödünç kitabı konuşulan gün geri vermek","right":"Sözü yerine getirmek","explanation":"Zaman üzerinde yapılan anlaşmaya uyulur."},{"left":"Kitabın sayfası zarar görünce sahibine söylemek","right":"Hatasını dürüstçe açıklamak","explanation":"Hasarı saklamak yerine çözüm için açık olunur."},{"left":"Eşyayı başkasına vermeden sahibine sormak","right":"İzin sınırını gözetmek","explanation":"Emanetçi olmak sahip olmak değildir."},{"left":"Bir ürünün kusurunu alıcıdan gizlememek","right":"Doğru bilgi vermek","explanation":"Karşı tarafın kararını etkileyen bilgi saklanmaz."}]},"decision":{"question":"Ödünç aldığın kitabın bir sayfası yanlışlıkla yırtıldı. Güveni koruyan yaklaşım hangisi?","options":["Fark edilmez diye sessizce teslim etmek","Aynı kitabı izinsiz başka birinin kitabıyla değiştirmek","Sahibine anlatıp uygun telafiyi birlikte konuşmak"],"answer":2,"explanations":["Sessiz kalmak, sahibinin bilmesi gereken zararı gizler.","Başka bir emaneti izinsiz kullanmak yeni bir sorun çıkarır.","Doğru: dürüst açıklama ve telafi arayışı birlikte yürütülür."]},"quiz":[{"question":"El-Emîn hangi anlamı taşır?","options":["Güvenilir","Yol gösteren coğrafyacı","Ticaret yolunun adı"],"answer":0,"explanation":"Unvanın temel anlamı güvenilirliktir."},{"question":"Hangisi emanet ile sahipliği doğru ayırır?","options":["Elimdeyse dilediğim kişiye verebilirim.","Korurum; kullanma ve teslim şartında sahibinin iznini gözetirim.","Teslim tarihi geçince eşya bana ait olur."],"answer":1,"explanation":"Emanet, sahibinin hakkını ortadan kaldırmaz."},{"question":"Güvenilirliğin zamanla güçlendiğini en iyi gösteren şey hangisidir?","options":["Sık sık kendini övmek","Bir kez çok etkili konuşmak","Verilen sözle davranışın düzenli olarak uyuşması"],"answer":2,"explanation":"Güven yalnız iddiayla değil, tekrarlanan doğru davranışlarla oluşur."}],"teacher":{"misconception":"El-Emîn'i yalnız ticaret kazancının yüksekliğiyle açıklamayın. 'Hiç hata yapmazsam güvenilirim' yerine hatayı saklamama ve telafiyi de işleyin.","differentiation":"Küçük sınıflar davranış-ilke eşlesin; büyük sınıflar emanet ile sahiplik arasındaki izin farkını açıklasın.","exit":"El-Emîn'in anlamını söyle; güveni koruyan bir davranış ve nedenini ekle."},"sources":[{"title":"TDV — Siyer: hayat ve kronoloji","url":"https://islamansiklopedisi.org.tr/muhammed#1-hayati"}]},{"id":9,"module":2,"title":"Haksızlığa karşı birlikte: Hilfü'l-fudûl","date":"Peygamberlikten önce; yaklaşık 590","objective":"Hilfü'l-fudûl'ün amacını adalet düşüncesiyle ilişkilendirir.","hook":{"question":"Tanımadığın biri haksızlığa uğradığında onun hakkı daha mı az önemlidir?","options":["Aynı gruptan değilse daha az önemlidir.","Kim olduğundan bağımsız olarak hakkı gözetilmelidir.","Yalnız güçlü biri yanında durursa önemlidir."],"note":"Sınıftan kişisel olay adı istemeden adaletin aidiyete bağlı olmadığını tartıştırın."},"frames":[{"title":"Bir tüccarın hakkı","kind":"market","labels":["Mekke","Yabancı tüccar","Ödenmeyen bedel","Hak arama"],"narration":"Mekke'de dışarıdan gelen bir tüccarın malının bedelini alamaması, haksızlığa karşı ortak bir girişimin doğmasına yol açan olaylar arasında anlatılır. Kabile desteği olmayan bir kişi hakkını almakta zorlanabiliyordu. Burada ayrıntılı kişi listelerini ezberlemekten önce sorunu belirleyelim: alışveriş yapılmış, fakat ödeme hakkı korunmamıştı. Bir toplumda güvenin sürmesi, yalnız güçlülerin değil herkesin hakkının gözetilmesine bağlıdır."},{"title":"Hilfü'l-fudûl anlaşması","kind":"agreement","labels":["Bir araya gelme","Hakkı savunma","Dayanışma","Mekke"],"narration":"Bazı Mekkeliler haksızlığa uğrayanları desteklemek için bir araya gelerek Hilfü'l-fudûl adıyla anılan anlaşmayı yaptı. Amaç, mağdurun hakkını güçlü kişilerin isteğine bırakmamaktı. Bu nedenle girişim yalnız ticaretle ilgili bir kazanç ortaklığı değildir. Hak sahibini korumaya yönelik ortak sorumluluk üstlenilmiştir. Anlaşma kartında 'kimin hakkı, hangi amaçla, birlikte nasıl korunuyor' sorularını takip ederek temel düşünceyi bulalım."},{"title":"Gençlikte adalete katılmak","kind":"timeline","labels":["Peygamberlik öncesi","Hilfü'l-fudûl","Sonraki takdir"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) peygamberlikten önce bu anlaşmaya katıldı. Peygamber Efendimiz (sallallahü aleyhi ve sellem) daha sonraki yıllarda da girişimi değerli bir örnek olarak andı. Bu iki bilgi arasında süreklilik vardır: hak savunmayı değerli görmek belirli bir güne ait kalmamıştır. Olayı zaman çizgisine yerleştirirken henüz ilk vahiy dönemine gelmediğimizi hatırlayalım. Adalet konusu gençlik hayatının da önemli bir parçasıdır."},{"title":"Adalet ve güvenli destek","kind":"community","labels":["Dinle","Kanıtı incele","Hakkı gözet","Yardım iste"],"narration":"Bugünkü bir sınıf örneğinde, haksız yere dışlanan arkadaşın hakkını savunmak için önce durumu anlamak gerekir. Tarafları dinlemek, acele suçlamamak ve öğretmen desteği istemek güvenli yollardır. Bu öneriler Hilfü'l-fudûl'ün aynen tekrarı değil, adalet düşüncesinden çıkardığımız uygulamalardır. Yardım ederken yeni bir haksızlığa yol açmamaya dikkat ederiz. Hak savunmak, yalnız kendi arkadaş grubunu korumaktan daha geniş bir sorumluluktur."}],"game":{"kind":"classify","title":"Hakkı mı, grubu mu koruyor?","prompt":"Davranışların adaleti destekleyip desteklemediğine karar ver.","groups":["Hakkı gözetiyor","Adaleti zedeliyor"],"items":[{"text":"Tanımadığı kişinin şikâyetini de dikkatle dinlemek","group":0,"explanation":"Hak arama, yalnız yakınlara tanınan bir ayrıcalık değildir."},{"text":"Kendi arkadaşı haksızsa bunu dürüstçe belirtmek","group":0,"explanation":"Yakınlık, haklılık yerine geçmez."},{"text":"Ödeme yapılmadığı iddiasında bilgileri kontrol etmek","group":0,"explanation":"Adil karar için durum anlaşılmalıdır."},{"text":"Aynı gruptan diye bütün davranışları savunmak","group":1,"explanation":"Kör bağlılık başka kişinin hakkını zedeleyebilir."},{"text":"Yabancı kişinin sözünü dinlemeden geri çevirmek","group":1,"explanation":"Aidiyete göre hak aramayı engeller."},{"text":"Yardım etmek için başka bir öğrenciyi kanıtsız suçlamak","group":1,"explanation":"Birini desteklerken yeni haksızlık yapılmamalıdır."}]},"decision":{"question":"Grup çalışmasında bir öğrenci dışlanmış; fakat olayın tamamını henüz bilmiyorsun. İlk adımın ne olmalı?","options":["Hemen bir tarafı sınıfın önünde suçlamak","Durumu dinleyip öğretmenle adil çözüm aramak","Arkadaş grubunda olmadığı için ilgilenmemek"],"answer":1,"explanations":["Bilgi toplamadan suçlamak yeni bir haksızlık oluşturabilir.","Doğru: hak gözetme, dikkatli dinleme ve güvenli destek birlikte yürür.","Adalet, yalnız tanıdık kişileri korumak değildir."]},"quiz":[{"question":"Hilfü'l-fudûl'ü ticari kazanç ortaklığından ayıran amaç nedir?","options":["Yalnız kervan sayısını artırmak","Yalnız anlaşmaya katılanların mallarını satmak","Haksızlığa uğrayanın hakkını savunmak"],"answer":2,"explanation":"Temel amaç mağdurun hakkını korumak için ortak sorumluluk üstlenmektir."},{"question":"Olayın ilk vahye göre yeri nedir?","options":["Peygamberlik öncesindedir.","Hicretten sonradır.","Veda haccıyla aynı yıldadır."],"answer":0,"explanation":"Hilfü'l-fudûl gençlik döneminde, peygamberlikten önce gerçekleşmiştir."},{"question":"Girişimin sonraki yıllarda değerli anılması neyi gösterir?","options":["Bütün ayrıntıların aynı dönemde yaşandığını","Hak gözetme değerinin sürekliliğini","Yardımın yalnız zenginlere yapılacağını"],"answer":1,"explanation":"Dönem değişse de haksızlığa karşı dayanışma değerli görülmüştür."}],"teacher":{"misconception":"Olayı şiddetle hesap sorma oyunu yapmayın. Yaklaşık tarih ve yaş tartışmalarını kesin sayıya indirgemeden adalet amacı üzerinde durun.","differentiation":"Küçük sınıflar hakkı gözeten davranışları ayırsın; büyük sınıflar yakınını koruma ile adalet arasındaki olası çatışmayı açıklasın.","exit":"Hilfü'l-fudûl'ün amacını ve bugün güvenli hak savunmanın bir yolunu söyle."},"sources":[{"title":"TDV — Hilfü’l-fudûl","url":"https://islamansiklopedisi.org.tr/hilful-fudul"}]},{"id":10,"module":2,"title":"Hadîce vâlidemiz ile kurulan yuva","date":"Yaklaşık 595","objective":"Aile hayatında güven ve karşılıklı desteğin önemini tanır.","hook":{"question":"Bir ortak çalışmada güveni en çok ne güçlendirir?","options":["Yalnız en çok paraya sahip olmak","Doğru davranmak ve sorumluluğu paylaşmak","Bütün kararları tek kişinin vermesi"],"note":"Aile yaşamlarını karşılaştırmaya zorlamadan, ortak çalışma örneği üzerinden giriş yapın."},"frames":[{"title":"Ticaretle başlayan tanışıklık","kind":"market","labels":["Hadîce vâlidemiz","Ticaret","Güven","Dürüstlük"],"narration":"Hadîce vâlidemiz ticaretle uğraşıyor, güvendiği kişilerle iş ilişkileri kuruyordu. Peygamber Efendimiz (sallallahü aleyhi ve sellem)'in dürüstlüğü ve güvenilirliği bu ilişkide önemliydi. Önceki dersteki el-Emîn kavramını burada yeniden hatırlayabiliriz. İnsanların güvenini kazanmak yalnız bir işin kârlı sonuçlanmasına bağlı değildir; işin nasıl yapıldığı da önemlidir. Doğruluk ve sorumluluk, bu hayat dönemini anlamamız için temel kelimelerdir."},{"title":"Kurulan aile yuvası","kind":"home","labels":["Yaklaşık 595","Evlilik","Aile hayatı","Karşılıklı güven"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) ile Hadîce vâlidemiz yaklaşık 595 yılında evlendi. Böylece hayat çizgimizde aile yuvasının kurulduğu yeni bir aşamaya geliyoruz. Evliliği anlatırken kaynakta olmayan konuşmalar ve ayrıntılar üretmeyeceğiz. Bu bölümün odağı, güven üzerine kurulan birliktelik ve ortak hayattır. Zaman çizgisinde bu olayın ilk vahiyden önce gerçekleştiğini gösterelim; sonraki destekleri öğrenirken bu bağı hatırlayacağız."},{"title":"Yıllar boyunca süren destek","kind":"timeline","labels":["Ticaret","Aile yuvası","İlk vahiy","Destek"],"narration":"Hadîce vâlidemizin desteği yalnız evliliğin başlangıcıyla sınırlı kalmadı. İlk vahiyden sonra dikkatle dinlemesi, güven vermesi ve ilk iman eden kişi olması ileride işleyeceğimiz önemli olaylardır. Şimdilik bu bilgiyi bir zaman köprüsü olarak kullanalım. Önceki bir güven ilişkisinin sonraki zor dönemde de sürmesi, hayatın bölümlerinin birbirinden kopuk olmadığını gösterir. Her ayrıntıyı aynı tarihe yerleştirmemeye dikkat edelim."},{"title":"Güveni günlük davranışta görmek","kind":"values","labels":["Dinlemek","Sözünü tutmak","Paylaşmak","Değer vermek"],"narration":"Aile ve yakın ilişkilerde güven, karşıdakini dinlemek ve sorumluluğu paylaşmak gibi davranışlarla görünür olur. Bu derste kişileri servetleriyle değerlendirmemeyi de düşünürüz. Bir öğrencinin aile biçimini sınıfta açıklaması gerekmez; örnekleri ortak bir görev üzerinden kurabiliriz. Sözüne sadık kalan ve başkasının emeğini gözeten bir çalışma arkadaşını neden güvenilir bulduğumuzu açıklamak, öğrendiğimiz değeri günlük hayatla ilişkilendirir."}],"game":{"kind":"sequence","title":"Güven bağının zaman çizgisi","prompt":"Bu derslerde öğrendiğin aşamaları önce-sonra sırasına koy.","items":[{"text":"Gençlikte dürüstlük ve güvenilirlikle tanınma","explanation":"Güvenilirlik aile yuvasının kurulmasından önce de biliniyordu."},{"text":"Hadîce vâlidemizle ticaret ilişkisi","explanation":"Ticarette güven, tanışıklığın önemli bir parçasıdır."},{"text":"Yaklaşık 595 yılında evlilik","explanation":"Aile hayatı ilk vahiyden önce başlamıştır."},{"text":"610 yılında ilk vahiy sonrasında destek","explanation":"Bu daha sonraki olay, güvenin sürekliliğini gösterir."}]},"decision":{"question":"Bir öğrenci bu birlikteliği yalnız servet üzerinden açıklayan bir afiş hazırlıyor. Hangi ekleme konuyu daha doğru tamamlar?","options":["Dürüstlük, karşılıklı güven ve sonraki destek örneklerini eklemek","Bütün tarihleri kaldırıp yalnız ticaret miktarı yazmak","İlk vahiy ile evliliği aynı olay gibi göstermek"],"answer":0,"explanations":["Doğru: kaynaklarda öne çıkan ahlâk ve destek boyutları görünür olur.","Ticaret miktarı aile bağının anlamını tek başına açıklamaz.","Ayrı zamanlarda gerçekleşen olaylar birleştirilmemelidir."]},"quiz":[{"question":"Evlilik ile ilk vahyin sırası hangisidir?","options":["İlk vahiy, sonra evlilik","Evlilik, sonra ilk vahiy","İkisi aynı olayın iki adıdır."],"answer":1,"explanation":"Evlilik yaklaşık 595, ilk vahiy 610 yılıyla ilişkilendirilir."},{"question":"Hadîce vâlidemizin ticaret ilişkilerinde öne çıkan ölçüt nedir?","options":["Yalnız kişinin yaşadığı mahallenin adı","Yalnız en uzun yolculuğu yapmış olması","Güvenilir ve dürüst davranması"],"answer":2,"explanation":"Güven ve doğruluk, iş ilişkisinin önemli dayanaklarıdır."},{"question":"Desteğin farklı yıllarda sürmesi hangi sonucu güçlendirir?","options":["Güvenin süreklilik gösteren davranışlarla anlam kazandığını","Her olayın tek bir günde yaşandığını","Aile hayatının toplumdan tamamen kopuk olduğunu"],"answer":0,"explanation":"Birlikte yaşanan farklı dönemlerde sorumluluk ve güvenin sürmesi önemlidir."}],"teacher":{"misconception":"Evlilik yaşlarıyla ilgili farklı rivayetleri kesin bir yaş hesabı yarışına dönüştürmeyin; servet odaklı anlatım yerine güven ve destek boyutunu koruyun.","differentiation":"5–6. sınıf olay sırasını kursun; 7–8. sınıf güvenin sürekliliğini iki farklı dönem üzerinden açıklasın.","exit":"Evlilikten önceki ve sonraki güven örneklerini ayrı zamanlara yerleştir."},"sources":[{"title":"TDV — Hadîce vâlidemiz","url":"https://islamansiklopedisi.org.tr/hatice"}]},{"id":11,"module":2,"title":"Aile bağlarını öğrenelim","date":"Mekke'deki aile hayatı","objective":"Çocukların adlarını ve aile bağlarını tanır.","hook":{"question":"Bir aile şemasında aynı ada rastlamak neyi gerektirir?","options":["İki kaydı hemen tek kişiye birleştirmeyi","İsimle birlikte aile bağını da kontrol etmeyi","Şemayı tarih bilgisi olmadan okumayı"],"note":"Aynı adın farklı kişilerde bulunabildiğini hatırlatın; özel aile bilgisi istemeyin."},"frames":[{"title":"Kız evlatların adları","kind":"family","labels":["Hazret-i Zeyneb","Hazret-i Rukıyye","Hazret-i Ümmü Külsûm","Hazret-i Fâtıma"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) ile Hadîce vâlidemizin kızları Hazret-i Zeyneb, Hazret-i Rukıyye, Hazret-i Ümmü Külsûm ve Hazret-i Fâtıma'dır. Aile şemasında bu dört adı aynı kuşak üzerinde görüyoruz. Bir şema hem adları hem ilişkileri göstermelidir. Her kartı kız evlat başlığıyla eşleştirelim; anneleri, sütanneleri veya başka akrabalarla aynı kutuya yerleştirmeyelim. Aile bilgisinde yakınlık bağını doğru okumak önemlidir."},{"title":"Oğullar ve erken kayıplar","kind":"family","labels":["Kāsım","Abdullah","Küçük yaşta vefat"],"narration":"Yaygın siyer anlatımında Hadîce vâlidemizden dünyaya gelen oğullar Kāsım ve Abdullah adıyla anılır; ikisi de küçük yaşta vefat etmiştir. Bu kayıpları incelikle öğreniriz, öğrencilerin kendi aile kayıplarını anlatmasını istemeyiz. Kāsım adı aile hikâyesinde bir evlat bağıdır; adların yalnız ezberlenecek bir liste olmadığını hatırlatır. Farklı kaynaklarda adlandırma ayrıntıları bulunduğunda öğretmen bunları ayrıca açıklayabilir."},{"title":"İbrâhim farklı dönemdedir","kind":"timeline","labels":["Mekke dönemi","Medine dönemi","Mâriye vâlidemiz","İbrâhim"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) İbrâhim adlı oğlu, daha sonraki Medine döneminde Mâriye vâlidemizden dünyaya geldi. Bu nedenle bütün çocuk adlarını aynı anne ve aynı dönem altında toplamak doğru olmaz. Şemaya zaman bilgisi ekleyelim: Mekke'de ele aldığımız aile hayatı ile Medine'deki bu doğum farklı dönemlerdedir. Bir kartın doğru yeri, hem aile bağına hem de zamana dikkat edilince bulunur."},{"title":"Adı değil, ilişkiyi de oku","kind":"book","labels":["Ad","Aile bağı","Dönem","Kaynak"],"narration":"Daha önce bakım sağlayan Hazret-i Fâtıma bint Esed'i öğrenmiştik. Bu dersteki kız evlat Hazret-i Fâtıma ile aynı kişi değildir. Benzer adları ayırmak için aile bağına ve tam ada bakarız. Şemada bilmediğimiz alanı tahminle doldurmak yerine kaynak kontrolü yapabiliriz. Bu yöntem yalnız siyer için değil, herhangi bir hayat hikâyesini doğru okumak için de yararlıdır."}],"game":{"kind":"classify","title":"Aile kartlarını doğru kuşağa yerleştir","prompt":"Bu altı kişinin derslerdeki bağlarını kız evlatlar ve diğer aile/bakım bağları olarak ayır.","groups":["Kız evlat","Diğer aile veya bakım bağı"],"items":[{"text":"Hazret-i Zeyneb","group":0,"explanation":"Kız evlatlar arasında yer alır."},{"text":"Hazret-i Rukıyye","group":0,"explanation":"Hadîce vâlidemizin kızlarından biridir."},{"text":"Hazret-i Ümmü Külsûm","group":0,"explanation":"Kız evlat kuşağında gösterilir."},{"text":"Hazret-i Fâtıma","group":0,"explanation":"Bu kart kız evlat Hazret-i Fâtıma'yı gösterir."},{"text":"Hazret-i Halîme","group":1,"explanation":"Çocuklukta sütanne bağıyla öğrenildi; kız evlat değildir."},{"text":"Âmine","group":1,"explanation":"Anne bağıyla aile şemasının önceki kuşağında yer alır."}]},"decision":{"question":"Bir öğrenci İbrâhim'i, Hadîce vâlidemizin Mekke'deki çocuklarıyla aynı anne ve dönem altında yazıyor. Nasıl düzeltmeli?","options":["İbrâhim adını bütün şemadan silmeli.","Mâriye vâlidemiz ve Medine dönemi bilgisini ayrı göstermeli.","Mekke ve Medine adlarını tek dönem adı gibi kullanmalı."],"answer":1,"explanations":["Adı silmek bilgiyi kaybettirir; gereken doğru bağla yerleştirmektir.","Doğru: hem anne bağı hem dönem doğru gösterilir.","İki şehir ve hayat dönemi birbirinden ayrılmalıdır."]},"quiz":[{"question":"Hangi dört isim kız evlatları doğru gösterir?","options":["Âmine, Hazret-i Halîme, Hadîce vâlidemiz, Hazret-i Ümmü Eymen","Hazret-i Zeyneb, Hazret-i Rukıyye, Hazret-i Ümmü Külsûm, Hazret-i Fâtıma","Kāsım, Abdullah, İbrâhim, Abdülmuttalib"],"answer":1,"explanation":"Bu dört kız evlat, aynı kuşakta yer alır; diğer seçenekler farklı bağlardaki adları içerir."},{"question":"İbrâhim için doğru eşleştirme hangisidir?","options":["Âmine — çocukluk dönemi","Hadîce vâlidemiz — ilk vahiy öncesi","Mâriye vâlidemiz — Medine dönemi"],"answer":2,"explanation":"İbrâhim, daha sonraki Medine döneminde Mâriye vâlidemizden doğmuştur."},{"question":"İki benzer adı birbirinden ayırmak için neye bakmalıyız?","options":["Tam ada, aile bağına ve döneme","Yalnız ilk sözcüğün yazılışına","Şemadaki kartların rengine"],"answer":0,"explanation":"Tam ad ve ilişkiler, isim benzerliğinin oluşturduğu karışıklığı giderir."}],"teacher":{"misconception":"Tayyib ve Tâhir adlandırmalarını yeni evlat sayısı gibi kesinleştirmeyin; bu derste yaygın Kāsım-Abdullah anlatımını kullanın. İki Hazret-i Fâtıma'yı ayırın.","differentiation":"5–6. sınıf ad ve aile bağı eşlesin; 7–8. sınıf anne ve dönem sütunlarını birlikte denetlesin.","exit":"Bir kız evlat adı söyle; İbrâhim'i doğru anne ve dönemle eşleştir."},"sources":[{"title":"TDV — Hadîce vâlidemiz","url":"https://islamansiklopedisi.org.tr/hatice"},{"title":"TDV — Siyer: hayat ve kronoloji","url":"https://islamansiklopedisi.org.tr/muhammed#1-hayati"}]},{"id":12,"module":2,"title":"Bir anlaşmazlığa ortak çözüm","date":"Yaklaşık 605","objective":"Hacerülesved hakemliğinde kapsayıcı çözümün önemini fark eder.","hook":{"question":"Bir işi tamamlamanın şerefini birkaç grup birden istiyorsa nasıl bir çözüm ararsın?","options":["Yalnız en güçlü gruba görev veririm.","Kararı süresiz erteleyip işi bırakırım.","Tarafların ortak katkısını mümkün kılan çözüm ararım."],"note":"Cevapları sınıf projesi örneğiyle alın; tarihî şahısların rolüne girmelerini istemeyin."},"frames":[{"title":"Onarımda çıkan anlaşmazlık","kind":"city","labels":["Kâbe onarımı","Hacerülesved","Yerine koyma","Anlaşmazlık"],"narration":"Kâbe'nin onarımı sırasında Hacerülesved'in yerine konulması konusunda kabileler arasında anlaşmazlık çıktı. Her taraf bu görevin şerefini üstlenmek istiyordu. Burada ortak amaç ile görev paylaşımını ayıralım: yapı tamamlanacaktı, fakat son aşamadaki sorumluluğun kimde olacağı tartışılıyordu. Bir grubun isteği diğerinin dışlandığı duygusuna dönüşünce çözüm zorlaşabilir. Olayın düğümünü doğru tanımlamak, bulunan çözümü anlamanın ilk adımıdır."},{"title":"Güvenilen hakem","kind":"agreement","labels":["Güvenilirlik","Hakemlik","Taraflar","Çözüm"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) hakem olarak kabul edildi. Önceki derste öğrendiğimiz el-Emîn unvanıyla bu olay arasında bir bağ kurabiliriz: insanlar anlaşmazlıkta güven duydukları birinin çözümünü kabul etmeye daha açıktır. Hakem olmak, taraflardan birini peşinen kayırmak değildir. Olayı okurken yalnız kimin seçildiğini değil, önerilen çözümün taraflara nasıl yer verdiğini de inceleyeceğiz. Güven, ortak karar için önemli bir zemindir."},{"title":"Bir örtü, ortak katkı","kind":"community","labels":["Örtü","Ortak taşıma","Tarafların katkısı","Yerine yerleştirme"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) Hacerülesved'in bir örtü üzerine konularak birlikte taşınmasını sağladı. Böylece taraflar göreve ortak katkıda bulundu. Ardından Peygamber Efendimiz (sallallahü aleyhi ve sellem) taşı yerine yerleştirdi. Bu iki aşamayı ayıralım: birlikte taşıma ve son yerleştirme aynı hareket değildir. Çözümün değeri, anlaşmazlığı büyütmeden ortak amaca ulaşması ve katkıyı tek bir grubun elinde bırakmamasıdır."},{"title":"Ortak amaç, belirli roller","kind":"values","labels":["Amacı belirle","Katkıyı paylaş","Rolleri netleştir","İşi tamamla"],"narration":"Bu olaydan sınıf çalışmasına taşınabilecek düşünce, herkesin katkısına yer veren bir görev paylaşımıdır. Bir afiş hazırlarken araştırma, çizim ve anlatım farklı kişilerce yapılabilir. Herkesin aynı işi aynı anda yapması gerekmez; katkıların ortak amaca bağlanması önemlidir. Tarihî çözümün aynısını her durumda kopyalamak yerine, hangi ilkenin işe yaradığını anlamak gerekir. Adil paylaşım ve açık roller, anlaşmazlığı azaltmaya yardım eder."}],"game":{"kind":"sequence","title":"Çözümün dört aşaması","prompt":"Hacerülesved hakemliğinin akışını sırala.","items":[{"text":"Yerine koyma görevi üzerinde anlaşmazlık çıkması","explanation":"Önce çözülmesi gereken sorun ortaya çıkar."},{"text":"Güvenilen hakemin kabul edilmesi","explanation":"Taraflar çözüm için ortak bir başvuru noktası kabul eder."},{"text":"Taşın bir örtü üzerinde birlikte taşınması","explanation":"Taraflara ortak katkı imkânı verilir."},{"text":"Taşın yerine yerleştirilmesi","explanation":"Ortak amaç tamamlanır; taşıma ile son yerleştirme ayrılır."}]},"decision":{"question":"Üç grup sınıf panosunun tamamını yalnız kendisi yapmak istiyor. Bu dersteki ilkeden yararlanan çözüm hangisidir?","options":["Araştırma, görsel ve sunum görevlerini ortak hedef için paylaşmak","Bir grubun bütün emeğini görünmez bırakmak","Panoyu bitirmek yerine diğer grupları suçlamak"],"answer":0,"explanations":["Doğru: farklı katkılar görünür biçimde ortak amaca bağlanır.","Katkıyı görünmez bırakmak adil paylaşımı zedeler.","Suçlama, görev üzerindeki anlaşmazlığı çözmez."]},"quiz":[{"question":"Anlaşmazlık esas olarak ne üzerindeydi?","options":["Kâbe'nin hangi şehirde olduğu","Hacerülesved'i yerine koyma görevini kimin üstleneceği","Kervanların hangi mevsimde yola çıkacağı"],"answer":1,"explanation":"Taraflar görevin şerefini üstlenmek istiyordu."},{"question":"Ortak örtüyle taşımanın önemli sonucu neydi?","options":["Bütün sorumlulukların belirsiz kalması","Yapı onarımının bırakılması","Tarafların aynı amaca katkı sunabilmesi"],"answer":2,"explanation":"Çözüm, katkıyı yalnız bir tarafa vermeden ortak işi ilerletti."},{"question":"Olay hangi bilgiyi destekler?","options":["Güvenilirlik, anlaşmazlık çözümünde kabul görmeye katkı sağlayabilir.","Hakemlik her zaman en güçlü tarafı seçmektir.","Ortak işte herkesin aynı görevi yapması zorunludur."],"answer":0,"explanation":"Güven ve tarafları gözeten çözüm birlikte önem taşır."}],"teacher":{"misconception":"Hacerülesved'in kendisini veya taşıyan kişileri oyun nesnesi yapmayın; sıralama soyut olay kartlarıyla yürüsün. Taşıma ve yerine koyma aşamalarını ayırın.","differentiation":"Küçük sınıflar aşamaları sıralasın; büyük sınıflar ortak katkı ile aynı işi yapmanın neden farklı olduğunu açıklasın.","exit":"Anlaşmazlığı ve çözümün taraflara sağladığı ortak katkıyı iki cümlede özetle."},"sources":[{"title":"TDV — Hacerülesved","url":"https://islamansiklopedisi.org.tr/hacerulesved"}]},{"id":13,"module":3,"title":"Hira'da tefekkür","date":"İlk vahiyden önce","objective":"Hira'yı ilk vahye uzanan süreçte doğru konumlandırır.","hook":{"question":"Bir konuyu dikkatle düşünmek için hangi ortam sana yardımcı olur?","options":["Dikkati toparlayabileceğim sakin bir ortam","Sürekli birbirini kesen birçok uyaran","Soruyu hiç incelemeden cevabı seçmek"],"note":"Öğrencinin öğrenme alışkanlığını sorun; vahyi sıradan düşünme sonucu gibi göstermemeye dikkat edin."},"frames":[{"title":"Hira'yı haritada bulalım","kind":"map","labels":["Mekke","Hira","Nur Dağı","Mağara"],"narration":"Hira, Mekke yakınında, Nur Dağı adıyla da bilinen dağdaki mağarayla tanınır. Bu yer bir şehir değildir; Mekke çevresindeki belirli bir mekândır. Haritada şehir noktası ile mağara işaretini ayrı okuyalım. Mekân türlerini ayırmak, ileride Hira ile hicret yolculuğunda anılacak başka mağaraları karıştırmamızı önler. Bir ismin yalnız ezberini değil, nerede ve ne tür bir yer olduğunu öğreniyoruz."},{"title":"İbadet ve tefekkür zamanı","kind":"journey","labels":["Hira","Yalnız kalma","İbadet","Tefekkür"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) ilk vahiyden önce zaman zaman Hira'da yalnız kalarak ibadet ve tefekkür ediyordu. Tefekkür, dikkatle düşünmek anlamını taşır. Bu dönemi ilk vahyin kendisiyle aynı olay saymayalım; zaman çizgisinde önce ibadet ve tefekkür, ardından ilk vahiy yer alır. Mekân aynı olsa da yaşanan olayların niteliği farklıdır. Bu ayrım, sonraki dersi daha doğru anlamamızı sağlayacak."},{"title":"Şehir ve mağara arasındaki bağ","kind":"route","labels":["Mekke'deki ev","Hazırlık","Hira","Geri dönüş"],"narration":"Hira'daki kalışlar Mekke'deki hayatla bağın bütünüyle kesilmesi değildi. Azık hazırlanıyor, ihtiyaçlar karşılanıyor ve şehre dönülüyordu. Bu bilgi, yalnız kalmayı insanlara karşı bütün sorumluluklardan vazgeçmek gibi düşünmememize yardım eder. Haritada ev ile Hira arasında bir bağ gösterelim. Yalnızca bir mağara görüntüsüne bakmak yerine, mekânın hayatın diğer alanlarıyla ilişkisini de fark edelim."},{"title":"Tefekkür ile vahyi ayıralım","kind":"book","labels":["İnsan düşünür","Kaynak araştırır","Vahiy","Allahü teâlâdan bildirim"],"narration":"Düşünmek ve öğrenmek insanın yaptığı faaliyetlerdir. Vahiy ise Allahü teâlânın peygamberine bildirmesidir; sıradan düşünmenin başka adı değildir. Bu derste sessizce bir öğrenme sorusu üzerinde çalışmamız Hira'daki tarihî olayı canlandırmak anlamına gelmez. Kendi çalışmamız için dikkat, soru ve kaynak seçimi yaparız. Kavramları doğru ayırmak, benzetmelerin sınırını bilmemizi ve ilk vahyi yerli yerinde öğrenmemizi sağlar."}],"game":{"kind":"match","title":"Mekân ve kavram kartları","prompt":"Her kartı bu dersteki doğru açıklamasıyla eşleştir.","pairs":[{"left":"Mekke","right":"Hira'nın yakınında bulunduğu şehir","explanation":"Şehir ile çevresindeki mağara aynı tür mekân değildir."},{"left":"Hira","right":"İbadet ve tefekkürle anılan mağara","explanation":"İlk vahiy de burada gelecektir."},{"left":"Tefekkür","right":"Dikkatle düşünmek","explanation":"İnsanın düşünme faaliyeti olarak öğrenilir."},{"left":"Vahiy","right":"Allahü teâlânın peygamberine bildirmesi","explanation":"Vahyi sıradan düşünme veya araştırmayla aynı saymayız."}]},"decision":{"question":"Bir öğrenci 'Uzun düşününce ortaya çıkan her fikir vahiydir' diyor. Hangi açıklama doğru?","options":["Düşünceyle vahiy aynı kavramdır.","Tefekkür insanın düşünmesidir; vahiy Allahü teâlâdan peygambere bildirimdir.","Bir fikir sessiz bir yerde bulunmuşsa mutlaka vahiydir."],"answer":1,"explanations":["Kavramların kaynağı ve niteliği farklıdır.","Doğru: düşünme faaliyeti ile ilâhî bildirim ayrılıyor.","Sessiz ortam bir insan düşüncesini vahiy yapmaz."]},"quiz":[{"question":"Hira için doğru yer tanımı hangisidir?","options":["Mekke yakınındaki dağda bulunan mağara","Medine'nin diğer adı","Hicretin varış şehri"],"answer":0,"explanation":"Hira bir şehir değil, Mekke çevresindeki mağarayla tanınan mekândır."},{"question":"Bu dersin zaman sırası hangisidir?","options":["Veda haccı, sonra Hira'da tefekkür","Hicret, sonra çocukluk","Hira'da ibadet ve tefekkür, ardından ilk vahiy"],"answer":2,"explanation":"İlk vahye uzanan süreçte önceki kalışları ve vahiy olayını ayırırız."},{"question":"Hira'dan şehre dönüşler hangi yorumu düzeltir?","options":["Hira'nın Mekke yakınında bulunduğunu","Yalnız kalmanın bütün hayat bağlarını kesmek olduğunu","İnsanların yolculukta ihtiyaçları olduğunu"],"answer":1,"explanation":"Kalışlar sırasında ihtiyaç ve aile hayatıyla bağ sürüyordu."}],"teacher":{"misconception":"Vahyi yoğun düşünmenin ürünü gibi sunmayın. Hira'yı Sevr ile karıştırmayın; mağara temsili bir mekân çizimi olmalı, tarihî şahıs tasviri kullanılmamalı.","differentiation":"5–6. sınıf şehir-mağara ayrımını yapsın; 7–8. sınıf tefekkür ile vahiy kavramlarını gerekçesiyle ayırsın.","exit":"Hira'nın yerini söyle ve tefekkür ile vahiy arasındaki temel farkı açıkla."},"sources":[{"title":"TDV — Hira","url":"https://islamansiklopedisi.org.tr/hira"}]},{"id":14,"module":3,"title":"İlk vahiy: öğrenmeye çağrı","date":"610, ramazan ayı","objective":"İlk vahyin temel bilgilerini ve öğrenmeyle ilişkisini açıklar.","hook":{"question":"İlk vahyi öğrenirken hangi dört bilgiyi birlikte takip etmeliyiz?","options":["Yalnız mağaranın yüksekliğini","Yer, zaman, getiren melek ve gelen âyet-i kerîmeleri","Yalnız Mekke'nin ticaret yollarını"],"note":"Önceki dersteki Hira kartını açın; yeni bilgileri dört başlık altında toplayın."},"frames":[{"title":"610 yılında Hira","kind":"timeline","labels":["610","Ramazan","Hira","İlk vahiy"],"narration":"İlk vahiy, 610 yılında ramazan ayında Hira'da geldi. Peygamber Efendimiz (sallallahü aleyhi ve sellem) yaklaşık kırk yaşındaydı. Zaman çizgimizde artık peygamberlik vazifesinin başlangıcına ulaşıyoruz. Önceki derslerde öğrenilen çocukluk, gençlik, aile hayatı ve Hira'daki tefekkür bu başlangıçtan önce yer alır. Bir hayatı dönemlere ayırmak olayları koparmak için değil, hangi bilginin hangi zamana ait olduğunu doğru görmek içindir."},{"title":"Vahyi getiren melek","kind":"book","labels":["Allahü teâlâ","Vahiy","Cebrâil aleyhisselâm","Peygamberlik"],"narration":"İlk vahyi Cebrâil aleyhisselâm getirdi. Vahiy, Allahü teâlâdan gelen bildiridir; Peygamber Efendimiz (sallallahü aleyhi ve sellem) peygamberlik vazifesine bu bildirimle başladı. Önceki derste düşünme ile vahyin aynı olmadığını öğrenmiştik. Burada da kaynak, getiren melek ve bildirimin ulaştığı peygamber birbirinden ayrı başlıklardır. Şemayı bir resimlendirme olarak değil, kavramlar arasındaki ilişkiyi gösteren yazılı bir düzen olarak okuyalım."},{"title":"Alak sûresinin başlangıcı","kind":"book","labels":["Alak sûresi","İlk beş âyet-i kerîme","Okuma","Öğrenme"],"narration":"İlk gelen bölüm, Kur'ân-ı Kerîm'deki Alak sûresinin ilk beş âyet-i kerîmesidir. Bu başlangıçta okuma, yaratılış ve öğretme üzerinde durulur. Âyet-i kerîmelerin metnini ve anlamını güvenilir bir Kur'ân-ı Kerîm kaynağından öğretmen rehberliğinde inceleyebiliriz. Kendi hazırladığımız özetin âyet-i kerîmenin birebir metni olmadığını bilmeliyiz. Bu ders, öğrenmenin değerini ve bilginin kaynağına dikkat etmeyi birlikte düşünmeye çağırır."},{"title":"Yeni bir vazifenin başlangıcı","kind":"journey","labels":["İlk vahiy","Peygamberlik vazifesi","Sonraki davet","Sorumluluk"],"narration":"İlk vahiy, siyer çizgisinde yeni bir dönemin başlangıcıdır. Sonraki derslerde bu bildirimin ardından yaşanan destekleri ve davetin nasıl geliştiğini öğreneceğiz. İlk vahiy ile bütün sonraki olayları tek bir güne sıkıştırmayalım. Bugün için dört ana bilgiyi ilişkilendirmek yeterlidir: Hira, 610 ramazanı, Cebrâil aleyhisselâm ve Alak sûresinin başlangıcı. Böyle bir bilgi ağı, yalnız tarih ezberinden daha sağlam bir anlayış kurar."}],"game":{"kind":"match","title":"İlk vahyin bilgi ağı","prompt":"Dört ana bilgiyi uygun sorusuyla eşleştir.","pairs":[{"left":"Hira","right":"Nerede?","explanation":"Önceki derste konumunu tanıdığımız mağaradır."},{"left":"610 yılı ramazan ayı","right":"Ne zaman?","explanation":"İlk vahyin zamanını belirtir."},{"left":"Cebrâil aleyhisselâm","right":"Vahyi getiren melek kim?","explanation":"Vahiy Allahü teâlâdan, getiren melek Cebrâil aleyhisselâmdır."},{"left":"Alak sûresinin ilk beş âyet-i kerîmesi","right":"İlk gelen bölüm hangisi?","explanation":"Sûre adı ile ilk gelen bölümün sınırı birlikte öğrenilir."}]},"decision":{"question":"Bir öğrenci kendi yazdığı öğrenme sloganını 'ilk âyet-i kerîmenin aynısı' diye sunuyor. Ne yapılmalı?","options":["Anlamı yakınsa kaynak kontrolüne gerek yoktur.","Sloganı âyet-i kerîme olarak yayımlamaya devam etmeli.","Asıl metni güvenilir kaynaktan kontrol edip kendi cümlesini yorum olarak ayırmalı."],"answer":2,"explanations":["Yakın bir anlam, birebir metin olduğu anlamına gelmez.","Kendi cümlesini âyet-i kerîme diye sunmak yanlış atıftır.","Doğru: metin, anlam açıklaması ve kişisel yorum ayrı tutulur."]},"quiz":[{"question":"İlk vahiy için hangi eşleştirme doğrudur?","options":["Hira — 610 ramazanı","Medine — 622","Tâif — 630"],"answer":0,"explanation":"İlk vahiy Hira'da 610 yılının ramazan ayında geldi."},{"question":"İlk gelen bölüm hangisidir?","options":["Kureyş sûresinin tamamı","Alak sûresinin ilk beş âyet-i kerîmesi","Fîl sûresinin ilk bölümü"],"answer":1,"explanation":"İlk vahiy Alak sûresinin başlangıcıyla ilişkilidir."},{"question":"Bu olay hayat çizgisinde hangi başlangıcı gösterir?","options":["Çocukluk bakımının başlamasını","Hicretin tamamlanmasını","Peygamberlik vazifesinin başlamasını"],"answer":2,"explanation":"İlk vahiy peygamberlik döneminin başlangıcıdır; hicret daha sonra gerçekleşir."}],"teacher":{"misconception":"Kesin ramazan günü üzerine rivayetleri tek görüş gibi vermeyin. Cebrâil aleyhisselâm veya vahiy sahnesi tasvir edilmemeli; yazı, mekân ve zaman şeması kullanılmalı.","differentiation":"Küçük sınıflar dört bilgi-soru eşleştirmesi yapsın; büyük sınıflar kaynak, melek ve ilk gelen metin başlıklarını ayırsın.","exit":"İlk vahyi yer, zaman, getiren melek ve gelen bölüm başlıklarıyla dört parçalı anlat."},"sources":[{"title":"TDV — Hira","url":"https://islamansiklopedisi.org.tr/hira"}]},{"id":15,"module":3,"title":"Hadîce vâlidemizin desteği","date":"610","objective":"İlk vahiy sonrasındaki desteği ve dikkatle dinlemenin önemini anlar.","hook":{"question":"Kaygılı birini dinlerken hangi davranış destek olur?","options":["Cümlesi bitmeden kendi yorumunu söylemek","Dikkatle dinleyip ihtiyacını anlamaya çalışmak","Korkusunu başkalarına anlatarak yaymak"],"note":"Destek örneklerini bugünkü sınıf hayatından alın; tarihî konuşmayı öğrencilerle canlandırmayın."},"frames":[{"title":"İlk vahiyden sonra eve dönüş","kind":"route","labels":["Hira","İlk vahiy","Eve dönüş","Hadîce vâlidemiz"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) ilk vahiyden sonra eve dönerek yaşananları Hadîce vâlidemize anlattı. Önceki dersin sonuyla bu dersin başlangıcı arasında doğrudan bir bağ vardır. Hira'daki ilk vahyi, ardından gelen eve dönüş ve paylaşım izler. Olayları bu sırayla okumak Hadîce vâlidemizin desteğinin hangi durumda ortaya çıktığını gösterir. Zor bir deneyimin ardından güven duyulan birine anlatabilmek önemlidir."},{"title":"Güzel ahlâkı hatırlatan destek","kind":"values","labels":["Doğruluk","Akrabayı gözetmek","Yardıma koşmak","Misafiri ağırlamak"],"narration":"Hadîce vâlidemiz dikkatle dinledi ve güven veren bir tutum gösterdi. Destek verirken doğruluk, akrabayı gözetme, ihtiyaç sahibine yardım ve misafiri ağırlama gibi güzel davranışları hatırlattı. Burada boş bir teselli yerine daha önce bilinen davranışlara dayanan güven görüyoruz. Bu anlatımı birebir alıntı diye sunmadan anlamıyla öğreniyoruz. Bir kişinin geçmişteki iyiliklerini fark etmek, desteğin somutlaşmasına yardım edebilir."},{"title":"Varaka ile görüşme","kind":"community","labels":["Hadîce vâlidemiz","Varaka b. Nevfel","Dinlemek","Bilgiye başvurmak"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) ve Hadîce vâlidemiz, Varaka b. Nevfel ile görüştü. Varaka önceki kutsal kitaplar hakkında bilgisi olan biriydi; anlatılanları bu bilgi çerçevesinde değerlendirdi. Bu görüşmeyi vahyin kaynağıyla karıştırmayalım. İlk vahiy daha önce Hira'da gelmişti. Görüşme, yaşananların anlatıldığı sonraki aşamadır. Zaman sırası, bir olayın değerlendirilmesiyle o olayın kaynağını birbirinden ayırmamıza yardımcı olur."},{"title":"İman ve devam eden yakınlık","kind":"agreement","labels":["İlk iman","Güven","Dikkatli dinleme","Destek"],"narration":"Hadîce vâlidemiz ilk iman eden kişi olarak İslâm'ın başlangıcında özel bir yere sahiptir. Desteği yalnız bir konuşmayla sınırlı kalmadı; sonraki zorluklarda da sürdü. Biz bu bölümde dinlemek, duyguyu küçümsememek ve gerektiğinde güvenilir bilgiye başvurmak üzerinde duruyoruz. Bir arkadaşımıza destek verirken onun adına her şeyi bildiğimizi varsaymadan yanında olabiliriz. Süreklilik gösteren özen, güven ilişkisini güçlendirir."}],"game":{"kind":"sequence","title":"Destek zincirini sırala","prompt":"İlk vahiyden sonra anlatılan aşamaları kronolojik sıraya koy.","items":[{"text":"Hira'da ilk vahyin gelmesi","explanation":"Önceki dersin temel olayıdır."},{"text":"Eve dönerek Hadîce vâlidemize anlatma","explanation":"Yaşananlar güven duyulan yakınla paylaşılır."},{"text":"Hadîce vâlidemizin dinleyip destek vermesi","explanation":"Güzel ahlâk ve yardım davranışları hatırlatılır."},{"text":"Varaka b. Nevfel ile görüşme","explanation":"Bu görüşme ilk vahiyden sonraki değerlendirme aşamasıdır."}]},"decision":{"question":"Kaygılı arkadaşın bir sorun anlatıyor; ayrıntıları henüz bilmiyorsun. En uygun ilk cevap hangisi?","options":["Seni dinliyorum; istersen birlikte öğretmenden destek isteyebiliriz.","Buna üzülmen gereksiz, hemen unut.","Ne olduğunu biliyorum; anlatmana gerek yok."],"answer":0,"explanations":["Doğru: dinleme, seçim hakkı ve güvenilir yardım birlikte sunuluyor.","Duyguyu küçümsemek kişinin anlaşılmadığını hissettirebilir.","Dinlemeden bildiğini varsaymak gerçek ihtiyacı gözden kaçırır."]},"quiz":[{"question":"Hadîce vâlidemizin desteğinde hangi özellik öne çıkar?","options":["Yaşananları dinlemeden geçiştirmek","Dinlemek ve bilinen güzel ahlâkı hatırlatarak güven vermek","Yalnız yolculuğun uzunluğunu hesaplamak"],"answer":1,"explanation":"Destek, dikkatli dinlemeye ve somut güzel davranışların bilinmesine dayanıyordu."},{"question":"Varaka ile görüşme ilk vahye göre ne zamandır?","options":["İlk vahiyden önce ve onun yerine","Çocuklukta Yesrib ziyareti sırasında","İlk vahiyden sonra"],"answer":2,"explanation":"Görüşme, Hira'daki vahiyden sonraki aşamadır; vahyin kaynağı değildir."},{"question":"Hadîce vâlidemizin desteği hangi ifadeyle en doğru açıklanır?","options":["İlk imanla başlayan ve sonraki zorluklarda da süren bir destektir.","Yalnız ticaret dönemine ait olup ilk vahiyden sonra bitmiştir.","Ancak hicretten sonra başlayan bir dayanışmadır."],"answer":0,"explanation":"İlk iman eden kişi olarak desteği, İslâm'ın başlangıcında ve sonraki güçlüklerde sürmüştür."}],"teacher":{"misconception":"Varaka'yı vahyin kaynağı gibi sunmayın. Hadîce vâlidemizin sözlerini birebir alıntı kullanmadan anlamıyla aktardığınızı belirtin; uydurma diyalog eklemeyin.","differentiation":"Küçük sınıflar olay sırasını kursun; büyük sınıflar güven veren somut destek ile dinlemeden teselli etme arasındaki farkı açıklasın.","exit":"Hadîce vâlidemizin iki destek davranışını ve Varaka görüşmesinin zamanını söyle."},"sources":[{"title":"TDV — Hadîce vâlidemiz","url":"https://islamansiklopedisi.org.tr/hatice"}]},{"id":16,"module":3,"title":"İlk Müslümanlar","date":"610'dan itibaren","objective":"İslâm'ı ilk kabul edenlerden bazılarını tanır.","hook":{"question":"Bir topluluğu tanımak için yalnızca adları bilmek yeterli mi?","options":["Adlar yeterlidir","Aralarındaki bağları da öğrenmeliyiz","Sadece yaşlarını bilmeliyiz"],"note":"Bir doğru cevap aramadan ad, yakınlık ve toplumsal çevre ayrımını görünür kılın."},"frames":[{"title":"İlk kabul ve ilk destek","kind":"home","labels":["Hadîce vâlidemiz","İlk iman","Aile desteği"],"narration":"İlk vahiyden sonra İslâm'ı ilk kabul eden kişi Hadîce vâlidemiz oldu. Peygamber Efendimiz (sallallahü aleyhi ve sellem) ile aynı yuvayı paylaşan Hadîce vâlidemiz, doğruluğa ve güzel ahlâka yakından şahit olmuştu. Bu başlangıcı yalnız bir isim olarak ezberlemeyelim: İman etmek, inanılan mesajı kabul etmek; destek olmak ise zor zamanda yanında durmaktır. Bu iki davranış ilk günlerde birlikte görüldü."},{"title":"Aynı ev, farklı hayatlar","kind":"family","labels":["Hazret-i Ali","Hazret-i Zeyd b. Hârise","Yakın çevre"],"narration":"Hazret-i Ali ile Hazret-i Zeyd b. Hârise de ilk Müslümanlar arasındaydı. Hazret-i Ali, Peygamber Efendimiz (sallallahü aleyhi ve sellem) ile amca çocuğuydu ve o sırada henüz gençti. Hazret-i Zeyd b. Hârise ise aile çevresinde büyüyen, özgürlüğüne kavuşmuş bir kimseydi. Aynı yakın çevrede bulunmaları, hayat hikâyelerinin ve yaşlarının aynı olduğu anlamına gelmez; ilişki haritasında her bağı ayrı okuyalım."},{"title":"Dostluk yoluyla tanışma","kind":"community","labels":["Hazret-i Ebû Bekr","Güven ilişkisi","Yeni tanışmalar"],"narration":"Hazret-i Ebû Bekr ilk Müslümanlardan ve Peygamber Efendimiz (sallallahü aleyhi ve sellem) ile yakın dostluk bağı bulunan kişilerden biriydi. Tanıdığı insanlara da İslâm'ı anlattı. Böylece mesaj yalnız bir evin içinde kalmadı; güvene dayanan ilişkilerle yeni insanlara ulaştı. Bir haberin kimden duyulduğu ile doğru olup olmadığı farklı sorulardır; burada dostluk, dinlemeye ve tanışmaya imkân sağlayan bir bağdır."},{"title":"Bir listeyi anlamlı okumak","kind":"values","labels":["Farklı yaşlar","Farklı geçmişler","Ortak iman"],"narration":"İlk Müslümanlar arasında kadınlar, gençler, yetişkinler ve farklı toplumsal geçmişlerden insanlar vardı. İsimleri aynı sıraya dizmek yerine, bildiğimiz yakınlıkları ve ortak noktaları karşılaştırabiliriz. Her kişi için kesin bir kabul sırası vermek kaynak farklılıklarını gözden kaçırabilir. Bu derste güvenilir biçimde bildiğimiz ortak noktaya odaklanıyoruz: Farklı hayatlar, İslâm'a iman ve destek etrafında buluştu."}],"game":{"kind":"match","title":"İsim ve bilgi bağları","prompt":"Her ismi, bu derste öğrendiğimiz ayırt edici bilgiyle eşleştir.","pairs":[{"left":"Hadîce vâlidemiz","right":"İslâm'ı ilk kabul eden kişi","explanation":"İlk iman ve aile içindeki destek birlikte hatırlanır."},{"left":"Hazret-i Ali","right":"İlk Müslümanlar arasındaki genç akraba","explanation":"Yaşının genç olması erken dönemdeki katkısını azaltmaz."},{"left":"Hazret-i Zeyd b. Hârise","right":"Yakın aile çevresindeki ilk Müslümanlardan","explanation":"Aynı çevredeki kişiler farklı hayat geçmişlerine sahipti."},{"left":"Hazret-i Ebû Bekr","right":"Dost çevresine de İslâm'ı anlatan ilk Müslümanlardan","explanation":"Güven ilişkileri yeni insanların mesajla tanışmasına yardımcı oldu."}]},"decision":{"question":"Sınıf panosuna 'İlk Müslümanların hepsi yetişkin erkeklerdi' yazılmış. Hangi düzeltme gerekçelidir?","options":["Yalnız yetişkin kelimesini silelim","Hadîce vâlidemiz ve Hazret-i Ali örnekleriyle ifadeyi düzeltelim","İlk Müslümanlar yerine sonraki Müslümanlar yazalım"],"answer":1,"explanations":["Bu değişiklik kadınların da ilk Müslümanlar arasında bulunduğunu açıklamaz.","İki örnek, hem yaş hem kadın-erkek bakımından yapılan genellemeyi düzeltir.","Sorun konu başlığında değil, bütün topluluğu aynı özellikte kabul etmektedir."]},"quiz":[{"question":"Hadîce vâlidemiz için hangi bilgi bu dersin temel dayanağıdır?","options":["İlk Akabe Biatı'na katılması","İslâm'ı ilk kabul eden kişi olması","Habeşistan hükümdarı olması"],"answer":1,"explanation":"Hadîce vâlidemiz ilk iman eden kişidir; diğer seçenekler farklı kişi ve dönemleri karıştırır."},{"question":"İlk Müslümanlar arasındaki farklı yaşlar bize ne gösterir?","options":["İlk davetin yalnız bir yaş grubuyla sınırlı olmadığını","Bütün kabul tarihlerinin aynı gün olduğunu","Yakın çevrenin davette rol oynamadığını"],"answer":0,"explanation":"Yaş çeşitliliğinden kabul günlerinin aynı olduğu sonucu çıkmaz."},{"question":"Bir kaynak ilk kabul sırasını farklı veriyorsa nasıl davranmalıyız?","options":["Bütün isimleri listeden çıkarmalıyız","Sıralamayı görmezden gelip kesin diyerek aktarmalıyız","Ortak bilgileri ayırıp sıralama farklılığını belirtmeliyiz"],"answer":2,"explanation":"İlk Müslümanlardan olmak ile herkesin kesin kabul sırasını bilmek aynı iddia değildir."}],"teacher":{"misconception":"İlk Müslümanları tek yaş, cinsiyet veya toplumsal çevreye indirgemeyi düzeltin; kişiler arasında üstünlük yarışı yaptırmayın.","differentiation":"5–6. sınıfta dört isim-bilgi eşleştirmesi; 7–8. sınıfta bir genellemeyi iki kanıtla düzeltme isteyin.","exit":"İlk Müslümanların iki farklı özelliğini ve bir ortak noktasını söyle."},"sources":[{"title":"TDV — İlk Müslümanlar","url":"https://islamansiklopedisi.org.tr/sabikun"},{"title":"TDV — Hazret-i Zeyd b. Hârise","url":"https://islamansiklopedisi.org.tr/zeyd-b-harise"},{"title":"TDV — Hazret-i Ebû Bekr","url":"https://islamansiklopedisi.org.tr/ebu-bekir"}]},{"id":17,"module":3,"title":"Dârülerkam: birlikte öğrenmek","date":"Mekke'de ilk davet yılları","objective":"Dârülerkam'ın eğitim ve buluşma işlevini tanır.","hook":{"question":"Bir öğrenme yerini değerli yapan en önemli şey sence nedir?","options":["Binanın büyüklüğü","İçeride yapılan öğrenme ve paylaşma","Yalnızca bulunduğu sokak"],"note":"Öğrencinin fiziksel mekân ile mekânın işlevini ayırmasını sağlayın."},"frames":[{"title":"Mekke'de bir ev","kind":"city","labels":["Mekke","Safâ çevresi","Dârülerkam"],"narration":"Dârülerkam, Mekke'de Hazret-i Erkam b. Ebü'l-Erkam'a ait evin adıdır. İlk Müslümanların bir araya geldiği bu ev, Safâ tepesi yakınındaydı. Peygamber Efendimiz (sallallahü aleyhi ve sellem) burada insanlarla buluşuyor ve İslâm'ı öğretiyordu. Haritada şehri, yakın çevreyi ve evi farklı ölçeklerde düşünelim: Mekke bir şehir, Safâ bir mevki, Dârülerkam ise belirli bir öğrenme ve buluşma mekânıdır."},{"title":"İçeride neler öğreniliyordu?","kind":"book","labels":["Kur'ân-ı Kerîm","İbadet","Soru ve öğrenme"],"narration":"Dârülerkam'da Kur'ân-ı Kerîm okunuyor, dinî bilgiler öğreniliyor ve birlikte ibadet ediliyordu. Peygamber Efendimiz (sallallahü aleyhi ve sellem) mesajı yeni duyan insanlarla da burada görüşüyordu. Bu yüzden ev yalnız daha önce iman edenlerin buluştuğu kapalı bir arkadaş grubu gibi düşünülmemelidir. Öğrenme, soruları dinleme ve yeni insanların İslâm'la tanışması aynı mekânda birbirini tamamlayan işlerdi; işlev kartlarını bu ayrımla okuyalım."},{"title":"Neden güvenli bir buluşma yeri?","kind":"home","labels":["Baskı ortamı","Buluşma","Öğrenmenin sürmesi"],"narration":"Mekke'de Müslümanların karşılaştığı baskılar, rahatça buluşmalarını zorlaştırıyordu. Bir evde düzenli olarak bir araya gelmek, öğrenmenin sürmesine yardımcı oldu. Dârülerkam'ı önemli yapan şey görkemli bir okul binası olması değildi; ihtiyaca uygun bir buluşma imkânı sağlamasıydı. Dönemin bir evini bugünkü sınıfla aynı saymayalım; benzerlik öğrenmede, farklılık tarihî şartlar ve mekânın kullanım biçimindedir."},{"title":"Mekân ile işlevi ayırmak","kind":"community","labels":["Ev sahibi","Öğreten","Öğrenen topluluk"],"narration":"Dârülerkam örneği bize bir mekânın birden fazla işe yarayabileceğini gösterir. Ev sahibi bir alan sunar, öğretim bilgiyi paylaşır, öğrenciler dinleyip öğrenir. Bugün çevrim içi derste de ekranın bulunması tek başına öğrenmeyi sağlamaz. Söz sırasına uymak, anlaşılmayanı sormak ve arkadaşının bilgisini izinsiz paylaşmamak öğrenme ortamını korur; bu son örnekler tarihî olayın kendisi değil, bugüne yönelik uygulamamızdır."}],"game":{"kind":"classify","title":"Yer mi, işlev mi?","prompt":"Kartları 'mekânı tanıtan bilgi' ve 'orada yapılan iş' olarak ayır.","groups":["Mekânı tanıtan bilgi","Öğrenme işlevi"],"items":[{"text":"Mekke'de bulunması","group":0,"explanation":"Bu bilgi nerede sorusuna cevap verir."},{"text":"Safâ çevresinde olması","group":0,"explanation":"Şehir içindeki konumu açıklar."},{"text":"Hazret-i Erkam'ın evi olması","group":0,"explanation":"Mekânın kime ait olduğunu bildirir."},{"text":"Kur'ân-ı Kerîm'in öğretilmesi","group":1,"explanation":"Öğrenme etkinliğini anlatır."},{"text":"Yeni gelenlerle dinî bilgilerin paylaşılması","group":1,"explanation":"Mesajı tanıtma işlevini anlatır."},{"text":"Birlikte ibadet edilmesi","group":1,"explanation":"Mekânın kullanım biçimlerinden biridir."}]},"decision":{"question":"Bir öğrenci 'Dârülerkam bir ev olduğuna göre eğitim yeri sayılamaz' diyor. Hangi bilgi yanılgıyı giderir?","options":["Evin bulunduğu şehrin adını tekrar etmek","Yapının yaşını tahmin etmek","Orada Kur'ân-ı Kerîm ve dinî bilgilerin öğretildiğini açıklamak"],"answer":2,"explanations":["Konum tek başına eğitim işlevini açıklamaz.","Bir yapının yaşı hangi amaçla kullanıldığını göstermez.","Bir mekânın eğitim işlevi, içinde yapılan öğrenme çalışmalarından anlaşılır."]},"quiz":[{"question":"Dârülerkam adı hangi mekânı belirtir?","options":["Medine'deki Mescid-i Nebevî'yi","Mekke'de Hazret-i Erkam'ın evini","Habeşistan'daki hükümdarlık sarayını"],"answer":1,"explanation":"Dârülerkam, ilk Mekke döneminin öğrenme ve buluşma yeridir."},{"question":"Dârülerkam'ın önemini en iyi hangi ikili açıklar?","options":["Güvenli buluşma ve dinî öğrenme","Büyük bina ve uzak yolculuk","Ticaret deposu ve yeni şehir"],"answer":0,"explanation":"Dersin odağı binanın büyüklüğü değil, baskı ortamında öğrenme ve buluşmadır."},{"question":"'Çevrim içi derste söz sırasına uyalım' cümlesi nasıl sınıflanır?","options":["Dârülerkam'da aynen söylenmiş tarihî söz","Evin mimarisi hakkında bilgi","Tarihî örnekten hareketle geliştirdiğimiz güncel uygulama"],"answer":2,"explanation":"Güncel davranış örneğini tarihî kişilere ait bir söz gibi aktarmamalıyız."}],"teacher":{"misconception":"Dârülerkam'ı modern okul binası veya yalnız gizli toplantı mekânı gibi tek işleve indirgemeyin.","differentiation":"5–6. sınıf yer/işlev kartlarını ayırsın; 7–8. sınıf tarihî şartlarla güncel benzerliği sınırlarıyla açıklasın.","exit":"Dârülerkam'ın nerede olduğunu ve iki işlevini söyle."},"sources":[{"title":"TDV — Dârülerkam","url":"https://islamansiklopedisi.org.tr/darulerkam"},{"title":"TDV — Hazret-i Erkam b. Ebü'l-Erkam","url":"https://islamansiklopedisi.org.tr/erkam-b-ebul-erkam"}]},{"id":18,"module":3,"title":"Davet genişliyor","date":"Yaklaşık 613'ten itibaren","objective":"Davetin yakın çevreden daha geniş topluma yönelişini açıklar.","hook":{"question":"Bir mesajın daha çok kişiye ulaşması, herkesin hemen kabul ettiği anlamına gelir mi?","options":["Evet, ulaşmak ve kabul etmek aynıdır","Hayır, dinlemek ile kabul etmek farklıdır","Yalnız kalabalık yerlerde aynıdır"],"note":"Davetin kapsamı ile kabul sonucunu birbirinden ayırın."},"frames":[{"title":"Yakın çevreden başlayan davet","kind":"community","labels":["Aile çevresi","Dostlar","İlk öğrenme"],"narration":"İlk yıllarda İslâm'a davet özellikle yakın çevrede yürütüldü. Aile bağları ve dostluklar, insanların mesajı dinlemesine imkân sağlıyordu. Peygamber Efendimiz (sallallahü aleyhi ve sellem) Allahü teâlânın birliğini, sorumluluğu ve güzel ahlâkı anlatıyordu. Yakın çevre ifadesi, yalnız bir kişinin veya tek bir evin kastedildiği anlamına gelmez; farklı ilişkiler üzerinden yavaş yavaş genişleyen bir tanışma sürecini düşünmemize yardım eder."},{"title":"Daha geniş topluma sesleniş","kind":"city","labels":["Yakınlar","Safâ","Mekke toplumu"],"narration":"Davet daha sonra açık biçimde daha geniş bir çevreye yöneldi. Safâ tepesindeki çağrı bu sürecin bilinen örneklerindendir. Peygamber Efendimiz (sallallahü aleyhi ve sellem) insanları Allahü teâlâya iman etmeye ve sorumluluklarını düşünmeye davet etti. Haritada aynı şehirde kalırken dinleyici çevresinin genişlediğini fark edelim: Buradaki değişim, ilk aşamada bir yerden başka şehre göç etmek değil, çağrının daha çok kişiye ulaştırılmasıdır."},{"title":"Mesaj ve karşılık","kind":"values","labels":["Tevhid","Sorumluluk","Farklı tepkiler"],"narration":"İslâm'a çağrının merkezinde Allahü teâlânın birliği bulunuyordu. İnsanların davranışlarından sorumlu olması ve güzel ahlâk da bu çağrının önemli parçalarıydı. Mesajın duyulması herkesten aynı karşılığın alınmasını sağlamadı; kabul edenler bulunduğu gibi karşı çıkanlar da oldu. Bu nedenle tarih anlatırken 'davet genişledi' cümlesinden 'Mekke'nin tamamı hemen Müslüman oldu' sonucunu çıkaramayız; bu iki ifade aynı bilgiyi vermez."},{"title":"Süreçleri doğru ayırmak","kind":"timeline","labels":["Yakın çevre","Açık davet","Sonraki hicret"],"narration":"Yakın çevrede davet, açık davet ve hicret aynı olayın üç adı değildir. Birincisi çağrının başlangıç çevresini, ikincisi daha geniş topluma yönelişini, üçüncüsü ise daha sonra gerçekleşen yer değiştirmeyi anlatır. Zaman çizgisinde her kavramın yerini ayrı tutalım. Böylece siyer anlatısını yalnız adlardan oluşan bir liste yerine, birbiriyle bağlantılı fakat farklı aşamalar olarak okuyabiliriz; yıllar olayların anlamının yerine geçmez."}],"game":{"kind":"sequence","title":"Davetin genişleyen çevresi","prompt":"Bu derste izlediğimiz gelişim basamaklarını sıraya koy.","items":[{"text":"Yakın çevrenin İslâm'la tanışması","explanation":"Davetin ilk yıllarında aile ve dost çevresi önemliydi."},{"text":"İlk Müslümanların öğrenmeye devam etmesi","explanation":"İman edenler bilgilerini ve ibadetlerini öğreniyordu."},{"text":"Açık çağrının daha geniş topluma yönelmesi","explanation":"Safâ çağrısı, daha geniş çevreye seslenişin örneklerindendir."},{"text":"Farklı kişilerin çağrıya farklı karşılıklar vermesi","explanation":"Duyurulması, herkesin aynı anda kabul etmesi demek değildir."}]},"decision":{"question":"Bir zaman çizgisinde 'Açık davet: Mekke'den Medine'ye göç' yazıyor. Nasıl düzeltirsin?","options":["Açık daveti daha geniş topluma çağrı, göçü hicret olarak ayırırım","Göç yerine yalnız yolculuk yazarım","İki olayı aynı tarihte tutup şehirleri silerim"],"answer":0,"explanations":["Kavramların anlamını ayırmak yanlışlığı kökünden düzeltir.","Sözcüğü değiştirmek açık davetin gerçek anlamını açıklamaz.","Şehirleri silmek, iki ayrı süreci tek olay gibi göstermeye devam eder."]},"quiz":[{"question":"Açık davette değişen temel unsur hangisidir?","options":["Vahyin ilk defa gelmesi","Çağrının ulaştığı çevrenin genişlemesi","Medine'de mescidin tamamlanması"],"answer":1,"explanation":"İlk vahiy daha öncedir; Medine'deki mescid ise hicret sonrasıdır."},{"question":"Safâ çağrısını hangi başlıkta değerlendirmek uygundur?","options":["Habeşistan'a sığınma","Medine'nin ortak sözleşmesi","Mekke'de açık davet"],"answer":2,"explanation":"Safâ, Mekke'de daha geniş topluma seslenilen davet süreciyle ilişkilidir."},{"question":"Davetin duyulması ile kabul edilmesi arasındaki ilişki nedir?","options":["Duyan herkesin kabul etmesi zorunlu değildir","Aynı anlama gelirler","Kabul etmek için mesajın duyulması gereksizdir"],"answer":0,"explanation":"Çağrının kapsamı ile insanların verdiği karşılık ayrı ayrı incelenir."}],"teacher":{"misconception":"Yakın çevre/açık davet/hicret kavramlarını aynı olay gibi anlatmayın; açık davet tarihini yaklaşık olarak belirtin.","differentiation":"5–6. sınıf kavramları ayırsın; 7–8. sınıf 'ulaşmak' ve 'kabul edilmek' arasında kanıta dayalı fark kursun.","exit":"Açık daveti, göç sözcüğünü kullanmadan açıkla."},"sources":[{"title":"TDV — Safâ ve Merve","url":"https://islamansiklopedisi.org.tr/safa-ve-merve"},{"title":"TDV — Açık davetin başlangıcı","url":"https://islamansiklopedisi.org.tr/ebu-leheb"},{"title":"TDV — Siyer: davet dönemi","url":"https://islamansiklopedisi.org.tr/muhammed#1-hayati"}]},{"id":19,"module":4,"title":"Baskı karşısında dayanışma","date":"Mekke dönemi","objective":"İlk Müslümanların karşılaştığı baskıları ve dayanışmayı kavrar.","hook":{"question":"Birine destek olmak için iyi dilekte bulunmanın yanında ne gerekir?","options":["Somut ihtiyacını fark etmek","Onun yerine bütün kararları almak","Yaşadığını herkese anlatmak"],"note":"Tarihî baskıyı canlandırmayın; güvenli ve somut destek kavramını tartışın."},"frames":[{"title":"İnanç nedeniyle baskı","kind":"city","labels":["Mekke dönemi","İnanç","Baskı"],"narration":"Mekke'de İslâm'ı kabul eden bazı insanlar baskı ve kötü muameleyle karşılaştı. Özellikle güçlü bir aile veya kabile tarafından korunmayan kişiler daha savunmasız kalabiliyordu. Bu durum, ilk Müslümanların yaşadığı güçlüğü anlamamıza yardım eder. Baskıyı ayrıntılı acı sahnelerine dönüştürmeden konuşacağız: Bir insanın inancı sebebiyle zarar görmesi haksızlıktır; dayanışma ise bu haksızlığın etkisini azaltmak için somut sorumluluk almayı gerektirir."},{"title":"Hazret-i Bilâl-i Habeşî","kind":"values","labels":["İman","Sebat","İnsan onuru"],"narration":"Hazret-i Bilâl-i Habeşî, inancı yüzünden ağır baskıyla karşılaşan ilk Müslümanlardandı. Kölelik altında bulunması, kendisini koruyacak imkânlarını sınırlıyordu. Yaşadıklarını anlatırken kişiyi yalnız uğradığı zarar üzerinden tanımayalım; Hazret-i Bilâl-i Habeşî imanıyla ve daha sonraki hizmetleriyle de tanınır. Bir tarihî kişinin hayatını öğrenmek, hem dönemin adaletsiz şartlarını hem de kişinin onurunu ve iradesini görebilmeyi gerektirir."},{"title":"Özgürlüğe kavuşturan destek","kind":"community","labels":["Hazret-i Ebû Bekr","Özgürlüğe kavuşma","Somut yardım"],"narration":"Hazret-i Ebû Bekr, Hazret-i Bilâl-i Habeşî'nin özgürlüğüne kavuşmasına vesile oldu. Kaynaklar bu kurtarmanın ayrıntılarını farklı biçimlerde anlatsa da âzat edilme bilgisi ortaktır. Burada destek, yalnız üzüldüğünü söylemekle sınırlı kalmadı; kişinin hayat şartını değiştiren bir yardıma dönüştü. Olayı bir alışveriş yarışması gibi düşünmeyelim: Dersimizin odağı insan onuru, haksızlığın giderilmesi ve imkânı olanın sorumluluk almasıdır."},{"title":"Tarihten bugüne dikkatli bağ","kind":"values","labels":["Dinle","Güvenliği gözet","Yardım iste"],"narration":"Bugün bir arkadaşımız dışlanıyorsa tarihî olayla yaşadığı durum tamamen aynı değildir. Yine de dayanışma üzerine düşünmek için bir bağlantı kurabiliriz. Önce neye ihtiyaç duyduğunu dinlemek, yalnız kalmamasına yardımcı olmak ve güvenilir bir yetişkine haber vermek mümkündür. Onun görüntüsünü veya özel bilgisini izinsiz yaymak destek sayılmaz; yardım, kişinin güvenliğini ve onurunu koruduğunda anlam kazanır."}],"game":{"kind":"classify","title":"Destek mi, yeni bir yük mü?","prompt":"Güncel okul örneklerini, kişinin güvenliği ve onuru açısından iki gruba ayır.","groups":["Güvenli destek","Yardımı zorlaştıran davranış"],"items":[{"text":"İhtiyacını sözünü kesmeden dinlemek","group":0,"explanation":"Destek, kişinin neye ihtiyacı olduğunu anlamakla başlar."},{"text":"Güvenilir öğretmene durumu bildirmek","group":0,"explanation":"Bir çocuk güçlüğü tek başına çözmek zorunda değildir."},{"text":"İstemediği bir görüntüyü paylaşmamak","group":0,"explanation":"Mahremiyeti korumak insan onurunu gözetir."},{"text":"Dışlanma görüntüsünü sınıf grubuna yaymak","group":1,"explanation":"Daha fazla görünürlük her zaman yardım değildir; yeni bir zarar doğurabilir."},{"text":"Sormadan onun adına herkese cevap vermek","group":1,"explanation":"Kişinin kendi sözünü ve tercihini yok saymamak gerekir."},{"text":"Sorun büyümesin diye yetişkinden yardım istememek","group":1,"explanation":"Güvenli yardım yolunu kapatmak sorunun sürmesine neden olabilir."}]},"decision":{"question":"Bir öğrenci Hazret-i Bilâl-i Habeşî hakkında yalnız baskı gördüğünü yazmış. Daha dengeli tanıtım için ne eklemeli?","options":["Acının daha ayrıntılı tasvirini","İmanını, özgürlüğüne kavuşmasını ve sonraki hizmetlerini","Olayı günümüzde olmuş gibi bir konuşmayı"],"answer":1,"explanations":["Daha ayrıntılı acı tasviri kişinin hayatını bütünleştirmez.","Kişiyi yalnız uğradığı zarar üzerinden değil, iradesi ve hayatının bütünüyle tanımamızı sağlar.","Uydurma konuşma tarihî bilgiyi güvenilir kılmaz."]},"quiz":[{"question":"Hazret-i Ebû Bekr'in desteğinin somut sonucu nedir?","options":["Hazret-i Bilâl-i Habeşî'nin özgürlüğüne kavuşması","Habeşistan'ın yeni bir şehir olması","Mekke'deki bütün baskıların aynı gün sona ermesi"],"answer":0,"explanation":"Bir kişinin özgürlüğe kavuşması bilgisi, şehirdeki bütün baskıların bittiğini göstermez."},{"question":"Baskı görenleri anlatırken hangi tutum uygundur?","options":["Acıyı oyun puanına dönüştürmek","Sadece uğranılan zararı anlatmak","Kişinin onurunu, iradesini ve hayatını birlikte gözetmek"],"answer":2,"explanation":"Tarihî kişileri yalnız mağduriyetleriyle sınırlamak eksik bir tanıtımdır."},{"question":"Tarihî dayanışma ile bugünkü okul desteği nasıl ilişkilendirilebilir?","options":["Bütün şartlar aynı sayılarak","Ortak değerler düşünülüp dönem farkı korunarak","Tarihî kişilere güncel konuşmalar yazılarak"],"answer":1,"explanation":"Benzer değerleri konuşabiliriz; iki farklı dönemi aynı olay gibi sunmayız."}],"teacher":{"misconception":"Dayanışmayı acıya katlanma yarışması veya başkasının bütün kararlarını üstlenmek gibi göstermeyin.","differentiation":"5–6. sınıf destek kartlarını gerekçelendirsin; 7–8. sınıf somut yardım ile görünürlük arasındaki farkı açıklasın.","exit":"Bu tarihî olaydan öğrendiğin bir bilgiyi ve bugüne ait ayrı bir uygulamayı söyle."},"sources":[{"title":"TDV — Hazret-i Bilâl-i Habeşî","url":"https://islamansiklopedisi.org.tr/bilal-i-habesi"},{"title":"TDV — Hazret-i Ebû Bekr","url":"https://islamansiklopedisi.org.tr/ebu-bekir"}]},{"id":20,"module":4,"title":"Habeşistan'a güvenli yolculuk","date":"615 ve devamı","objective":"Habeşistan hicretinin sebebini ve sağlanan korumayı öğrenir.","hook":{"question":"Bir yolculuğun sebebini anlamak için önce hangi soruyu sorarsın?","options":["Yol ne kadar uzundu?","Yolcular neden ayrılmak zorundaydı?","Yanlarında kaç eşya vardı?"],"note":"Haritaya geçmeden sebep, güzergâh ve sonucu ayırın."},"frames":[{"title":"Güven içinde yaşama arayışı","kind":"journey","labels":["Mekke","Baskı","Güven arayışı"],"narration":"Mekke'deki baskılar artınca Peygamber Efendimiz (sallallahü aleyhi ve sellem), bazı Müslümanlara Habeşistan'a gitmelerini tavsiye etti. İlk kafile 615 yılında yola çıktı; daha sonra başka Müslümanlar da katıldı. Bu yolculuğun temel amacı ticaret yapmak veya yeni yerler görmek değildi. İnsanlar inançlarını güven içinde yaşayabilecekleri bir yer arıyordu; bu ihtiyaç, hicretin sebebini ve taşıdığı güçlüğü anlamanın başlangıç noktasıdır."},{"title":"Denizin iki yakası","kind":"map","labels":["Mekke","Kızıldeniz","Habeşistan"],"narration":"Habeşistan, Kızıldeniz'in Afrika tarafındaki tarihî bölgeyi ifade eder. Mekke ise Arabistan'dadır. Haritada iki kıyıyı ve aradaki denizi ayırdığımızda bu yolculuğun Medine'ye hicretle aynı olmadığını görürüz. Şematik harita bütün konakları veya kesin deniz rotasını göstermez; yalnız ana coğrafî ilişkiyi açıklar. Yolun yönünü anlamak için şehir adı, bölge adı ve deniz adını birbirine karıştırmadan okumalıyız."},{"title":"Dinlenmek ve korunmak","kind":"agreement","labels":["Hazret-i Necâşî","Sığınan Müslümanlar","Koruma"],"narration":"Habeşistan hükümdarı Hazret-i Necâşî, sığınan Müslümanları dinledi ve onları korudu. Mekkeli temsilcilerin geri götürme isteği karşısında Müslümanların kendilerini anlatmalarına fırsat verilmesi önemliydi. Böylece sığınanların hakkında yalnız karşı tarafın anlattığına bakılarak karar verilmedi. Bu olayı öğrenirken dinlemek ile hemen hüküm vermek arasındaki farkı düşünelim; koruma kararı, yolculuk sonunda güvenli bir hayat kurabilmenin temel şartlarından biriydi."},{"title":"Hazret-i Ca'fer'in açıklaması","kind":"book","labels":["İnancı anlatmak","Yolculuğun sebebi","Doğru temsil"],"narration":"Hazret-i Ca'fer b. Ebû Tâlib, Müslümanların inançlarını ve yurtlarından ayrılma sebeplerini hükümdarın huzurunda açıkladı. Kur'ân-ı Kerîm'den okunan bölümler de bu tanıtımda yer aldı. Bir topluluk adına konuşurken anlaşılır olmak kadar doğru bilgi vermek de önemlidir. Burada tarihî konuşmayı yeniden uydurmuyoruz; bildiğimiz işlevi tanıyoruz: Yanlış anlaşılmaları gidermek, inancı açıklamak ve güvenli yaşama ihtiyacını duyurmak."}],"game":{"kind":"sequence","title":"Sebep, yol ve sonuç","prompt":"Habeşistan hicretini anlatan dört kartı tarihî akışa yerleştir.","items":[{"text":"Mekke'de baskıların artması","explanation":"Yola çıkma ihtiyacını doğuran temel şarttır."},{"text":"Habeşistan'a gitme tavsiyesi ve hazırlık","explanation":"Güvenli bir yer aramak için plan yapılır."},{"text":"Kızıldeniz'in öte yakasına yolculuk","explanation":"Habeşistan, Arabistan'ın karşısındaki Afrika kıyısı tarafındadır."},{"text":"İnancın açıklanması ve koruma sağlanması","explanation":"Hazret-i Ca'fer açıkladı; Hazret-i Necâşî sığınanları korudu."}]},"decision":{"question":"Bir öğrenci Habeşistan hicretini '622'de Mekke'den Medine'ye yolculuk' diye özetledi. Hangi düzeltme gerekir?","options":["Sadece şehir adlarının yazımını değiştirmek","Sadece 622 sayısını silmek","615'te başlayan Habeşistan göçünü, 622 Medine hicretinden ayırmak"],"answer":2,"explanations":["Yanlışlık yazım değil, iki farklı göçün karıştırılmasıdır.","Yılı silmek hedef bölge karışıklığını gidermeyecektir.","Başlangıç zamanı ve hedef yer birlikte düzeltilmelidir; iki olayın ortak yönü güven arayışıdır."]},"quiz":[{"question":"Habeşistan yolculuğunun temel gerekçesi hangisidir?","options":["Medine'deki mescidi tamamlamak","İnancı güven içinde yaşayabilmek","Kâbe'nin onarımını yönetmek"],"answer":1,"explanation":"Diğer seçenekler farklı olayları bu yolculukla karıştırmaktadır."},{"question":"Haritada Habeşistan'ı Mekke'den ayıran deniz hangisidir?","options":["Kızıldeniz","Karadeniz","Hazar Denizi"],"answer":0,"explanation":"Ana coğrafî ilişki Arabistan, Kızıldeniz ve Afrika kıyısı arasında kurulur."},{"question":"Hazret-i Ca'fer ile Hazret-i Necâşî'nin bu olaydaki rolleri nasıl ayrılır?","options":["İkisi de Mekke'den gelen temsilcilerdir","Hazret-i Ca'fer hükümdar, Hazret-i Necâşî sığınandır","Hazret-i Ca'fer açıklayan, Hazret-i Necâşî dinleyip koruyandır"],"answer":2,"explanation":"Kişilerin rollerini ayırmak olayın karar sürecini doğru anlamayı sağlar."}],"teacher":{"misconception":"Habeşistan hicretini 622'deki Medine hicretiyle karıştırmayın; şematik haritayı kesin rota belgesi diye sunmayın.","differentiation":"5–6. sınıf sebep-yol-sonuç sıralasın; 7–8. sınıf iki hicreti zaman, yer ve amaç bakımından karşılaştırsın.","exit":"Habeşistan hicretini bir sebep, bir coğrafî bilgi ve bir sonuçla anlat."},"sources":[{"title":"TDV — Hazret-i Necâşî","url":"https://islamansiklopedisi.org.tr/necasi-ashame"},{"title":"TDV — Hazret-i Ca'fer b. Ebû Tâlib","url":"https://islamansiklopedisi.org.tr/cafer-b-ebu-talib"},{"title":"TDV — Hicret","url":"https://islamansiklopedisi.org.tr/hicret"}]},{"id":21,"module":4,"title":"Hazret-i Hamza ve Hazret-i Ömer","date":"İlk Mekke yılları; yaygın tarihle yaklaşık 616","objective":"İslâm'ı kabul eden yeni kişilerin topluluğa katkısını anlar.","hook":{"question":"Bir topluluğun güçlenmesi yalnızca kişi sayısının artmasıyla mı açıklanır?","options":["Yalnız sayı önemlidir","Katılanların desteği ve sorumluluğu da önemlidir","Sadece aynı aileden olmak yeterlidir"],"note":"Gücü yalnız fiziksel kuvvet veya çatışma olarak tanımlamadan toplumsal destek boyutunu açın."},"frames":[{"title":"Hazret-i Hamza'yı tanıyalım","kind":"family","labels":["Hazret-i Hamza","Amca-yeğen bağı","Mekke dönemi"],"narration":"Hazret-i Hamza, Peygamber Efendimiz (sallallahü aleyhi ve sellem) ile amca-yeğen bağı bulunan bir yakındı. Mekke döneminde İslâm'ı kabul etti ve Müslümanların yanında yer aldı. Kaynaklarda kabul yılına ilişkin farklı tarihler bulunur; bu yüzden tek bir günü kesinmiş gibi ezberlemiyoruz. Akrabalık ilişkisini bilmek ile Müslüman oluşunu bilmek ayrı bilgilerdir; bir akrabalık bağı, kişinin inancını kendiliğinden açıklamaz."},{"title":"Hazret-i Ömer'in kabulü","kind":"book","labels":["Hazret-i Ömer","Kur'ân-ı Kerîm","İslâm'ı kabul"],"narration":"Hazret-i Ömer, başlangıçta İslâm'a karşı çıkarken Mekke döneminde Müslüman oldu. Kaynaklarda bu kabulün nasıl gerçekleştiğini anlatan farklı rivayetler vardır. Meşhur anlatımda Kur'ân-ı Kerîm'i dinlemenin etkisi ve Dârülerkam'a gidiş yer alır. Bir kişinin önceki tutumu ile sonraki kararını ayırmak, hayatını anlamamızı sağlar; yalnız ilk tutumuna bakarak bütün hayatı hakkında hüküm vermek tarihî değişimi gözden kaçırır."},{"title":"Topluluğa gelen destek","kind":"community","labels":["Yeni katılım","Cesaret","Dayanışma"],"narration":"Hazret-i Hamza ve Hazret-i Ömer'in İslâm'ı kabul etmesi, Müslümanların toplumsal gücüne ve cesaretine katkı sağladı. Buradaki güçlenme yalnız iki kişinin sayıya eklenmesi olarak okunmamalıdır. Tanınan kişilerin destek vermesi, baskı altındaki topluluk açısından ayrıca anlam taşıyordu. Bununla birlikte yeni destekler bütün güçlükleri bir anda bitirmedi; sonraki boykot yılları, sıkıntıların devam ettiğini gösteren önemli bir örnektir."},{"title":"Ayrı bilgiler, ortak sonuç","kind":"timeline","labels":["Akrabalık bilgisi","Kabul süreci","Topluluğa katkı"],"narration":"Bu derste iki kişi hakkında öğrendiklerimizi tek bir hikâyeye karıştırmayalım. Amca-yeğen bağı Hazret-i Hamza ile ilgilidir; önce karşı çıkıp sonra Müslüman olma bilgisi Hazret-i Ömer'in kabul sürecini anlatır. İkisinin ortak yönü ise Mekke döneminde İslâm'ı benimseyerek topluluğa destek olmalarıdır. Karşılaştırma yaparken bir kişiye ait ayrıntıyı diğerine taşımadan, benzerlik ve farklılıkları ayrı işaretlemek gerekir."}],"game":{"kind":"match","title":"Bilgiyi doğru başlığa bağla","prompt":"Kişiye veya ortak sonuca ait bilgileri ayırt et.","pairs":[{"left":"Hazret-i Hamza'nın akrabalığı","right":"Amca-yeğen bağı","explanation":"Bu özel yakınlık bilgisi Hazret-i Hamza'ya aittir."},{"left":"Hazret-i Ömer'in değişen tutumu","right":"Önce karşı çıkış, sonra kabul","explanation":"Bir insanın hayatındaki değişimi görebilmek gerekir."},{"left":"İki kabulün ortak dönemi","right":"Mekke yılları","explanation":"Bu gelişmeler Medine'ye hicretten öncedir."},{"left":"İki kabulün topluluğa etkisi","right":"Destek ve cesaretin artması","explanation":"Güçlenme, bütün zorlukların bittiği anlamına gelmez."}]},"decision":{"question":"Panoda 'Hazret-i Hamza ve Hazret-i Ömer Müslüman olunca Mekke'deki baskı bitti' yazıyor. Hangi düzeltme uygundur?","options":["Güçlenme oldu; fakat baskıların tamamen bittiği söylenemez","İki kişinin kabulü topluluğu hiç etkilemedi","Bu olaylar ancak Medine'de gerçekleşmiş olabilir"],"answer":0,"explanations":["Katkıyı kabul ederken sonraki zorlukları da hesaba katmış oluruz.","Kaynaklar kabulün topluluğu güçlendirdiğini belirtir.","Her iki kabul de Mekke dönemindedir; yeri değiştirmek yanlışı büyütür."]},"quiz":[{"question":"Amca-yeğen bağı bu derste hangi kişiyle ilgilidir?","options":["Hazret-i Ömer","Hazret-i Hamza","Hazret-i Erkam"],"answer":1,"explanation":"Hazret-i Hamza'nın aile içindeki konumunu diğer kişilerin hayatıyla karıştırmayalım."},{"question":"Yeni katılanların topluluğa katkısı nasıl açıklanmalıdır?","options":["Yalnız beden gücüyle","Bütün sorunların sona ermesiyle","Sayı yanında destek ve cesaretle"],"answer":2,"explanation":"Toplumsal güçlenme, sayının ve destek imkânlarının birlikte değerlendirilmesini gerektirir."},{"question":"Kabul yılına dair farklı rivayetler varsa hangisi doğrudur?","options":["Farklılığı belirtip yaklaşık dönem kullanmak","Tek bir tarihi kaynaksız kesinleştirmek","Kişinin Müslüman olduğunu da yok saymak"],"answer":0,"explanation":"Bir ayrıntının tarihi farklı aktarılabilir; bu, ortak ana bilgiyi ortadan kaldırmaz."}],"teacher":{"misconception":"İmanı fiziksel güç gösterisine veya kişileri yarıştırmaya çevirmeyin. Katkı ile bütün baskıların sona ermesi arasındaki farkı koruyun.","differentiation":"5–6. sınıf kişi-bilgi kartlarını bağlasın; 7–8. sınıf 'güçlendi' ve 'sorun bitti' önermelerini ayırsın.","exit":"İki kişinin bir ortak yönünü ve Hazret-i Hamza'ya ait bir özel bilgiyi söyle."},"sources":[{"title":"TDV — Hazret-i Hamza","url":"https://islamansiklopedisi.org.tr/hamza"},{"title":"TDV — Hazret-i Ömer","url":"https://islamansiklopedisi.org.tr/omer"}]},{"id":22,"module":4,"title":"Boykot yılları","date":"Yaklaşık 616–619","objective":"Boykotun günlük hayata etkisini ve dayanışmanın önemini açıklar.","hook":{"question":"Bir topluluğun alışverişi ve ilişkileri engellenirse hangi ihtiyaçları etkilenir?","options":["Yalnız yeni eşya alma isteği","Yiyecekten güvene kadar birçok ihtiyaç","Yalnız uzak yolculuklar"],"note":"İhtiyaç ile istek ayrımını örnekleyin; öğrencinin kendi yaşadığı yoksunlukları açıklamasını istemeyin."},"frames":[{"title":"Boykot neyi engelledi?","kind":"market","labels":["Alışveriş","Akrabalık ilişkileri","Baskı"],"narration":"Mekke'de Hâşimoğulları ve Muttaliboğulları sosyal ve ekonomik boykotla karşılaştı. Alışverişin ve toplumsal ilişkilerin kısıtlanması, bu toplulukları ağır bir baskı altında bıraktı. Boykot kelimesini yalnız bir dükkândan alışveriş yapmamak gibi dar düşünmeyelim; burada yiyeceğe ulaşmayı ve insanlarla ilişki kurmayı birlikte zorlaştıran bir uygulama söz konusuydu. Etkisini anlamak için gündelik hayatın birbirine bağlı ihtiyaçlarına bakacağız."},{"title":"Kimler etkilendi?","kind":"community","labels":["Hâşimoğulları","Muttaliboğulları","Ortak sıkıntı"],"narration":"Boykot, Peygamber Efendimiz (sallallahü aleyhi ve sellem) için koruma sağlayan aile çevrelerini hedef aldı. Etkilenenlerin tamamını aynı inançta kişiler olarak düşünmek doğru değildir; aile dayanışması sebebiyle farklı kişiler de sıkıntıyı paylaştı. Bir topluluğa yönelen kısıtlama yalnız görüşünü değiştirmesi istenen kişiyi etkilemez. Aynı çevrede yaşayanların günlük düzeni, yiyeceğe erişimi ve birbirine destek olma imkânı da bu baskının içine girer."},{"title":"Bir ihtiyacın diğerine etkisi","kind":"home","labels":["Yiyeceğe erişim","Geçim","İlişkiler"],"narration":"Yiyecek almak zorlaşınca yalnız öğünler değişmez; ailelerin geçimi ve güvende hissetmesi de etkilenir. İlişkiler kısıtlanınca yardım ulaştırmak da güçleşebilir. Boykot yıllarını bu bağlantıları görerek öğrenmek, yalnız bir başlangıç ve bitiş tarihi ezberlemekten daha anlamlıdır. Kaynaklarda dönemin tarihlendirilmesinde farklılıklar vardır; burada yaklaşık üç yıl süren ağır sıkıntıyı ve ihtiyaçlar arasındaki bağı esas alıyoruz, acıyı bir oyun konusu yapmıyoruz."},{"title":"Sona ermesi neyi gösterir?","kind":"timeline","labels":["Kısıtlamalar","Dayanışma","Boykotun kalkması"],"narration":"Boykot yaklaşık üç yıl sonra sona erdi. Kısıtlamanın kalkması, uygulamanın doğurduğu güçlüğün hafiflemesi bakımından önemliydi. Ancak bundan Mekke'deki herkesin Müslüman olduğu veya bütün sorunların çözüldüğü sonucu çıkarılamaz. Bir tarihî gelişmenin doğrudan sonucunu, bizim eklediğimiz geniş yorumlardan ayırmalıyız. Dayanışma ihtiyacı ve davet çalışmaları devam etti; sonraki dersler bu zor dönemin ardından yaşanan gelişmeleri ayrı ayrı ele alacak."}],"game":{"kind":"match","title":"Kısıtlama ve etkisi","prompt":"Her kısıtlamayı günlük hayatta doğurabileceği en doğrudan sonuçla eşleştir.","pairs":[{"left":"Yiyecek alışverişinin engellenmesi","right":"Temel besinlere ulaşmanın zorlaşması","explanation":"Bu, isteğe bağlı bir alışverişten daha temel bir ihtiyaçtır."},{"left":"Toplumsal ilişkilerin kısıtlanması","right":"Destek ağının daralması","explanation":"İnsanlarla bağlantı, yardıma ulaşmada da önemlidir."},{"left":"Ticaretin zorlaştırılması","right":"Geçim imkânlarının azalması","explanation":"Alışveriş hem alıcıyı hem geçimini ticaretle sağlayanı etkiler."},{"left":"Boykotun sona ermesi","right":"Bu kısıtlamaların kaldırılması","explanation":"Bu sonuç bütün fikir ayrılıklarının bittiği anlamına gelmez."}]},"decision":{"question":"Bir öğrenci 'Boykotta yalnız Müslümanlar vardı, bu yüzden bütün aileler aynı inançtaydı' diyor. Hangi bilgiyle düzeltirsin?","options":["Boykot sözcüğünü anlatımdan çıkarırım","Aile dayanışması nedeniyle farklı inançtaki yakınların da etkilendiğini söylerim","Süreyi daha kısa yazarım"],"answer":1,"explanations":["Kavramı çıkarmak, hedef alınan toplulukları anlamamızı engeller.","Topluluğu paylaşmak ile aynı inancı paylaşmak ayrı durumlardır.","Süreyi değiştirmek, kimlerin etkilendiğine ilişkin genellemeyi düzeltmez."]},"quiz":[{"question":"Boykotun sosyal ve ekonomik olması ne demektir?","options":["Hem ilişkileri hem alışverişi kısıtlaması","Yalnız yolculuk süresini artırması","Yalnız bir kişinin evini değiştirmesi"],"answer":0,"explanation":"İki alanın birlikte kısıtlanması günlük hayat üzerindeki etkiyi ağırlaştırır."},{"question":"Boykotun sona ermesinden hangi sonuç çıkarılabilir?","options":["Mekke'deki herkes aynı inancı benimsedi","Bütün sonraki güçlükler sona erdi","Boykotun getirdiği kısıtlamalar kaldırıldı"],"answer":2,"explanation":"Doğrudan sonuç ile kanıtlanmayan geniş genellemeleri ayırmalıyız."},{"question":"Bu dönemi öğrenirken en anlamlı yaklaşım hangisidir?","options":["Yalnız gün ve ayı ezberlemek","Kısıtlamaların insanların temel ihtiyaçlarını nasıl etkilediğini açıklamak","Zor şartları öğrenciler arasında yarıştırmak"],"answer":1,"explanation":"Neden-sonuç ilişkisi tarihî dönemi anlamayı sağlar; acı yarışma malzemesi yapılmaz."}],"teacher":{"misconception":"Boykot edilen çevrenin bütün üyelerini aynı inançta saymayın. Yaklaşık süreyi kaynaklardaki farklı tarih aralıklarıyla karıştırmadan aktarın.","differentiation":"5–6. sınıf ihtiyaç-sonuç eşleştirsin; 7–8. sınıf bir kısıtlamanın iki dolaylı etkisini açıklasın.","exit":"Boykotun iki farklı alandaki etkisini ve sona ermesinin doğrudan sonucunu söyle."},"sources":[{"title":"TDV — Siyer: boykot dönemi","url":"https://islamansiklopedisi.org.tr/muhammed#1-hayati"},{"title":"TDV — Ebû Tâlib ve himaye","url":"https://islamansiklopedisi.org.tr/ebu-talib"},{"title":"TDV — Mekke döneminden hicrete","url":"https://islamansiklopedisi.org.tr/hicret"}]},{"id":23,"module":4,"title":"Hüzün yılı ve Tâif","date":"Yaklaşık 619–620","objective":"Kayıplar ve Tâif yolculuğunu sabır ve umut açısından değerlendirir.","hook":{"question":"İyi bir amaç için yapılan ilk girişim sonuç vermediğinde hangi ihtiyaç öne çıkar?","options":["Desteğe ve yeni bir değerlendirmeye ihtiyaç","Hiç üzülmemek zorunda olmak","Yaşananı hemen başarı diye adlandırmak"],"note":"Kayıp yaşamış öğrencilerden kişisel deneyim istemeyin; sabrı duyguları yok sayma olarak sunmayın."},"frames":[{"title":"İki önemli kayıp","kind":"family","labels":["Hadîce vâlidemiz","Ebû Tâlib","Hüzün Yılı"],"narration":"Hadîce vâlidemiz ile Ebû Tâlib'in vefat ettiği dönem Hüzün Yılı diye anılır. Hadîce vâlidemiz ilk iman eden kişi ve yakın destekti; Ebû Tâlib ise amca olarak koruma sağlamıştı. Peygamber Efendimiz (sallallahü aleyhi ve sellem) için bu iki kayıp hem aile hayatı hem de Mekke'deki şartlar açısından önemliydi. Aynı dönemde anılmaları, iki kişinin destek biçiminin aynı olduğu anlamına gelmez."},{"title":"Tâif'e yöneliş","kind":"route","labels":["Mekke","Tâif","Davet ve destek"],"narration":"Bu zor dönemde Peygamber Efendimiz (sallallahü aleyhi ve sellem), İslâm'ı anlatmak ve destek aramak için Tâif'e gitti. Tâif, Mekke'den ayrı bir şehirdir; bu yolculuk Medine'ye hicretle aynı olay değildir. Haritada iki şehri ayırırken yolculuğun amacını da hatırlayalım. Yer değiştirmek tek başına amacı açıklamaz; burada ticaret veya kalıcı yerleşme bilgisi değil, davetin yeni bir çevreye ulaştırılması öne çıkar."},{"title":"Zor bir karşılık","kind":"values","labels":["Davet","Reddedilme","Çabanın sürmesi"],"narration":"Tâif'te beklenen destek sağlanmadı; Peygamber Efendimiz (sallallahü aleyhi ve sellem) ağır bir karşılık gördü. Bu olayı acı veren ayrıntıları canlandırmadan, amacı ve sonucu üzerinden öğreneceğiz. Davetin bu girişimde kabul görmemesi, daha sonra bütün çalışmaların bırakıldığı anlamına gelmedi. Bir olayın kısa vadeli sonucu ile uzun vadeli yolculuğu farklı olabilir; siyer çizgisini sonraki görüşmelerle birlikte okumak bu farkı görmemizi sağlar."},{"title":"Sabır, duygu ve destek","kind":"community","labels":["Üzüntüyü tanımak","Destek aramak","Çabayı sürdürmek"],"narration":"Sabır, insanın hiç üzülmemesi veya hiç yardım istememesi demek değildir. Hüzün Yılı ve Tâif sürecini öğrenirken kayıpları küçümsemeden, destek arayışını ve çabanın sürmesini birlikte görüyoruz. Bugünkü bir okul girişimiyle bu tarihî yaşantı aynı değildir; fakat sonuç alamadığımızda düşünmek, güvenilir kişilerden yardım istemek ve uygun yeni yollar aramak üzerine konuşabiliriz. Tarihî bilgi ile güncel uygulamamızı ayrı tutacağız."}],"game":{"kind":"match","title":"Olay, kişi ve anlam","prompt":"Bu dersteki bilgileri birbirine karıştırmadan bağla.","pairs":[{"left":"Hadîce vâlidemizin vefatı","right":"Aile içindeki yakın desteğin kaybı","explanation":"Hadîce vâlidemiz ilk iman eden ve destek olan kişiydi."},{"left":"Ebû Tâlib'in vefatı","right":"Amcanın sağladığı himayenin kaybı","explanation":"Akrabalık koruması dönemin toplumsal şartlarında önemliydi."},{"left":"Tâif yolculuğu","right":"İslâm'ı anlatmak ve destek aramak","explanation":"Bu yolculuk Medine'ye hicret değildir."},{"left":"Davetin sürdürülmesi","right":"Bir girişimin sonucuyla bütün geleceği eşitlememek","explanation":"Beklenen destek sağlanmadı; çaba devam etti."}]},"decision":{"question":"Bir öğrenci 'Sabırlı olmak için üzüntümüzü kimseye söylememeliyiz' sonucunu çıkarıyor. Nasıl düzeltirsin?","options":["Üzüntünün hiç yaşanmadığını söyleyerek","Her girişimin hemen başarılı olduğunu söyleyerek","Sabrın, duyguyu tanımak ve destek aramakla birlikte olabileceğini açıklayarak"],"answer":2,"explanations":["Hüzün Yılı adı bile kayıpların önemini hatırlatır; üzüntüyü yok sayamayız.","Tâif'te beklenen desteğin sağlanmaması bu genellemeyi desteklemez.","Duyguyu küçümsemeden dayanmak ve yardım aramak birbirini dışlamaz."]},"quiz":[{"question":"Hüzün Yılı hangi iki vefatla ilişkilidir?","options":["Hadîce vâlidemiz ve Ebû Tâlib","Hazret-i Hamza ve Hazret-i Ömer","Hazret-i Mus'ab ve Hazret-i Ca'fer"],"answer":0,"explanation":"Ders, Mekke dönemindeki iki yakın kaybı birlikte ele alır."},{"question":"Tâif yolculuğunun temel amacı hangisidir?","options":["Medine'deki mescidi ziyaret","İslâm'ı anlatmak ve destek aramak","Kızıldeniz üzerinden göç etmek"],"answer":1,"explanation":"Tâif yolculuğu, Habeşistan hicreti veya Medine'ye yerleşmeyle karıştırılmamalıdır."},{"question":"Tâif'te beklenen destek sağlanmaması hangi sonucu gösterir?","options":["Davetin bütünüyle sona erdiğini","Daha sonraki görüşmelerin yapılmadığını","Bu girişimin o sırada beklenen sonucu vermediğini"],"answer":2,"explanation":"Tek olayın sonucu, bütün sonraki gelişmeleri belirleyen bir genellemeye çevrilmez."}],"teacher":{"misconception":"Sabır ile duyguları bastırmayı eşitlemeyin; vefatlar hakkında sınıfta kişisel kayıp anlatmayı zorunlu tutmayın.","differentiation":"5–6. sınıf kişi-olay ayrımı yapsın; 7–8. sınıf kısa vadeli sonuç ile sürecin devamını ayırsın.","exit":"Tâif yolculuğunun amacıyla o sıradaki sonucunu iki ayrı cümleyle anlat."},"sources":[{"title":"TDV — Hadîce vâlidemiz","url":"https://islamansiklopedisi.org.tr/hatice"},{"title":"TDV — Ebû Tâlib","url":"https://islamansiklopedisi.org.tr/ebu-talib"},{"title":"TDV — Tâif","url":"https://islamansiklopedisi.org.tr/taif"}]},{"id":24,"module":4,"title":"İsrâ ve miraç","date":"Hicretten önce; kesin tarihi tartışmalıdır","objective":"İsrâ ve miraç kavramlarını birbirinden ayırır.","hook":{"question":"İsrâ, miraç ve hicret aynı yolculuğun üç adı mıdır?","options":["Üçü aynı olaydır","İsrâ ve miraç bağlantılıdır; hicret ayrı bir olaydır","Yalnız başlangıç şehirleri farklıdır"],"note":"Terimleri ayırın; olağanüstü hadiseyi çizilmiş fiziksel rota veya tarihî şahıs tasviriyle sunmayın."},"frames":[{"title":"İsrâ: gece yolculuğu","kind":"map","labels":["Mescid-i Harâm","Mescid-i Aksâ","İsrâ"],"narration":"İsrâ, Peygamber Efendimiz (sallallahü aleyhi ve sellem) için Mescid-i Harâm'dan Mescid-i Aksâ'ya gerçekleşen gece yolculuğunu anlatır. İsrâ sûresinin ilk âyet-i kerîmesinde bu yolculuk bildirilir. Burada başlangıç ve varış yerlerini tanımak kavramı anlamamıza yardımcı olur. Ekrandaki bağlantı şeması, olayın nasıl gerçekleştiğini gösteren bir tasvir değildir; yalnız isimleri ve iki mekân arasındaki kavramsal ilişkiyi ayırmak içindir."},{"title":"Miraç: bağlantılı yükseliş","kind":"book","labels":["İsrâ","Miraç","Kaynak bilgisi"],"narration":"Miraç, Peygamber Efendimiz (sallallahü aleyhi ve sellem) için bu gece yolculuğuyla bağlantılı yükselişi ifade eder. Türkçede bazen miraç sözcüğü iki safhayı birlikte anlatmak için de kullanılır. Kavramları öğrenirken ayrımı açık tutuyoruz: İsrâ, Mescid-i Harâm ile Mescid-i Aksâ arasındaki gece yolculuğu; miraç ise yükseliştir. Bunları sıradan bir seyahat çizelgesi gibi resmetmek yerine, kaynakların verdiği anlamlar üzerinden tanıyacağız."},{"title":"Beş vakit namaz","kind":"values","labels":["Miraç","Beş vakit namaz","İbadet"],"narration":"Hadîs-i şerîf rivayetlerinde beş vakit namazın farz kılınması miraç hadisesiyle ilişkilendirilir. Bu bilgi, olayın Müslümanların günlük ibadet hayatıyla bağlantısını gösterir. Namazı yalnız bir tarih sorusunun cevabı olarak düşünmeyelim; gün içinde Allahü teâlâya yönelmeyi ve kulluk sorumluluğunu hatırlatan bir ibadettir. Bu derste namazın bütün hükümlerini öğrenmiyoruz; siyer olayının ibadetle kurduğu temel bağı fark ediyoruz."},{"title":"Tarih ve kavramda dikkat","kind":"book","labels":["Hicretten önce","Tarih farklılıkları","Kavramları ayır"],"narration":"İsrâ ve miraç hicretten önce gerçekleşmiştir; kesin gün ve yıl konusunda kaynaklarda farklı görüşler bulunur. Bir anma tarihini, herkesin üzerinde birleştiği tarihî gün gibi sunmamak gerekir. Hicret ise Mekke'den Medine'ye göç sürecidir ve ayrı bir olaydır. Bu üç kavramı öğrenirken başlangıç yerini, anlamı ve dönemi birbirine karıştırmadan okumak, ayrıntıları kesinleştirmeye çalışmaktan önce gelir."}],"game":{"kind":"match","title":"Kavramların yerini bul","prompt":"Kavramı doğru açıklamayla eşleştir; benzer görünenleri ayır.","pairs":[{"left":"İsrâ","right":"Mescid-i Harâm'dan Mescid-i Aksâ'ya gece yolculuğu","explanation":"İki kutsal mekân arasındaki gece yolculuğunu belirtir."},{"left":"Miraç","right":"Gece yolculuğuyla bağlantılı yükseliş","explanation":"İsrâ ile bağlantılıdır; kavramsal olarak ayrı açıklanır."},{"left":"Medine'ye hicret","right":"Mekke'den Medine'ye göç","explanation":"İsrâ ve miraçla aynı olay değildir."},{"left":"Beş vakit namaz","right":"Miraçla ilişkilendirilen ibadet emri","explanation":"Hadîs-i şerîf rivayetlerinde bu bağlantı yer alır."}]},"decision":{"question":"Bir sunumda miraç için kesin tarihli, bütün durakları çizilmiş sıradan bir yol haritası hazırlanmış. Nasıl düzeltirsin?","options":["Kavram şeması kullanır, tarih farklılığını belirtirim","Haritaya daha fazla tahminî durak eklerim","İsrâ yerine hicret yazıp aynı çizimi bırakırım"],"answer":0,"explanations":["Kaynakların verdiği kavramları açıklamak, bilmediğimiz ayrıntıları varmış gibi göstermeyi önler.","Tahminî duraklar tarihî veya dinî bilgiymiş gibi sunulmamalıdır.","Terimi değiştirmek iki ayrı olayı karıştırır."]},"quiz":[{"question":"İsrâ'nın başlangıç ve varış yerleri hangileridir?","options":["Mekke ve Habeşistan","Mescid-i Harâm ve Mescid-i Aksâ","Kubâ ve Medine"],"answer":1,"explanation":"İsrâ gece yolculuğudur; diğer seçenekler başka yolculuklarla ilişkilidir."},{"question":"Beş vakit namazın farz kılınması rivayetlerde hangi hadiseyle ilişkilidir?","options":["Mekke'nin fethi","Birinci Akabe Biatı","Miraç"],"answer":2,"explanation":"Dersin temel ibadet bağlantısı miraç ile beş vakit namaz arasındadır."},{"question":"Kesin tarih konusunda farklı rivayetler varken ne söylenebilir?","options":["Hicretten önce olduğu belirtilip kesinlik iddiasından kaçınılır","Bütün ayrıntılar aynı gün üzerinde birleşmiştir denir","Olay Medine'den sonra diye kesinleştirilir"],"answer":0,"explanation":"Bilinen dönem ile tartışılan ayrıntının güven düzeyini ayrı ifade ederiz."}],"teacher":{"misconception":"İsrâ, miraç ve hicreti eş anlamlı göstermeyin; dinî hadisenin tasviri veya rol canlandırması yapılmasın.","differentiation":"5–6. sınıf dört kavramı eşleştirsin; 7–8. sınıf kaynak kesinliği ile yaygın anma tarihi arasındaki farkı açıklasın.","exit":"İsrâ ile hicretin neden aynı olay olmadığını birer yer bilgisi kullanarak söyle."},"sources":[{"title":"TDV — İsrâ ve miraç","url":"https://islamansiklopedisi.org.tr/mirac"},{"title":"TDV — Hicret","url":"https://islamansiklopedisi.org.tr/hicret"}]},{"id":25,"module":5,"title":"Yesrib'den gelen umut: Akabe","date":"620–621","objective":"Akabe görüşmelerinin Medine'ye uzanan süreçteki yerini anlar.","hook":{"question":"Bir görüşmenin yapıldığı yer ile katılanların geldiği şehir aynı olmak zorunda mı?","options":["Her zaman aynıdır","Yalnız hac mevsiminde aynıdır","Hayır, iki ayrı yer bilgisi olabilir"],"note":"Akabe'nin Mekke çevresinde, katılanların Yesrib'den olduğunu haritada ayırın."},"frames":[{"title":"Yesrib'den gelenler","kind":"map","labels":["Yesrib","Mekke","Hac mevsimi"],"narration":"Hac mevsiminde farklı bölgelerden insanlar Mekke'ye geliyordu. Peygamber Efendimiz (sallallahü aleyhi ve sellem), 620 yılında Yesrib'den gelen bir grupla görüştü ve İslâm'ı anlattı. Böylece Mekke dışındaki bir toplulukla yeni bir bağ kuruldu. Haritada görüşmenin yeriyle gelenlerin şehrini ayrı işaretleyelim: İnsanlar Yesrib'den gelmişti, fakat buluşma Yesrib'de yapılmamıştı. Bu ayrım daha sonraki gidiş gelişleri anlamamıza yardım edecektir."},{"title":"Akabe hangi yer?","kind":"city","labels":["Mekke çevresi","Mina","Akabe"],"narration":"Bu dersin Akabe adı, Mekke çevresinde Mina yakınındaki mevkii belirtir. Aynı ad farklı coğrafyalarda da kullanılabilir; bu yüzden yalnız yer adını okumak bazen yeterli olmaz. Akabe görüşmelerini anlatırken Mekke ve hac mevsimi bilgileri birlikte anlam kazanır. İnsanların nereden geldiği, nerede buluştuğu ve sonra nereye döndüğü ayrı sorulardır; bir harita bu üç soruya aynı noktayı göstermemelidir."},{"title":"Birinci biat: verilen sözler","kind":"agreement","labels":["621","İman","Güzel davranış"],"narration":"Ertesi yıl, 621'de Yesrib'den gelen kişiler Birinci Akabe Biatı'nda Peygamber Efendimiz (sallallahü aleyhi ve sellem) için bağlılık sözü verdi. Allahü teâlâya ortak koşmamak ve kötü davranışlardan uzak durmak gibi inanç ve ahlâk esasları bu sözler arasında yer alıyordu. Biat, burada rastgele bir dilek değil, yerine getirilmesi gereken sorumlulukları kabul etmektir. Verilen sözün içeriğini bilmek, yalnız görüşmenin adını ezberlemekten daha önemlidir."},{"title":"Yesrib'e taşınan haber","kind":"route","labels":["Görüşme","Yesrib'e dönüş","Yeni öğrenenler"],"narration":"Görüşmeye katılanlar Yesrib'e döndüklerinde İslâm'ı çevrelerine anlattı. Böylece bir buluşmanın etkisi yalnız yapıldığı yerde kalmadı. Öğretim ihtiyacı arttı ve sonraki aşamada Hazret-i Mus'ab b. Umeyr'in görevlendirilmesine uzanan bir süreç oluştu. Bu gelişmeyi henüz hicret tamamlanmış gibi okumayalım; Akabe görüşmeleri, şehirler arasında bağ kuran ve daha sonraki hicrete zemin hazırlayan basamaklar arasındadır."}],"game":{"kind":"sequence","title":"Bir buluşmadan yeni öğrenmeye","prompt":"Akabe sürecinin bu bölümde öğrendiğimiz basamaklarını sırala.","items":[{"text":"Yesrib'den gelenlerle 620'de ilk görüşme","explanation":"Mekke'deki hac mevsimi, farklı şehirlerden insanlarla görüşme imkânı sağladı."},{"text":"Görüşenlerin Yesrib'de İslâm'ı anlatması","explanation":"Haber ve öğrenme yeni çevrelere ulaştı."},{"text":"621'de Birinci Akabe Biatı","explanation":"İnanç ve davranışlarla ilgili sorumluluklar kabul edildi."},{"text":"Yesrib'de öğretim ihtiyacının güçlenmesi","explanation":"Sonraki ders Hazret-i Mus'ab'ın görevlendirilmesini ele alacak."}]},"decision":{"question":"Haritada Akabe görüşmesi Yesrib'in içine yerleştirilmiş. Hangi bilgi düzeltmeyi sağlar?","options":["Katılanların Yesrib'den geldiği için işaretin doğru olduğunu söylemek","Görüşmenin Mekke çevresinde, katılanların ise Yesribli olduğunu ayırmak","Yesrib adını tamamen haritadan kaldırmak"],"answer":1,"explanations":["Bir kişinin geldiği şehir, görüşmenin yapıldığı yerle aynı olmak zorunda değildir.","İki yer bilgisi ayrı işaretlenince gidiş geliş ilişkisi görünür olur.","Yesrib bilgisi de gereklidir; sorun bilgiyi silmek değil, doğru yerde göstermektir."]},"quiz":[{"question":"Akabe görüşmelerine katılan bu topluluk nereden geliyordu?","options":["Yesrib'den","Habeşistan'dan","Tâif'ten"],"answer":0,"explanation":"Katılanların şehri Yesrib'dir; görüşmenin yeri Mekke çevresidir."},{"question":"Birinci Akabe Biatı'nda öne çıkan içerik hangisidir?","options":["Mescid-i Nebevî'nin yapı planı","Bir ticaret kervanının kazanç paylaşımı","İnanç ve güzel davranış sorumlulukları"],"answer":2,"explanation":"Biatın bu aşamasında iman ve ahlâk esaslarına ilişkin sözler verildi."},{"question":"Akabe görüşmelerinin hicretle ilişkisi nasıl açıklanır?","options":["Hicretin ardından yapılan kutlamadır","Hicrete zemin hazırlayan gelişmelerdendir","Habeşistan yolculuğunun başka adıdır"],"answer":1,"explanation":"Görüşmeler yeni bir şehirle bağ kurdu; hicret henüz sonraki aşamadır."}],"teacher":{"misconception":"Akabe'yi Yesrib'in bir mahallesi gibi göstermeyin; 620 ilk görüşme ile 621 Birinci Biatı ayırın.","differentiation":"5–6. sınıf geldiği yer/buluştuğu yer ayrımını yapsın; 7–8. sınıf görüşmenin sonraki gelişmeye etkisini açıklasın.","exit":"Akabe için bir yer, bir tarih ve bir sorumluluk bilgisi söyle."},"sources":[{"title":"TDV — Akabe biatları","url":"https://islamansiklopedisi.org.tr/akabe-biatlari"},{"title":"TDV — Hazret-i Mus'ab b. Umeyr","url":"https://islamansiklopedisi.org.tr/musab-b-umeyr"}]},{"id":26,"module":5,"title":"Hazret-i Mus'ab'ın öğretmenliği ve ikinci biat","date":"621–622","objective":"Öğreticilik vazifesini ve ikinci biatın önemini tanır.","hook":{"question":"Bir şehre bilgi götürmek için yalnızca çok konuşmak yeterli olur mu?","options":["Bilmek, anlaşılır anlatmak ve dinlemek birlikte gerekir","Yalnız ezberlemek yeterlidir","Yalnız kalabalık bir yerde konuşmak yeterlidir"],"note":"Öğreticiliği konuşma süresiyle değil, öğrenmeye yardım etme işiyle ilişkilendirin."},"frames":[{"title":"Yesrib'e gönderilen öğretmen","kind":"route","labels":["Birinci Akabe Biatı","Hazret-i Mus'ab","Yesrib"],"narration":"Birinci Akabe Biatı'nın ardından Peygamber Efendimiz (sallallahü aleyhi ve sellem), Hazret-i Mus'ab b. Umeyr'i İslâm'ı ve Kur'ân-ı Kerîm'i öğretmek üzere Yesrib'e gönderdi. Bu görev, görüşmelerle başlayan ilişkinin düzenli öğrenmeye dönüşmesini sağladı. Hazret-i Mus'ab yalnız haber taşıyan bir yolcu değildi; insanların dini tanımasına yardım eden bir öğreticiydi. Zaman çizgisinde görevlendirmenin birinci biattan sonra, büyük hicret yolculuğundan önce olduğunu işaretleyelim."},{"title":"Evlerden topluma yayılan öğrenme","kind":"community","labels":["Hazret-i Es'ad b. Zürâre","Dinleme","Öğrenme"],"narration":"Hazret-i Mus'ab, Yesrib'de Hazret-i Es'ad b. Zürâre'nin desteğiyle çalıştı. Kur'ân-ı Kerîm'i öğretmesi ve insanlarla görüşmesi, şehirde İslâm'ı tanıyanların artmasına katkı sağladı. Bir kişinin başka bir şehre gitmesi tek başına bütün sonucu açıklamaz; ev sahipliği, güven, bilgiyi anlaşılır aktarma ve yeni görüşmeler birlikte etkiliydi. Böylece önceki derste başladığımız şehirler arası bağın gündelik öğrenme ilişkilerine dönüştüğünü görüyoruz."},{"title":"İkinci Akabe Biatı","kind":"agreement","labels":["622","Koruma sözü","Yeni sorumluluk"],"narration":"622 yılındaki İkinci Akabe Biatı'nda Yesribli Müslümanlar Peygamber Efendimiz (sallallahü aleyhi ve sellem) için koruma ve destek sözü verdi. Bu, önceki ahlâk ve iman sözlerini gereksiz kılan bir gelişme değildi; yeni şartlarda daha geniş sorumluluk üstlenmekti. İki biatı karşılaştırırken ortak bağlılığı koruyalım, fakat ikinci görüşmede hicrete imkân sağlayan koruma sözünün belirginleştiğini de fark edelim. Başlık benzerliği, içeriklerin bütünüyle aynı olduğunu göstermez."},{"title":"Hicrete hazırlanan bağ","kind":"timeline","labels":["Öğretim","İkinci biat","Hicret hazırlığı"],"narration":"Hazret-i Mus'ab'ın öğretim çalışmaları, Yesrib'deki topluluğun güçlenmesi ve ikinci biattaki koruma sözü birbiriyle ilişkili gelişmelerdir. Bunları tek bir kişinin bir günde yaptığı işler gibi anlatmamalıyız. Öğrenme ve güven zaman içinde oluştu; verilen sözler de yeni sorumluluklar doğurdu. Sonraki derste hicret yolculuğuna geçerken, yolculuğun öncesinde insanları birbirine bağlayan bu hazırlık aşamalarını hatırlamak neden-sonuç ilişkisini görünür kılar."}],"game":{"kind":"classify","title":"Öğretim mi, koruma sözü mü?","prompt":"Kartları doğrudan anlattıkları işe göre ayır; iki işin aynı sürece katkı verdiğini hatırla.","groups":["Yesrib'de öğretim","İkinci biattaki sorumluluk"],"items":[{"text":"Kur'ân-ı Kerîm'i öğretmek","group":0,"explanation":"Hazret-i Mus'ab'ın temel görevi öğrenmeye yardımcı olmaktı."},{"text":"İslâm'ı yeni tanıyanların sorularını ele almak","group":0,"explanation":"Anlaşılır açıklama öğretimin bir parçasıdır."},{"text":"Hazret-i Es'ad'ın desteğiyle insanlarla görüşmek","group":0,"explanation":"Şehirdeki bağlar öğretim çalışmalarına imkân sağladı."},{"text":"Hicret sonrasında güvenliğe destek vermeyi üstlenmek","group":1,"explanation":"İkinci biatta koruma sözü öne çıktı."},{"text":"Verilen koruma sözünün gereğini kabul etmek","group":1,"explanation":"Söz yalnız iyi dilek değil, sorumluluktur."},{"text":"Yeni gelecek topluluğa destek için hazır olmak","group":1,"explanation":"Koruma ve destek, hicretin toplumsal hazırlığıyla ilişkilidir."}]},"decision":{"question":"Bir öğrenci 'İkinci biat yapıldıysa birinci biatın iman ve ahlâk sözleri bırakılmıştır' diyor. Hangi açıklama doğrudur?","options":["İki biatı tek görüşme kabul edelim","Önceki esaslar devam ederken koruma sorumluluğu belirginleşmiştir","Birinci biatı zaman çizgisinden çıkaralım"],"answer":1,"explanations":["İki ayrı görüşmeyi birleştirmek gelişimin aşamalarını kaybettirir.","Yeni sorumluluk üstlenmek, önceki ahlâkî esaslardan vazgeçmek değildir.","Önceki aşamayı silmek ikinci biatın nasıl hazırlandığını anlamayı zorlaştırır."]},"quiz":[{"question":"Hazret-i Mus'ab'ın Yesrib'e gönderilmesindeki temel amaç nedir?","options":["İslâm'ı ve Kur'ân-ı Kerîm'i öğretmek","Mekke'deki Kâbe'yi onarmak","Medine Vesikası'nın yerine yeni bir metin yazmak"],"answer":0,"explanation":"Bu görevlendirme Birinci Akabe Biatı sonrasında öğrenme ihtiyacına cevap verdi."},{"question":"İkinci Akabe Biatı'nda hangi sorumluluk özellikle öne çıkar?","options":["Habeşistan'a deniz yolculuğu","Kâbe hakemliği","Koruma ve destek sözü"],"answer":2,"explanation":"Bu söz hicret için güven ve destek ortamının hazırlanmasında önemlidir."},{"question":"Doğru sıra hangisidir?","options":["Hicret → ilk vahiy → Birinci Akabe","Birinci Akabe → öğretim çalışmaları → İkinci Akabe","İkinci Akabe → İlk vahiy → öğretim"],"answer":1,"explanation":"Hazret-i Mus'ab'ın öğretim görevi iki biat arasındaki sürecin önemli parçasıdır."}],"teacher":{"misconception":"Öğretmenliği yalnız hitabet yeteneğine indirgemeyin; iki biatı birbirinin iptali gibi anlatmayın.","differentiation":"5–6. sınıf görev/söz kartlarını ayırsın; 7–8. sınıf öğretim ile toplumsal güven arasında iki bağlantı kursun.","exit":"Hazret-i Mus'ab'ın göreviyle ikinci biattaki koruma sözünün hicrete nasıl katkı verdiğini anlat."},"sources":[{"title":"TDV — Hazret-i Mus'ab b. Umeyr","url":"https://islamansiklopedisi.org.tr/musab-b-umeyr"},{"title":"TDV — Akabe biatları","url":"https://islamansiklopedisi.org.tr/akabe-biatlari"}]},{"id":27,"module":5,"title":"Hicret: hazırlık ve güven","date":"622","objective":"Hicrette tevekkülün hazırlık ve sorumlulukla birlikte olduğunu kavrar.","hook":{"question":"Bir yolculukta güvenmek ile hazırlık yapmak nasıl ilişkilidir?","options":["Hazırlık yapılırsa güven kalmaz","Güvenmek bütün tedbirleri bırakmaktır","Sorumluluk almak ve güvenmek birlikte olabilir"],"note":"Tevekkülü edilgen bekleyişe çevirmeden plan ve görev paylaşımı üzerinden açın."},"frames":[{"title":"Mekke'den yeni bir hayata","kind":"route","labels":["Mekke","622","Yesrib"],"narration":"Akabe görüşmelerinin ardından Müslümanlar Mekke'den Yesrib'e hicret etmeye başladı. Herkes aynı gün, aynı kafileyle yola çıkmadı; gidebilenler farklı zamanlarda ayrıldı. Peygamber Efendimiz (sallallahü aleyhi ve sellem) için de hicret yolculuğu 622 yılında gerçekleşti. Hicreti yalnız haritada bir çizgi olarak görmeyelim: Evden ayrılmak, güvenli bir varış yeri bulmak ve yeni bir topluluk hayatı kurmak bu sürecin birbirine bağlı parçalarıydı."},{"title":"Yol arkadaşı ve görev paylaşımı","kind":"community","labels":["Hazret-i Ebû Bekr","Hazret-i Ali","Yol rehberi"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) yolculuğa Hazret-i Ebû Bekr ile çıktı. Yol bilgisine sahip bir rehberle anlaşılmış, ulaşım ve buluşma için hazırlık yapılmıştı. Hazret-i Ali'ye de emanetlerin sahiplerine ulaştırılması görevi verildi. Böylece yolculuk hazırlığı yalnız yola çıkacak kişilerin ihtiyaçlarından oluşmadı; geride yerine getirilmesi gereken sorumluluklar da gözetildi. Güvenilir olmak, zor bir anda bile başkasına ait hakkı unutmamayı gerektiriyordu."},{"title":"Sevr'de bekleme","kind":"journey","labels":["Mekke çevresi","Sevr mağarası","Üç gün"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) ve Hazret-i Ebû Bekr, yolculuğun başlangıcında Sevr mağarasında üç gün kaldı. Sevr, ilk vahyin geldiği Hira ile aynı yer değildir. Hazırlıkta belirlenen buluşma ve rehber desteğiyle yolculuk daha sonra devam etti. Burada beklemek, yolculuğun amacından vazgeçmek anlamına gelmez; güvenliği gözeten planın bir aşamasıdır. Haritada mağara adını, işlevini ve dönemi ayrı okuyalım."},{"title":"Tedbir ve tevekkül","kind":"values","labels":["Hazırlık","Görev paylaşımı","Allahü teâlâya güven"],"narration":"Hicret örneğinde tedbir almak ile Allahü teâlâya güvenmek birlikte görülür. Yol rehberi seçmek, ulaşımı hazırlamak ve görev paylaşmak insanın sorumluluğunu yerine getirmesidir. Sonucu bütünüyle kontrol ettiğini sanmamak ise hazırlığı değersiz kılmaz. Bugünkü bir okul gezisini hicretle aynı saymıyoruz; fakat sorumlu hazırlığın güvenle çelişmediğini anlamak için kendi hayatımızdan daha küçük ve uygun örnekler üzerinde düşünebiliriz."}],"game":{"kind":"sequence","title":"Hicretin hazırlık ve yol basamakları","prompt":"Kartları bu derste anlatılan akışa göre yerleştir; Hira ile Sevr'i karıştırma.","items":[{"text":"Yesrib'de destek ortamının oluşması","explanation":"Akabe süreci hicretin toplumsal hazırlığını sağladı."},{"text":"Ulaşım, rehber ve görevlerin planlanması","explanation":"Yolculuktan önce tedbir alındı."},{"text":"Mekke'den ayrılıp Sevr'de kalınması","explanation":"Sevr, hicret yolculuğunun başlangıcındaki konaktır."},{"text":"Rehber eşliğinde yolculuğun sürdürülmesi","explanation":"Beklemenin ardından varış yönündeki yol devam etti."}]},"decision":{"question":"Bir sunum 'Hicrette hiçbir hazırlık yapılmadı; yalnız güvenildi' diyor. Hangi kanıt bunu düzeltir?","options":["Rehber, ulaşım ve görev paylaşımına ilişkin bilgiler","Mekke'nin bir şehir olması","Hicret sözcüğünün kısa olması"],"answer":0,"explanations":["Bu somut hazırlıklar, güvenin sorumluluk almayı dışlamadığını gösterir.","Şehir bilgisi doğru olsa da hazırlık iddiasını sınamaz.","Sözcüğün biçimi tarihî olayın nasıl gerçekleştiğine kanıt olmaz."]},"quiz":[{"question":"Hicret yolculuğunda Sevr mağarasının yeri nedir?","options":["İlk vahyin geldiği yer","Başlangıçta bir süre kalınan yer","Medine'de kurulan mescid"],"answer":1,"explanation":"İlk vahiy Hira ile ilişkilidir; Sevr ise hicret yolculuğunda farklı bir işleve sahiptir."},{"question":"Emanetlerin sahiplerine ulaştırılması hangi tutumu gösterir?","options":["Yolculuğun iptal edildiğini","Geride kalan hakların önemsiz olduğunu","Zor şartlarda da sorumluluğun gözetildiğini"],"answer":2,"explanation":"Kendi güvenliğiyle ilgilenmek, başkasının hakkını unutmak anlamına gelmez."},{"question":"Tedbir ve tevekkül için doğru ifade hangisidir?","options":["Hazırlık ve Allahü teâlâya güven birlikte olabilir","Hazırlık yapılırsa tevekkül olmaz","Tevekkül için görevler bırakılmalıdır"],"answer":0,"explanation":"Dersin somut hazırlıkları bu iki tutumun birlikte olabileceğini gösterir."}],"teacher":{"misconception":"Hira/Sevr ayrımını özellikle kontrol edin; bütün Müslümanların tek kafilede çıktığını söylemeyin.","differentiation":"5–6. sınıf hazırlık örneklerini saysın; 7–8. sınıf bir iddiayı üç tarihî kanıtla düzeltsin.","exit":"Hicrette hazırlığa iki örnek ver ve Sevr'in işlevini bir cümleyle açıkla."},"sources":[{"title":"TDV — Hicret","url":"https://islamansiklopedisi.org.tr/hicret"},{"title":"TDV — Hazret-i Ebû Bekr","url":"https://islamansiklopedisi.org.tr/ebu-bekir"},{"title":"TDV — Hazret-i Ali","url":"https://islamansiklopedisi.org.tr/ali"}]},{"id":28,"module":5,"title":"Kubâ'dan Medine'ye","date":"622 / Hicretin birinci yılı","objective":"Hicretin varış aşamasını ve Medine adını tanır.","hook":{"question":"Bir yolculuğun sonuna yaklaşırken uğranan yer ile asıl yerleşilen şehir aynı şey midir?","options":["Evet, bütün duraklar aynı sayılır","Hayır, varış aşamasında da farklı duraklar olabilir","Yalnız kısa yolculuklarda farklıdır"],"note":"Kubâ ile Medine merkezini ayrı işaretleyin; bunları ayrı ülkeler gibi sunmayın."},"frames":[{"title":"Medine çevresindeki Kubâ","kind":"map","labels":["Hicret yolu","Kubâ","Medine merkezi"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem), hicret yolculuğunun sonunda Medine merkezine geçmeden önce Kubâ'da kaldı. Kubâ, Medine çevresindeki bir yerleşimdi; Habeşistan gibi başka bir ülke veya Mekke'nin başka adı değildi. Varış bölgesine ulaşmakla şehir merkezine yerleşmeyi ayırdığımızda yolculuğun son aşaması daha anlaşılır olur. Şemada Kubâ'yı Medine'yle ilişkisi içinde okuyalım; şema ayrıntılı tarihî sokak planı değildir."},{"title":"Kubâ'daki mescid","kind":"city","labels":["Kubâ","Mescid","Birlikte çalışma"],"narration":"Kubâ'da bir mescidin kuruluşuna Peygamber Efendimiz (sallallahü aleyhi ve sellem) bizzat katıldı. Bu çalışma, hicretin yalnız yer değiştirme değil, yeni yerde ibadet ve topluluk hayatı kurma süreci olduğunu gösterir. Kubâ Mescidi ile daha sonra Medine merkezinde yapılacak Mescid-i Nebevî'yi ayırmamız gerekir. İkisi de hicretin varış dönemindeki önemli mekânlardır, fakat aynı bina veya birbirinin farklı adı değildir."},{"title":"Şehir merkezine doğru","kind":"route","labels":["Kubâ","Rânûnâ vadisi","Medine"],"narration":"Kubâ'dan ayrıldıktan sonra Peygamber Efendimiz (sallallahü aleyhi ve sellem), Rânûnâ vadisinde cuma namazını kıldırdı ve Medine'ye ulaştı. Bu son aşamada yer adlarını sırayla görmek yolculuğun nasıl tamamlandığını anlamamıza yardım eder. Bir olayın aynı yol üzerinde gerçekleşmesi, bütün durakların aynı işleve sahip olduğu anlamına gelmez; Kubâ'da mescid, Rânûnâ'da cuma ve şehir merkezinde yerleşme bilgilerini ayrı kutulara yerleştirelim."},{"title":"Misafirlikten yerleşmeye","kind":"home","labels":["Hazret-i Ebû Eyyûb","Misafirlik","Medine hayatı"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem), Medine'de Hazret-i Ebû Eyyûb el-Ensârî'nin evinde misafir oldu. Yesrib şehri hicretten sonra Medine adıyla tanındı. Ev sahipliği, yeni gelenlerin yerleşme sürecinde somut bir destek örneğiydi. Bu bilgi bize hem bir kişi hem de toplumsal bir işlev tanıtır: Misafir ağırlamak yalnız hoş geldin demekle bitmez; barınma, rahatlık ve günlük ihtiyaçları gözetmeyi de içerir."}],"game":{"kind":"sequence","title":"Varışın son durakları","prompt":"Bu derste yer alan yer ve olayları yolculuk akışına göre sırala.","items":[{"text":"Hicret yolculuğunda Medine çevresine ulaşmak","explanation":"Yolun son bölümünde varış bölgesine gelinir."},{"text":"Kubâ'da kalmak ve mescidin kuruluşuna katılmak","explanation":"Kubâ, şehir merkezinden önceki duraktır."},{"text":"Rânûnâ vadisinde cuma namazı","explanation":"Kubâ'dan Medine'ye geçiş sırasında gerçekleşir."},{"text":"Medine merkezine ulaşmak","explanation":"Sonraki yerleşme ve topluluk hayatının merkezi burasıdır."},{"text":"Hazret-i Ebû Eyyûb'un evinde misafir olmak","explanation":"Yeni dönemde barınma ve ev sahipliği desteği sağlanır."}]},"decision":{"question":"Bir öğrenci Kubâ Mescidi ile Mescid-i Nebevî'yi aynı fotoğrafın iki adı olarak yazmış. Hangi düzeltme gerekir?","options":["İki adı da kaldırıp yalnız mescid yazmak","Kubâ'daki mescid ile Medine merkezindeki mescidi ayrı mekânlar olarak göstermek","İkisinin de Mekke'de olduğunu söylemek"],"answer":1,"explanations":["İsimleri silmek iki önemli yerin farkını öğrenmemizi engeller.","Aynı döneme bağlı olmaları, aynı yapı oldukları anlamına gelmez.","Her iki mekân da Medine çevresi ve Medine hayatıyla ilişkilidir."]},"quiz":[{"question":"Kubâ'nın bu dersteki yeri hangisidir?","options":["Medine merkezine geçmeden önce kalınan yer","İlk vahyin geldiği mağara","Habeşistan'daki liman"],"answer":0,"explanation":"Kubâ, hicretin Medine'ye varış aşamasında ele alınır."},{"question":"Medine'deki ev sahipliği hangi kişiyle ilişkilidir?","options":["Hazret-i Necâşî","Hazret-i Erkam","Hazret-i Ebû Eyyûb el-Ensârî"],"answer":2,"explanation":"Hazret-i Ebû Eyyûb, hicret sonrasında evinde misafir etmesiyle tanınır."},{"question":"Yesrib ve Medine için doğru ilişki hangisidir?","options":["Birbirinden tamamen ayrı iki ülkedir","Hicret sonrasında Medine adıyla tanınan aynı şehir söz konusudur","İki farklı mağaranın adıdır"],"answer":1,"explanation":"Ad değişimi şehir değişimi gibi anlaşılmamalıdır."}],"teacher":{"misconception":"Kubâ'yı ayrı ülke, Yesrib'i Medine'den ayrı şehir, iki mescidi tek yapı gibi göstermeyin.","differentiation":"5–6. sınıf durakları sıralasın; 7–8. sınıf yer adı ile o yerdeki işlevi birlikte açıklasın.","exit":"Kubâ, Medine ve Hazret-i Ebû Eyyûb adlarını kullanarak varış aşamasını anlat."},"sources":[{"title":"TDV — Hicret","url":"https://islamansiklopedisi.org.tr/hicret"},{"title":"TDV — Medine","url":"https://islamansiklopedisi.org.tr/medine"},{"title":"TDV — Hazret-i Ebû Eyyûb el-Ensârî","url":"https://islamansiklopedisi.org.tr/ebu-eyyub-el-ensari"},{"title":"TDV — Mescid-i Nebevî","url":"https://islamansiklopedisi.org.tr/mescid-i-nebevi"}]},{"id":29,"module":5,"title":"Mescid-i Nebevî ve öğrenen toplum","date":"622 ve sonrası","objective":"Mescid-i Nebevî'nin ibadet, eğitim ve buluşma işlevlerini tanır.","hook":{"question":"Bir mekân hem ibadet hem öğrenme hem de görüşme için kullanılabilir mi?","options":["Hayır, bir mekânın yalnız bir işi olabilir","Ancak çok büyükse olabilir","Evet, kullanım amacı ve düzen buna imkân sağlayabilir"],"note":"Bugünkü büyük yapı fotoğraflarıyla ilk sade yapıyı birbirine karıştırmadan işlev kavramını açın."},"frames":[{"title":"Yeni şehirde ortak bir merkez","kind":"city","labels":["Medine","Mescid-i Nebevî","Ortak emek"],"narration":"Hicretten sonra Medine'de gerçekleştirilen önemli işlerden biri Mescid-i Nebevî'nin inşasıydı. Peygamber Efendimiz (sallallahü aleyhi ve sellem) yapım çalışmalarına bizzat katıldı. Muhacirlerle ensarın birlikte çalışması, yeni toplumun ortak iş yapmasına da imkân verdi. Bu yüzden inşayı yalnız taş ve duvarlardan oluşan bir olay olarak okumayalım; mekân hazırlanırken insanlar arasında çalışma, sorumluluk ve yardımlaşma bağları da güçleniyordu."},{"title":"Sade bir yapı","kind":"home","labels":["Kerpiç duvar","Hurma kütükleri","Gölgelik"],"narration":"Mescid-i Nebevî'nin ilk yapısı sadeydi; kerpiç duvarlar ve hurma kütükleri gibi dönemin malzemeleri kullanıldı. Zaman içinde bina genişletildi ve değişti. Bugünkü büyük kubbeleri, minareleri ve avluları ilk yapının aynısı gibi düşünmemeliyiz. Bir tarihî mekânın bugünkü fotoğrafı, ilk inşa gününü doğrudan göstermez; dönemleri ayırmak, mimari görselleri de kaynak bilgisiyle birlikte okumamızı gerektirir."},{"title":"İbadet, öğrenme ve görüşme","kind":"community","labels":["İbadet","Eğitim","Toplumsal görüşmeler"],"narration":"Mescid-i Nebevî ibadet edilen bir yer olmasının yanında, dinî bilgilerin öğrenildiği ve toplumsal meselelerin görüşüldüğü bir merkezdi. İnsanlar burada bir araya geliyor, sorularını soruyor ve ihtiyaçlarını konuşabiliyordu. Aynı yapıda farklı işler yapılması, bu işlerin birbirinin aynısı olduğu anlamına gelmez. Ekrandaki işlev kartlarını ayrı inceleyelim: Namaz ibadet, bir konuyu öğrenme eğitim, ortak meseleyi değerlendirme ise görüşme işlevini gösterir."},{"title":"Suffe ve öğrenen topluluk","kind":"book","labels":["Suffe","Öğrenme","Dayanışma"],"narration":"Mescidle bağlantılı Suffe, barınma ihtiyacı bulunan bazı sahâbîlerin kaldığı ve öğrenmeyle meşgul olduğu yer olarak tanındı. Böylece eğitim ile dayanışma arasında somut bir bağ oluştu. Bir öğrenme ortamının iyi işlemesi için yalnız bir öğreticinin bulunması yetmez; insanların oraya ulaşabilmesi, ihtiyaçlarının gözetilmesi ve birbirini saygıyla dinlemesi de önemlidir. Bu son ilkeler, tarihî örnekten hareketle kendi sınıfımız için düşündüğümüz uygulamalardır."}],"game":{"kind":"classify","title":"Yapı bilgisi mi, kullanım mı?","prompt":"Mescidle ilgili kartları yapı özelliği veya kullanım işlevi olarak ayır.","groups":["Yapı ve malzeme","Kullanım işlevi"],"items":[{"text":"Kerpiç duvarların bulunması","group":0,"explanation":"Bu, ilk yapının malzemesiyle ilgili bilgidir."},{"text":"Hurma kütüklerinin kullanılması","group":0,"explanation":"Yapıyı oluşturan malzemeyi anlatır."},{"text":"Zamanla genişletilmesi","group":0,"explanation":"Binanın farklı dönemlerde geçirdiği değişimi bildirir."},{"text":"Birlikte namaz kılınması","group":1,"explanation":"Mescidin ibadet işlevini gösterir."},{"text":"Dinî bilgilerin öğrenilmesi","group":1,"explanation":"Eğitim işlevini açıklar."},{"text":"Toplumsal meselelerin görüşülmesi","group":1,"explanation":"İnsanların ortak konuları ele aldığı kullanımı anlatır."}]},"decision":{"question":"Bir sunumda bugünkü Mescid-i Nebevî fotoğrafının altına '622'deki yapı aynen böyleydi' yazılmış. Nasıl düzeltirsin?","options":["Bugünkü görünüm ile ilk sade yapıyı dönemleriyle ayırırım","Sadece fotoğrafı büyütürüm","Yapının zamanla değişmediğini eklerim"],"answer":0,"explanations":["Tarihî yapılar farklı dönemlerde değişebilir; fotoğrafın gösterdiği zaman belirtilmelidir.","Görüntüyü büyütmek tarih yanlışını düzeltmez.","Kaynaklar genişletme ve değişiklikleri anlatır; böyle bir ek yanlışlığı artırır."]},"quiz":[{"question":"Mescid-i Nebevî'nin kuruluşu hangi dönemdedir?","options":["İlk vahiyden önce Mekke'de","Hicret sonrasında Medine'de","Habeşistan yolculuğu sırasında"],"answer":1,"explanation":"Mescid, yeni Medine toplumunun önemli merkezlerinden biri olarak kuruldu."},{"question":"Aşağıdaki üçlüden hangisi mescidin işlevlerini anlatır?","options":["Kerpiç, direk, duvar","Yol, liman, kervan","İbadet, öğrenme, görüşme"],"answer":2,"explanation":"İşlev, yapının ne için kullanıldığıdır; malzeme listesi farklı bir soruya cevap verir."},{"question":"Suffe örneği hangi ilişkiyi gösterir?","options":["Öğrenme ile ihtiyaçları gözetmenin bağlantısını","Yalnız görkemli yapıların eğitim verebileceğini","Mescidde öğrenmenin bulunmadığını"],"answer":0,"explanation":"Barınma ve öğrenmeyle ilişkili Suffe, eğitim ile dayanışmayı birlikte düşünmemizi sağlar."}],"teacher":{"misconception":"Bugünkü cami görünümünü ilk yapı diye sunmayın; Suffe'yi bugünkü yatılı okulun bütün özellikleriyle aynı saymayın.","differentiation":"5–6. sınıf malzeme/işlev ayırsın; 7–8. sınıf bir fotoğrafın tarihî kanıt olarak sınırını açıklasın.","exit":"Mescid-i Nebevî'nin üç işlevini ve ilk yapıya ait bir özelliği söyle."},"sources":[{"title":"TDV — Mescid-i Nebevî","url":"https://islamansiklopedisi.org.tr/mescid-i-nebevi"},{"title":"TDV — Suffe","url":"https://islamansiklopedisi.org.tr/suffe"},{"title":"TDV — Medine","url":"https://islamansiklopedisi.org.tr/medine"}]},{"id":30,"module":5,"title":"Kardeşlik ve birlikte yaşama","date":"Hicretin ilk yılları","objective":"Muâhâtı ve Medine'deki ortak sorumluluk düzenini birbirinden ayırır.","hook":{"question":"Yeni gelenlere yardım etmek ile herkes için ortak kurallar koymak aynı iş midir?","options":["Tamamen aynıdır","Birbirini tamamlayan ama farklı işlerdir","Birlikte yapılamazlar"],"note":"Muâhât ve vesikayı günlük örnek üzerinden ayırın; tarihî kurumları bugünkü sınıf düzeniyle özdeşleştirmeyin."},"frames":[{"title":"Muhacir ve ensar","kind":"community","labels":["Muhacir","Ensar","Medine"],"narration":"Mekke'den Medine'ye hicret eden Müslümanlara muhacir, Medine'de onlara yardım eden Müslümanlara ensar denildi. Bu kelimeler yalnız iki kişinin özel adı değildir; hicret sürecindeki toplulukları ve üstlendikleri rolleri tanıtır. Göç edenlerin yerleşme ve geçim ihtiyaçları vardı. Yardım edenlerin desteği de bu ihtiyaçların karşılanmasına katkı sağladı; iki kavramı yolculuk ve yardım ilişkisi içinde birlikte öğrenelim."},{"title":"Muâhât: kardeşlik bağı","kind":"family","labels":["Muhacirler","Ensar","Muâhât"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem), muhacirlerle ensardan bazı kişileri kardeş ilân etti. Muâhât adı verilen bu bağ, kan bağıyla kardeş olma anlamına gelmiyordu; din kardeşliğini karşılıklı sorumluluk ve dayanışmayla güçlendiriyordu. Yeni gelenlerin hayat kurmasına yardım etmek, yalnız bir karşılama töreniyle biten iş değildi. Paylaşma, birbirini gözetme ve gündelik ihtiyaçlarla ilgilenme bu kardeşlik anlayışını somutlaştıran davranışlar olarak düşünülmelidir."},{"title":"Şehirde farklı topluluklar","kind":"city","labels":["Müslümanlar","Yahudi topluluklar","Diğer şehir sakinleri"],"narration":"Medine'de yalnız tek bir inanç grubundan insanlar yaşamıyordu. Müslümanlarla birlikte Yahudi topluluklar ve başka şehir sakinleri de bulunuyordu. Yeni şehir hayatında farklı grupların ilişkilerini, güvenliği ve ortak sorumlulukları düzenlemek gerekiyordu. İnsanların aynı şehirde yaşaması bütün inançlarının veya geleneklerinin aynı olduğu anlamına gelmez; birlikte yaşama düzeni bu farklılıkları yok saymadan hak ve sorumlulukları ele almayı gerektirir."},{"title":"Medine Vesikası","kind":"agreement","labels":["Ortak sorumluluk","İlişkilerin düzeni","Medine Vesikası"],"narration":"Medine Vesikası, şehirdeki grupların ilişkileri ve ortak sorumluluklarıyla ilgili bir metindir. Muâhât ise muhacirlerle ensar arasında kurulan kardeşlik bağıdır. İkisi de yeni toplumun düzenine katkı verir; fakat birbirinin farklı adı değildir. Vesikayı bugünkü bir anayasanın bütün ayrıntılarıyla aynı saymak da doğru olmaz. Tarihî metni kendi dönemi içinde, hangi ihtiyaçlara cevap verdiğini sorarak okumalıyız."}],"game":{"kind":"classify","title":"Kardeşlik bağı mı, ortak düzen mi?","prompt":"Her kartı doğrudan ilgili olduğu başlığa yerleştir.","groups":["Muâhât","Medine Vesikası"],"items":[{"text":"Muhacir ile ensardan kişilerin kardeş ilân edilmesi","group":0,"explanation":"Muâhât, belirli kişiler arasında kardeşlik bağı kurar."},{"text":"Yeni gelenin yerleşme ve geçim ihtiyacına destek","group":0,"explanation":"Kardeşlik ilişkisinin gündelik dayanışma boyutudur."},{"text":"Kan bağı olmadan din kardeşliği kurulması","group":0,"explanation":"Burada biyolojik akrabalık değil, sorumluluk bağı vardır."},{"text":"Şehirdeki farklı grupların ilişkilerinin düzenlenmesi","group":1,"explanation":"Vesika ortak şehir düzenine ilişkin bir metindir."},{"text":"Ortak güvenlikle ilgili sorumlulukların belirlenmesi","group":1,"explanation":"Farklı grupları ilgilendiren ortak meseleleri ele alır."},{"text":"Birlikte yaşamanın yazılı esaslarının ele alınması","group":1,"explanation":"Yazılı düzenleme, kardeşlik ilânıyla aynı işlem değildir."}]},"decision":{"question":"Bir öğrenci 'Muâhât ile Medine Vesikası aynı şeydir; ikisi de yardım demek' diyor. Hangi açıklama yeterlidir?","options":["İkisinin de Medine'de olduğunu tekrarlamak","İsimlerinden birini silmek","Birinin kardeşlik bağı, diğerinin ortak ilişkileri düzenleyen metin olduğunu açıklamak"],"answer":2,"explanations":["Ortak yer bilgisi aralarındaki işlev farkını göstermez.","İsmi silmek iki ayrı gelişmeyi öğrenmemizi engeller.","İkisi birbirini tamamlayabilir; fakat kapsamları ve biçimleri farklıdır."]},"quiz":[{"question":"Ensar kelimesi bu bağlamda kimleri tanıtır?","options":["Mekke'den göç eden Müslümanları","Medine'de yardım eden Müslümanları","Habeşistan'a gönderilen Mekkeli temsilcileri"],"answer":1,"explanation":"Muhacir göç eden, ensar yardımcı olan topluluğu belirtir."},{"question":"Muâhât ile ilgili doğru ifade hangisidir?","options":["Din kardeşliğini dayanışma ve sorumlulukla güçlendirir","Herkesin kan bağıyla akraba olduğunu bildirir","Şehirdeki bütün grupların aynı inançta olduğunu gösterir"],"answer":0,"explanation":"Kardeşlik ilânı biyolojik akrabalık veya bütün şehrin tek inancı olduğu iddiası değildir."},{"question":"Medine Vesikası hangi soruya cevap verir?","options":["İlk vahiy hangi mağarada geldi?","Habeşistan'a hangi denizden geçildi?","Şehirdeki farklı grupların ortak ilişkileri nasıl düzenlenecek?"],"answer":2,"explanation":"Vesikanın odağı yeni toplumda ilişkiler ve ortak sorumluluklardır."}],"teacher":{"misconception":"Muhacir/ensarı kişi adı, muâhâtı biyolojik akrabalık veya vesikayı bütün grubun tek inanca geçtiği belge gibi sunmayın.","differentiation":"5–6. sınıf iki kurumun kartlarını ayırsın; 7–8. sınıf dayanışma ve ortak kuralların birbirini nasıl tamamladığını açıklasın.","exit":"Muhacir, ensar, muâhât ve Medine Vesikası kelimelerinin her birini bir cümlede doğru kullan."},"sources":[{"title":"TDV — Muâhât","url":"https://islamansiklopedisi.org.tr/muahat"},{"title":"TDV — Medine Vesikası","url":"https://islamansiklopedisi.org.tr/medine-vesikasi"},{"title":"TDV — Ensar","url":"https://islamansiklopedisi.org.tr/ensar"}]},{"id":31,"module":6,"title":"Aynı yöne yönelmek: Kıble","date":"624 / Hicrî 2","objective":"Kıblenin değişmesini ve ibadette birlik düşüncesini açıklar.","hook":{"question":"İstanbul ve Medine'deki iki kişi namazda farklı pusula yönlerine dönebilir mi?","options":["Evet; ikisi de bulundukları yerden Kâbe'ye yönelir.","Hayır; herkes pusulada aynı yönü seçmelidir.","Ancak aynı şehirde yaşayanlar aynı kıbleyi paylaşabilir."],"note":"Önce tahminleri alın; doğru cevabı haritadaki oklar üzerinden açıklayın. İbadetin Allahü teâlâ için olduğu ayrımını koruyun."},"frames":[{"title":"Üç şehir, iki yön","kind":"map","labels":["Kudüs","Medine","Mekke"],"narration":"Hicretten sonra Müslümanlar Medine'de bir süre namazlarını Kudüs yönüne dönerek kıldılar. Haritada önce Medine'yi, sonra Kudüs'ü bul. İki şehir arasında çizilen ok bir yolculuğu değil, namazda yönelinen doğrultuyu gösteriyor. Haritadaki işaretlerin ne anlattığını anlamak, yalnız şehir adlarını ezberlemekten daha önemlidir. Şimdi Mekke'nin Medine'ye göre hangi tarafta kaldığını incele."},{"title":"Medine döneminde değişen kıble","kind":"timeline","labels":["622: Hicret","Kudüs yönü","624: Kâbe yönü"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) Medine'de iken kıblenin Kâbe yönüne çevrilmesini bildiren ilahî emir geldi. Bu gelişme hicretin ikinci yılına, milâdî 624'e yerleştirilir. Zaman çizgisinde önce hicreti, sonra kıble değişikliğini görürüz. Böylece aynı şehirde yaşayan topluluğun namaz yönünün zaman içinde değiştiğini anlarız. Değişikliğin dayanağı insanların kendi aralarında yaptığı bir yön seçimi değildi."},{"title":"Yönelinen yer ve ibadet edilen","kind":"values","labels":["Kâbe: kıble","Namaz: ibadet","Allahü teâlâ"],"narration":"Kıble, namazda yönelinen doğrultudur; Müslümanlar Kâbe'ye ibadet etmez. İbadet Allahü teâlâ içindir. Bu iki bilgiyi ayırmak, konunun temelini doğru anlamamızı sağlar. Bir işaretin yön göstermesiyle ibadetin kime yapıldığı aynı soru değildir. Ekrandaki iki başlığı karşılaştır: Birincisi mekânla, ikincisi inançla ilgilidir. Açıklamanı yaparken ikisini birbirinin yerine kullanmamaya dikkat et."},{"title":"Farklı yerlerden ortak merkeze","kind":"map","labels":["Bulunduğumuz yer","Yön oku","Ortak kıble"],"narration":"Dünyanın farklı yerlerinde yaşayan Müslümanlar, bulundukları konuma göre Kâbe'ye yönelir. Bu yüzden pusuladaki yön herkes için aynı olmayabilir. Şemada farklı noktalardan aynı merkeze uzanan okları takip et. Ortak bir kıble, uzakta yaşayan insanların ibadetinde birlik olduğunu gösterir. Gerçek kıble belirlenirken doğru konum bilgisi ve güvenilir yöntem gerekir; bu çizim yalnız düşünceyi açıklayan bir şemadır."}],"game":{"kind":"classify","title":"Yön mü, ibadet mi?","prompt":"Kartların hangi soruyu cevapladığını ayır.","groups":["Nereye yöneliriz?","Kime ibadet ederiz?"],"items":[{"text":"Namazda Kâbe doğrultusunu seçmek","group":0,"explanation":"Bu bilgi namazda yönelinen yeri açıklar."},{"text":"Namazı Allahü teâlâ için kılmak","group":1,"explanation":"İbadetin muhatabı Allahü teâlâdır."},{"text":"Bulunduğumuz yerden kıbleyi belirlemek","group":0,"explanation":"Konum, kıble doğrultusunu bulmak için kullanılır."},{"text":"Duada Allahü teâlâya yönelmek","group":1,"explanation":"Burada yön kelimesi ibadetin kime yapıldığıyla ilgilidir."},{"text":"Haritada Medine'den Mekke'ye ok çizmek","group":0,"explanation":"Ok bir mekân doğrultusunu gösterir."},{"text":"Kâbe'ye dönmenin Kâbe'ye ibadet olmadığını söylemek","group":1,"explanation":"Bu ayrım ibadetin yalnız Allahü teâlâya yapıldığını belirtir."}]},"decision":{"question":"Bir arkadaşın 'Kıble değişince ibadet edilen de değişmiş' diyor. Hangi açıklama doğru?","options":["Yalnız namaz kılınan şehir değişti.","Yön değişti; ibadet yine Allahü teâlâ içindi.","Önce Kudüs'e, sonra Kâbe'ye ibadet edildi."],"answer":1,"explanations":["Kıble değişikliği için Medine'den taşınmak gerekmedi; değişen namaz yönüydü.","Doğru: mekân doğrultusu ile ibadetin muhatabını birbirinden ayırdın.","Kudüs ve Kâbe ibadet edilen varlıklar değildir; ibadet Allahü teâlâ içindir."]},"quiz":[{"question":"Medine'de kıble değişikliğini gösteren sıra hangisidir?","options":["Kâbe yönü → Kudüs yönü","Medine yönü → Mekke yönü","Kudüs yönü → Kâbe yönü"],"answer":2,"explanation":"Hicretten sonra bir süre Kudüs'e yönelindi; ilahî emirle Kâbe yönüne dönüldü."},{"question":"Haritada farklı yerlerden aynı merkeze uzanan oklar neyi açıklar?","options":["Ortak kıbleye farklı konumlardan yönelmeyi","Herkesin Mekke'ye göç ettiğini","Bütün şehirlerin aynı pusula yönünde olduğunu"],"answer":0,"explanation":"Oklar ortak merkeze yönelmeyi anlatır; yolculuk veya göç göstermeleri gerekmez."},{"question":"Kıble değişikliği zaman çizgisinde nereye yerleştirilir?","options":["İlk vahiyden önceki Mekke yıllarına","Hicretten sonraki Medine yıllarına","Veda haccından sonraki yıllara"],"answer":1,"explanation":"Olay 624, hicrî ikinci yıldadır; bu nedenle hicretten sonraki Medine dönemine aittir."}],"teacher":{"misconception":"Kâbe'ye yönelmek ile Kâbe'ye ibadet etmek birbirine karıştırılmamalı. Şematik harita gerçek kıble ölçüm aracı değildir.","differentiation":"5–6. sınıfta okların başlangıç ve bitişini okutun; 7–8. sınıfta farklı konumlardan aynı merkeze yönelmeyi gerekçelendirin.","exit":"Kıblede değişen şey …; ibadetin muhatabı ise … cümlesini tamamla."},"sources":[{"title":"TDV — Kıble","url":"https://islamansiklopedisi.org.tr/kible"}]},{"id":32,"module":6,"title":"Bedir: Zor kararlar ve istişare","date":"624 / Hicrî 2","objective":"Bedir'in tarihî bağlamını ve danışmanın önemini kavrar.","hook":{"question":"Bir ekip zor bir karardan önce neden farklı görüşler dinler?","options":["Karar sorumluluğunu tamamen başkasına bırakmak için.","Bilmediği ayrıntıları fark edip daha bilinçli karar vermek için.","Her öneriyi aynı anda uygulamak için."],"note":"İstişareyi yalnız oylama sanan öğrencilerden, iyi bir önerinin nasıl değerlendirileceğine örnek isteyin."},"frames":[{"title":"Hicretten sonra süren gerilim","kind":"timeline","labels":["622: Hicret","Gerilim sürüyor","624: Bedir"],"narration":"Hicretle Medine'de yeni bir hayat başlamıştı; fakat Mekke'deki Kureyş ile yaşanan gerilim bitmemişti. Bedir'i anlamak için bu arka planı hatırlamak gerekir. Olayları yalnız tek bir günün içine sıkıştırırsak öncesindeki şartları gözden kaçırırız. Zaman çizgisinde hicret ile Bedir arasındaki aralığı incele. Aynı çizgide bulunmaları, iki olayın aynı olay olduğu anlamına gelmez."},{"title":"Kervan, haber ve karşılaşma","kind":"route","labels":["Medine","Kervan güzergâhı","Bedir çevresi"],"narration":"Mekke'ye dönen Kureyş kervanıyla ilgili gelişmeler, tarafların hareketlenmesine yol açtı. Ardından Müslümanlarla Mekke'den gelen Kureyş ordusu Bedir çevresinde karşılaştı. Haritada yol, yerleşim ve karşılaşma bölgesi farklı işaretlerle gösteriliyor. Bu işaretler bir savaş oyununun hedefleri değildir. Amaç, bir haberin ve karşılıklı hareketlerin nasıl daha büyük bir tarihî gelişmeye dönüştüğünü anlamaktır."},{"title":"Görüş sormak ve gerekçe dinlemek","kind":"community","labels":["Görüş","Gerekçe","Karar"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) hazırlık sırasında Eshâb-ı kirâmın görüşlerini dinledi. İstişare, bir konuda bilgisi veya tecrübesi olan insanların düşüncelerini değerlendirmektir. Her görüşün aynı anda uygulanması gerekmez; önerinin gerekçesi ve içinde bulunulan şartlar önemlidir. Bir sınıf çalışmasında da yalnız en yüksek sesle söylenen öneriyi seçmek yerine, önerinin problemi nasıl çözdüğünü açıklamak daha sağlıklı karar vermeyi sağlar."},{"title":"Sonuç ve tarih okuması","kind":"book","labels":["Bedir","624 / Hicrî 2","Sonuç ve sorumluluk"],"narration":"Bedir Savaşı 624 yılında Müslümanların üstünlüğüyle sonuçlandı. Ancak bir tarih dersinde yalnız sonucu söylemek yeterli değildir. Olayın öncesini, kararları ve sonrasında ortaya çıkan sorumlulukları birlikte düşünürüz. Bugünkü ders, hazırlık ve danışma üzerinde duruyor. Sonraki bölümde savaş sonrasında insanlara nasıl davranıldığına bakacağız. Böylece bir olayı tek kelimelik bir başarı etiketine indirgemeden öğrenmiş oluruz."}],"game":{"kind":"sequence","title":"Bir kararı anlamanın adımları","prompt":"Bedir'i tarihî bağlamıyla okumak için aşamaları sırala.","items":[{"text":"Hicretten sonra süren gerilimi öğren","explanation":"Bedir'den önceki şartları bilmek, olayın arka planını açıklar."},{"text":"Kervanla ilgili gelişmeleri ve hareketleri incele","explanation":"Tarafları Bedir çevresine getiren gelişmeler bundan sonra ele alınır."},{"text":"Hazırlık ve istişareyi değerlendir","explanation":"Kararların hangi şartlarda alındığını anlamaya çalışırız."},{"text":"Karşılaşmanın sonucunu ve sonraki sorumlulukları konuş","explanation":"Tarih okuması sonuçla birlikte sonrasını da kapsar."}]},"decision":{"question":"Sınıf gezisinde bir öğrenci güzergâhın kapalı olduğunu söylüyor. İstişareye uygun tutum hangisidir?","options":["Çoğunluk eski yolu istediği için bilgiyi dikkate almamak.","Yeni bilgiyi doğrulayıp diğer önerileri de değerlendirerek karar vermek.","Kararı hiç değiştirmemek için yalnız ilk öneriyi dinlemek."],"answer":1,"explanations":["Çoğunluğun tercihi, doğrulanmış önemli bir bilgiyi gereksiz hâle getirmez.","Doğru: istişare, görüş kadar gerekçeyi ve yeni bilgiyi de değerlendirmeyi gerektirir.","İlk öneri yararlı olabilir; fakat başka bilgileri dinlememek istişareyi sınırlar."]},"quiz":[{"question":"Bedir'i hicretten bağımsız anlatmak hangi bilgiyi eksiltir?","options":["Sonuçta hangi tarafın üstün geldiğini","Kervanların hangi araçları kullandığını","Mekke ile Medine arasındaki süren gerilimi"],"answer":2,"explanation":"Hicretten sonra gerilim bitmediği için Bedir'in arka planı bu dönemle bağlantılıdır."},{"question":"İstişareyi en iyi açıklayan davranış hangisidir?","options":["Görüşleri gerekçeleriyle dinleyip değerlendirmek","Her öneriyi değiştirmeden uygulamak","En çok konuşan kişinin kararını kabul etmek"],"answer":0,"explanation":"İstişare düşünceleri değerlendirmeyi içerir; bütün önerileri aynı anda uygulamak değildir."},{"question":"Bedir hangi tarihî döneme aittir?","options":["İlk vahiyden önceki gençlik yıllarına","Hicretten sonraki Medine dönemine","Mekke'nin fethinden sonraki döneme"],"answer":1,"explanation":"Bedir 624'te, hicretten sonra ve Mekke'nin fethinden önce gerçekleşti."}],"teacher":{"misconception":"İstişareyi kararsızlık veya yalnız çoğunluk sayma şeklinde sunmayın; bilgi, gerekçe ve sorumluluk boyutunu vurgulayın.","differentiation":"5–6. sınıfta dört aşamayı sözlü kurdurun; 7–8. sınıfta haber, yorum ve karar arasındaki farkı açıklatın.","exit":"Bedir'in öncesinden bir gelişme ve istişareden çıkarılabilecek bir davranış söyle."},"sources":[{"title":"TDV — Bedir Gazvesi","url":"https://islamansiklopedisi.org.tr/bedir-gazvesi"}]},{"id":33,"module":6,"title":"Bedir'den sonra: İnsanlık ve öğrenme","date":"624 / Hicrî 2","objective":"Savaş sonrasında insan onuru ile eğitimin önemini fark eder.","hook":{"question":"Bir çatışma bittikten sonra karşı taraftaki insanlara ilişkin sorumluluklar biter mi?","options":["Evet; sonuç belli olunca başka sorumluluk kalmaz.","Yalnız güçlü kişiler için devam eder.","Hayır; insanlara iyi davranma sorumluluğu sürer."],"note":"Tarihî esaret ile bugünün hukuk düzenini aynı sanmalarını önleyin. Çocuklara kişisel zor deneyimler anlattırmayın."},"frames":[{"title":"Savaşın bitmesi, sorumluluğun bitmesi değildir","kind":"values","labels":["Savaşın sonu","İnsan onuru","Yeni sorumluluk"],"narration":"Bedir'in ardından ele alınması gereken konulardan biri esirlerin durumuydu. Bir karşılaşmanın sonucu, insanlara nasıl davranılacağı sorusunu ortadan kaldırmaz. Bu bölümde dikkatimizi savaş sahnelerine değil, sonrasındaki sorumluluklara yöneltiyoruz. Bir tarih olayını bu açıdan okumak, yalnız kazanan tarafı öğrenmekten daha derin bir anlayış sağlar. Güç sahibi olmak, davranışların sonuçlarını düşünme sorumluluğunu da beraberinde getirir."},{"title":"İyi davranma ilkesi","kind":"community","labels":["İhtiyaçları gözetmek","İyi davranmak","İnsan olarak görmek"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) Bedir'den sonra esirlere iyi davranılmasını istedi. Bu bilgi, karşı tarafta bulunmanın bir insanın ihtiyaçlarını ve onurunu yok saymayı haklı kılmadığını gösterir. Dersimizde işkence veya savaş canlandırması yapmıyoruz. Bir davranışı değerlendirirken insanın kim olduğundan önce nasıl muamele gördüğünü soruyoruz. Tarihî örnek, zor koşullarda bile davranışlarımızın ahlâkî bir ölçüsü olması gerektiğini düşünmemize yardım eder."},{"title":"Farklı durumlar, farklı uygulamalar","kind":"agreement","labels":["Görüşme","Şartları değerlendirme","Serbest bırakma"],"narration":"Esirlerin durumu Eshâb-ı kirâm ile görüşüldü; serbest bırakılmaları için farklı yollar uygulandı. Herkesin aynı imkâna sahip olduğu varsayılmadı. Bu nedenle tek bir uygulamayı bütün esirler için geçerliymiş gibi anlatmak doğru olmaz. Kaynak okurken 'bazıları' ile 'hepsi' arasındaki farkı dikkatle izleriz. Küçük görünen bu kelime farkı, tarihî bilginin doğruluğunu önemli ölçüde değiştirebilir."},{"title":"Bilginin bir değere dönüşmesi","kind":"book","labels":["Okuma yazma","Öğretme","Öğrenme imkânı"],"narration":"Siyer kaynakları, okuma yazma bilen bazı esirlerin öğretmenlik yaparak serbest bırakıldığını anlatır. Bu örnek, bilgi ve öğretimin toplum için taşıdığı değeri gösterir. Öğretmek yalnız bir bilgiyi söylemek değildir; öğrenenin anlayıp anlamadığını da gözetmeyi gerektirir. Şimdi kolay bir beceriyi arkadaşına nasıl açıklayacağını düşün. Tarihî uygulamayı bugünün sınıfına aynen taşımadan, bilginin paylaşılması üzerinde durabiliriz."}],"game":{"kind":"classify","title":"Kaynağın söylediği ve aşırı genelleme","prompt":"İfadeleri kaynak bilgisini koruyanlar ve sınırı aşan genellemeler olarak ayır.","groups":["Bilgiyi koruyor","Aşırı genelliyor"],"items":[{"text":"Bazı esirler okuma yazma öğretmiştir.","group":0,"explanation":"Kaynak bilgisi bütün esirlere yayılmadan aktarılıyor."},{"text":"Bütün esirler aynı görevle serbest bırakılmıştır.","group":1,"explanation":"Farklı yollar uygulanmıştır; hepsi demek bilgiyi değiştirir."},{"text":"Esirlerin durumları görüşülmüştür.","group":0,"explanation":"Karar sürecinde görüşme olduğu korunuyor."},{"text":"Savaş bittikten sonra insanlara karşı sorumluluk kalmamıştır.","group":1,"explanation":"İyi davranma ve ihtiyaçları gözetme sorumluluğu sürmüştür."},{"text":"Öğretim, bazı esirlerin serbest bırakılmasıyla ilişkilidir.","group":0,"explanation":"Öğretim ile serbest bırakılma arasındaki bağ doğru kuruluyor."},{"text":"O dönemde herkes okuma yazma biliyordu.","group":1,"explanation":"Bazı kişilerin öğretmenlik yapması bütün toplumun okuryazar olduğunu göstermez."}]},"decision":{"question":"Bir sunuma 'Bedir esirlerinin hepsi öğretmen oldu' yazılmış. Nasıl düzeltirsin?","options":["Cümleyi 'Okuma yazma bilen bazı esirler öğretmenlik yaptı' diye sınırlarım.","Sayı verilmediği için hepsi ifadesini korurum.","Öğretimle ilgili bütün bilgiyi silerim."],"answer":0,"explanations":["Doğru: hem öğretim bilgisini hem de kaynağın koyduğu sınırı korudun.","Sayı verilmemesi, bütün kişilere aynı uygulamanın yapıldığını göstermez.","Bilgiyi bütünüyle silmek gerekmez; doğru kapsamla ifade etmek gerekir."]},"quiz":[{"question":"Bu derste öğretim örneğinin öne çıkardığı değer nedir?","options":["Bilgiyi yalnız kendine saklamak","Öğrenme imkânını paylaşmak","Okumayı yalnız savaş döneminde gerekli görmek"],"answer":1,"explanation":"Okuma yazma öğretimi, bilginin başkalarının hayatında yararlı hâle gelmesine örnektir."},{"question":"Kaynakta 'bazı esirler' denmesi ne gerektirir?","options":["Bilgiyi bütün esirlere genellememeyi","Esirler hakkında hiçbir şey söylememeyi","Olayın kesinlikle yaşanmadığını düşünmeyi"],"answer":0,"explanation":"Bazı kelimesi bilginin kapsamını sınırlar; bu sınır korunmalıdır."},{"question":"Bedir sonrasındaki davranışları incelemek ne kazandırır?","options":["Yalnız savaşın tarihini ezberlemeyi","Savaşın öncesini tamamen unutmayı","Sonuçtan sonra da süren insanî sorumlulukları görmeyi"],"answer":2,"explanation":"Tarihî olayın sonrası, insanlara muamele ve toplumsal sorumluluk bakımından önemlidir."}],"teacher":{"misconception":"Esirlik ve serbest bırakılma uygulamalarını günümüz sınıfında canlandırmayın. Bazıları/hepsi ayrımını görünür kılın.","differentiation":"5–6. sınıfta iki genelleme örneğini düzeltin; 7–8. sınıfta bir kaynak cümlesinin kapsamını koruyarak yeniden yazdırın.","exit":"Bugün öğrendiğin tarihî bilgi ile o bilgiden çıkardığın yorumu ayrı iki cümleyle söyle."},"sources":[{"title":"TDV — Bedir Gazvesi","url":"https://islamansiklopedisi.org.tr/bedir-gazvesi"}]},{"id":34,"module":6,"title":"Uhud: Sorumluluk ve sonuçlar","date":"625 / Hicrî 3","objective":"Uhud'da görevlerin ve birlikte hareket etmenin önemini açıklar.","hook":{"question":"Bir ekipte görevini bitmiş sanan kişi bunu kontrol etmeden ayrılırsa ne olabilir?","options":["Kendi işi bittiği için bütün işler tamamlanır.","Birbirine bağlı başka görevler de etkilenebilir.","Görev planının önemi tamamen ortadan kalkar."],"note":"Öğrencileri suçlu aramaya değil, görevlerin birbirine bağlılığını görmeye yönlendirin."},"frames":[{"title":"Bedir'den bir yıl sonra","kind":"timeline","labels":["624: Bedir","625: Uhud","Medine çevresi"],"narration":"Uhud, Bedir'den bir yıl sonra, 625 yılında Medine yakınlarında gerçekleşti. Kureyş ordusu yeniden hazırlanarak bölgeye geldi. İki olayın yerini ve zamanını ayırmak önemlidir: Bedir ile Uhud aynı savaşın iki adı değildir. Zaman çizgisinde birbirini izleyen bu gelişmeler, Medine'deki topluluğun güvenlik sorunlarının bir günde sona ermediğini gösterir. Önceki dersle bağlantıyı burada kurabiliriz."},{"title":"Bir noktayı koruma görevi","kind":"map","labels":["Uhud çevresi","Görev noktası","Birbirine bağlı görevler"],"narration":"Uhud'da okçular belirli bir noktayı korumakla görevlendirilmişti. Bu görev, diğer birliklerin durumuyla bağlantılıydı. Şemadaki işaretler ayrıntılı askerî taktik öğretmek için değil, bir sorumluluğun daha geniş bir düzenin parçası olduğunu göstermek içindir. Bir noktada yapılan tercih, başka yerlerdeki insanları da etkileyebilir. Bu nedenle görev, yalnız onu yapan kişinin kendi işi olarak düşünülemez."},{"title":"Erken verilmiş bir kararın sonucu","kind":"values","labels":["Durumu yorumlamak","Görevden ayrılmak","Gidişatın değişmesi"],"narration":"Savaşın ilk aşamasındaki durumu değerlendirerek görev yerini terk eden bazı okçuların hareketi, savaşın gidişini etkiledi. Burada 'bazı' kelimesini korumalıyız; bütün okçular aynı davranışı göstermedi. Olayı öğrenirken kişileri küçümsemek yerine karar ile sonuç arasındaki bağı anlamaya çalışırız. Bir işin tamamlandığını düşünmekle gerçekten tamamlandığını doğrulamak arasında önemli bir fark vardır; bu fark ortak çalışmalarda da karşımıza çıkar."},{"title":"Kayıplar ve toparlanma","kind":"community","labels":["Yaralanmalar","Kayıplar","Dayanışma"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) Uhud'da yaralandı; Hazret-i Hamza ve birçok Müslüman şehit oldu. Bu gelişmeler Medine'deki aileleri de etkiledi. Tarihi öğrenirken kayıpları bir puan veya oyun sonucu gibi ele almayız. İnsanların yaşadığı acıyı saygıyla hatırlar, sonrasında nasıl dayanışma gösterildiğini düşünürüz. Sonraki ders, zor zamanlarda birbirinin ihtiyacını gözetmenin bu toplumsal yönünü daha yakından ele alacak."}],"game":{"kind":"sequence","title":"Neden ve sonuç bağlantısı","prompt":"Uhud'da dersimizde ele alınan süreci sırala.","items":[{"text":"Belirli bir noktayı koruma görevi verilmesi","explanation":"Önce sorumluluk ve görev yeri belirlenmiştir."},{"text":"İlk gelişmelerin bazı okçular tarafından farklı yorumlanması","explanation":"Görevden ayrılma kararından önce durumun yorumlanması vardır."},{"text":"Bazı okçuların görev yerinden ayrılması","explanation":"Kaynakta bütün okçular değil, bir kısmı söz konusudur."},{"text":"Bu ayrılığın savaşın gidişini etkilemesi","explanation":"Bir görevdeki değişim daha geniş durumu etkilemiştir."}]},"decision":{"question":"Bir grup ödevinde afişi hazırlayan öğrenci, sunum provası yapılmadan işin bittiğini sanıyor. Hangi yaklaşım dersin çıkarımıyla uyumlu?","options":["Görevini tamamladığını düşünmesini tek ölçü saymak.","Onu herkesin önünde suçlayarak görevi bırakmasını istemek.","Ortak planı kontrol edip prova için hangi görevin sürdüğünü açıklamak."],"answer":2,"explanations":["Kişinin kendi değerlendirmesi, ortak çalışmanın bütününün tamamlandığını göstermeyebilir.","Hata ile sonucu konuşmak gerekir; küçük düşürmek çözüm üretmez.","Doğru: görevler arasındaki bağı ve tamamlanma ölçüsünü birlikte kontrol ettin."]},"quiz":[{"question":"Uhud ile Bedir arasındaki doğru ilişki hangisidir?","options":["Uhud, Bedir'den sonra gerçekleşmiştir.","İkisi aynı olayın iki adıdır.","Uhud, hicretten önce gerçekleşmiştir."],"answer":0,"explanation":"Bedir 624, Uhud 625 yılındadır; ayrı olaylardır."},{"question":"Uhud'daki okçularla ilgili hangi ifade daha doğrudur?","options":["Bütün okçular aynı anda görevini bıraktı.","Bazı okçuların yerinden ayrılması gidişatı etkiledi.","Görev yerinin savaşın gidişiyle bağlantısı yoktu."],"answer":1,"explanation":"Kaynağın kapsamı korunmalı; olay bazı okçularla ve görevlerin bağlantısıyla ilgilidir."},{"question":"Bu olaydan ortak çalışma için hangi sonuç çıkarılabilir?","options":["Bir hata olursa bütün ekip suçlanmalıdır.","İlk olumlu gelişme bütün görevleri sona erdirir.","Görevin tamamlandığı ortak plan ve şartlarla kontrol edilmelidir."],"answer":2,"explanation":"Görevler birbirine bağlı olduğundan yalnız ilk izlenime göre hareket etmek yeterli değildir."}],"teacher":{"misconception":"Uhud'u basit bir suçlu bulma hikâyesine veya savaş oyununa çevirmeyin. Bazı okçular ifadesini koruyun.","differentiation":"5–6. sınıfta neden-sonuç kartlarını eşleştirin; 7–8. sınıfta gözlem ile varsayım arasındaki farkı tartıştırın.","exit":"Görev paylaşımında yalnız kendi işimi değil, … da düşünmeliyim."},"sources":[{"title":"TDV — Uhud Gazvesi","url":"https://islamansiklopedisi.org.tr/uhud-gazvesi"}]},{"id":35,"module":6,"title":"Zor zamanlarda birbirini gözetmek","date":"625–627 / Medine dönemi","objective":"Kayıp ve sıkıntı yaşayan insanlara destek olmanın yollarını belirler.","hook":{"question":"Zor bir gün geçiren arkadaşına yardım etmeden önce neyi öğrenmen gerekir?","options":["Neye ihtiyaç duyduğunu ve yardım isteyip istemediğini","Yaşadığı bütün özel ayrıntıları","Başkalarının onun hakkında ne düşündüğünü"],"note":"Öğrencilerin kişisel kayıp açıklamasını istemeyin. Günlük, güvenli ve kurmaca sınıf örnekleriyle çalışın."},"frames":[{"title":"Bir olayın ailelere uzanan etkisi","kind":"community","labels":["Uhud sonrası","Aileler","Günlük ihtiyaçlar"],"narration":"Uhud'un sonuçları yalnız karşılaşmanın yaşandığı yerde kalmadı. Yaralanmalar ve kayıplar, Medine'deki ailelerin günlük hayatını da etkiledi. Tarihî olayları öğrenirken bu görünmeyen tarafı da düşünürüz. Bir aile zor bir dönem yaşadığında yemek, su, bakım veya günlük işlerle ilgili desteğe ihtiyaç duyabilir. Bu ihtiyaçları fark etmek, olayların insan hayatındaki etkisini daha dikkatli okumamızı sağlar."},{"title":"Dayanışmanın somut işleri","kind":"values","labels":["Su taşımak","Bakımla ilgilenmek","İhtiyacı karşılamak"],"narration":"Uhud sırasında ve sonrasında Eshâb-ı kirâmın üstlendiği işler arasında su ve yiyecek ulaştırmak, yaralıların bakımıyla ilgilenmek de vardı. Dayanışma bazen uzun bir konuşmadan çok, ihtiyaç duyulan bir işi zamanında yapmakla görünür olur. Bu örnekler tarihî toplulukta farklı görevlerin değerini gösterir. Yalnız en çok görünen işi değil, başkalarının hayatını kolaylaştıran emeği de fark etmeye çalışırız."},{"title":"Toparlanmak zaman ister","kind":"timeline","labels":["Zorluk","Destek","Yeniden düzen"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) güçlüklerin ardından topluluğun toparlanmasına ve dayanışmanın sürmesine önem verdi. Toparlanma, herkesin aynı anda aynı duyguyu yaşaması demek değildir. Günümüzde bir arkadaşımıza destek olurken onu hemen neşelenmeye zorlamamak ve özel ayrıntıları anlatması için sıkıştırmamak gerekir. Bu günlük davranış önerileri, tarihî örnekten hareketle yaptığımız bir uygulamadır; geçmişte söylenmiş sözler gibi aktarılmamalıdır."},{"title":"Yardımın yerinde ve ölçülü olması","kind":"home","labels":["İhtiyacı sor","Uygun destek","Mahremiyeti koru"],"narration":"Bir öğrenci hastalık sebebiyle derslerden uzak kaldığında notlarını paylaşmak, öğretmeninden destek istemesine yardım etmek veya uygun zamanda yanında olmak yararlı olabilir. Yardım teklifinin kabul edilmemesine de saygı duyarız. Arkadaşımızın özel durumunu sınıfa duyurmak yardımın şartı değildir. Tarihî dayanışmayı hayatımıza taşırken hem ihtiyacı hem kişinin rahatlığını düşünürüz. Çözmekte zorlandığımız durumlarda güvenilir bir yetişkinden destek isteriz."}],"game":{"kind":"classify","title":"Destek mi, baskı mı?","prompt":"Günlük okul örneklerini ihtiyaç gözeten destek ve baskı olarak ayır.","groups":["İhtiyacı gözeten destek","Baskı veya mahremiyet ihlali"],"items":[{"text":"İstersen kaçırdığın dersin notlarını paylaşabilirim.","group":0,"explanation":"Yardım somut ve isteğe bağlı sunuluyor."},{"text":"İyiliğin için olanları herkese anlatacağım.","group":1,"explanation":"İzin olmadan özel bilgiyi paylaşmak destek değildir."},{"text":"Konuşmak istemediğinde bunu anlayabilirim.","group":0,"explanation":"Kişinin sınırlarına ve zamanına saygı gösteriliyor."},{"text":"Artık üzülme; hemen neşelenmelisin.","group":1,"explanation":"Duygulara süre vermek, kişiyi baskı altında bırakabilir."},{"text":"Bir öğretmenden yardım istemek ister misin?","group":0,"explanation":"Uygun yetişkin desteği seçenek olarak sunuluyor."},{"text":"Yardım etmem için bütün ayrıntıları anlatmalısın.","group":1,"explanation":"Destek, özel ayrıntıları açıklama şartına bağlanmamalı."}]},"decision":{"question":"Arkadaşın bir süredir okula gelmedi. Destek mesajının en uygun başlangıcı hangisi?","options":["Neler olduğunu sınıfta herkes merak ediyor, ayrıntıları yaz.","Geçmiş olsun. İstersen ders notlarını paylaşabilirim; cevap vermek zorunda değilsin.","Yarın mutlaka gelmelisin, yoksa daha çok geri kalırsın."],"answer":1,"explanations":["Bu başlangıç arkadaşının ihtiyacından çok başkalarının merakını öne çıkarır.","Doğru: somut yardım teklif edip arkadaşının zamanına ve sınırlarına saygı gösterdin.","Baskı yapmak, kişinin içinde bulunduğu şartları bilmeden çözüm dayatmak olur."]},"quiz":[{"question":"Uhud sonrasını ailelerin hayatıyla birlikte düşünmek neyi gösterir?","options":["Tarihî olayların günlük hayata da etkisi olduğunu","Tarihte yalnız ailelerin karar verdiğini","Olayların yaşandığı yerin önemsiz olduğunu"],"answer":0,"explanation":"Yaralanma ve kayıplar bakım ve günlük ihtiyaçları da etkiler."},{"question":"Tarihî bilgi ile bugünkü uygulamayı ayıran ifade hangisidir?","options":["Bugünkü destek mesajımız geçmişte aynen söylenmiştir.","Her tarihî ayrıntıyı bugünün sınıfında canlandırmalıyız.","Tarihî dayanışmadan hareketle bugün uygun bir yardım örneği tasarlıyoruz."],"answer":2,"explanation":"Geçmişteki örnek ile bizim ondan çıkardığımız günlük davranış birbirinden ayrılmalıdır."},{"question":"İyi niyetli yardımın hangi özelliği önemlidir?","options":["Herkes tarafından görülmesi","İhtiyaç ve kişinin sınırlarıyla uyumlu olması","En çok konuşan kişinin seçmesi"],"answer":1,"explanation":"Yardımın değeri görünürlüğünden çok ihtiyacı karşılaması ve kişiyi gözetmesidir."}],"teacher":{"misconception":"Tarihî bakım örnekleri bugünün sağlık müdahalesi talimatı değildir. Kayıp yaşayan öğrencilerden deneyim anlatmalarını istemeyin.","differentiation":"5–6. sınıfta uygun iki destek cümlesi seçtirin; 7–8. sınıfta yardımın niyetiyle etkisinin neden farklı olabileceğini tartıştırın.","exit":"Bir yardım teklifinde hem … hem … gözetilmelidir."},"sources":[{"title":"TDV — Uhud Gazvesi","url":"https://islamansiklopedisi.org.tr/uhud-gazvesi"}]},{"id":36,"module":6,"title":"Hendek: Bir fikir, ortak emek","date":"627 / Hicrî 5","objective":"Hendek savunmasını iş birliği ve farklı tecrübelerden yararlanmayla ilişkilendirir.","hook":{"question":"Daha önce başka bir yerde işe yarayan fikir, yeni bir sorunu çözebilir mi?","options":["Yalnız fikri söyleyen kişi her işi yaparsa.","Şartlara uygunluğu değerlendirilip birlikte uygulanırsa.","Sırf yeni olduğu için incelenmeden kabul edilirse."],"note":"Farklı tecrübeyi dinlemek ile her öneriyi sorgulamadan kabul etmek arasındaki farkı konuşun."},"frames":[{"title":"Medine'ye yönelen kuşatma","kind":"map","labels":["Medine","Doğal engeller","Savunulacak kesim"],"narration":"Hicretin beşinci yılında, 627'de farklı kuvvetlerin birleşerek Medine'ye yönelmesi ciddi bir güvenlik sorunu oluşturdu. Şehrin her tarafı aynı yapıda değildi; doğal engeller bulunan yerlerle savunmanın güçlendirilmesi gereken kesimler ayrılıyordu. Haritada bu farkı görmek, hazırlığın neden belirli bir alana yöneldiğini anlamamıza yardım eder. Burada araziyi inceliyor, savaşı bir oyun veya hedef vurma etkinliğine dönüştürmüyoruz."},{"title":"Farklı bir tecrübeden gelen öneri","kind":"community","labels":["Hazret-i Selmân","Fikir paylaşımı","Hendek önerisi"],"narration":"Kaynaklarda hendek kazma önerisinin Hazret-i Selmân-ı Fârisî tarafından getirildiği anlatılır. Başka bir coğrafyada bilinen savunma yöntemi, Medine'nin şartları düşünülerek değerlendirildi. Bu örnek, yararlı bilginin yalnız alıştığımız çevreden gelmeyebileceğini gösterir. Bir fikri kimin söylediğini öğrenmek önemlidir; fakat fikrin hangi ihtiyaca cevap verdiğini anlamak da gerekir. Etkinlikte öneri, ihtiyaç ve uygulama arasındaki bağlantıyı kuracağız."},{"title":"Öneriden ortak emeğe","kind":"values","labels":["Yer belirleme","Görev paylaşımı","Birlikte çalışma"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) hendek hazırlıklarına bizzat katıldı. Bir önerinin işe yarar hâle gelmesi için yerin belirlenmesi, işin paylaşılması ve emeğin sürdürülmesi gerekiyordu. Yalnız güzel bir fikir söylemekle hazırlık tamamlanmış olmuyordu. Şemadaki üç aşamayı takip et: plan, görev ve çalışma. Bunlar ayrı kutular gibi görünse de birbirine bağlıdır; birindeki eksiklik ortak sonucu etkileyebilir."},{"title":"Kuşatmanın sonu ve öğrenilen","kind":"timeline","labels":["Hazırlık","Kuşatma","Kuvvetlerin çekilmesi"],"narration":"Kuşatma sonunda Medine'ye saldıran kuvvetler geri çekildi. Hendek, bu süreçte şehrin savunulmasında önemli bir rol oynadı. Dersi yalnız tek bir kişinin fikrine indirgemeden, öneriyi değerlendiren ve uygulayan topluluğu da hatırlarız. Başarılı bir ortak çalışmada bilgi, plan ve emek birbirini tamamlar. Şimdi bu bağlantıyı okulda karşılaşılabilecek bir problemi çözmek için kullanmayı deneyeceğiz."}],"game":{"kind":"match","title":"Fikir nasıl işe dönüşür?","prompt":"Her aşamayı Hendek hazırlıklarındaki anlamıyla eşleştir.","pairs":[{"left":"İhtiyacı belirleme","right":"Medine'nin savunulacak kesimini tanıma","explanation":"Öneri, gerçek ihtiyacın anlaşılmasıyla anlam kazanır."},{"left":"Tecrübeyi paylaşma","right":"Hazret-i Selmân'ın hendek önerisi","explanation":"Farklı coğrafyadan gelen bilgi değerlendirilmiştir."},{"left":"Ortak uygulama","right":"Hazırlığa birlikte katılma","explanation":"Planın gerçekleşmesi emek ve görev paylaşımı ister."},{"left":"Sonucu değerlendirme","right":"Kuşatma sonunda kuvvetlerin çekilmesini inceleme","explanation":"Sonuç, hazırlık ve süreçle birlikte anlaşılır."}]},"decision":{"question":"Okul bahçesinde su birikiyor. Yeni gelen öğrenci başka okulundaki çözümü anlatıyor. Ne yapılmalı?","options":["Yöntemin buranın şartlarına uygunluğunu inceleyip sorumlu yetişkinlerle plan yapmak.","Öneri başka okuldan geldiği için dinlememek.","Yöntemi güvenliğini değerlendirmeden hemen uygulamak."],"answer":0,"explanations":["Doğru: farklı tecrübeyi dinledin, şartlara uygunluğu ve görev paylaşımını gözetiyorsun.","Farklı bir yerden gelen bilgi yararlı olabilir; kaynağı yüzünden dışlanmamalı.","Her yerin şartı farklıdır; yararlı görünen fikir de güvenli ve uygun biçimde değerlendirilmelidir."]},"quiz":[{"question":"Hendek önerisinin öne çıkardığı özellik hangisidir?","options":["Bütün işleri tek kişinin yapması","Alışılmış yöntemi her şartta sürdürmek","Farklı tecrübelerden yararlanmak"],"answer":2,"explanation":"Hazret-i Selmân'ın önerisi, farklı bir çevrede bilinen yöntemin değerlendirilmesine örnektir."},{"question":"Medine haritasında doğal engelleri göstermek neyi anlamaya yardım eder?","options":["Savunmanın neden uygun kesimlerde güçlendirildiğini","Bütün şehirlerin aynı biçimde kurulduğunu","Hendek kazmanın hiçbir plan gerektirmediğini"],"answer":0,"explanation":"Arazi farklılıkları, hazırlığın nerede yapılacağını etkiler."},{"question":"Hendek hazırlığında fikir ile emek arasındaki ilişki hangisidir?","options":["Fikir söylenince uygulama kendiliğinden olur.","Fikrin uygulanması plan ve ortak çalışma gerektirir.","Ortak çalışmada planın önemi kalmaz."],"answer":1,"explanation":"Öneri, yer belirleme, görev paylaşımı ve emekle hayata geçirilir."}],"teacher":{"misconception":"Hendeğin bütün şehri aynı biçimde çevrelediği izlenimini vermeyin. Farklı tecrübeyi dinlemek, her öneriyi sorgusuz uygulamak değildir.","differentiation":"5–6. sınıfta fikir-plan-emek sırasını kurdurun; 7–8. sınıfta bir yöntemin başka ortama aktarılırken hangi şartlarının inceleneceğini açıklatın.","exit":"Hendek örneğinde yararlı fikir ile ortak emek nasıl birleşti?"},"sources":[{"title":"TDV — Hendek Gazvesi","url":"https://islamansiklopedisi.org.tr/hendek-gazvesi"}]},{"id":37,"module":7,"title":"Kâbe'yi ziyaret etme isteği","date":"628 / Hicrî 6","objective":"Hudeybiye yolculuğunun başlangıç amacını ayırt eder.","hook":{"question":"Bir yolculuğun amacını anlamak için önce hangi bilgiye bakarsın?","options":["Yola çıkanların başlangıç niyetine","Sonradan anlatılan en heyecanlı ayrıntıya","Yolculukta kullanılan bütün eşyaların sayısına"],"note":"Başlangıç amacı ile yol boyunca ortaya çıkan gelişmeleri birbirinden ayırmaya hazırlayın."},"frames":[{"title":"Bir ziyaret niyeti","kind":"journey","labels":["Medine","Umre niyeti","Mekke"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) ve Eshâb-ı kirâm, hicretin altıncı yılında umre yapmak amacıyla Mekke'ye doğru yola çıktı. Bu başlangıç niyeti, yolculuğu doğru anlamak için temel bilgidir. Yolda yaşanan her gelişmeyi en baştan planlanmış gibi düşünmemeliyiz. Ekrandaki güzergâhın çıkış noktasıyla hedefini bul; sonra 'Nereye gidiliyor?' ve 'Niçin gidiliyor?' sorularının farklı cevaplar istediğini fark et."},{"title":"Hudeybiye'de karşılaşılan engel","kind":"map","labels":["Medine yolu","Hudeybiye çevresi","Mekke'ye giriş"],"narration":"Kureyş, Müslümanların o yıl Mekke'ye girişini engelledi. Kafile Hudeybiye çevresinde bulunduğu sırada ziyaretin nasıl gerçekleşebileceği bir görüşme konusu hâline geldi. Haritadaki durak, yeni bir şehir kurulduğunu veya umrenin orada tamamlandığını göstermez. Yolculuğun hedefi ile beklenen yer farklıdır. Bir olayın mekânını doğru okumak, sonraki antlaşmanın neden bu adla anıldığını da anlamamızı kolaylaştırır."},{"title":"Elçilerle sürdürülen görüşme","kind":"agreement","labels":["Kafile","Elçiler","Kureyş"],"narration":"Taraflar arasında elçiler gidip geldi. Hazret-i Osman da görüşme için Mekke'ye gönderildi. Elçi, bir tarafın mesajını diğer tarafa ulaştıran görevlidir; kendi düşüncesiyle temsil ettiği mesajı birbirine karıştırmamalıdır. İletişimin bu şekilde sürdürülmesi, engelin yalnız tepki gösterilerek ele alınmadığını gösterir. Dersimizde tarihî konuşmalar uydurmadan, görev ile mesaj arasındaki ilişkiyi anlamaya çalışıyoruz."},{"title":"Amaç, engel ve yöntem","kind":"values","labels":["Amaç: ziyaret","Engel: giriş izni","Yöntem: görüşme"],"narration":"Hudeybiye'yi üç ayrı başlıkla okumak yararlıdır: Başlangıçta bir ziyaret amacı vardı; ardından giriş engeliyle karşılaşıldı; bu engel karşısında görüşmeler yürütüldü. Bu başlıkları birbirine karıştırırsak yolculuğun amacı değişmiş gibi anlatabiliriz. Bir sonraki derste görüşmelerin ulaştığı antlaşmayı inceleyeceğiz. Şimdilik öğrencinin görevi, henüz gerçekleşmemiş sonucu başlangıç niyetinin yerine koymadan olayın ilk aşamalarını açıklamaktır."}],"game":{"kind":"sequence","title":"Yolculuğun ilk aşamaları","prompt":"Başlangıç amacı ile karşılaşılan gelişmeleri doğru sıraya koy.","items":[{"text":"Umre yapmak amacıyla Medine'den yola çıkılması","explanation":"Yolculuğun başlangıç amacı Kâbe'yi ziyaret ederek umre yapmaktır."},{"text":"Kureyş'in Mekke'ye girişi engellemesi","explanation":"Yol üzerinde karşılaşılan engel, başlangıç niyetinden ayrıdır."},{"text":"Hudeybiye çevresinde beklenmesi","explanation":"Hudeybiye, görüşmelerin yürütüldüğü çevredir."},{"text":"Elçiler aracılığıyla görüşmelerin sürdürülmesi","explanation":"Hazret-i Osman da bu görüşmelerde görev almıştır."}]},"decision":{"question":"Bir sunumda 'Hudeybiye'ye antlaşma imzalamak amacıyla yola çıkıldı' yazıyor. En doğru düzeltme hangisi?","options":["Başlangıç amacı umreydi; antlaşma daha sonra gelişen görüşmelerin sonucuydu.","Başlangıç amacı Medine'ye yerleşmekti.","Antlaşma yapıldığı için başlangıç amacını öğrenmek gereksizdir."],"answer":0,"explanations":["Doğru: niyet ile sonradan ortaya çıkan sonucu ayırdın.","Medine'ye yerleşme hicretle ilgilidir; bu yolculuk Medine'den Mekke yönündedir.","Sonucu bilmek önemlidir; fakat başlangıç niyetini silmek olayın gelişimini bozar."]},"quiz":[{"question":"Hudeybiye yolculuğunun başlangıç amacı hangisiydi?","options":["Mekke'de yeni bir yerleşim kurmak","Umre yapmak","Medine'yi kuşatmak"],"answer":1,"explanation":"Yola umre niyetiyle çıkılmış; giriş engeliyle karşılaşılınca görüşmeler yapılmıştır."},{"question":"Hazret-i Osman'ın bu süreçteki görevi neydi?","options":["Elçi olarak görüşmeye katılmak","Medine'de yeni bir mescid yapmak","Habeşistan'a göç hazırlamak"],"answer":0,"explanation":"Hazret-i Osman Mekke'ye görüşme için gönderilmiştir."},{"question":"Hudeybiye ile Mekke'yi haritada ayırmak niçin önemlidir?","options":["Kafilenin hedefinin Hudeybiye olduğunu göstermek için","Umrenin Hudeybiye'de tamamlandığını söylemek için","Beklenen yer ile ziyaret edilmek istenen yeri karıştırmamak için"],"answer":2,"explanation":"Hudeybiye görüşme çevresidir; başlangıçta ziyaret edilmek istenen yer Mekke'deki Kâbe'dir."}],"teacher":{"misconception":"Başlangıç amacı umredir; sonradan yapılan antlaşmayı yola çıkış niyeti gibi anlatmayın. Harita ölçeksiz ise açıkça şematik deyin.","differentiation":"5–6. sınıfta amaç-engel-yöntem başlıklarına kart yerleştirin; 7–8. sınıfta sonucu bilerek geçmişi yeniden yorumlama hatasını tartıştırın.","exit":"Hudeybiye yolculuğunun amacı … idi; karşılaşılan engel üzerine … yapıldı."},"sources":[{"title":"TDV — Hudeybiye Antlaşması","url":"https://islamansiklopedisi.org.tr/hudeybiye-antlasmasi"}]},{"id":38,"module":7,"title":"Hudeybiye: Barış için sabır","date":"628 / Hicrî 6","objective":"Hudeybiye Antlaşması'nın kısa ve uzun vadeli sonuçlarını karşılaştırır.","hook":{"question":"Bir anlaşma ilk gün zor görünse de daha sonra yararlı olabilir mi?","options":["Hayır; ilk duygu bütün sonucu belirler.","Yalnız anlaşmanın hiçbir şartı yoksa.","Evet; kısa ve uzun vadeli sonuçları birlikte değerlendirmek gerekir."],"note":"Sabır kavramını haksızlığa kayıtsız kalma şeklinde genellemeyin; bu tarihî antlaşmanın şart ve sonuçlarına bağlı konuşun."},"frames":[{"title":"Görüşmelerden antlaşmaya","kind":"agreement","labels":["Müslümanlar","Kureyş","Hudeybiye Antlaşması"],"narration":"Hudeybiye'de yürütülen görüşmeler, Müslümanlarla Kureyş arasında bir antlaşmayla sonuçlandı. Böylece tarafların ilişkisini düzenleyen yazılı şartlar ortaya çıktı. Antlaşmayı yalnız bir kâğıt parçası gibi düşünmeyiz; yerine getirilmesi beklenen karşılıklı sorumlulukları içerir. Bu derste bütün maddeleri ezberlemek yerine ziyaretin ertelenmesini ve barış ortamının etkisini karşılaştıracağız. Önceki dersteki başlangıç amacını hatırlamak bu karşılaştırmanın ilk adımıdır."},{"title":"O yıl dönmek, ertesi yıl ziyaret etmek","kind":"timeline","labels":["628: geri dönüş","Bekleyiş","629: ziyaret"],"narration":"Antlaşmaya göre Müslümanlar o yıl umre yapmadan geri dönecek, ertesi yıl Mekke'yi ziyaret edebilecekti. Yaklaşılmış bir hedefin ertelenmesi kolay değildi. Fakat ertelenmek ile tamamen vazgeçmek aynı şey değildir. Zaman çizgisindeki iki yılı ayrı ayrı incele. Bir yılın sonunda yapılmayan ziyaret, sonraki yıl için belirlenen şartların içinde yeniden yer alıyordu."},{"title":"İlk izlenim ve uzun vadeli sonuç","kind":"values","labels":["İlk zorluk","Barış ortamı","Artan iletişim"],"narration":"Bazı şartlar ilk anda Müslümanlara ağır görünmüştü. Buna rağmen oluşan barış ortamı, insanların görüşmesini ve İslâm'ı daha yakından tanımasını kolaylaştırdı. Kısa vadede yaşanan güçlük ile uzun vadede ortaya çıkan imkânı aynı sütuna yazmamak gerekir. Bir gelişmeyi değerlendirirken yalnız ilk duyguyu değil, daha sonra nelerin değiştiğini de inceleriz. Bu yaklaşım tarihî yorumlarımızı daha dikkatli hâle getirir."},{"title":"Sabır ve söze bağlılık","kind":"community","labels":["Şartları bilmek","Sözü sürdürmek","Sonucu izlemek"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) antlaşmanın şartlarına bağlı kaldı. Bu tavır, bir kararın yalnız duyurulduğu gün değil, uygulanırken de sorumluluk gerektirdiğini gösterir. Dersimizde sabır, hiçbir şey yapmadan beklemek anlamında kullanılmıyor; şartları gözeterek süreci sürdürmek üzerinde duruyoruz. Günümüzde bir anlaşmayı değerlendirirken de neye söz verildiğini, kimlerin etkilendiğini ve sözün nasıl yerine getirileceğini açıkça konuşmak gerekir."}],"game":{"kind":"classify","title":"Hemen görülen ve zamanla ortaya çıkan","prompt":"Hudeybiye bilgilerini kısa vadeli durum ve sonraki imkân olarak ayır.","groups":["O yıl görülen durum","Sonraki imkân veya sonuç"],"items":[{"text":"Umre yapılmadan geri dönülmesi","group":0,"explanation":"Bu, antlaşmanın o yıl için getirdiği durumdur."},{"text":"Ertesi yıl ziyaretin mümkün hâle gelmesi","group":1,"explanation":"Ziyaret tamamen kaldırılmamış, sonraki yıla bağlanmıştır."},{"text":"Bazı şartların ilk anda ağır görünmesi","group":0,"explanation":"Bu ifade başlangıçtaki değerlendirmeyi anlatır."},{"text":"Barış ortamında görüşmelerin artması","group":1,"explanation":"İletişimdeki genişleme zaman içinde görülen etkiler arasındadır."},{"text":"Kafile için beklenen ziyaretin ertelenmesi","group":0,"explanation":"Ertelenme o yılın zorluğudur; bütünüyle vazgeçmek değildir."},{"text":"İnsanların İslâm'ı tanıma fırsatlarının artması","group":1,"explanation":"Barış ortamı daha uzun vadeli bir tanışma imkânı oluşturmuştur."}]},"decision":{"question":"Bir öğrenci 'O yıl umre yapılamadı; demek ki antlaşmanın hiçbir yararı olmadı' diyor. Hangi cevap daha doğru?","options":["Yalnız ilk yılın sonucuna baktın; sonraki ziyaret ve barış ortamını da incelemeliyiz.","Antlaşmanın hiçbir zorluğu olmadığı için yorumun yanlış.","Sonuçları konuşmak yerine yalnız tarihini ezberlemeliyiz."],"answer":0,"explanations":["Doğru: başlangıçtaki güçlüğü inkâr etmeden daha uzun dönemi değerlendirdin.","Zorluklar vardı; onları yok saymak dengeli bir değerlendirme değildir.","Tarih, olayların sırasını gösterir; sonuçları anlamanın yerini tutmaz."]},"quiz":[{"question":"Hudeybiye'de ziyaret için kararlaştırılan düzenleme hangisiydi?","options":["Ziyaretin o yıl yapılması ve bir daha tekrarlanmaması","O yıl dönülmesi, ertesi yıl ziyaret edilmesi","Kâbe ziyaretinin bütün Müslümanlara sürekli kapatılması"],"answer":1,"explanation":"Antlaşma o yıl geri dönüşü ve sonraki yıl ziyareti içeriyordu."},{"question":"Ertelenmek ile vazgeçmek arasındaki farkı hangi bilgi gösterir?","options":["Kafilenin yolda bulunması","Görüşmelerin elçilerle yapılması","Sonraki yıl için ziyaret imkânı belirlenmesi"],"answer":2,"explanation":"Yeni ziyaret zamanı belirlenmesi hedefin tamamen kaldırılmadığını gösterir."},{"question":"Hudeybiye'yi değerlendirirken hangi yöntem daha uygundur?","options":["İlk zorluklarla sonraki etkileri birlikte incelemek","Yalnız ilk anda hissedilenleri esas almak","Antlaşmanın bütün şartlarını önemsiz saymak"],"answer":0,"explanation":"Dengeli tarih okuması kısa ve uzun vadeli sonuçları birlikte ele alır."}],"teacher":{"misconception":"Hudeybiye örneğini her haksızlığa sessiz kalma kuralı gibi genellemeyin. Tarihî şartları, sorumlulukları ve sonuçları birlikte ele alın.","differentiation":"5–6. sınıfta iki sütuna yerleştirme yaptırın; 7–8. sınıfta kısa vadeli maliyet ve uzun vadeli sonuç ayrımını gerekçelendirin.","exit":"Hudeybiye'nin o yılki bir zorluğunu ve sonraki bir yararını söyle."},"sources":[{"title":"TDV — Hudeybiye Antlaşması","url":"https://islamansiklopedisi.org.tr/hudeybiye-antlasmasi"},{"title":"Diyanet Kur’an Yolu — Fetih sûresi","url":"https://kuran.diyanet.gov.tr/tefsir/sure/48"}]},{"id":39,"module":7,"title":"Uzak ülkelere ulaşan davet","date":"628 ve sonrası","objective":"Elçiler ve mektuplar yoluyla kurulan iletişimi tanır.","hook":{"question":"Bir mesajın doğru ulaşması için hangisi birlikte gereklidir?","options":["Uzun olması ve çok kişi tarafından okunması","Mesajın açık olması ve güvenilir biçimde taşınması","Taşıyan kişinin istediği gibi değiştirebilmesi"],"note":"Mektup, gönderen, muhatap ve elçi rollerini başlangıçta ayrı renklerle gösterin."},"frames":[{"title":"Davetin genişleyen çevresi","kind":"map","labels":["Medine","Çevredeki yöneticiler","Davet mektupları"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) Hudeybiye sonrasında çevredeki yöneticilere İslâm'a davet mektupları gönderdi. Böylece iletişim, yalnız aynı şehirde yüz yüze yapılan görüşmelerle sınırlı kalmadı. Haritada Medine'den farklı yönlere uzanan oklar, mesajların ulaştırılmak istendiği çevreyi gösteriyor. Okların çizilmesi, her muhatabın aynı cevabı verdiği anlamına gelmez. Bir davetin gönderilmesiyle kabul edilmesi ayrı bilgilerdir; bu ayrımı korumalıyız."},{"title":"Elçinin taşıdığı sorumluluk","kind":"journey","labels":["Gönderen","Elçi","Muhatap"],"narration":"Mektupları ulaştırmak için Eshâb-ı kirâmdan farklı kişiler görevlendirildi. Elçinin işi yalnız bir nesneyi taşımak değildi; doğru kişiye doğru mesajı ulaştırma sorumluluğu da vardı. Ekrandaki üç rolü birbirinden ayır: mesajı gönderen, taşıyan ve alan. Mesajın sahibi ile taşıyıcısını aynı kişi sanmak, tarihî kayıtlarda görevleri karıştırmamıza yol açabilir. Öğrenme oyununda bu rolleri eşleştireceğiz."},{"title":"Hazret-i Dihye'nin görevi","kind":"route","labels":["Hazret-i Dihye","Herakleios","Davet mektubu"],"narration":"Bizans hükümdarı Herakleios'a gönderilen mektubu ulaştırmakla Hazret-i Dihye bin Halîfe görevlendirildi. Bu örnek, bir sahâbînin elçilik göreviyle tanınmasına dikkat çekiyor. Burada isimleri bir ezber listesine çevirmek yerine aralarındaki ilişkiyi kuruyoruz: Kim taşıdı, kime ulaştırıldı, ne amaçla gönderildi? Aynı üç soru, başka bir tarihî belgenin izlediği yolu incelerken de kullanılabilir; belgeyi anlamayı kolaylaştırır."},{"title":"Belgeyi dikkatle okumak","kind":"book","labels":["Amaç","Muhatap","Kaynak kontrolü"],"narration":"Tarihî bir mektup hakkında konuşurken metnin amacı, muhatabı ve kaynaklarda nasıl aktarıldığı birlikte değerlendirilir. Bu derste tarihî mektubun aslını taklit etmiyoruz veya eksik sözlerini hayal ederek tamamlamıyoruz. Günlük bir okul daveti hazırlarken ise selamlama, açık amaç ve nazik kapanış kullanabiliriz. Böylece geçmişe ait belgeyle bugün yazdığımız özgün metnin sınırı açık kalır; ikisini birbirine karıştırmayız."}],"game":{"kind":"match","title":"Mektubun yolunu anla","prompt":"Kavramları bu dersteki görevleriyle eşleştir.","pairs":[{"left":"Elçi","right":"Mesajı muhatabına ulaştıran görevli","explanation":"Elçi, gönderenin mesajını taşır."},{"left":"Muhatap","right":"Mektubun ulaştırılmak istendiği kişi","explanation":"Muhatap mesajın alıcısıdır."},{"left":"Hazret-i Dihye bin Halîfe","right":"Herakleios'a mektup ulaştıran sahâbî","explanation":"Bu derste ele alınan elçilik örneği budur."},{"left":"Davet","right":"Mektubun İslâm'ı tanıtmaya yönelik amacı","explanation":"Mesajın gönderilme amacı ile alınan cevap ayrı konulardır."}]},"decision":{"question":"Bir arkadaşın 'Mektup gönderildiyse bütün yöneticiler kabul etmiştir' diyor. Hangi cevap uygundur?","options":["Elçi güvenilir olduğu için her muhatap aynı cevabı vermiştir.","Mektubun uzunluğunu bilirsek bütün cevapları öğreniriz.","Gönderilme bilgisi tek başına kabul edildiğini göstermez; cevap için ayrıca kaynak gerekir."],"answer":2,"explanations":["Elçinin güvenilirliği ile muhatabın tercihi aynı şey değildir.","Metnin uzunluğu, muhatapların verdikleri cevapları tek başına göstermez.","Doğru: gönderme ile kabul etme bilgisini ayırıp kanıt aradın."]},"quiz":[{"question":"Hazret-i Dihye bin Halîfe'nin bu dersteki görevi hangisidir?","options":["Davet mektubunu Herakleios'a ulaştırmak","Hudeybiye'de umre tarihini değiştirmek","Hayber'de tarım düzenini kurmak"],"answer":0,"explanation":"Hazret-i Dihye elçilik göreviyle Herakleios'a mektup ulaştırmıştır."},{"question":"Bir mektubun gönderildiğini bilmek hangi sonuca tek başına yetmez?","options":["Bir iletişim girişimi olduğunu anlamaya","Muhatabın daveti kabul ettiğini söylemeye","Mektubun bir amacı bulunduğunu düşünmeye"],"answer":1,"explanation":"Kabul veya ret hakkında ayrıca bilgi gerekir; gönderilme bunu kanıtlamaz."},{"question":"Tarihî bir mektubu işlerken hangisi doğrudur?","options":["Eksik bölümlerini hayal ederek tamamlamak","Bugünkü okul davetimizi tarihî metin diye sunmak","Kaynakta aktarılanı kendi yazdığımız örnekten ayırmak"],"answer":2,"explanation":"Tarihî bilgi ile pedagojik amaçla yazılan yeni metnin sınırı açık olmalıdır."}],"teacher":{"misconception":"Mektup gönderilen herkesin aynı cevabı verdiği çıkarımını önleyin. Elçi ve muhatap rollerini karıştırmayın.","differentiation":"5–6. sınıfta gönderen-elçi-muhatap çizgisi kurdurun; 7–8. sınıfta belgenin gönderilmesi ve karşılığının kaynaklarını ayrı sorgulatın.","exit":"Bir tarihî mektubu anlamak için soracağın üç soruyu söyle."},"sources":[{"title":"TDV — Hazret-i Dihye bin Halîfe","url":"https://islamansiklopedisi.org.tr/dihye-b-halife"}]},{"id":40,"module":7,"title":"Hayber: Bir bölgenin değişen düzeni","date":"628 / Hicrî 7","objective":"Hayber'i dönemin siyasî ve ekonomik şartları içinde konumlandırır.","hook":{"question":"Bir yerleşimi tanımak için yalnız savaş tarihini bilmek yeterli mi?","options":["Evet; ekonomik hayatın tarih açısından önemi yoktur.","Hayır; konumu, geçim kaynakları ve düzeni de önemlidir.","Yalnız orada yaşayan herkesin adını bilirsek yeterlidir."],"note":"Hayber'i yalnız askerî bir etiketle anmak yerine yer, tarım ve toplumsal düzen boyutlarını açın."},"frames":[{"title":"Medine'nin kuzeyindeki yerleşim","kind":"map","labels":["Medine","Hayber","Kuzey yönü"],"narration":"Hayber, Medine'nin kuzeyinde bulunan bir yerleşim bölgesiydi. Haritada Mekke, Medine ve Hayber'i ayrı işaretlerle görebiliriz. Üçünün adını bilmek kadar birbirlerine göre konumlarını anlamak da önemlidir. Medine'den Hayber'e çizilen ok ile Mekke'ye çizilen okun aynı yönde olmaması, farklı olayları aynı güzergâhta düşünmemizi engeller. Bu harita yaklaşık konumları anlatır; ayrıntılı yol tarifi değildir."},{"title":"Kaleler kadar tarım da","kind":"city","labels":["Yerleşimler","Kaleler","Tarım alanları"],"narration":"Hayber, kaleleri ve tarımıyla tanınan bir bölgeydi. Bu iki özellik, yerleşimin farklı yönlerini gösterir: kaleler güvenlikle, tarım ise geçim ve üretimle ilişkilidir. Bir yerin tarihini yalnız çatışmaları üzerinden okumak, orada süren günlük hayatı görünmez kılar. Ekrandaki yerleşim şemasında üretim alanlarını da bul. İnsanların ne yetiştirdiğini ve nasıl geçindiğini sormak tarih öğrenmenin önemli bir parçasıdır."},{"title":"Hudeybiye'den sonraki sefer","kind":"timeline","labels":["628: Hudeybiye","Hayber seferi","Yeni düzenleme"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) Hudeybiye'den sonra Hayber seferine çıktı. İki gelişmenin zaman çizgisindeki sırası, dönemin farklı bölgelerle ilişkilerini anlamamıza yardım eder. Olayları yalnız peş peşe sıralamakla yetinmeyiz; her birinin hangi yerde ve hangi şartlarda gerçekleştiğini de sorarız. Hudeybiye bir antlaşma süreciydi; Hayber ise başka bir yerleşim bölgesinde yaşanan gelişmedir. İsimleri veya amaçları birbirinin yerine kullanmamalıyız."},{"title":"Üretimin sürmesi ve paylaşım","kind":"market","labels":["Yerli çiftçiler","Üretim","Ürün paylaşımı"],"narration":"Seferin ardından yerli çiftçilerle ürün paylaşımına dayanan bir çalışma düzenlemesi yapıldı. Bu bilgi, tarihî gelişmenin yalnız yönetim değişikliğiyle sınırlı kalmadığını; üretimin nasıl sürdürüleceğinin de ele alındığını gösterir. Dersimizde ayrıntılı hukuk hükümleri çıkarmıyoruz. Üretici, ürün ve paylaşım arasındaki bağı anlamaya çalışıyoruz. Bir bölgenin günlük hayatı, siyasî gelişmeler sonrasında da düzenlenmesi gereken ihtiyaçlar taşır; tarım bunlardan biridir."}],"game":{"kind":"classify","title":"Hayber'i iki açıdan okuyalım","prompt":"Bilgileri yer ve konum ile üretim ve düzen başlıklarına ayır.","groups":["Yer ve konum","Üretim ve düzen"],"items":[{"text":"Medine'nin kuzeyinde bulunması","group":0,"explanation":"Bu bilgi Hayber'in coğrafî yerini açıklar."},{"text":"Yerli çiftçilerin tarımla uğraşması","group":1,"explanation":"Geçim ve üretimle ilgili bir bilgidir."},{"text":"Haritada Mekke'den ayrı işaretlenmesi","group":0,"explanation":"Yerleşimlerin birbirinden ayrılması konum okumasıdır."},{"text":"Ürün paylaşımı düzenlemesi","group":1,"explanation":"Üretim sonrası ürünün paylaşılma düzeni ele alınıyor."},{"text":"Medine'den kuzeye uzanan yön oku","group":0,"explanation":"Ok yaklaşık yönü gösterir."},{"text":"Tarımın sefer sonrasında da sürmesi","group":1,"explanation":"Bu bilgi ekonomik hayatın devamıyla ilgilidir."}]},"decision":{"question":"Hayber afişinde yalnız kaleler var; öğrenciler oradaki hayatı sadece çatışmadan ibaret sanıyor. Ne eklemek daha uygun?","options":["Tarım alanları, üretici ve ürün paylaşımı düzenlemesini gösteren bir bölüm.","Başka şehirlerin bütün savaşlarını gösteren bir liste.","Kalelerin sayısını bilmeden tüm afişi kaldırmak."],"answer":0,"explanations":["Doğru: yerleşimin geçim ve günlük hayat yönünü de görünür kıldın.","Başka olayları eklemek Hayber'deki günlük hayat eksikliğini doğrudan gidermez.","Bilinmeyen ayrıntıları uydurmamak gerekir; fakat doğrulanmış tarım bilgisini kullanabiliriz."]},"quiz":[{"question":"Hayber'in Medine'ye göre konumu hangisidir?","options":["Güneyinde, Mekke yolunda","Kuzeyinde","Medine'nin aynı adlı mahallesi"],"answer":1,"explanation":"Hayber, Medine'nin kuzeyindeki bir yerleşim bölgesidir."},{"question":"Ürün paylaşımı düzenlemesi hangi yönü aydınlatır?","options":["Tarım ve ekonomik hayatın nasıl sürdürüldüğünü","Kıblenin nasıl belirlendiğini","Umrenin hangi gün yapıldığını"],"answer":0,"explanation":"Bu düzenleme üretim ve ürünün paylaşımıyla ilgilidir."},{"question":"Hudeybiye ile Hayber arasındaki doğru sıra hangisidir?","options":["Hayber → ilk vahiy → Hudeybiye","Hayber → hicret → Hudeybiye","Hudeybiye → Hayber seferi"],"answer":2,"explanation":"Hayber seferi Hudeybiye Antlaşması'ndan sonra gerçekleşmiştir."}],"teacher":{"misconception":"Hayber'i Mekke'nin eski adı gibi karıştırmayın. Ürün paylaşımı bilgisinden bugüne yönelik ayrıntılı hukuk hükmü çıkarmayın.","differentiation":"5–6. sınıfta kuzey-güney yönlerini işaretletin; 7–8. sınıfta siyasî değişim ile üretimin devamı arasındaki ilişkiyi açıklatın.","exit":"Hayber hakkında bir konum bilgisi ve bir geçim bilgisi söyle."},"sources":[{"title":"TDV — Hayber","url":"https://islamansiklopedisi.org.tr/hayber"}]},{"id":41,"module":7,"title":"Beklenen ziyaret: Kaza umresi","date":"629 / Hicrî 7","objective":"Kaza umresini Hudeybiye'de verilen sözle ilişkilendirir.","hook":{"question":"Bir ziyaret ertelendiğinde, ertesi yıl verilen söze göre gerçekleşmesi neyi gösterir?","options":["İlk planın hiçbir önemi olmadığını","Sözün zaman içinde yerine getirildiğini","Antlaşmanın artık hatırlanmasına gerek olmadığını"],"note":"Öğrencilerden söz, bekleyiş ve gerçekleşme kelimelerini bir zaman çizgisine yerleştirmelerini isteyin."},"frames":[{"title":"Önceki yılın sözü","kind":"timeline","labels":["628: Hudeybiye","Ertelenen ziyaret","629: Kaza umresi"],"narration":"Hudeybiye'de o yıl yapılamayan umre için ertesi yıl ziyaret imkânı belirlenmişti. Kaza umresini öğrenirken önce bu anlaşmayı hatırlarız. Bir olayın adı tek başına yeterli açıklama sunmaz; onu hazırlayan önceki gelişme de gerekir. Zaman çizgisinde antlaşma ile ziyaret arasındaki boşluk, unutulmuş bir hedefi değil, beklenen süreyi gösterir. Böylece erteleme ile vazgeçme arasındaki fark görünür olur."},{"title":"Yeniden Mekke yolunda","kind":"route","labels":["Medine","Mekke yolu","Kâbe ziyareti"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) ve Eshâb-ı kirâm, ertesi yıl umre için yeniden Mekke'ye gitti. Bu yolculuk, önceki yılki engelin ardından beklenen ziyaretin gerçekleşmesiydi. Haritadaki güzergâhı izlerken iki ayrı yolculuğu aynı olay gibi düşünmemeliyiz. Başlangıçta umre niyetiyle yapılan Hudeybiye yolculuğu ile daha sonra gerçekleştirilen ziyaret, birbirine bağlı fakat farklı zamanlara ait gelişmelerdir."},{"title":"Belirlenen süreye bağlı ziyaret","kind":"agreement","labels":["Ziyaret hakkı","Üç günlük süre","Şartlara bağlılık"],"narration":"Antlaşmada Mekke'deki ziyaret için üç günlük bir süre belirlenmişti. Müslümanlar ziyareti bu şartlar içinde gerçekleştirdi. Bir söze bağlı kalmak, yalnız kendi isteğimiz yerine geldiğinde sevinmek değildir; üzerinde anlaşılan sınırları da gözetmeyi gerektirir. Bu nedenle ziyaretin gerçekleşmesi kadar nasıl gerçekleştirildiği de önem taşır. Ekrandaki süre işareti, antlaşmanın uygulama aşamasını görünür kılıyor."},{"title":"Bir olaydan iki bilgi","kind":"book","labels":["İbadet","Ahde vefa","Kronolojik bağ"],"narration":"Kaza umresi hem bir ibadetin yerine getirilmesi hem de Hudeybiye'deki sözün uygulanması bakımından önemlidir. Bu iki yönü birlikte açıklayabiliriz. Olayı yalnız bir tarih ezberi olarak bırakmak, önceki antlaşmayla bağını zayıflatır. Şimdi bir küçük sözün verildiği zaman ile yerine getirileceği zamanı ayrı yaz. Bu günlük uygulama, tarihî olayı taklit etmeden sorumluluk üzerinde düşünmene yardım eder."}],"game":{"kind":"sequence","title":"Sözden ziyarete","prompt":"Hudeybiye ile kaza umresi arasındaki bağı sırala.","items":[{"text":"628'de umre niyetiyle yola çıkılması","explanation":"Başlangıçta amaç umre ziyaretidir."},{"text":"Hudeybiye'de görüşmeler ve antlaşma yapılması","explanation":"Engelle karşılaşılınca ziyaret için şartlar belirlenmiştir."},{"text":"O yıl ziyaret yapılmadan geri dönülmesi","explanation":"Antlaşma gereği umre sonraki yıla kalmıştır."},{"text":"629'da belirlenen şartlarla umrenin gerçekleştirilmesi","explanation":"Kaza umresi önceki yılın sözüyle bağlantılıdır."}]},"decision":{"question":"Bir afişte Hudeybiye ile kaza umresi aynı tarihli tek olay gibi gösterilmiş. Nasıl düzeltirsin?","options":["İki olayı ayrı yıllara yerleştirip aralarına antlaşmayla kurulan bağı çizerim.","İsimleri farklı olduğu için aralarındaki bağı tamamen silerim.","Her ikisinde Mekke geçtiği için tek olay olarak bırakırım."],"answer":0,"explanations":["Doğru: olayları ayırırken neden birbirine bağlı olduklarını da gösterdin.","Ayrı olaylar olmaları bağlantısız oldukları anlamına gelmez.","Aynı yerle ilgili iki gelişme farklı zamanlarda gerçekleşebilir."]},"quiz":[{"question":"Kaza umresinin Hudeybiye ile bağı nedir?","options":["Hudeybiye'den önce yapılmış olması","Hudeybiye'de belirlenen sonraki yıl ziyaretinin gerçekleşmesi","Hudeybiye'deki antlaşmayı gereksiz kılması"],"answer":1,"explanation":"Kaza umresi, antlaşmada sonraki yıl için belirlenen ziyaretle bağlantılıdır."},{"question":"Ziyaretin belirlenen süre içinde yapılması neyi gösterir?","options":["Antlaşma şartlarına bağlılığı","Mekke'de sürekli kalma kararını","İlk yolculuğun hiç yapılmadığını"],"answer":0,"explanation":"Üç günlük süreye uyulması, sözün uygulama aşamasındaki bağlılıktır."},{"question":"Bu dersi en iyi özetleyen iki kavram hangisidir?","options":["Göç ve yeni şehir kurma","Kuşatma ve savunma hendeği","İbadet ve ahde vefa"],"answer":2,"explanation":"Kaza umresi bir ibadet ziyareti ve antlaşmadaki sözün yerine getirilmesidir."}],"teacher":{"misconception":"Hudeybiye ile kaza umresini aynı yıl gerçekleşen tek olay gibi anlatmayın. Kaza kelimesini bugünkü trafik kazası anlamıyla karıştıran öğrenciye tarihî terimi açıklayın.","differentiation":"5–6. sınıfta iki yıl arasındaki oku kurdurun; 7–8. sınıfta söz vermek, süre koymak ve uygulamak arasındaki bağı açıklatın.","exit":"Kaza umresi, Hudeybiye'de verilen … yerine gelmesidir."},"sources":[{"title":"TDV — Umretü'l-kazâ","url":"https://islamansiklopedisi.org.tr/umretul-kaza"},{"title":"TDV — Hudeybiye Antlaşması","url":"https://islamansiklopedisi.org.tr/hudeybiye-antlasmasi"}]},{"id":42,"module":7,"title":"Mûte: Zor şartlarda sorumluluk","date":"629 / Hicrî 8","objective":"Mûte'nin temel olaylarını öğrenir ve görev devamlılığını kavrar.","hook":{"question":"Bir ekipte sorumlu kişi görevini sürdüremezse hazırlıklı olmak ne gerektirir?","options":["Görevi önceden açıklanmış bir devam planı","Kimsenin diğerinin işini bilmemesi","Bütün çalışmanın mutlaka durması"],"note":"Konuyu modern bir okul projesi üzerinden açın; tarihî şahısları canlandırmayın ve savaş oyunu kurmayın."},"frames":[{"title":"Mûte'ye giden süreç","kind":"route","labels":["Medine","Kuzey yönü","Mûte"],"narration":"Mûte, 629 yılında Medine'nin kuzeyindeki bölgede gerçekleşen bir karşılaşmadır. Bir elçinin öldürülmesi, bu sefere giden önemli gelişmeler arasında yer alır. Olayı öğrenirken mesaj taşıyan görevlilerin güvenliğinin neden önemli olduğunu da düşünürüz. Haritadaki ok, ordunun hareketini yaklaşık olarak gösterir. Ancak bu çizim askerî taktik öğretmek için kullanılmaz; olayın Medine dışında geçtiğini anlamamıza yardım eder."},{"title":"Önceden belirlenen görev sırası","kind":"timeline","labels":["Hazret-i Zeyd","Hazret-i Ca'fer","Hazret-i Abdullah"],"narration":"Ordunun başına sırasıyla görev almak üzere Hazret-i Zeyd bin Hârise, Hazret-i Ca'fer bin Ebû Tâlib ve Hazret-i Abdullah bin Revâha belirlendi. Bu düzenleme, bir komutan görevini sürdüremezse sorumluluğun kime geçeceğini açıklıyordu. İsimleri öğrenirken asıl kavramı da hatırlarız: görev devamlılığı. Belirsizliğin zor anlarda artmaması için sorumlulukların önceden açıkça tanımlanması önem taşır."},{"title":"Kayıplar ve yeni sorumluluk","kind":"community","labels":["Üç komutanın kaybı","Hazret-i Hâlid","Ordunun dönüşü"],"narration":"Önceden belirlenen üç komutan Mûte'de şehit oldu. Daha sonra yönetimi Hazret-i Hâlid bin Velîd üstlendi ve ordunun Medine'ye dönmesini sağladı. Bu gelişmeleri bir yarışma sıralaması gibi ele almıyoruz. Bir kaybın ardından sorumluluğun nasıl devam ettiğini ve insanların güvenli biçimde geri dönüşünü anlamaya çalışıyoruz. Tarihî kişileri saygıyla anmak, yaşananları eğlencelik bir başarı tablosuna çevirmemeyi de gerektirir."},{"title":"Katılım ile görevlendirmeyi ayırmak","kind":"book","labels":["Görevlendirme","Mûte'deki birlik","Medine"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) Mûte seferine bizzat katılmadı. Bu ayrıntı, bir görevi vermekle görevin yürütüldüğü yerde bulunmanın farklı şeyler olduğunu gösterir. Kaynak okurken aynı cümlede geçen herkesin aynı yerde olduğunu varsaymayız. Bir okul projesinde de çalışmayı planlayan kişiyle belirli aşamayı yürüten kişi farklı olabilir. Etkinlikte sorumluluk, görev devri ve bulunulan yer bilgilerini ayrı ayrı değerlendireceğiz."}],"game":{"kind":"match","title":"Görev ve bilgi ayrımı","prompt":"Kavramları Mûte dersindeki anlamlarıyla eşleştir.","pairs":[{"left":"Görev devamlılığı","right":"Sorumluluğun kime geçeceğinin belirlenmesi","explanation":"Önceden belirtilen sıra belirsizliği azaltır."},{"left":"Önceden belirlenen komutanlar","right":"Hazret-i Zeyd, Hazret-i Ca'fer, Hazret-i Abdullah","explanation":"Üç komutanın görev sırası önceden açıklanmıştır."},{"left":"Daha sonra yönetimi üstlenen","right":"Hazret-i Hâlid bin Velîd","explanation":"Üç komutanın şehadetinden sonra sorumluluk üstlenmiştir."},{"left":"Bizzat katılma bilgisi","right":"Görevlendirmeden ayrı kontrol edilir","explanation":"Bir sefere görevli göndermek, o sefere bizzat katılmak değildir."}]},"decision":{"question":"Bir grup projesinde dosyayı yalnız bir öğrenci biliyor; o gün okula gelemiyor. Hangi hazırlık en yararlı olurdu?","options":["Bütün işi baştan başka bir konuya çevirmek.","Görevleri ve gerekli bilgileri paylaşarak bir yedek sorumlu belirlemek.","Kimin ne yaptığını hiç yazmamak."],"answer":1,"explanations":["Bazen plan değişebilir; fakat asıl eksik görev devamlılığının hazırlanmamış olmasıdır.","Doğru: görev devri için kişi kadar bilginin de paylaşılması gerekir.","Belirsizlik, sorumlu kişi bulunmadığında çalışmayı daha çok zorlaştırır."]},"quiz":[{"question":"Komutanların önceden sıralanması hangi ihtiyaca cevap verir?","options":["Herkesin aynı anda aynı emri vermesine","Görev değişiminde belirsizliği azaltmaya","Hiçbir kararın sorumluluğunu üstlenmemeye"],"answer":1,"explanation":"Görev devamlılığı için sorumluluğun hangi sırayla geçeceği açıklanmıştır."},{"question":"Mûte'ye bizzat katılım hakkında doğru bilgi hangisidir?","options":["Peygamber Efendimiz (sallallahü aleyhi ve sellem) bu sefere bizzat katılmadı.","Peygamber Efendimiz (sallallahü aleyhi ve sellem) üç komutandan sonra Mûte'de yönetimi üstlendi.","Mûte, Medine'nin içindeki bir toplantının adıdır."],"answer":0,"explanation":"Görevlendirme ile bizzat katılım farklıdır; Mûte seferi Medine dışında gerçekleşmiştir."},{"question":"Üç komutandan sonra yönetimi kim üstlendi?","options":["Hazret-i Dihye bin Halîfe","Hazret-i Selmân-ı Fârisî","Hazret-i Hâlid bin Velîd"],"answer":2,"explanation":"Hazret-i Hâlid bin Velîd yönetimi üstlenerek ordunun Medine'ye dönüşünü sağlamıştır."}],"teacher":{"misconception":"Mûte'yi bizzat katılınan bir gazve gibi sunmayın. Komutan sırası yarışma veya rol oyunu konusu yapılmamalı.","differentiation":"5–6. sınıfta görev devri şeması kurdurun; 7–8. sınıfta yedek kişinin yanında hangi bilginin de paylaşılması gerektiğini açıklatın.","exit":"Görev devamlılığı için önceden … belirlenmelidir."},"sources":[{"title":"TDV — Mûte Savaşı","url":"https://islamansiklopedisi.org.tr/mute-savasi"}]},{"id":43,"module":8,"title":"Antlaşma bozulunca","date":"630 / Hicrî 8","objective":"Mekke'nin fethine giden süreci antlaşma sorumluluğuyla ilişkilendirir.","hook":{"question":"Bir ortak sözleşmede bir grubun destek verdiği davranış da önemli midir?","options":["Yalnız kendi eliyle yaptığı işler önemlidir.","Destek verdiği ihlal, sözleşme sorumluluğuyla ilgili olabilir.","Sözleşme imzalandıktan sonra davranışlara bakılmaz."],"note":"Bu soruyu bireylere toplu suç yüklemek için kullanmayın; belirli tarihî tarafların belirli eylem ve desteklerini konuşun."},"frames":[{"title":"Hudeybiye'nin kurduğu ilişkiler","kind":"agreement","labels":["Müslümanlar","Kureyş","İttifak kuran kabileler"],"narration":"Hudeybiye Antlaşması yalnız ziyaret tarihini düzenlemiyordu; kabilelerin taraflarla ittifak kurmasına da imkân veriyordu. Huzâa, Müslümanların; Benî Bekir ise Kureyş'in müttefiki oldu. Bu ilişkileri şemada çizgilerle gösteriyoruz. İttifak çizgisi, kabile üyelerinin hepsinin aynı inanca sahip olduğunu söylemez. Buradaki bilgi, taraflar arasındaki siyasî ilişki ve karşılıklı sorumluluklarla ilgilidir; kavramları bu sınır içinde kullanmalıyız."},{"title":"Antlaşmayı bozan gelişme","kind":"timeline","labels":["İttifaklar","Huzâa'ya saldırı","Kureyş'in desteği"],"narration":"Benî Bekir'in Huzâa'ya saldırması ve Kureyş'in bu saldırıya destek vermesi, Hudeybiye Antlaşması'nın bozulmasına yol açtı. Olayın nedenini yalnız 'zaman geçti' diyerek açıklayamayız; belirli bir ihlal söz konusuydu. Bu yüzden zaman sırasıyla neden-sonuç ilişkisini birlikte kurmak gerekir. Bir olay diğerinden sonra gerçekleşebilir, fakat aradaki gerçek sebebi göstermek için ayrıca bilgiye ihtiyaç vardır."},{"title":"İhlalin ardından başvuru ve hazırlık","kind":"journey","labels":["Huzâa heyeti","Medine","Mekke'ye hazırlık"],"narration":"Huzâa'dan gelen başvuru, yaşananların Medine'ye ulaşmasını sağladı. Gelişmelerin ardından Mekke'ye yönelik hazırlık yapıldı. Bu aşamayı önceki antlaşmadan tamamen koparırsak fethin yakın sebebini gözden kaçırırız. Ekranda haberin gelişi ile hazırlık ayrı duraklar olarak yer alıyor. Kaynak okurken hangi bilginin kime ulaştığını ve sonrasında hangi kararın alındığını takip etmek, süreci daha anlaşılır kılar."},{"title":"Sözleşme, imzadan sonra da sürer","kind":"values","labels":["Verilen söz","Davranış","Sorumluluk"],"narration":"Bir antlaşmanın anlamı, yalnız imzalanmasında değil, sonraki davranışlarla sürdürülmesindedir. Hudeybiye'nin bozulmasını öğrenirken bu sorumluluk boyutunu görürüz. Bugünkü bir sınıf sözleşmesinde de kuralların açık olması ve bir sorun çıktığında ne yapılacağının bilinmesi önemlidir. Bununla birlikte tarihî devlet ve kabile ilişkilerini sınıftaki küçük anlaşmazlıklarla aynı büyüklükte görmeyiz; yalnız sorumluluk kavramı üzerinden bir öğrenme bağlantısı kurarız."}],"game":{"kind":"sequence","title":"Fethe giden yakın süreç","prompt":"Antlaşma ile hazırlık arasındaki gelişmeleri sırala.","items":[{"text":"Hudeybiye'de kabilelerin ittifak kurabilmesi","explanation":"Önce ilişkileri düzenleyen antlaşma çerçevesi vardır."},{"text":"Huzâa ile Benî Bekir'in farklı taraflarla ittifakı","explanation":"Huzâa Müslümanların, Benî Bekir Kureyş'in müttefikidir."},{"text":"Huzâa'ya saldırı ve Kureyş'in desteği","explanation":"Bu gelişme antlaşmanın ihlali olarak önemlidir."},{"text":"Başvuru ve gelişmelerin ardından Mekke'ye hazırlık","explanation":"Fethin yakın süreci antlaşmanın bozulmasıyla bağlantılıdır."}]},"decision":{"question":"Bir öğrenci 'Mekke'nin fethi, Hudeybiye'nin doğal süresi dolduğu için oldu' yazmış. Hangi düzeltme gerekir?","options":["Asıl yakın gelişme antlaşmanın ihlaliydi; Huzâa'ya saldırı ve Kureyş'in desteği belirtilmeli.","Antlaşmanın bütün maddeleri ve tarihi çıkarılmalı.","İttifaklar olduğu için hiçbir ihlal yaşanamayacağı söylenmeli."],"answer":0,"explanations":["Doğru: yalnız zamanın geçmesini değil, kaynakta belirtilen ihlali açıklamaya ekledin.","Antlaşma bilgisini silmek, olaylar arasındaki bağı koparır.","İttifak kurmak ihlali imkânsız yapmaz; tam tersine sorumlulukları da beraberinde getirir."]},"quiz":[{"question":"Huzâa'nın Hudeybiye sonrasındaki ilişkisi hangisidir?","options":["Kureyş'in müttefiki olması","Hiçbir tarafla ilişki kurmaması","Müslümanların müttefiki olması"],"answer":2,"explanation":"Huzâa Müslümanlarla, Benî Bekir Kureyş'le ittifak kurmuştur."},{"question":"Fethe giden yakın süreçte belirleyici olay hangisidir?","options":["Antlaşmanın kendiliğinden unutulması","Huzâa'ya saldırı ve Kureyş'in desteğiyle antlaşmanın ihlali","Kıblenin Kâbe'ye çevrilmesi"],"answer":1,"explanation":"Bu ihlal, Mekke'ye yönelik hazırlığın yakın bağlamını oluşturur."},{"question":"İttifak şemasını okurken hangi çıkarımdan kaçınmalıyız?","options":["Aynı taraftaki herkesin aynı inanca sahip olduğunu varsaymaktan","Taraflar arasında sorumluluk olduğunu görmekten","Kabilelerin ilişkilerini çizgilerle göstermekten"],"answer":0,"explanation":"Siyasî ittifak bilgisi, bütün üyelerin inancı hakkında tek başına hüküm vermez."}],"teacher":{"misconception":"Bütün kabile üyelerine topluca suç yüklemeyin; kaynakta belirtilen saldırı ve desteği anlatın. İttifak ile aynı inanca sahip olmayı eşitlemeyin.","differentiation":"5–6. sınıfta dört olayın sırasını kurdurun; 7–8. sınıfta 'sonra oldu' ile 'bu yüzden oldu' arasındaki farkı açıklatın.","exit":"Mekke'nin fethine giden yakın süreci 'antlaşma–ihlal–hazırlık' kelimeleriyle açıkla."},"sources":[{"title":"TDV — Mekke: fethin süreci","url":"https://islamansiklopedisi.org.tr/mekke"},{"title":"TDV — Huzâa","url":"https://islamansiklopedisi.org.tr/huzaa-beni-huzaa"}]},{"id":44,"module":8,"title":"Mekke'ye dönüş","date":"630 / Hicrî 8","objective":"Mekke'nin fethinin temel gelişmelerini kronolojik olarak sıralar.","hook":{"question":"622'de Mekke'den ayrılış ile 630'da Mekke'ye dönüşü aynı olay sayabilir miyiz?","options":["Aynı şehir geçtiği için evet.","Hayır; zamanları, yönleri ve şartları farklıdır.","Yalnız iki tarih birbirine yakınsa aynı sayılır."],"note":"İki yönlü ok gösterin. Çocukların hicret ve fetih terimlerini ayrı olaylara bağlamasını sağlayın."},"frames":[{"title":"Ayrılıştan dönüşe","kind":"timeline","labels":["622: Hicret","Medine yılları","630: Fetih"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) 622'de hicret ederek ayrıldığı Mekke'ye 630'da büyük bir toplulukla döndü. Bu iki olay arasında Medine'de geçen yıllar ve birçok gelişme bulunur. Zaman çizgisindeki okları yalnız gidiş-dönüş yolculuğu gibi okumayız; şartların nasıl değiştiğini de düşünürüz. Hicret ile fetih aynı olay değildir. İkisinin bağlantısını kurarken her birinin kendi tarihini ve anlamını korumak gerekir."},{"title":"Mekke'ye giriş","kind":"city","labels":["Mekke","Giriş güzergâhları","Çatışmayı sınırlama"],"narration":"Mekke büyük ölçüde çatışma yaşanmadan alındı; bazı noktalarda sınırlı çatışmalar oldu. Bu nedenle 'hiçbir yerde hiçbir çatışma olmadı' demek de, bütün şehri büyük bir savaş alanı gibi anlatmak da doğru değildir. Tarihî bir gelişmeyi anlatırken ölçülü ifadeler kullanırız. Ekrandaki şehir şeması yerleşimi gösterir; çatışmayı canlandıran veya kişileri hedef yapan bir oyun değildir."},{"title":"Kâbe ve tevhid","kind":"values","labels":["Kâbe","Putların kaldırılması","Tevhid"],"narration":"Fetih sırasında Kâbe'deki putlar kaldırıldı. Kâbe'nin tevhid inancıyla ibadet edilen merkez olması vurgulandı. Tevhid, Allahü teâlânın birliğini kabul etmektir; Kâbe ise namazda yönelinen kıbledir. Daha önceki kıble dersini hatırlarsak, mekânın önemini ibadetin kime yapıldığıyla karıştırmayız. Bu bölümde dinî anlamı, zaman çizgisindeki siyasî gelişmelerle birlikte fakat kavramları birbirine karıştırmadan öğreniyoruz."},{"title":"Yeni dönem, devam eden sorumluluk","kind":"community","labels":["Şehir halkı","Güvence","Yeni ilişkiler"],"narration":"Fetih sonrasında şehir halkıyla nasıl ilişki kurulacağı da önemliydi. Bir şehrin yönetimindeki değişim, orada yaşayan insanların hayatını doğrudan etkiler. Bu yüzden yalnız giriş anını öğrenmek yeterli olmaz; güvence ve merhamet yaklaşımını da incelemek gerekir. Bir sonraki bölüm bu konuya ayrılıyor. Böylece fetih, sadece tarih ve yer bilgisinden oluşan kısa bir başlık olarak kalmayacak."}],"game":{"kind":"match","title":"Üç dönüm noktası","prompt":"Olayları tarihleri ve temel anlamlarıyla eşleştir.","pairs":[{"left":"610 — İlk vahiy","right":"Mekke döneminde peygamberliğin başlangıcı","explanation":"İlk vahiy, hicretten önce gerçekleşmiştir."},{"left":"622 — Hicret","right":"Mekke'den Medine'ye göç","explanation":"Hicret ile Medine dönemi başlamıştır."},{"left":"630 — Mekke'nin fethi","right":"Mekke'ye dönüş ve yeni dönem","explanation":"Fetih, hicretten yıllar sonra gerçekleşmiştir."},{"left":"Tevhid","right":"Allahü teâlânın birliğini kabul etmek","explanation":"Kâbe'nin dinî önemi tevhid ve ibadet çerçevesinde anlaşılır."}]},"decision":{"question":"Bir arkadaşın sunumunda 'Fetihte hiçbir yerde çatışma olmadı' yazıyor. Hangi ifade kaynak bilgisini daha iyi korur?","options":["Şehir büyük ölçüde çatışmasız alındı; bazı noktalarda sınırlı çatışmalar oldu.","Bütün şehirde uzun süre büyük çatışmalar yaşandı.","Ayrıntı bulunduğu için fethin gerçekleştiği söylenemez."],"answer":0,"explanations":["Doğru: genel durumu ve istisnayı birlikte koruyarak ölçülü bir ifade kullandın.","Bu ifade olayın genel niteliğini abartılı biçimde değiştirir.","Bazı ayrıntıların bulunması olayın gerçekleştiği bilgisini ortadan kaldırmaz."]},"quiz":[{"question":"Hicret ve Mekke'nin fethi için doğru sıra hangisidir?","options":["630: Hicret → 622: Fetih","622: Hicret → 630: Fetih","610: Fetih → 622: Hicret"],"answer":1,"explanation":"Hicret 622'de, Mekke'nin fethi 630'da gerçekleşmiştir."},{"question":"Tevhid kavramı neyi ifade eder?","options":["Bir şehirde kalıcı olarak yerleşmeyi","Bütün yolların Mekke'de birleşmesini","Allahü teâlânın birliğini kabul etmeyi"],"answer":2,"explanation":"Tevhid inançla ilgilidir; yalnız coğrafî veya siyasî bir kavram değildir."},{"question":"Fethi yalnız şehre giriş anıyla anlatmak neyi eksik bırakır?","options":["Şehir halkıyla kurulan ilişkileri ve sonraki sorumlulukları","Mekke'nin adının nasıl yazıldığını","Bütün olayların aynı yıl olduğunu"],"answer":0,"explanation":"Fetih sonrası güvence ve toplumsal ilişkiler de olayın önemli bir yönüdür."}],"teacher":{"misconception":"Hicreti fetihle karıştırmayın. 'Tamamen çatışmasız' veya 'büyük bir şehir savaşı' gibi aşırı genellemelerden kaçının.","differentiation":"5–6. sınıfta 610–622–630 çizgisini kurdurun; 7–8. sınıfta genel durumla istisnayı aynı cümlede doğru anlatmayı çalıştırın.","exit":"Hicret ile Mekke'nin fethini tarih, yön ve anlam bakımından birer ifadeyle ayır."},"sources":[{"title":"TDV — Mekke","url":"https://islamansiklopedisi.org.tr/mekke"}]},{"id":45,"module":8,"title":"Güçlüyken merhametli olmak","date":"630 / Mekke'nin fethi","objective":"Mekke'nin fethindeki geniş af yaklaşımını anlar.","hook":{"question":"Güçlü durumda olan birinin geçmişteki anlaşmazlığı çözmesinde hangi ölçü önemlidir?","options":["İntikamı bir başarı göstergesi saymak","Herkesi aynı davranıştan sorumlu tutmak","Adaleti, güvenliği ve merhameti birlikte gözetmek"],"note":"Affetmeyi her zarar karşısında susma veya güvensiz ilişkiye dönme zorunluluğu olarak açıklamayın."},"frames":[{"title":"Şehir halkının endişesi","kind":"city","labels":["Geçmiş karşıtlıklar","Fetih günü","Gelecek endişesi"],"narration":"Mekke'de geçmişte Müslümanlara karşı çıkmış birçok kişi, fetih sırasında kendisine nasıl davranılacağını merak ediyordu. Şehirde değişen güç dengesi, insanların günlük hayatını ve güvenlik duygusunu etkiliyordu. Bu durumu anlamak için yalnız güçlü olan tarafın imkânlarına değil, şehir halkının kaygılarına da bakarız. Böylece tarihî olayın insanî yönü görünür olur; merhamet konusunu gerçek bir bağlam içinde ele alırız."},{"title":"Geniş af ve güvence","kind":"community","labels":["Güvence","Geniş af","Hayatın devamı"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) Mekke halkının büyük çoğunluğuna güvence verdi ve geniş bir af yaklaşımı gösterdi. Burada kullanılan 'büyük çoğunluk' ifadesi önemlidir; bütün ayrıntıları tek cümlede yok saymıyoruz. Fetihteki bu yaklaşım, gücün kişisel intikam için kullanılmamasına güçlü bir örnektir. İnsanların geleceğine ilişkin güven duyması, bir şehirde hayatın yeniden düzenlenmesi bakımından da büyük önem taşır."},{"title":"Bir güvence örneği","kind":"home","labels":["Hazret-i Ebû Süfyân'ın evi","Güvence","İnsanların korunması"],"narration":"Fetih günü Hazret-i Ebû Süfyân'ın evine sığınanlara güvence verildiği kaynaklarda anlatılır. Bu örnek, güvence kavramını soyut bir söz olmaktan çıkarıp somut bir uygulamayla ilişkilendirir. Ekrandaki ev çizimi yalnız temsilîdir; tarihî yapının gerçek görünüşü olduğu iddia edilmez. Burada önemli olan binanın biçimini ezberlemek değil, insanlara verilen emniyetin ne anlama geldiğini kavramaktır."},{"title":"Merhamet ve güveni birlikte düşünmek","kind":"values","labels":["İntikamdan uzaklaşmak","Sorumluluğu kabul etmek","Güveni yeniden kurmak"],"narration":"Fetihteki merhamet örneği, bugün bir anlaşmazlığı çözerken yalnız karşılık verme isteğiyle hareket etmemeyi düşündürür. Ancak affetmek, devam eden zararı görmezden gelmek veya kendini güvensiz bir duruma sokmak demek değildir. Günlük hayatta özür, sorumluluk alma ve güveni yeniden kurma birlikte ele alınabilir. Zorlandığımız durumlarda bir yetişkinden destek isteriz. Bu uygulama önerisini tarihî olayın kendisinden ayrı tutarız."}],"game":{"kind":"classify","title":"Merhamet ile sınırları birlikte düşün","prompt":"Günlük örnekleri yapıcı yaklaşım ve sorunu büyüten yaklaşım olarak ayır.","groups":["Yapıcı ve güvenli yaklaşım","Sorunu büyüten yaklaşım"],"items":[{"text":"Hata kabul edildiğinde nasıl telafi edileceğini konuşmak","group":0,"explanation":"Sorumluluk ve güvenin yeniden kurulması birlikte düşünülüyor."},{"text":"Geçmişteki hatayı her fırsatta küçük düşürmek için kullanmak","group":1,"explanation":"Bu davranış çözümden çok intikamı ve aşağılamayı sürdürür."},{"text":"Tekrarlanan zarar karşısında güvenilir yetişkinden yardım istemek","group":0,"explanation":"Merhamet göstermek güvenliği ve sınırları bırakmayı gerektirmez."},{"text":"Bir kişinin hatası yüzünden bütün grubunu suçlamak","group":1,"explanation":"Sorumluluk belirli davranışa göre ele alınmalı, herkese yayılmamalıdır."},{"text":"Özürle birlikte davranışın değişmesini beklemek","group":0,"explanation":"Güven yalnız sözle değil sonraki davranışlarla da güçlenir."},{"text":"Affetmeyi zarara sessiz kalma zorunluluğu saymak","group":1,"explanation":"Af ve merhamet, güvenli sınırlarla birlikte düşünülebilir."}]},"decision":{"question":"Bir arkadaşın eşyanı izinsiz aldığı için özür diliyor; aynı davranış daha önce de olmuş. Hangi cevap daha uygun?","options":["Özür dilediği için bir daha sınır koymamalıyım.","Özrünü dinleyip eşyamı izinsiz almamasını açıkça söyler, gerekirse öğretmenden destek isterim.","Bundan sonra bütün arkadaşlarını da suçlarım."],"answer":1,"explanations":["Özrü değerlendirmek, sınırlarından vazgeçmek zorunda olduğun anlamına gelmez.","Doğru: barışma isteğini, davranış değişikliğini ve güvenli desteği birlikte düşündün.","Bir kişinin davranışı bütün arkadaşlarının sorumluluğu değildir; topluca suçlamak adil olmaz."]},"quiz":[{"question":"Fetihteki geniş af yaklaşımı hangi tutuma örnektir?","options":["Gücü kişisel intikam için kullanmamaya","Geçmişte hiç anlaşmazlık yaşanmadığını söylemeye","Herkese aynı suçu yüklemeye"],"answer":0,"explanation":"Geçmiş karşıtlıklara rağmen geniş af ve güvence verilmesi intikamdan uzaklaşmayı gösterir."},{"question":"Kaynak bilgisini aktarırken hangi ifade daha ölçülüdür?","options":["Bütün olaylar ve bütün kişiler için hiçbir istisna yoktu.","Fetihte hiç kimse geleceği hakkında kaygı duymadı.","Halkın büyük çoğunluğuna güvence ve geniş af yaklaşımı gösterildi."],"answer":2,"explanation":"Bu ifade genel yaklaşımı anlatırken tarihî ayrıntıları tek bir mutlak hükümle silmez."},{"question":"Bugünkü bir anlaşmazlıkta merhamet ile güvenlik nasıl birlikte düşünülebilir?","options":["Sınırları tamamen kaldırarak","Özrü dinleyip telafi, davranış değişikliği ve gerektiğinde destek arayarak","Yalnız karşı tarafı cezalandırmayı düşünerek"],"answer":1,"explanation":"Yapıcı çözüm, merhameti kişinin güvenliği ve sorumluluklarla birlikte gözetir."}],"teacher":{"misconception":"Af öğretimini öğrenciyi zorbalığa, tekrarlanan zarara veya güvensiz ilişkiye katlanmaya zorlayan bir mesaja dönüştürmeyin. Genel af anlatımında tarihî istisnaları yok sayan mutlak ifadeler kullanmayın.","differentiation":"5–6. sınıfta özür ve telafi örneklerini ayırın; 7–8. sınıfta af, adalet, sınır ve güven kavramlarını birlikte açıklatın.","exit":"Merhametli bir çözümde hem … hem … korunabilir."},"sources":[{"title":"TDV — Mekke: fetih ve güvence","url":"https://islamansiklopedisi.org.tr/mekke"},{"title":"TDV — Hazret-i Ebû Süfyân","url":"https://islamansiklopedisi.org.tr/ebu-sufyan"}]},{"id":46,"module":8,"title":"Huneyn: Çokluğa güvenmek yetmez","date":"630 / Hicrî 8","objective":"Huneyn'den çıkarılan hazırlık ve alçak gönüllülük dersini açıklar.","hook":{"question":"Bir grubun kalabalık olması, karşılaşacağı her güçlüğü aşmasını sağlar mı?","options":["Sayı arttıkça sonuç kesinleşir.","Sayı önemlidir; hazırlık ve uyum da gerekir.","Kalabalık gruplar hiçbir zaman başarılı olmaz."],"note":"Cevapları henüz puanlamayın. Sayı ile hazırlığı birbirinden ayıran bir gerekçe isteyin."},"frames":[{"title":"Fetihten sonraki gelişme","kind":"timeline","labels":["Mekke'nin fethi","Huneyn","630 yılı"],"narration":"Mekke'nin fethinden sonra bölgede bütün sorunlar bir anda sona ermedi. Hevâzin ve Sakīf topluluklarıyla yaşanan gerilim Huneyn karşılaşmasına yol açtı. Olay 630 yılında, hicrî sekizinci yılda gerçekleşti. Zaman çizgisinde önce fethi, ardından Huneyn'i bul. Böylece aynı yıl içinde gerçekleşen iki ayrı olayın sebebini ve yerini birbirine karıştırmamış olursun."},{"title":"Sayı ile hazırlık aynı şey değildir","kind":"values","labels":["Kalabalık","Hazırlık","Uyum","Dikkat"],"narration":"Huneyn'e katılan Müslümanların sayısı önceki birçok karşılaşmadan fazlaydı. Buna rağmen başlangıçta beklenmedik bir saldırıyla karşılaşılması düzensizliğe yol açtı. Çok sayıda kişinin aynı yerde bulunması, herkesin aynı bilgiye sahip olduğunu göstermez. Şemada kalabalık ile hazırlığı ayrı kutularda görüyorsun. Bir ekibin birlikte hareket etmesi için bu ikisinin yanına hangi becerilerin eklenmesi gerektiğini düşün."},{"title":"Zor anda yeniden toparlanmak","kind":"community","labels":["Güçlük","Sakinlik","Haberleşme","Toparlanma"],"narration":"İlk karışıklık karşılaşmanın son sonucu olmadı. Peygamber Efendimiz (sallallahü aleyhi ve sellem) yerinde kaldı; yapılan çağrılarla dağılmış olanlar yeniden toplandı. Huneyn, başlangıçtaki güçlüğün ardından toparlanılan bir olay olarak hatırlandı. Burada kişileri suçlama yarışına girmiyoruz. Olayların akışını okuyor; iletişimin kesildiği bir anda ortak yönü yeniden bulmanın neden önemli olduğunu tartışıyoruz."},{"title":"Kur'ân-ı Kerîm'in hatırlatması","kind":"book","labels":["Tevbe 9/25","Çokluğa güven","Tevbe 9/26","Allahü teâlânın yardımı"],"narration":"Kur'ân-ı Kerîm'in Tevbe sûresindeki ilgili âyet-i kerîmeler, Huneyn'de çoklukla övünmenin yeterli olmadığını hatırlatır ve Allahü teâlânın yardımını bildirir. Buradan çıkaracağımız ders, hazırlığı bırakmak değildir. İmkânlarımızla gurura kapılmadan sorumluluğumuzu yerine getirmektir. Tarihî olay ile bugün çıkardığımız ders arasındaki bağı kurarken, kendi yorumumuzu âyet-i kerîmenin doğrudan sözü gibi sunmamaya dikkat ederiz."}],"game":{"kind":"sequence","title":"Huneyn'in akışını kuralım","prompt":"Sonucu başa almadan dört gelişmeyi sıraya yerleştir.","items":[{"text":"Mekke'nin fethi gerçekleşti.","explanation":"Huneyn, Mekke'nin fethinden sonraki gelişmelerdendir."},{"text":"Huneyn'de karşılaşma başladı.","explanation":"Bölgedeki gerilim bu karşılaşmaya dönüştü."},{"text":"Başlangıçta karışıklık yaşandı.","explanation":"Kalabalık olmak ilk güçlüğü engellemedi."},{"text":"Dağılanlar yeniden toplandı.","explanation":"İlk güçlük ile olayın sonunu birbirinden ayırırız."}]},"decision":{"question":"Bir öğrenci 'Huneyn bize plan yapmanın işe yaramadığını öğretir' diyor. Hangi düzeltme isabetlidir?","options":["Plan yapmak yerine yalnızca kişi sayısını artırmalıyız.","Ders, hazırlığı bırakmak değil çokluğa güvenip gurura kapılmamaktır.","İlk güçlük yaşandığı için Huneyn'in sonrasını öğrenmemize gerek yok."],"answer":1,"explanations":["Sayının tek başına yeterli olmadığı özellikle vurgulanıyor.","Evet. Sorumluluk, hazırlık ve alçak gönüllülük birlikte düşünülür.","Olayın başlangıcı kadar toparlanma süreci de öğrenilmelidir."]},"quiz":[{"question":"Huneyn'i zaman çizgisine doğru yerleştiren ifade hangisi?","options":["Mekke'nin fethinden sonra, 630 yılında","Hicretten önce, Mekke döneminde","Veda haccından sonra, 632 yılında"],"answer":0,"explanation":"Huneyn hicrî sekizinci yılda, Mekke'nin fethinden sonra gerçekleşti."},{"question":"Başlangıçta yaşanan güçlük hangi düşünceyi sorgulatır?","options":["Haberleşmenin önemli olduğunu","Sayıca üstünlüğün başarıyı tek başına garanti ettiğini","Bir olayın farklı aşamaları bulunduğunu"],"answer":1,"explanation":"Kalabalık grubun da beklenmedik güçlük yaşayabildiğini görüyoruz."},{"question":"Olayı anlatan bir öğrenci neyi ayırmalıdır?","options":["Mekke ile Medine'nin iklimini","Kaynaklı gelişmeler ile kendi çıkardığı günlük hayat dersini","Bütün tarihî olayları yalnızca kazanan ve kaybeden diye"],"answer":1,"explanation":"Tarihî bilgiye sadık kalırız; kendi yorumumuzu kaynakta geçiyormuş gibi sunmayız."}],"teacher":{"misconception":"'Kalabalık olmak önemsizdir' ve 'hazırlık gereksizdir' sonuçlarını düzeltin; ders tek bir etkenin yeterli olmamasıdır.","differentiation":"5–6. sınıfta önce-sonra okları; 7–8. sınıfta başlangıç ve sonuç arasındaki değişimin iki sebebi.","exit":"'Çokluğun yanında … gerekir; bunu olayın … aşamasından anlıyorum.' cümlesini tamamlatın."},"sources":[{"title":"TDV — Huneyn Gazvesi","url":"https://islamansiklopedisi.org.tr/huneyn-gazvesi"}]},{"id":47,"module":8,"title":"Tâif ve Medine'ye dönüş","date":"630 / Hicrî 8","objective":"Huneyn sonrasındaki gelişmeleri ve Medine'ye dönüşü tanır.","hook":{"question":"Bir şehrin kuşatılması, o şehrin aynı sırada alındığı anlamına gelir mi?","options":["İkisi aynı anlamdadır.","Sonucu ayrıca öğrenmem gerekir.","Kuşatma varsa daha sonra görüşme yapılamaz."],"note":"Kuşatma, kuşatmanın kaldırılması ve daha sonra yapılan görüşmeyi üç ayrı olay olarak açıklayın."},"frames":[{"title":"Huneyn'den Tâif'e","kind":"route","labels":["Huneyn","Tâif","630 yılı"],"narration":"Huneyn'den sonra gelişmeler Tâif çevresinde devam etti. Tâif, Mekke'nin doğusunda bulunan, yüksek ve verimli bir yerleşim yeriydi. Şehrin güçlü surları vardı. Haritada şehir adını bulurken bir ayrımı koru: Huneyn bir karşılaşmanın adı ve yeri, Tâif ise bir şehirdir. Aynı yolculuk içindeki bu iki durağı tek bir olaymış gibi anlatmayız."},{"title":"Kuşatma ve sonuç","kind":"city","labels":["Şehir surları","Kuşatma","Kuşatmanın kaldırılması"],"narration":"Tâif kuşatıldı; fakat şehir bu kuşatma sırasında alınmadı. Bir süre sonra kuşatma kaldırıldı. Bu sonucu açıkça söylemek, tarihî anlatımı doğru kurmanın bir parçasıdır. Haritada bir yere ok çizmek, orada ne yaşandığını tek başına anlatmaz. Okun yanına olayın adını ve sonucunu birlikte koyduğumuzda hareket ile sonuç arasındaki fark görünür olur."},{"title":"Daha sonra gelen heyet","kind":"agreement","labels":["Kuşatma sonrası","Sakīf heyeti","Medine'de görüşme"],"narration":"Tâif'in hikâyesi kuşatmanın kaldırılmasıyla bitmedi. Daha sonraki süreçte Sakīf kabilesinden bir heyet Medine'ye geldi ve görüşmeler yapıldı. Bu ziyaret, önceki kuşatmayla aynı anda gerçekleşmiş gibi gösterilemez. Zaman çizgisindeki iki kutu arasında boşluk bırakılması bu yüzden önemlidir. Bazen bir gelişmeyi anlayabilmek için hemen sonraki günü değil, daha sonraki dönemi de incelememiz gerekir."},{"title":"Merkez olarak Medine","kind":"map","labels":["Mekke","Tâif","Medine","Dönüş"],"narration":"Mekke'nin fethinden sonra Peygamber Efendimiz (sallallahü aleyhi ve sellem) hayatını Medine'de sürdürdü. İslâm toplumunun yönetim ve öğrenme merkezi Medine olmaya devam etti. Mekke'nin dinî öneminin artması ile yönetim merkezinin değişmesi aynı şey değildir. Yolculuk haritasında dönüş okunu Medine'ye yerleştir. Ardından iki şehrin bu dönemdeki rollerini birer cümleyle ayırt et."}],"game":{"kind":"classify","title":"Olay mı, daha sonraki gelişme mi?","prompt":"Kartları 630'daki kuşatma süreci ve sonraki görüşme olarak ayır.","groups":["Kuşatma süreci","Daha sonraki görüşme"],"items":[{"text":"Tâif surları önünde bulunulması","group":0,"explanation":"Bu, şehrin kuşatıldığı aşamadır."},{"text":"Şehrin kuşatma sırasında alınmaması","group":0,"explanation":"Kuşatmanın sonucu budur."},{"text":"Kuşatmanın kaldırılması","group":0,"explanation":"Askerî kuşatma bu kararla sona erdi."},{"text":"Sakīf temsilcilerinin Medine'ye gelmesi","group":1,"explanation":"Heyetin gelişi daha sonraki süreçtedir."},{"text":"Medine'de heyetle meselelerin görüşülmesi","group":1,"explanation":"Bu, kuşatma ekranından ayrı bir görüşme aşamasıdır."},{"text":"Tâif ile ilgili yeni ilişkinin görüşmelerle kurulması","group":1,"explanation":"Sonraki görüşmeler tarihin devamını gösterir."}]},"decision":{"question":"Sınıf panosuna '630: Tâif kuşatıldı ve aynı gün alındı' yazılmış. En doğru düzeltme hangisi?","options":["Kuşatma sırasında alınmadığını, daha sonra heyet geldiğini yazmak","Tâif adını silip yerine Medine yazmak","Tâif ile ilgili bütün olayların tarihini aynı kabul etmek"],"answer":0,"explanations":["Kuşatma sonucu ile sonraki görüşmeyi doğru ayırır.","Şehir adını değiştirmek yanlış bilgiyi düzeltmez.","Bir şehirdeki her olay aynı tarihte gerçekleşmez."]},"quiz":[{"question":"Tâif kuşatması için doğru sonuç hangisi?","options":["Şehir kuşatma sırasında alındı.","Kuşatma kaldırıldı; şehir o sırada alınmadı.","Bu olay hicretten önce gerçekleşti."],"answer":1,"explanation":"Kuşatma ve fetih aynı anlama gelmez; burada kuşatma kaldırıldı."},{"question":"Sakīf heyetinin gelişi nasıl yerleştirilmelidir?","options":["Kuşatmayla aynı an olarak","Huneyn'den önceki olay olarak","Daha sonraki gelişme olarak"],"answer":2,"explanation":"Görüşmeler önceki kuşatmadan sonraki süreçte yapıldı."},{"question":"Mekke'nin fethinden sonra yönetim merkezi nerede kaldı?","options":["Medine","Tâif","Mekke"],"answer":0,"explanation":"Mekke'nin dinî önemine rağmen merkez Medine olarak sürdü."}],"teacher":{"misconception":"Kuşatma=fetih ve Mekke'nin fethi=Medine'nin önemini kaybetmesi eşitliklerini düzeltin.","differentiation":"Küçük sınıflar üç şehir adıyla ok kurar; büyük sınıflar kuşatma sonucu ile sonraki görüşmeyi iki ayrı zaman kutusunda açıklar.","exit":"'Tâif'te önce …; daha sonra …; yönetim merkezi ise …' cümlesini tamamlatın."},"sources":[{"title":"TDV — Tâif","url":"https://islamansiklopedisi.org.tr/taif"}]},{"id":48,"module":8,"title":"Tebük: Güçlük içinde dayanışma","date":"630 / Hicrî 9","objective":"Tebük seferinin zorluklarını ve sonucunu bilir.","hook":{"question":"Uzak bir yolculuğun hazırlığında yalnızca gidilecek yeri bilmek yeterli midir?","options":["Yer adı yeterlidir.","Yol, su, yiyecek ve görev paylaşımı da düşünülmelidir.","Hazırlık ancak yolculuk bittikten sonra yapılır."],"note":"Çocuklardan para dışında bir ihtiyaç söylemelerini isteyin; lojistiği yaşa uygun somutlaştırın."},"frames":[{"title":"Medine'nin kuzeyindeki yol","kind":"map","labels":["Medine","Kuzeye yolculuk","Tebük"],"narration":"Tebük seferi 630 yılında, hicrî dokuzuncu yılda yapıldı. Tebük, Medine'nin kuzeyinde, Suriye yönüne giden yol üzerindeydi. Bizans tarafındaki gelişmelerin oluşturduğu tehdit haberleri sefer hazırlığında etkili oldu. Haritadaki yön okunu izlerken yalnızca varış noktasına bakma. Uzaklık, bir topluluğun yanında ne taşıması ve hangi hazırlıkları yapması gerektiğini de değiştirir."},{"title":"Güçlük zamanı","kind":"journey","labels":["Sıcaklık","Uzaklık","Malzeme ihtiyacı","Hazırlık"],"narration":"Sefer hazırlıkları sıcaklık ve geçim sıkıntılarının hissedildiği bir döneme rastladı. Uzun yol, binek ve erzak ihtiyacını artırıyordu. Bu sebeple Tebük, güçlüklerle birlikte anılan bir seferdir. Burada yolculuğu bir hız yarışına çevirmiyoruz. Aynı mesafeyi, yeterli su ve dinlenme imkânı olmadan düşünerek hazırlığın neden ortak bir sorumluluk hâline geldiğini anlamaya çalışıyoruz."},{"title":"İmkân kadar katkı","kind":"community","labels":["Malzeme","Emek","Paylaşım","İmkân"],"narration":"Eshâb-ı kirâm hazırlıklara imkânları ölçüsünde destek verdi. Katkıları sadece miktar bakımından karşılaştırmak, herkesin aynı şartlarda olduğunu varsaymak olur. Birinin geniş imkânı, diğerinin sınırlı imkânı olabilir. Dersimizde yardımın değerini bir sıralama yarışına çevirmiyoruz. Günümüzdeki ortak bir çalışmada da malzeme hazırlamak, düzenlemek ve zaman ayırmak gibi farklı katkıları görünür kılabiliriz."},{"title":"Savaş olmadan dönen sefer","kind":"agreement","labels":["Tebük'e varış","Büyük savaş olmadı","Anlaşmalar","Medine'ye dönüş"],"narration":"Tebük'te beklenen büyük savaş gerçekleşmedi. Çevredeki bazı topluluklarla anlaşmalar yapıldı ve Medine'ye dönüldü. Dolayısıyla her seferi mutlaka bir savaş sahnesiyle anlatmak doğru değildir. Bir olayın sonucunu değerlendirirken görüşmeleri, güvenliği ve kurulan ilişkileri de inceleriz. Hazırlık yapılmış olması ile çatışmanın gerçekleşmiş olması, zaman çizgisinde ayrı sorulara verilen ayrı cevaplardır."}],"game":{"kind":"match","title":"Hazırlığın nedenini bul","prompt":"Her ihtiyacı onu açıklayan durumla eşleştir.","pairs":[{"left":"Su ve erzak planı","right":"Uzun yol ve sıcaklık","explanation":"Yolun şartları temel ihtiyaçların önceden düşünülmesini gerektirir."},{"left":"İmkâna göre destek","right":"Herkesin kaynaklarının farklı olması","explanation":"Katkının miktarı tek başına kişinin çabasını göstermez."},{"left":"Tebük'te anlaşmalar","right":"Beklenen büyük savaşın olmaması","explanation":"Seferin sonucu yalnız çatışma üzerinden anlatılmaz."},{"left":"Kuzeye uzanan güzergâh","right":"Medine'den Tebük yönüne yolculuk","explanation":"Tebük, Medine'nin kuzeyindeki yol üzerindedir."}]},"decision":{"question":"Bir öğrenci 'Savaş olmadıysa Tebük'te hiçbir şey yaşanmamış' diyor. Hangi kanıtla cevap verirsin?","options":["Hazırlık, uzun yolculuk ve yapılan anlaşmalar da olayın parçalarıdır.","Bütün seferlerin mutlaka savaşla bittiğini söylerim.","Tebük'ün Mekke'nin başka bir adı olduğunu söylerim."],"answer":0,"explanations":["Doğru. Tarih, sadece çatışmaların listesi değildir.","Bu genelleme Tebük'ün bilinen sonucuna uymaz.","Tebük ayrı bir yerleşim yeridir; Mekke ile karıştırılmaz."]},"quiz":[{"question":"Tebük yolculuğu haritada hangi yönde gösterilir?","options":["Medine'den güneye, Yemen'e","Medine'den kuzeye, Suriye yönüne","Medine'den Habeşistan'a deniz yoluyla"],"answer":1,"explanation":"Tebük, Medine'nin kuzeyindeki ticaret yolu üzerindedir."},{"question":"Tebük'ün güçlüklerle anılmasını hangi ikili açıklar?","options":["Kısa yol ve bol erzak","Uzun yol ve hazırlık sıkıntıları","Yakın mesafe ve deniz yolculuğu"],"answer":1,"explanation":"Uzaklık, sıcaklık ve malzeme ihtiyacı hazırlığı zorlaştırdı."},{"question":"Seferin sonucunu doğru anlatan ifade hangisi?","options":["Büyük savaş olmadı; anlaşmalar yapıldı.","Büyük bir çarpışma yaşandı; görüşmeler yapılmadı.","Tebük'e varmadan bütün hazırlıklar durduruldu."],"answer":0,"explanation":"Tebük'ün kendine özgü sonucunu diğer olaylardan ayırırız."}],"teacher":{"misconception":"Sefer=savaş ve çok yardım=her durumda daha büyük fedakârlık çıkarımlarını tartışın.","differentiation":"5–6. sınıfta ihtiyaç–sebep eşleştirmesi; 7–8. sınıfta kaynakları farklı iki kişinin katkısını neden miktarla kıyaslayamayacağımız.","exit":"Tebük'ün iki güçlüğünü ve savaş dışındaki bir sonucunu söyleyin."},"sources":[{"title":"TDV — Tebük Gazvesi","url":"https://islamansiklopedisi.org.tr/tebuk-gazvesi"}]},{"id":49,"module":9,"title":"Heyetler yılı: Gelenleri dinlemek","date":"630–631 / Hicrî 9","objective":"Medine'ye gelen heyetlerin amacını tanır.","hook":{"question":"Bir topluluğu temsil etmek için önce ne yapmak gerekir?","options":["Herkes adına kendi fikrimi söylemek","Temsil edeceğim kişileri dinlemek ve sorularını öğrenmek","Sadece en yüksek sesle konuşmak"],"note":"Heyet sözcüğünü 'bir topluluğu temsilen gelen kişiler' diye açıklayın."},"frames":[{"title":"Medine'ye gelen temsilciler","kind":"map","labels":["Farklı kabileler","Yollar","Medine","Görüşme"],"narration":"Mekke'nin fethinden sonra farklı kabilelerden Medine'ye çok sayıda temsilci topluluğu geldi. Bu topluluklara heyet denir. Gelenler kendi çevrelerinin sorularını, ihtiyaçlarını ve kararlarını taşıyorlardı. Haritadaki birden fazla okun aynı şehre yönelmesi, farklı insanlar arasında kurulan ilişkiyi gösterir. Her okun aynı topluluğu temsil etmediğini fark etmek, ziyaretlerin çeşitliliğini anlamamıza yardımcı olur."},{"title":"Neden Heyetler Yılı?","kind":"timeline","labels":["Fetih sonrası","Hicrî 9","630–631","Yoğun ziyaretler"],"narration":"Daha önce de Medine'ye heyetler gelmişti. Fakat hicrî dokuzuncu yılda bu ziyaretler özellikle yoğunlaştı. Bu yüzden dönem Heyetler Yılı adıyla anılır. Bir döneme isim verilmesi, aynı türden olayların başka zamanlarda hiç yaşanmadığı anlamına gelmez. Tarih çizgisinde ziyaretlerin arttığı aralığı göster; tek bir günün işareti yerine bir zaman dilimi kullan."},{"title":"Görüşmelerde neler vardı?","kind":"agreement","labels":["İslâm'ı öğrenmek","Soruları konuşmak","Anlaşmak","Bilgiyi taşımak"],"narration":"Heyetlerin görüşmelerinde İslâm'ı öğrenme, toplulukların meselelerini konuşma ve anlaşmalar yapma gibi amaçlar bulunuyordu. Peygamber Efendimiz (sallallahü aleyhi ve sellem) gelenlerle görüştü. Bir ziyaretin amacını anlamak için yalnızca kimlerin geldiğini değil, hangi konuların konuşulduğunu da sorarız. Temsilcilerin öğrendiklerini kendi çevrelerine götürmesi, Medine'deki görüşmelerin etkisini yolculuk sonrasında da sürdürebiliyordu."},{"title":"Dinlemek ve doğru aktarmak","kind":"community","labels":["Dinle","Sor","Anla","Doğru aktar"],"narration":"Heyetler konusundan bugün için çıkarabileceğimiz bir ders, temsil sorumluluğudur. Sınıfımız adına görüşmeye gittiğimizde arkadaşlarımızın sorularını doğru aktarmamız gerekir. Duyduğumuz her sözü hemen yorumlamak yerine, anlamadığımız noktayı açıklattırabiliriz. Bu örnek bugünkü sınıf hayatına aittir; tarihî görüşmelerde söylenmiş bir konuşma değildir. Olayı öğrenmekle ondan davranış ilkesi çıkarmayı böylece birbirinden ayırırız."}],"game":{"kind":"classify","title":"Bilgi ile çıkarımı ayıralım","prompt":"Kartları tarihî bilgi veya bugünkü uygulama önerisi olarak yerleştir.","groups":["Tarihî bilgi","Bugünkü uygulama"],"items":[{"text":"Hicrî dokuzuncu yıl Heyetler Yılı olarak anılır.","group":0,"explanation":"Bu dönemin kaynaklarda kullanılan adıdır."},{"text":"Medine'ye farklı kabilelerin temsilcileri geldi.","group":0,"explanation":"Ziyaretlerin kimlerden geldiğini bildirir."},{"text":"Görüşmelerde öğrenme ve anlaşma amaçları vardı.","group":0,"explanation":"Görüşmelerin içeriğine ilişkin bilgidir."},{"text":"Sınıf temsilcisi arkadaşlarının sorularını toplamalı.","group":1,"explanation":"Bu, öğrendiğimiz ilkeden bugüne yönelik çıkardığımız öneridir."},{"text":"Ortak etkinlikte anlamadığımız noktayı açıklattırmalıyız.","group":1,"explanation":"Bugünkü davranışımızı planlayan bir cümledir."},{"text":"Toplantı sonunda alınan kararı doğru aktarmalıyız.","group":1,"explanation":"Temsil sorumluluğunun günümüzdeki uygulamasıdır."}]},"decision":{"question":"Bir öğrenci 'Heyetler Yılı denildiğine göre daha önce hiç heyet gelmemiş' diyor. Hangi cevap doğrudur?","options":["Ad, o yıl ziyaretlerin yoğunlaştığını belirtir; daha önce de heyetler gelmiştir.","Ad, bütün heyetlerin aynı kabileden geldiğini belirtir.","Ad, bütün görüşmelerin tek bir günde yapıldığını belirtir."],"answer":0,"explanations":["Dönemin adı, ziyaretlerin yoğunluğunu anlatır.","Gelen heyetler farklı kabilelerden oluşuyordu.","Ziyaretler bir yıl içindeki yoğunluğu gösterir; tek güne indirgenmez."]},"quiz":[{"question":"Heyet sözcüğü bu derste neyi ifade ediyor?","options":["Bir topluluğu temsil eden kişiler","Bir yolculuktaki bütün yolcular","Bir şehrin yalnız yöneticileri"],"answer":0,"explanation":"Heyetler toplulukları adına görüşmeye gelen temsilcilerdi."},{"question":"Heyetler Yılı hangi dönemdir?","options":["Hicretten önceki ilk yıl","Hicrî dokuzuncu yıl","Vefattan on yıl sonraki dönem"],"answer":1,"explanation":"630–631 yıllarıyla ilişkilendirilen hicrî dokuzuncu yılda ziyaretler yoğunlaştı."},{"question":"Görüşmelerin farklı amaçlarını hangi ifade bir arada verir?","options":["Yalnız ticaret malları için fiyat belirlemek","Yalnız yeni yol güzergâhları çizmek","İslâm'ı öğrenmek, meseleleri görüşmek ve anlaşmak"],"answer":2,"explanation":"Ziyaretler tek bir konuya indirgenemez; öğrenme ve ilişkiler birlikte ele alınır."}],"teacher":{"misconception":"Dönem adını olayın yalnız o tarihte yaşanması olarak yorumlamayın. Heyetlerin tamamına aynı amacı atfetmeyin.","differentiation":"Küçük sınıflar temsil kavramını sınıf örneğiyle anlatır; büyük sınıflar tarihî bilgi ile pedagojik çıkarımı ayırır.","exit":"Heyetlerin gelmesinin iki amacını ve temsilcinin bir sorumluluğunu söyleyin."},"sources":[{"title":"TDV — Heyetler Yılı","url":"https://islamansiklopedisi.org.tr/senetul-vufud"}]},{"id":50,"module":9,"title":"Gençlere güven ve görev vermek","date":"630–632 / Son Medine yılları","objective":"Bilgi, hazırlık ve güvenin sorumlulukla ilişkisini kurar.","hook":{"question":"Bir görev için birini seçerken yalnız yaşına bakmak yeterli midir?","options":["Yaş tek ölçüttür.","Bilgi, hazırlık ve güvenilirliği de değerlendirmek gerekir.","Genç birine yalnız kolay görünen işler verilebilir."],"note":"Sınıf görevlerinden somut bir örnek alın; yetişkin sorumluluklarını çocuğa yüklemeyin."},"frames":[{"title":"Bilgiyi başka bölgelere ulaştırmak","kind":"route","labels":["Medine","Öğretim görevi","Yemen","Rehberlik"],"narration":"İslâm'ı öğrenmek isteyen topluluklara rehberlik edecek kişiler görevlendiriliyordu. Peygamber Efendimiz (sallallahü aleyhi ve sellem) farklı bölgelere öğreticiler gönderdi. Bu görev, yalnızca bir yere gitmek demek değildi; bilgiyi doğru anlatmak ve insanların sorularını anlamak gerekiyordu. Haritada Medine'den çıkan yolu izlerken, yolculuğun yanında bilgi ve sorumluluğun da taşındığını düşün. Görevle hazırlık arasındaki bağı böyle kurabiliriz."},{"title":"Hazret-i Muâz'ın görevi","kind":"book","labels":["Hazret-i Muâz","Yemen","Öğretme","Bilgi"],"narration":"Hazret-i Muâz bin Cebel, Yemen'de görevlendirilen sahâbîlerdendi. Dinî bilgisi ve öğreticiliği bu görevin önemli yönleriydi. Bir ismi öğrenirken sadece ezberlemek yerine görevini de yanına yazmak, olayın anlamını hatırlamamıza yardım eder. İsim kartını Yemen ve öğretim kartlarıyla ilişkilendir. Ardından bu görevde doğru bilgi vermenin, dinlemenin ve sabırlı olmanın neden gerekli olduğunu açıkla."},{"title":"Hazret-i Üsâme'ye verilen güven","kind":"community","labels":["Hazret-i Üsâme","Gençlik","Komutanlık","Sorumluluk"],"narration":"Son dönemde genç Hazret-i Üsâme bin Zeyd'e bir ordunun komutanlığı verildi. Bu örnek, genç yaşın tek başına bir kişiyi sorumluluktan dışlamak için yeterli olmadığını gösterir. Burada komutanlığı bir oyun rolüne çevirmiyoruz. Görev verilmesi ile görevin gerektirdiği hazırlığı konuşuyoruz. Tarihî iki kişinin farklı görevlerini aynı işmiş gibi göstermemek de önemlidir."},{"title":"Güven, hazırlıkla büyür","kind":"values","labels":["Bilgi","Hazırlık","Güven","Yardım isteme"],"narration":"Gençlere güvenilmesi, her görevin hazırlıksız yapılabileceği anlamına gelmez. Bugün bir sınıf etkinliğinde görev almak için ne bildiğini, ne öğrenmen gerektiğini ve nerede yardım isteyeceğini belirleyebilirsin. Bu çalışma tarihî görevlendirmenin aynısı değildir; sorumluluk ilkesini yaşına uygun biçimde uygulamaktır. Görevini küçük adımlara ayırmak, hem güvenilir olmanı hem gerektiğinde destek almanı kolaylaştırır."}],"game":{"kind":"match","title":"Kişi, görev ve ilke","prompt":"Her kartı doğru açıklamayla eşleştir.","pairs":[{"left":"Hazret-i Muâz bin Cebel","right":"Yemen'de öğretim ve rehberlik görevi","explanation":"Bu görevlendirmede bilgi ve öğreticilik öne çıkar."},{"left":"Hazret-i Üsâme bin Zeyd","right":"Genç yaşta komutanlık görevi","explanation":"Gençlerin de sorumluluk alabileceğine tarihî bir örnektir."},{"left":"Görev öncesi hazırlık","right":"Gerekli bilgi ve beceriyi öğrenmek","explanation":"Güven verilmesi, hazırlığı gereksiz kılmaz."},{"left":"Görev sırasında destek","right":"Bilmediğin noktada yardım istemek","explanation":"Sorumluluk, her şeyi biliyormuş gibi davranmak değildir."}]},"decision":{"question":"Bir öğrenci 'Gençlere güveniliyorsa verilen her işi yardım almadan yapmalıyız' diyor. Ne dersin?","options":["Güven, öğrenmeyi ve gerektiğinde yardım istemeyi de kapsar.","Yardım isteyen kişi bir daha görev alamaz.","Gençlerin hiçbir görevi üstlenmemesi daha uygundur."],"answer":0,"explanations":["Doğru. Sorumluluğu iyi yerine getirmek için destek almak gerekebilir.","Yardım istemek her zaman yetersizlik değil, doğru karar olabilir.","Örnekler gençlerin bilgi ve hazırlıkla görev alabildiğini gösteriyor."]},"quiz":[{"question":"Hazret-i Muâz bin Cebel bu derste hangi bölgeyle ilişkilidir?","options":["Habeşistan","Yemen","Tâif"],"answer":1,"explanation":"Yemen'de öğretim ve rehberlikle ilgili görevler üstlendi."},{"question":"Hazret-i Üsâme bin Zeyd örneği neyi gösterir?","options":["Görev için yaş dışında hiçbir şeye bakılmadığını","Hazırlığın görev alınca sona erdiğini","Gençlerin de önemli sorumluluklar alabildiğini"],"answer":2,"explanation":"Gençlik tek başına sorumluluk almaya engel sayılmamıştır."},{"question":"İki görevi doğru ayıran eşleştirme hangisi?","options":["Hazret-i Muâz: Yemen; Hazret-i Üsâme: komutanlık","Hazret-i Muâz: Kâbe onarımı; Hazret-i Üsâme: ilk hicret","Her ikisi de aynı tarihte aynı şehirde aynı görevi yaptı."],"answer":0,"explanation":"İki örneğin ortak ilkesi güven; görevlerinin kendisi farklıdır."}],"teacher":{"misconception":"Gençlere güveni sınırsız ve hazırlıksız sorumluluk olarak yorumlamayın. Tarihî komutanlığı rol oyununa çevirmeyin.","differentiation":"5–6. sınıf kişi–görev eşleştirir; 7–8. sınıf bir görev için bilgi, beceri ve destek ihtiyacı tablosu kurar.","exit":"Yaşıma uygun bir görev için bildiğim …, öğreneceğim …, yardım isteyeceğim kişi …"},"sources":[{"title":"TDV — Hazret-i Muâz bin Cebel","url":"https://islamansiklopedisi.org.tr/muaz-b-cebel"},{"title":"TDV — Hazret-i Üsâme bin Zeyd","url":"https://islamansiklopedisi.org.tr/usame-b-zeyd"}]},{"id":51,"module":9,"title":"Veda haccı","date":"632 / Hicrî 10","objective":"Veda haccını hayat yolculuğundaki yerine yerleştirir.","hook":{"question":"Bir ibadetin nasıl yapıldığını öğrenirken anlatmak ile uygulayarak göstermek nasıl birleşebilir?","options":["Yalnız isimleri ezberlemek yeterlidir.","Açıklamayı izlenen uygulamayla ilişkilendirmek öğrenmeyi güçlendirir.","Uygulamayı görmek, hiçbir açıklamaya ihtiyaç bırakmaz."],"note":"Önce öğrencinin tanıdığı bir beceriden örnek alın; ardından hac yolculuğunun öğretim yönüne geçin."},"frames":[{"title":"Hayatın son yılındaki hac","kind":"timeline","labels":["Hicret: 622","Fetih: 630","Veda haccı: 632"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) hicretten sonraki tek haccını 632 yılında, hicrî onuncu yılda yaptı. Bu yolculuk Veda haccı adıyla anılır. Zaman çizgisinde hicret, Mekke'nin fethi ve Veda haccının yerlerini karşılaştır. Üçünün aynı şehirlerle ilişkili olması, aynı olay oldukları anlamına gelmez. Yolculukların amacı ve gerçekleştiği dönem, olayları birbirinden ayırmamızı sağlar."},{"title":"Medine'den hac yolculuğuna","kind":"route","labels":["Medine","Mekke","Arafat","Mina"],"narration":"Hac yolculuğuna çok sayıda Müslüman katıldı. Medine'den Mekke'ye gidildi; hac sırasında Arafat ve Mina gibi yerlerde bulunuldu. Buradaki harita, öğrenmekte olduğumuz yerleri tanıtır; bütün hac uygulamalarının ayrıntılı rehberi değildir. Bir şehrin adını bilmek ile o çevredeki ibadet yerlerini tanımak farklıdır. Haritada Mekke'yi, ardından Arafat ve Mina etiketlerini bul."},{"title":"Uygulayarak öğretmek","kind":"book","labels":["Açıklama","Uygulama","İzleme","Öğrenme"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) bu hac sırasında ibadetlerin nasıl yapılacağını gösterdi. Katılanlar hem uygulamayı gördüler hem yapılan açıklamaları dinlediler. Böylece öğrenme yalnız bir kavramı duymakla sınırlı kalmadı. Bir işlemin sırasını öğrenirken görmek, soru sormak ve doğru kaynaktan kontrol etmek birbirini tamamlar. Diyagramdaki açıklama ile uygulama kutularını bu yüzden aynı öğrenme yolunun parçaları olarak düşün."},{"title":"Farklı yerlerde verilen öğütler","kind":"values","labels":["Arafat","Mina","Öğütler","Sorumluluk"],"narration":"Veda haccında farklı yerlerde topluluğa öğütler verildi. İnsanların hakları, emanet ve sorumluluk gibi konular hatırlatıldı. Bu konuşmaları bir sonraki derste daha yakından inceleyeceğiz. Şimdi hac yolculuğunu yalnızca şehirler arasında hareket etmek olarak değil, ibadet ve öğrenmenin birlikte yer aldığı bir dönem olarak özetle. Haritadaki mekânlarla zaman çizgisindeki yılın birbirini tamamladığını fark et."}],"game":{"kind":"sequence","title":"Veda haccını zamanına yerleştir","prompt":"Bu dört dönüm noktasını eskiden yeniye sırala.","items":[{"text":"İlk vahiy: 610","explanation":"Davetin başlangıcındaki temel dönüm noktasıdır."},{"text":"Hicret: 622","explanation":"Mekke'den Medine'ye hicret, Veda haccından önce gerçekleşti."},{"text":"Mekke'nin fethi: 630","explanation":"Fetih ile Veda haccı aynı olay değildir."},{"text":"Veda haccı: 632","explanation":"Hayatın son yılında yapılan hacdır."}]},"decision":{"question":"Bir öğrenci 'Veda haccı, Mekke'nin fethinin başka adıdır' diyor. Hangi bilgi bu karışıklığı düzeltir?","options":["Her iki olayın da Mekke ile ilişkili olduğunu söylemek","Fethin 630, Veda haccının 632 yılında olduğunu ve amaçlarının farklılığını açıklamak","Her yolculuğun aynı isimle anıldığını söylemek"],"answer":1,"explanations":["Bu ortak nokta tek başına ayrımı açıklamaz.","Yıl ve amaç birlikte karşılaştırılınca iki olay ayrılır.","Siyerdeki yolculuklar amaçlarına ve dönemlerine göre ayrı adlarla anılır."]},"quiz":[{"question":"Veda haccı hangi yıldadır?","options":["610","622","632"],"answer":2,"explanation":"Hicrî onuncu yıl, milâdî 632 yılıdır."},{"question":"Veda haccının öğretici yönü hangisidir?","options":["İbadetin uygulanarak gösterilmesi","Yalnız yolculuk mesafelerinin öğretilmesi","Medine'deki bütün görüşmelerin aynı yerde yapılması"],"answer":0,"explanation":"İbadetin nasıl yapılacağı açıklama ve uygulamayla öğretildi."},{"question":"Bu derste Arafat ve Mina nasıl ele alındı?","options":["Medine'nin eski adları olarak","Hac yolculuğuyla ilgili yerler olarak","Hicretin başlangıç noktaları olarak"],"answer":1,"explanation":"Bu yerler Mekke çevresindeki hac uygulamaları ve öğütlerle ilişkilidir."}],"teacher":{"misconception":"Fetih, umre ve hac adlarını birbirinin yerine kullanmayın. Bu mikroders tam bir fıkhî hac uygulama rehberi değildir.","differentiation":"5–6. sınıfta yıl ve yer eşleştirmesi; 7–8. sınıfta fetih ile haccın amaçlarını karşılaştırma.","exit":"Veda haccının yılını, ilgili bir yeri ve öğretim yönünü tek cümlede söyleyin."},"sources":[{"title":"TDV — Veda Haccı","url":"https://islamansiklopedisi.org.tr/veda-hacci"}]},{"id":52,"module":9,"title":"Veda öğütleri: Hak ve sorumluluk","date":"632 / Veda haccı","objective":"Veda öğütlerinden günlük hayata ilişkin hak ilkeleri çıkarır.","hook":{"question":"Bir hakkın korunması, yalnızca o hakkın adını söylemekle gerçekleşir mi?","options":["İsmini bilmek her zaman yeterlidir.","Başkalarının hakkına karşı sorumluluk da üstlenmek gerekir.","Haklar yalnız büyük kalabalıklarda önemlidir."],"note":"Ödünç alınan bir kitap üzerinden hak ve sorumluluğu somutlaştırın."},"frames":[{"title":"Tek yerde yapılmış tek konuşma mı?","kind":"map","labels":["Arafat","Mina","Farklı konuşmalar","Veda öğütleri"],"narration":"Veda Hutbesi adıyla tanıdığımız öğütler, Veda haccı sırasında farklı yerlerde yapılan konuşmalarla ilişkilidir. Bunları tek yerde, tek anda söylenmiş uzun bir metin gibi düşünmemeliyiz. Arafat ve Mina etiketlerini karşılaştır. Kaynakların farklı konuşmaları bir araya getirmesi, okuduğumuz derlemenin nasıl oluştuğunu anlamamıza yardım eder. Metnin kaynağını bilmek, içeriğine gösterdiğimiz saygının bir parçasıdır."},{"title":"Can ve mal dokunulmazlığı","kind":"values","labels":["Can","Mal","Güven","Hak"],"narration":"Veda öğütlerinde insanların canına ve malına saygı gösterilmesi vurgulandı. Bir insanın güvenliği ve eşyası, güçlü veya yakın birine ait olduğu için değerli değildir. Hakların korunması topluluk içinde güven oluşturur. Bugünkü sınıf örneğinde de bir arkadaşının eşyasını izinsiz almak, ona ait karar hakkını yok sayar. Bu örnek, öğüdü yaşımıza uygun biçimde düşünmemizi sağlar."},{"title":"Emanet ve karşılıklı sorumluluk","kind":"agreement","labels":["Emanet","Sahibine iade","Aile hakları","Sorumluluk"],"narration":"Emanetleri koruma ve aile içindeki karşılıklı haklara dikkat etme, Veda öğütlerinde ele alınan konulardandır. Hak ile sorumluluk iki ayrı kişinin karşısına yerleşen bağlantılı kavramlardır. Bana bırakılan eşyanın sahibi, onu güvenle geri almayı bekler; benim sorumluluğum özen göstermektir. Şemadaki iki yönlü oku izle ve bir hakkın diğer kişiye hangi davranışı yüklediğini açıkla."},{"title":"Öğüdü günlük hayata taşımak","kind":"community","labels":["İzin istemek","Özen göstermek","İade etmek","Zararı bildirmek"],"narration":"Bir öğüdü örnek almak için büyük bir olay beklememiz gerekmez. Ödünç kitabı korumak, arkadaşının özel mesajını izinsiz paylaşmamak ve ortak eşyayı düzgün kullanmak sınıf hayatındaki uygulamalardır. Bunlar Veda konuşmalarının kelimesi kelimesine alıntısı değildir. Kaynaklı ilke ile günümüzde kurduğumuz örneği ayırarak hem doğru bilgi verir hem davranışımızı açık bir ölçüyle değerlendiririz."}],"game":{"kind":"match","title":"Hakkın karşısındaki sorumluluk","prompt":"Her hak kartını onu koruyan davranışla eşleştir.","pairs":[{"left":"Emanet eşyanın korunması","right":"Özenle kullanıp sahibine geri vermek","explanation":"Emanet ilişkisi güven ve iade sorumluluğu içerir."},{"left":"Kişinin güvenliği","right":"Zarar verecek davranıştan kaçınmak","explanation":"Can güvenliği, başka kişilerin özenli davranmasını da gerektirir."},{"left":"Başkasının malı üzerindeki hakkı","right":"Kullanmadan önce izin istemek","explanation":"İyi niyet, izin gereğini ortadan kaldırmaz."},{"left":"Aile içindeki karşılıklı haklar","right":"Yükü ve sorumluluğu gözeterek davranmak","explanation":"Birlikte yaşamak, yalnız kendi isteğimizi düşünmek değildir."}]},"decision":{"question":"Emanet aldığın kitabın bir sayfası yırtıldı. Hangi davranış hak ve sorumluluk ilişkisini korur?","options":["Fark edilmezse açıklamadan geri vermek","Durumu dürüstçe söyleyip nasıl telafi edebileceğini konuşmak","Kitabı geri vermeyi sürekli ertelemek"],"answer":1,"explanations":["Kusuru gizlemek, sahibinin doğru bilgiye ulaşmasını engeller.","Açıklamak ve uygun telafiyi konuşmak sorumluluk almaktır.","Ertelemek, emanet sahibinin hakkını daha da geciktirir."]},"quiz":[{"question":"Veda Hutbesi başlığı hangi konuşmalarla ilişkilidir?","options":["Veda haccında farklı yerlerde verilen öğütlerle","Yalnız Mekke'nin fethi günü yapılan konuşmayla","Yalnız hicret yolunda geçen konuşmalarla"],"answer":0,"explanation":"Arafat ve Mina gibi farklı yerlerdeki öğütler bu başlık altında anılır."},{"question":"Emanet ilişkisini doğru açıklayan ifade hangisi?","options":["Eşya bize bırakılınca sahibi değişir.","Eşya küçükse izin gerekmez.","Eşyayı koruma ve sahibine geri verme sorumluluğu vardır."],"answer":2,"explanation":"Emanet, geçici olarak güvenle korunmak üzere bırakılır."},{"question":"'Arkadaşımın mesajını izinsiz paylaşmam' cümlesi nasıl sunulmalı?","options":["Veda Hutbesi'nin kelimesi kelimesine alıntısı diye","Haklara saygının günümüzdeki uygulama örneği diye","632 yılındaki bir olayın aynısı diye"],"answer":1,"explanation":"Kaynağın ilkesi ile bugünkü örneğimiz birbirinden ayrılmalıdır."}],"teacher":{"misconception":"Veda Hutbesi'ni tek bir yerde kaydedilmiş tek uzun konuşma diye sunmayın; güncel örnekleri doğrudan Hadîs-i şerîf metni saymayın.","differentiation":"Küçük sınıflar kitap örneğiyle hak–sorumluluk eşleştirir; büyük sınıflar dijital içerik ve izin ilişkisini gerekçelendirir.","exit":"Bir hak seçin; 'Bu hakkı korumak için benim sorumluluğum …' deyin."},"sources":[{"title":"TDV — Veda Hutbesi","url":"https://islamansiklopedisi.org.tr/veda-hutbesi"}]},{"id":53,"module":9,"title":"Son günler: Yakınlık ve özen","date":"632 / Hicrî 11","objective":"Son hastalık dönemini saygılı bir dille anlatır.","hook":{"question":"Hasta birinin yanında bulunmak ile ona iyi destek olmak aynı şey midir?","options":["Yanında uzun süre kalmak her zaman yeterlidir.","Dinlenme ihtiyacını ve isteğini de gözetmek gerekir.","Yalnız konuşmak destek sayılır."],"note":"Dersi sakin tempoda yürütün. Öğrencinin kendi aile yaşantısını anlatmasını zorunlu tutmayın."},"frames":[{"title":"Medine'deki son hastalık","kind":"timeline","labels":["Veda haccı","Medine'ye dönüş","632 yılı","Hastalık"],"narration":"Veda haccından bir süre sonra Peygamber Efendimiz (sallallahü aleyhi ve sellem) Medine'de hastalandı. Bu dönem 632 yılına, hicrî on birinci yıla rastlar. Önceki dersteki yolculukla bu dönemi zaman çizgisinde birbirinden ayır. Son günleri öğrenirken ayrıntıları merak yarışına çevirmeden, kaynakların bildirdiği gelişmeleri saygıyla ele alıyoruz. Bir insanın hastalık dönemini anlatırken kullandığımız dilin özenli olması gerekir."},{"title":"Namazın devamı","kind":"community","labels":["Cemaat","Namaz","Hazret-i Ebû Bekr","Görev"],"narration":"Hastalık sırasında Peygamber Efendimiz (sallallahü aleyhi ve sellem) Hazret-i Ebû Bekr'in cemaate namaz kıldırmasını istedi. Bu bilgi, topluluğun ibadet düzeninin devam ettiğini gösterir. Görev verilmesi ile kişinin bakım ihtiyacı aynı dönemde birlikte bulunabilir. Şemadaki cemaat ve bakım kutuları farklı ihtiyaçları gösteriyor. Tarihî olayı açıklarken görev verilen kişinin adını ve görevin ne olduğunu birlikte hatırlayalım."},{"title":"Yakınların özeni","kind":"home","labels":["Âişe vâlidemiz","Bakım","Dinlenme","Yakınlık"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) son günlerini Âişe vâlidemizin yanında geçirdi. Yakınları bakım için hazır bulunuyordu. Bu bilgiler, siyerin yalnız yolculuk ve topluluk olaylarından oluşmadığını hatırlatır; aile içindeki yakınlık ve bakım da hayatın bir parçasıdır. Burada kişilerin yüzlerini veya odanın tarihî ayrıntılarını canlandırmıyoruz. İlişkileri ve ihtiyaçları, isim ve kavram kartları üzerinden anlamaya çalışıyoruz."},{"title":"İhtiyaca uygun destek","kind":"values","labels":["İhtiyacı sor","Dinlenmeye izin ver","Kısa ve nazik ol"],"narration":"Bugün hasta bir yakına destek olurken neye ihtiyacı olduğunu sormak, ziyaret süresini uygun tutmak ve dinlenmesine izin vermek önemlidir. Bu davranışlar, bakım konusunu kendi hayatımızda düşünmek için kullandığımız örneklerdir. Her insan aynı anda konuşmak veya ziyaretçi görmek istemeyebilir. Özen, kendi iyi niyetimiz kadar karşımızdaki kişinin ihtiyacını da dikkate almayı gerektirir."}],"game":{"kind":"classify","title":"Destek mi, yük mü?","prompt":"Bugünkü ziyaret örneklerini hastanın ihtiyacını gözetmesine göre ayır.","groups":["İhtiyacı gözeten","İhtiyacı zorlayan"],"items":[{"text":"Ziyaretin uygun olup olmadığını önceden sormak","group":0,"explanation":"Dinlenme ve ziyaret isteğini dikkate alır."},{"text":"Kısa ve nazik konuşup yorulunca ayrılmak","group":0,"explanation":"Destek olmayı ziyaret süresinden daha önemli görür."},{"text":"İstediği basit bir yardım için yetişkine danışmak","group":0,"explanation":"Yaşa uygun ve güvenli destek sunar."},{"text":"Dinlenmek isterken uzun süre konuşmak","group":1,"explanation":"İyi niyet, kişinin dinlenme ihtiyacını kaldırmaz."},{"text":"İstemediği hâlde herkese hastalığının ayrıntısını anlatmak","group":1,"explanation":"Özel bilgileri paylaşırken izin ve özen gerekir."},{"text":"Yorgun olduğunu söylediğinde bunu küçümsemek","group":1,"explanation":"Kişinin ihtiyacını ve ifadesini dikkate almamak destek değildir."}]},"decision":{"question":"Dersin tarihî bilgi kartına hangi cümle yazılabilir?","options":["Her hasta ziyaretçisinin bütün gün kalmasını ister.","Hazret-i Ebû Bekr'in cemaate namaz kıldırması istendi.","Son hastalık Mekke'nin fethinden önce yaşandı."],"answer":1,"explanations":["Bu hem genelleme hem tarihî olayla karıştırılmış bir günlük hayat varsayımıdır.","Bu, kaynaklarda bildirilen somut bir gelişmedir.","Son hastalık Veda haccından sonraki dönemdedir."]},"quiz":[{"question":"Son hastalık dönemi hangi şehirle ilişkilidir?","options":["Medine","Mekke","Tebük"],"answer":0,"explanation":"Veda haccından sonra Medine'deki son dönem ele alınıyor."},{"question":"Cemaate namaz kıldırması istenen sahâbî kimdir?","options":["Hazret-i Üsâme bin Zeyd","Hazret-i Muâz bin Cebel","Hazret-i Ebû Bekr"],"answer":2,"explanation":"Son hastalık döneminde bu görev Hazret-i Ebû Bekr'e verildi."},{"question":"Bu derste bakımın hangi yönü vurgulandı?","options":["Ziyaretin mümkün olduğunca uzun olması","Kişinin ihtiyaçlarının ve dinlenmesinin gözetilmesi","Hastalık ayrıntılarının herkese anlatılması"],"answer":1,"explanation":"Özenli destek, kişinin ihtiyacına göre davranmaktır."}],"teacher":{"misconception":"Günlük ziyaret örneklerini tarihî odada yaşanmış olaylar gibi sunmayın; ölüm ve hastalık konusunda dramatik canlandırma yapmayın.","differentiation":"5–6. sınıfta zaman–yer–görev üçlüsü; 7–8. sınıfta tarihî bilgi ile bugünkü bakım örneğini ayırma.","exit":"Kaynaklı bir tarihî bilgiyi ve bugünkü özenli destek davranışını ayrı cümlelerle söyleyin."},"sources":[{"title":"TDV — Siyer: son hastalık dönemi","url":"https://islamansiklopedisi.org.tr/muhammed"},{"title":"Diyanet — Hadislerle İslâm, 7/192","url":"https://hadislerleislam.diyanet.gov.tr/sayfa.php?CILT=7&SAYFA=192"}]},{"id":54,"module":9,"title":"Vefatı ve devam eden örnekliği","date":"632 / Hicrî 11","objective":"Vefatın yerini ve yılını bilir; hatırlamakla örnek almak arasındaki bağı kurar.","hook":{"question":"Bir kişinin hayatını öğrenirken olayları hatırlamak ile güzel davranışları örnek almak nasıl birleşir?","options":["Yalnız tarihleri bilmek yeterlidir.","Bilgi ve davranış üzerine düşünmek birbirini tamamlar.","Davranışları öğrenince tarihleri tamamen bırakabiliriz."],"note":"Sakin bir giriş yapın. Üzüntüyü ölçen veya yarıştıran soru sormayın."},"frames":[{"title":"632 yılında Medine","kind":"timeline","labels":["Mekke yılları","Hicret","Medine yılları","632: Vefat"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) 632 yılında Medine'de vefat etti. Böylece çocukluk, gençlik, davet, hicret ve Medine yıllarından oluşan hayat yolculuğunun son dönemine ulaşıyoruz. Zaman çizgisindeki bu son işaret, önceki dönemleri birbirinden koparmaz. Öğrendiğimiz olayları bir bütün içinde düşünmemizi sağlar. Şehir ve yılı birlikte söylemek, vefatı Mekke'deki doğumla veya fetihle karıştırmamıza engel olur."},{"title":"Topluluğun üzüntüsü","kind":"community","labels":["Üzüntü","Birlikte olma","Hazret-i Ebû Bekr","Hatırlatma"],"narration":"Vefat haberi Müslümanlar arasında derin üzüntüye yol açtı. Hazret-i Ebû Bekr, topluluğa Kur'ân-ı Kerîm'den hatırlatmalarda bulundu. Böylesi bir anda insanların duygularını anlamaya çalışmak, onları yargılamak anlamına gelmez. Dersimizde sahâbîlerin üzüntüsünü bir oyun veya puan konusu yapmıyoruz. Kaynakların bildirdiği olayı sakin biçimde öğreniyor, insanların zor zamanlarda birbirine nasıl destek olabileceğini düşünüyoruz."},{"title":"Defin yeri ve hatıra","kind":"city","labels":["Medine","Vefat edilen oda","Defin","Hürmet"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) vefat ettiği odaya defnedildi. Bu bilgi, Medine'nin siyer yolculuğundaki yerini tamamlayan önemli bir ayrıntıdır. Buradaki şema bir mezar veya tarihî odanın resimli canlandırması değildir; yer bilgisini kavramlarla gösterir. Hatıraya hürmet ederken güvenilir bilgiyi korumak, bilmediğimiz ayrıntıları hayalimizden eklememek ve kaynakların sınırını bilmek de önemlidir."},{"title":"Örnekliğin hayatımızdaki karşılığı","kind":"values","labels":["Doğruluk","Merhamet","Emanet","Sorumluluk"],"narration":"Hayatın sona ermesi, öğrenilen güzel ahlâk örneklerinin unutulması anlamına gelmez. Siyer boyunca doğruluk, merhamet, emanet ve sorumlulukla ilgili pek çok olay gördük. Bunları yalnız birer başlık olarak saymak yerine, bir olayı bir davranışla ilişkilendirebiliriz. Sonraki derslerde bu bağı evde, arkadaşlıkta ve çevremizde nasıl kurabileceğimizi çalışacağız. Hatırlamak, bilinçli bir davranışa da yön verebilir."}],"game":{"kind":"match","title":"Yolculuğun son bölümünü hatırlayalım","prompt":"Bilgi kartlarını doğru açıklamalarla eşleştir; bu çalışma puan yarışması değildir.","pairs":[{"left":"632","right":"Vefatın milâdî yılı","explanation":"Vefat, hicrî on birinci yıldadır."},{"left":"Medine","right":"Vefatın gerçekleştiği şehir","explanation":"Mekke'deki doğum ve Medine'deki vefat birbirinden ayrılır."},{"left":"Hazret-i Ebû Bekr","right":"Kur'ân-ı Kerîm'den hatırlatmada bulundu.","explanation":"Üzüntü yaşayan topluluğa temel hakikatleri hatırlattı."},{"left":"Örnek almak","right":"Öğrenilen değeri davranışla ilişkilendirmek","explanation":"Tarihî bilgiyi doğru öğrenmek ile ahlâkı uygulamak birbirini tamamlar."}]},"decision":{"question":"Bir öğrenci vefat konusunu işlerken kendi ailesinden söz etmek istemiyor. Sınıf nasıl davranmalı?","options":["Konuşmaya zorlamalı.","Dersin tarihî bilgileriyle devam edip paylaşmama tercihine saygı göstermeli.","Üzülmediğini varsaymalı."],"answer":1,"explanations":["Kişisel yaşantıyı anlatmak zorunlu tutulmaz.","Saygılı öğrenme, kişisel paylaşımı zorlamadan da mümkündür.","Birinin duygusunu konuşup konuşmamasından çıkaramayız."]},"quiz":[{"question":"Vefatın yılı ve şehri hangi seçenekte doğru?","options":["632 — Medine","630 — Mekke","622 — Tâif"],"answer":0,"explanation":"Hayat yolculuğunun son dönemi 632 yılında Medine'dedir."},{"question":"Hazret-i Ebû Bekr topluluğa hangi kaynaktan hatırlatmada bulundu?","options":["Sadece kendi tahminlerinden","Kur'ân-ı Kerîm'den","Bir ticaret defterinden"],"answer":1,"explanation":"Kaynaklar, Kur'ân-ı Kerîm'den yapılan hatırlatmayı bildirir."},{"question":"Siyer bilgisini davranışa dönüştürmeye hangi örnek uygundur?","options":["Yalnız tarihleri bir kere sıralamak","Kaynağı olmayan ayrıntılar eklemek","Emanetle ilgili öğrendiğim ilkeyi ödünç aldığım eşyada uygulamak"],"answer":2,"explanation":"Doğru bilgi, günlük hayatta bilinçli bir sorumluluğa bağlanabilir."}],"teacher":{"misconception":"Vefatın yılını fetihle karıştırmayı düzeltin. Bu bölümde süreli yarış, coşkulu ödül veya kişisel yas paylaşımı baskısı kullanmayın.","differentiation":"Küçük sınıflar yıl ve şehir; büyük sınıflar olay–kaynak–örneklik bağlantısını açıklar.","exit":"Bugün öğrendiğim bir tarihî bilgi …; hayatımda düşünmek istediğim bir değer …"},"sources":[{"title":"TDV — Siyer: hayat ve kronoloji","url":"https://islamansiklopedisi.org.tr/muhammed"},{"title":"Diyanet — Hadislerle İslâm, 6/276","url":"https://hadislerleislam.diyanet.gov.tr/sayfa.php?CILT=6&SAYFA=276"}]},{"id":55,"module":10,"title":"Evdeki örnek: Paylaşmak ve yardımcı olmak","date":"Hayatının farklı dönemlerinden tematik tekrar","objective":"Aile içindeki yardım ve nezaketi somut davranışlarla ilişkilendirir.","hook":{"question":"Evde yapılan küçük işler neden birlikte yaşamayı etkiler?","options":["Küçük işler görünmediği için önemsizdir.","Sorumluluk paylaşımı başkasının yükünü hafifletir.","Evde yalnız misafir gelince yardım gerekir."],"note":"Farklı aile düzenlerini kabul ederek, herkese uygun tek bir ev düzeni varsaymayın."},"frames":[{"title":"Ev içindeki örneklik","kind":"home","labels":["Aile","Günlük işler","Yardım","Özen"],"narration":"Âişe vâlidemiz, Peygamber Efendimiz (sallallahü aleyhi ve sellem) için evde aile işlerine yardımcı olma örneklerini aktarır. Bu anlatım, güzel ahlâkın yalnız kalabalıkların önünde görünmediğini gösterir. Evdeki küçük sorumluluklar da bir insanın yakınlarına nasıl davrandığını ortaya koyar. Şemadaki günlük işler kutusunu dikkatle incele; görünüşte küçük olan bir işin başkasının yorgunluğunu nasıl azaltabileceğini düşün."},{"title":"İşin sahibi kim?","kind":"family","labels":["Ortak ihtiyaç","Paylaşım","Yaşa uygun görev","Destek"],"narration":"Birlikte yaşanan yerde bazı ihtiyaçlar herkesi ilgilendirir. Eşyaları toplamak, ortak alanı düzenlemek ve hazırlığa yardım etmek bunlara örnektir. Öğrendiğimiz aile içi yardım ilkesini bugün uygularken görevleri yaşa, imkâna ve güvenliğe göre düşünürüz. Her ev aynı biçimde yaşamaz. Önemli olan, bütün yükü başkasına bırakmadan kendi yapabileceğimiz katkıyı fark etmek ve uygun yardımı istemektir."},{"title":"Nezaket, yardımın parçasıdır","kind":"values","labels":["Nazikçe sor","Yardımı planla","Özenle yap","Teşekkür et"],"narration":"Bir işi yapmak kadar, yaparken kullandığımız dil de önemlidir. Yardımı sürekli başa kakmak veya başkasının yaptığı işi küçümsemek, paylaşımın anlamını zayıflatır. Aile içindeki örneklik üzerine düşünürken hem davranışa hem söze bakarız. Bugünkü örneklerde nazikçe sormak, verilen görevi açıklığa kavuşturmak ve emeğe teşekkür etmek, sorumluluğu kırıcı olmadan paylaşmanın somut yollarıdır."},{"title":"Küçük ve sürdürülebilir görev","kind":"agreement","labels":["Hangi iş?","Ne zaman?","Hangi destek?","Kontrol"],"narration":"Bu hafta için yaşına uygun, küçük bir görev seçebilirsin. Görevin adı kadar zamanı ve gerektiğinde alacağın destek de belli olsun. Örneğin ortak masayı ders sonunda toplamak, yapılabilir ve gözlenebilir bir davranıştır. Bu, tarihî bir ev işinin aynısını yaptığımız iddiası değildir. Öğrendiğimiz yardım ve sorumluluk ilkesini kendi şartlarımız içinde bilinçli bir plana dönüştürürüz."}],"game":{"kind":"classify","title":"Paylaşımı güçlendiren davranışlar","prompt":"Evdeki örnekleri sorumluluğu paylaşmasına göre ayır.","groups":["Paylaşımı güçlendirir","Paylaşımı zorlaştırır"],"items":[{"text":"Yapabileceğim işi sorup zamanını belirlemek","group":0,"explanation":"Görevi açık ve uygulanabilir hâle getirir."},{"text":"Ortak alanda bıraktığım eşyaları toplamak","group":0,"explanation":"Kendi davranışımın oluşturduğu yükü üstlenirim."},{"text":"Bilmediğim bir işi güvenle öğrenmek için yardım istemek","group":0,"explanation":"Sorumluluk ve güvenlik birlikte gözetilir."},{"text":"Yardım ederken sürekli başa kakmak","group":1,"explanation":"Yapılan işin yanında kullanılan dil de önemlidir."},{"text":"Bütün işleri başka birinin fark etmesini beklemek","group":1,"explanation":"Ortak ihtiyaçların yükünü tek kişiye bırakır."},{"text":"Başkasının emeğini küçük görmek","group":1,"explanation":"Nezaket ve emeğe saygı paylaşımın bir parçasıdır."}]},"decision":{"question":"Bir çocuk 'Evde yardım etmek için bütün yetişkin işlerini tek başıma yapmalıyım' diyor. Hangi yaklaşım doğru?","options":["Her iş yaşına bakılmadan yapılmalıdır.","Yaşa ve güvenliğe uygun bir görev seçip gerektiğinde destek istemelidir.","Hiçbir iş üstlenmemek en iyi çözümdür."],"answer":1,"explanations":["Sorumluluk, yaşa ve güvenliğe uygun olmalıdır.","Paylaşım, yapabileceğimiz işi özenle üstlenmekle başlar.","Küçük, güvenli katkılar da değerlidir."]},"quiz":[{"question":"Ev içindeki yardıma ilişkin hatıraları bu derste kimden öğrendik?","options":["Âişe vâlidemizden","Hazret-i Üsâme bin Zeyd'den","Hazret-i Muâz bin Cebel'den"],"answer":0,"explanation":"Âişe vâlidemiz ev içindeki örneklikle ilgili bilgiler aktarır."},{"question":"Hangi görev planı daha açık?","options":["Bir ara her şeyi yaparım.","Masayı bugün ders bitince toplarım; ağır eşyada yardım isterim.","Herkes benim ne düşündüğümü anlar."],"answer":1,"explanation":"İş, zaman ve destek ihtiyacı belirtilmiştir."},{"question":"Yardım ile nezaket ilişkisini hangi ifade anlatır?","options":["İş yapıldıysa sözlerin önemi yoktur.","Yalnız teşekkür etmek bütün işleri tamamlar.","Yapılan iş kadar kullanılan dil de paylaşımı etkiler."],"answer":2,"explanation":"Özenli davranış ve incitmeyen söz birbirini tamamlar."}],"teacher":{"misconception":"Aile içi yardımı yalnız bir cinsiyete veya tek bir ev düzenine bağlamayın; çocuklara yetişkin yükü vermeyin.","differentiation":"Küçük sınıflar bir görev ve zaman seçer; büyük sınıflar görev paylaşımının görünmeyen emeğe etkisini tartışır.","exit":"Ben … işini … zamanında yapacağım; … için destek isteyeceğim."},"sources":[{"title":"Diyanet — Hadislerle İslâm, 6/367","url":"https://hadislerleislam.diyanet.gov.tr/sayfa.php?CILT=6&SAYFA=367"}]},{"id":56,"module":10,"title":"Çocuklara verilen değer","date":"Medine hayatından tematik tekrar","objective":"Çocuklara saygı ve şefkat gösteren davranışları ayırt eder.","hook":{"question":"Bir çocuğa değer verildiğini hangi küçük davranışlardan anlayabiliriz?","options":["Sözünü dinlemek ve selamını almak","Yalnız başarılı olduğunda fark etmek","Onun yerine her kararı almak"],"note":"Öğrencilerden duygularını açıklamalarını isteyebilirsiniz; kişisel örnek vermek zorunlu olmasın."},"frames":[{"title":"Selamla görünür olmak","kind":"community","labels":["Çocuklar","Selam","Dikkat","Değer"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) karşılaştığı çocuklara selam verirdi. Selam, bir kişinin varlığını fark ettiğimizi gösteren anlamlı bir iletişimdir. Bu örnek, çocukların topluluğun kenarında unutulmadığını hatırlatır. Kendi sınıfımızda da yeni gelen veya sessiz duran arkadaşımızı fark etmek, iletişime başlamak için küçük bir adımdır. Tarihî örnekle bugün seçtiğimiz davranış arasındaki bağı böyle kurabiliriz."},{"title":"Hazret-i Enes'in hatırası","kind":"book","labels":["Hazret-i Enes","Hatıra","Sabır","Yumuşaklık"],"narration":"Hazret-i Enes bin Mâlik, Peygamber Efendimiz (sallallahü aleyhi ve sellem) için sabır ve yumuşaklık örnekleri aktarır. Bir çocuğun hatırasını dinlemek, günlük ilişkilerin nasıl yaşandığını öğrenmemizi sağlar. Bu anlatımlar, hatayı düzeltmek ile kişiyi incitmek arasında fark bulunduğunu düşündürür. Kaynak kartında anlatan kişiyi ve aktardığı davranışı birlikte görüyorsun. Hatıranın sahibini bilmek, bilginin nereden geldiğini anlamayı kolaylaştırır."},{"title":"İhtiyacı fark etmek","kind":"values","labels":["Dinlemek","İhtiyacı anlamak","Nazikçe yönlendirmek","Gözetmek"],"narration":"Çocuklara şefkat, yalnız güzel söz söylemekle sınırlı değildir; ihtiyaçları ve duyguları fark etmeyi de içerir. Peygamber Efendimiz (sallallahü aleyhi ve sellem) çocukların durumunu gözetirdi. Kaynaklarda meyve ikramı ve çocukların varlığına dikkat eden davranışlar anlatılır. Bugünkü bir etkinlikte de sessiz kalan öğrencinin neye ihtiyaç duyduğunu sormak, onun adına hemen karar vermekten farklıdır. Önce dinlemek, doğru desteği bulmaya yardım eder."},{"title":"Katılmak için güvenli bir alan","kind":"agreement","labels":["Davet et","Söz ver","Dinle","Zorlamadan destekle"],"narration":"Sınıfta oyuna katılmak isteyen fakat çekinen bir arkadaşımız olabilir. Onu nazikçe davet etmek, kuralları anlatmak ve sözünü kesmeden dinlemek katılımı kolaylaştırır. Bu, günümüzde hazırladığımız bir uygulama örneğidir. Şefkat, kişinin bütün seçimlerini onun yerine yapmak anlamına gelmez. İhtiyacını sorup uygun destek vermek, hem değer gördüğünü hissetmesine hem kendi kararını ifade etmesine yardımcı olur."}],"game":{"kind":"classify","title":"Değer veren iletişim","prompt":"Sınıf örneklerini çocuğun sözünü ve duygusunu gözetmesine göre ayır.","groups":["Değer veren yaklaşım","Düzeltilmesi gereken yaklaşım"],"items":[{"text":"Yeni gelen arkadaşına selam verip adını öğrenmek","group":0,"explanation":"Onu fark ettiğimizi ve iletişime açık olduğumuzu gösterir."},{"text":"Soruyu bitirmesini bekleyip cevap vermek","group":0,"explanation":"Dinlemek, sözüne değer vermenin bir parçasıdır."},{"text":"Katılmak isteyip istemediğini nazikçe sormak","group":0,"explanation":"Kişinin tercihini ve ihtiyacını gözetir."},{"text":"Yanlış cevap verince kişiliğiyle alay etmek","group":1,"explanation":"Hata düzeltilebilir; kişiyi incitmek öğrenmeye yardımcı olmaz."},{"text":"Sessiz olduğu için ne düşündüğünü varsaymak","group":1,"explanation":"Sormadan anlamış olduğumuzu kabul etmek doğru değildir."},{"text":"Her sorusunu yaşını gerekçe göstererek geçiştirmek","group":1,"explanation":"Yaşa uygun bir açıklama yapmak, çocuğu ciddiye almaktır."}]},"decision":{"question":"Bir arkadaşın yeni oyunu bilmiyor. Şefkatli ve öğretici yaklaşım hangisi?","options":["Yerine bütün hamleleri yapıp hiç söz vermemek","Kuralları açıklayıp denemesine fırsat vermek; sorusunu dinlemek","Oyunu öğrenene kadar gruptan uzak tutmak"],"answer":1,"explanations":["Yardım, kişinin bütün kararlarını elinden almak değildir.","Hem öğrenme fırsatı hem destek sağlanır.","Dışlamak yerine yaşına ve ihtiyacına uygun açıklama yapılabilir."]},"quiz":[{"question":"Çocuklara selam verilmesi hangi ilkeyi gösterir?","options":["Çocukların fark edilip değer görmesini","Yalnız yetişkinlerin konuşabileceğini","İletişimin sadece ders sırasında gerektiğini"],"answer":0,"explanation":"Selam, günlük hayatta çocuğun varlığını ve değerini kabul eden davranışlardandır."},{"question":"Hazret-i Enes'in hatıraları bu derste hangi yönü aydınlatır?","options":["Heyetlerle yapılan anlaşmaları","Çocuklarla ilişkide sabır ve yumuşaklığı","Yemen'deki öğretim görevinin ayrıntılarını"],"answer":1,"explanation":"Günlük ilişkilerde gösterilen yaklaşımı hatıralar üzerinden öğreniyoruz."},{"question":"Şefkat ile çocuğun kararına saygı nasıl birleşir?","options":["Hiç açıklama yapmadan kendi hâline bırakarak","Her kararı onun yerine alarak","İhtiyacını sorup uygun destek ve seçim imkânı sunarak"],"answer":2,"explanation":"Destek olmak, dinlemeyi ve kişinin söz hakkını gözetmeyi de içerir."}],"teacher":{"misconception":"Şefkati bütün kuralları kaldırmak veya çocuk adına her kararı vermekle eşitlemeyin.","differentiation":"5–6. sınıf selam ve dinlemeyi örnekler; 7–8. sınıf yardım ile karar hakkı arasındaki farkı gerekçelendirir.","exit":"Bir arkadaşımın değer gördüğünü hissetmesi için … davranışını yapabilirim."},"sources":[{"title":"Diyanet — Hadislerle İslâm, 6/393","url":"https://hadislerleislam.diyanet.gov.tr/sayfa.php?CILT=6&SAYFA=393"}]},{"id":57,"module":10,"title":"Canlılara merhamet","date":"Tematik tekrar","objective":"Hayvanlara merhameti güvenli ve sorumlu davranışlara dönüştürür.","hook":{"question":"Bir hayvanı sevdiğimizi söylemek, onun bütün ihtiyaçlarını karşıladığımız anlamına gelir mi?","options":["Sevdiğimizi söylemek tek başına yeterlidir.","Beslenme, su, dinlenme ve güvenliğini de düşünmeliyiz.","Hayvanların ihtiyaçları her zaman aynıdır."],"note":"Hayvanlara yaklaşmayı gerektiren görev vermeyin; sınıfta ihtiyaç kartları üzerinde çalışın."},"frames":[{"title":"Merhametin kapsamı","kind":"values","labels":["İnsanlar","Hayvanlar","İhtiyaç","Merhamet"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) hayvanlara eziyet edilmesini yasakladı ve ihtiyaçlarının gözetilmesini öğretti. Merhamet, yalnız bize yakın veya sevimli görünen canlılara yönelmez. Bir canlının susuzluğu, yorgunluğu ve bakım ihtiyacı da dikkate alınır. Diyagramdaki ihtiyaç kutularını incelerken kendi isteğimiz ile hayvanın ihtiyacını ayır. Onunla ilgilenmek istememiz, her davranışımızın ona iyi geleceği anlamına gelmez."},{"title":"Beslenme ve dinlenme","kind":"journey","labels":["Yeterli besin","Su","Dinlenme","Bakım"],"narration":"Kaynaklarda Peygamber Efendimiz (sallallahü aleyhi ve sellem) için aç bırakılan ve fazla yorulan bir devenin durumuyla ilgilenme örneği anlatılır. Bu olay, hayvanın yalnız işe yaradığı ölçüde değerlendirilmemesi gerektiğini hatırlatır. Beslenme ve dinlenme, bakımın ayrı parçalarıdır. Şemada ikisini ayrı görüyorsun; bir ihtiyacın karşılanması diğerinin unutulmasını haklı çıkarmaz. Bu ilkeyi bugün de sorumlu bakım düşüncesiyle ilişkilendirebiliriz."},{"title":"Küçük yardımın değeri","kind":"community","labels":["Susuzluk","Su ulaştırmak","İhtiyacı gidermek","İyilik"],"narration":"Hadîs-i şerîflerde susamış bir hayvana su verilmesinin değeri anlatılır. Bu örnek, bir iyiliğin önemini yalnız büyüklüğü veya gösterişli oluşuyla ölçmememizi sağlar. Küçük bir katkı, gerçek bir ihtiyacı karşılıyorsa anlamlıdır. Fakat ihtiyaç sahibine yardım ederken yöntemin de uygun olması gerekir. Canlıyı korkutmak veya bulunduğu ortamı bozmak, iyi niyetle başladığımız davranışın sonucunu değiştirebilir."},{"title":"Güvenli ve uygun destek","kind":"agreement","labels":["Gözlemle","Yetişkine danış","Uygun yardım","Rahatsız etme"],"narration":"Tanımadığımız bir hayvana yaklaşmadan önce güvenliğimizi ve hayvanın durumunu düşünürüz. Yaralı bir canlı gördüğümüzde onu kendi başımıza taşımak yerine bir yetişkinden uygun yardım isteriz. Bu, merhametten uzaklaşmak değildir; yardımın doğru kişiye ve yönteme ulaşmasını sağlamaktır. Bugünkü görevimiz bir canlıya dokunmak değil, ihtiyacını fark edip güvenli bir destek planı hazırlamaktır. Canlıyı rahatsız etmemek de özenli davranıştır."}],"game":{"kind":"match","title":"İhtiyaca uygun davranış","prompt":"Her ihtiyaçla uygun desteği eşleştir.","pairs":[{"left":"Susuzluk","right":"Uygun biçimde suya ulaşmasını sağlamak","explanation":"Su verirken canlının türü ve güvenli koşullar dikkate alınır."},{"left":"Yorgunluk","right":"Dinlenmesine fırsat vermek","explanation":"Bir canlıyı sürekli hareket etmeye zorlamak bakım değildir."},{"left":"Yaralanma ihtimali","right":"Yetişkinden ve uygun uzmandan yardım istemek","explanation":"Bilinmeyen duruma tek başına müdahale etmek yerine doğru yardım aranır."},{"left":"Korku veya huzursuzluk","right":"Uzaklaşıp onu rahatsız etmemek","explanation":"İlgi göstermek her zaman yaklaşmak anlamına gelmez."}]},"decision":{"question":"Bahçede yaralı olabileceğini düşündüğün tanımadığın bir hayvan gördün. Ne yapmak daha uygun?","options":["Hemen kucağıma alıp eve taşırım.","Güvenli mesafede kalıp bir yetişkine haber veririm.","İyileşsin diye onu koşturmaya çalışırım."],"answer":1,"explanations":["Türünü ve durumunu bilmeden taşımak sana ve hayvana zarar verebilir.","Merhametli yardım, uygun kişiye güvenli biçimde haber vermeyi de kapsar.","Yaralı veya korkmuş canlıyı hareket etmeye zorlamak ihtiyacını gözetmez."]},"quiz":[{"question":"Hayvanlara merhameti hangi yaklaşım açıklar?","options":["Yalnız sevdiğimiz türleri gözetmek","Sadece işe yaradıklarında bakım yapmak","Beslenme, dinlenme ve bakım ihtiyaçlarını gözetmek"],"answer":2,"explanation":"Canlıların ihtiyaçları, bizim hoşumuza gitmelerinden bağımsız olarak önemlidir."},{"question":"Su verme örneğinin öğretici yönü nedir?","options":["Gerçek ihtiyacı karşılayan küçük iyiliğin değerli olması","İyiliğin yalnız herkes görürse anlam kazanması","Bütün hayvanların aynı yöntemle bakılabilmesi"],"answer":0,"explanation":"İyiliğin değeri yalnız gösterişli veya büyük olmasına bağlı değildir."},{"question":"Yardım için yetişkine başvurmak nasıl değerlendirilir?","options":["Merhametten vazgeçmek","Güvenli ve uygun desteğe ulaşmak","Hayvanın ihtiyacını yok saymak"],"answer":1,"explanation":"Doğru yardımın ulaşmasını sağlamak sorumlu merhametin bir parçasıdır."}],"teacher":{"misconception":"Hayvan sevgisini her hayvana yaklaşmak veya dokunmakla eşitlemeyin; ihtiyaç ve güvenli destek üzerinde durun.","differentiation":"Küçük sınıflar ihtiyaç eşleştirir; büyük sınıflar iyi niyet, yöntem ve sonuç arasındaki ilişkiyi açıklar.","exit":"Bir canlının … ihtiyacını fark edersem, güvenli biçimde … yapabilirim."},"sources":[{"title":"Diyanet — Hadislerle İslâm, 5/257","url":"https://hadislerleislam.diyanet.gov.tr/sayfa.php?CILT=5&SAYFA=257"},{"title":"Diyanet — Hadislerle İslâm, 3/92","url":"https://hadislerleislam.diyanet.gov.tr/sayfa.php?CILT=3&SAYFA=92"}]},{"id":58,"module":10,"title":"Dürüstlük: Görünmeyeni de saklamamak","date":"Medine hayatından tematik tekrar","objective":"Dürüstlüğün yalnızca açıkça yalan söylememek olmadığını kavrar.","hook":{"question":"Bir eşyanın sadece iyi taraflarını anlatmak, her zaman dürüst bir tanıtım mıdır?","options":["Söylediklerim doğruysa sakladığım kusurun önemi yoktur.","Karşıdakinin kararını etkileyen kusurları da açıklamalıyım.","Kusur varsa eşya hakkında hiç konuşmamalıyım."],"note":"İkinci el kitap örneği kullanın; öğrencilerden kişisel alışveriş veya aile bilgisi istemeyin."},"frames":[{"title":"Pazardaki yiyecek yığını","kind":"market","labels":["Görünen kısım","Alt kısım","Yiyecek","Bilgi"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) Medine pazarında bir yiyecek yığınını incelerken altında ıslaklık bulunduğunu fark etti. Yığının üstten görünüşü, bütününün durumunu göstermiyordu. Bu olayda önemli olan yalnız yiyeceğin ıslanmış olması değildir; alıcının bunu görebilmesi ve doğru bilgiyle karar verebilmesidir. Kesit diyagramında üst ve alt katmanı karşılaştır. Görünür bilgiyle saklı bilgi arasındaki farkı bul."},{"title":"Kusuru görünür kılmak","kind":"values","labels":["Islak kısmı belirt","Doğru bilgi ver","Kararı alıcıya bırak"],"narration":"Peygamber Efendimiz (sallallahü aleyhi ve sellem) ıslak kısmın insanların görebileceği biçimde gösterilmesi gerektiğini hatırlattı. Böylece alıcının durumu bilmeden karar vermesi önlenmiş olacaktı. Kusur hakkında susmak, yanlış bir cümle kurmamış olsak bile karşıdakini yanıltabilir. Dürüstlüğü yalnız sözlerin doğru olmasına indirgemiyoruz; karar için gerekli bilgiyi saklayıp saklamadığımıza da bakıyoruz. Şeffaflık, güvenli alışverişin önemli bir yönüdür."},{"title":"Bugünkü kitap örneği","kind":"book","labels":["İkinci el kitap","Eksik sayfa","Açık bilgi","Seçim"],"narration":"Bugün ikinci el bir kitabı arkadaşımıza vereceğimizi düşünelim. Kapağı temiz, fakat içindeki bazı sayfalar eksik olsun. Yalnız kapağını göstermek, kitabın gerçek durumunu tam anlatmaz. Eksik sayfaları önceden söylemek, karşıdakinin kitabın işine yarayıp yaramayacağına karar vermesini sağlar. Bu sınıf örneği tarihî olayın aynısı değildir; olayda öğrendiğimiz doğru bilgi verme ilkesini günümüzde uygulamaktır."},{"title":"Bilgi, güven ve telafi","kind":"agreement","labels":["Doğru açıkla","Kontrole izin ver","Soruyu cevapla","Hatayı düzelt"],"narration":"Bir tanıtımda gerekli bilgiyi açık vermek, karşıdakine kontrol etme imkânı tanımak ve bilmediğimiz noktayı dürüstçe söylemek güven oluşturur. Sonradan bir hata fark edersek bunu gizlemek yerine düzeltme yolunu konuşabiliriz. Her ayrıntıyı uzunca anlatmak zorunda değiliz; önemli olan kararı etkileyen bilgiyi saklamamaktır. Kısa fakat eksiksiz bir açıklama, süslü ve yanıltıcı sözlerden daha yararlıdır."}],"game":{"kind":"classify","title":"Açık bilgi mi, eksik tanıtım mı?","prompt":"Kitap tanıtımlarını karar için gerekli bilgiyi verip vermemesine göre ayır.","groups":["Gerekli bilgiyi açık verir","Önemli bilgiyi gizler"],"items":[{"text":"Kapağı temiz; iki sayfası eksik, istersen birlikte kontrol edelim.","group":0,"explanation":"Olumlu yanın yanında kararı etkileyen kusur da belirtiliyor."},{"text":"Bazı sayfalarda notlar var; hangi sayfalar olduğunu gösterebilirim.","group":0,"explanation":"Kullanım izleri açıkça bildiriliyor."},{"text":"Cildi gevşek; taşırken dikkat etmek gerekiyor.","group":0,"explanation":"Kitabın kullanımını etkileyen durum açıklanıyor."},{"text":"İçindeki eksik sayfaları bildiğim hâlde yalnız 'kapağı çok temiz' demek","group":1,"explanation":"Doğru bir ayrıntı söylemek, önemli kusuru gizlemeyi düzeltmez."},{"text":"Yırtığı görünmesin diye fotoğrafı yalnız önden çekmek","group":1,"explanation":"Görsel seçim de karşıdakini yanıltabilir."},{"text":"Sorulmadığı için bildiğim eksikliği hiç belirtmemek","group":1,"explanation":"Kararı etkileyen bilgi, soru beklemeden açıklanmalıdır."}]},"decision":{"question":"Bir öğrenci 'Kitabın temiz olduğunu söyledim; eksik sayfaları söylemediğim için yalan söylemiş sayılmam' diyor. Ne eksik?","options":["Kitabın fiyatını daha yüksek söylemesi","Karşıdakinin kararını etkileyen bilgiyi saklamaması","Kitabı hiç göstermemesi"],"answer":1,"explanations":["Fiyatı yükseltmek bilgi eksikliğini gidermez.","Dürüstlük, gerekli bilgiyi bilerek gizlememeyi de kapsar.","Kontrol imkânını azaltmak güveni daha da zayıflatır."]},"quiz":[{"question":"Pazardaki olayda hangi fark önemlidir?","options":["Üstte görünenle altta saklı kalan durumun farklı olması","Üstteki ve alttaki ürünlerin farklı satıcılara ait olması","Satıcının iki ayrı fiyat belirlemiş olması"],"answer":0,"explanation":"Alıcının göremediği ıslaklık kararını etkileyebilecek bir bilgiydi."},{"question":"Bir kusuru açıklamak neden önemlidir?","options":["Her alışverişi mutlaka iptal ettirmek için","Karşıdakinin doğru bilgiyle karar vermesi için","Yalnız satıcının daha uzun konuşması için"],"answer":1,"explanation":"Açık bilgi, karar hakkını korur."},{"question":"Hangi tanıtım daha dürüsttür?","options":["Kitabın sadece temiz kapağını anlatmak","Bildiklerimi yalnız sorulursa söylemek","Temiz kapağı ve eksik sayfaları birlikte belirtmek"],"answer":2,"explanation":"Olumlu ve kararı etkileyen olumsuz bilgiler birlikte açıklanır."}],"teacher":{"misconception":"Dürüstlüğü yalnız açık yalan söylememeye indirgemeyin. 'Her ayrıntıyı saymak' ile 'önemli kusuru gizlememek' farkını koruyun.","differentiation":"Küçük sınıflar iki tanıtımı karşılaştırır; büyük sınıflar görsel seçimin de yanıltıcı olabileceğini gerekçelendirir.","exit":"Bir eşyanın iyi yanı …, açıklamam gereken kusuru …; bunu şöyle söyleyebilirim: …"},"sources":[{"title":"Diyanet — Hadislerle İslâm, 3/507","url":"https://hadislerleislam.diyanet.gov.tr/sayfa.php?CILT=3&SAYFA=507"}]},{"id":59,"module":10,"title":"Siyeri güvenilir kaynaklarla öğrenmek","date":"Bütün yolculuğun tekrarı","objective":"Tarihî bilgi, yorum ve kaynağı belirtilmeyen anlatıyı ayırt eder.","hook":{"question":"Bir anlatının etkileyici olması, doğru olduğunu anlamamız için yeterli midir?","options":["Çok kişi paylaşmışsa yeterlidir.","Kaynağına ve nasıl aktarıldığına da bakmalıyız.","Eski görünen her metin aynı derecede güvenilirdir."],"note":"Çocuğun inancını sınamak yerine kaynak kullanma becerisini ele alın. Bilinmeyeni hemen yanlış ilan etmeyin."},"frames":[{"title":"Siyer neyi inceler?","kind":"book","labels":["Hayat","Olaylar","Mekân","Örneklik"],"narration":"Siyer, Peygamber Efendimiz (sallallahü aleyhi ve sellem) hayatını ve örnekliğini öğrenmemize yardımcı olan alandır. Bir olayın kimlerle, nerede ve hangi dönemde ilişkili olduğunu araştırırız. Ardından olayın anlamı üzerinde düşünürüz. Bilgi öğrenmek ile yorum yapmak aynı işlem değildir. Kaynak kartında olayın bilgisini, kendi defterinde ise bu bilgiden çıkardığın sonucu ayrı cümlelerle göstermek düşünceni daha açık hâle getirir."},{"title":"Kaynak türlerini tanımak","kind":"book","labels":["Kur'ân-ı Kerîm","Hadîs-i şerîf","Siyer eserleri","Araştırma"],"narration":"Kur'ân-ı Kerîm, Hadîs-i şerîfler ve siyer eserleri farklı türde bilgiler sağlar. Bunları inceleyen araştırmalar da bilgilerin anlaşılmasına yardımcı olur. Kaynağın adını söylemek tek başına her soruyu çözmez; aktarılan bilginin o kaynakta gerçekten bulunup bulunmadığına bakmak gerekir. Bir görsele kaynak adı eklenmiş olması, görseldeki her cümlenin doğrulandığını kendiliğinden göstermez. İlgili bölüm ve bağlam önemlidir."},{"title":"Kesin olmayanı doğru ifade etmek","kind":"timeline","labels":["Bilinen yıl","Yaklaşık tarih","Farklı rivayet","Dürüst ifade"],"narration":"Bazı olayların günü veya ayrıntıları hakkında farklı rivayetler bulunabilir. Böyle durumlarda yaklaşık tarih veya farklı görüş bulunduğunu belirten ifade kullanmak, bilgiyi zayıflatmak değil doğru sınırlarıyla sunmaktır. Siyer yolculuğunda doğum tarihini yaklaşık olarak vermemizin sebeplerinden biri budur. Her ayrıntıyı tek bir kesin sayıya dönüştürmek yerine, kaynağın ne kadar kesin konuştuğunu da dikkatle okuruz."},{"title":"Paylaşmadan önce kontrol","kind":"agreement","labels":["Kaynağı bul","İlgili yeri oku","Karşılaştır","Öğretmene danış"],"narration":"Kaynağı belirtilmeyen şaşırtıcı bir anlatıyla karşılaşınca hemen paylaşmak yerine durabiliriz. Önce anlatının nereden alındığını arar, ilgili bölümü okur ve güvenilir bir başvuruyla karşılaştırırız. Anlamadığımız noktayı öğretmenimize sorarız. Bu süreçte 'henüz doğrulayamadım' demek mümkündür. Doğrulayamadığımız her anlatıyı kesin yanlış, etkileyici bulduğumuz her anlatıyı kesin doğru saymadan düşünmek bilgiye karşı sorumluluğumuzdur."}],"game":{"kind":"match","title":"Cümlenin türünü tanı","prompt":"Her örneği onu en iyi açıklayan kavramla eşleştir.","pairs":[{"left":"Hicret 622 yılında gerçekleşti.","right":"Tarihî bilgi","explanation":"Bir olayı zamanıyla birlikte bildirir; güvenilir kaynakla kontrol edilir."},{"left":"Hicretten planlı çalışmanın önemini öğrendim.","right":"Kişisel çıkarım","explanation":"Tarihî olaydan çıkardığımız düşünceyi ifade eder."},{"left":"Bu olayın günü hakkında farklı rivayetler vardır.","right":"Belirsizliği açık belirtme","explanation":"Bilginin kesinlik sınırını korur."},{"left":"Kaynağını bilmediğim bir anlatı duydum.","right":"Doğrulama gerektiren anlatı","explanation":"Doğru veya yanlış hükmü vermeden kaynak araştırılmalıdır."}]},"decision":{"question":"Bir paylaşımın altında kaynak adı yazıyor ama ilgili yerde o cümleyi bulamadın. Ne yapmalısın?","options":["Kaynak adı bulunduğu için kesin doğru kabul etmek","Cümleyi daha etkileyici hâle getirip paylaşmak","Aktarımı kontrol edip öğretmenden yardım istemek"],"answer":2,"explanations":["Kaynak adı tek başına doğru aktarım garantisi değildir.","Doğrulanmayan anlatıya yeni ayrıntılar eklemek sorunu artırır.","İlgili bölümü ve aktarımı kontrol etmek doğru adımdır."]},"quiz":[{"question":"'Bu olaydan sabırlı olmayı öğrendim' cümlesi hangi türdedir?","options":["Kesin gün ve yıl bilgisi","Kişisel çıkarım","Kaynak künyesi"],"answer":1,"explanation":"Cümle olayın tarihini değil, öğrencinin çıkardığı dersi anlatıyor."},{"question":"Farklı tarih rivayetleri varsa hangi ifade daha uygundur?","options":["Biri seçilip bütün kaynaklar aynı söylüyormuş gibi yazılmalı.","Tarih konusundaki farklılık belirtilmeli.","Olayın hiçbir kısmı öğrenilmemeli."],"answer":1,"explanation":"Bilginin sınırını belirtmek, bilineni yok saymak anlamına gelmez."},{"question":"Bir iddiayı henüz doğrulayamadığında ne diyebilirsin?","options":["Kesin doğrudur.","Kesin yanlıştır.","Kaynağını henüz doğrulayamadım."],"answer":2,"explanation":"Kanıtın desteklemediği kesinlik yerine araştırmanın durumunu açıkça belirtiriz."}],"teacher":{"misconception":"Kaynak adı=doğru aktarım ve doğrulanmadı=kesin yanlış eşitliklerini düzeltin. Akademik değerlendirmeyi öğrencinin inancını sorgulamaya dönüştürmeyin.","differentiation":"5–6. sınıf bilgi ve yorum ayırır; 7–8. sınıf bağlam, kaynak künyesi ve kesinlik ifadesini birlikte kontrol eder.","exit":"Paylaşmadan önce kontrol edeceğim iki şey …; emin değilsem kullanacağım ifade …"},"sources":[{"title":"TDV — Siyer: hayat ve kronoloji","url":"https://islamansiklopedisi.org.tr/muhammed"}]},{"id":60,"module":10,"title":"Benim siyer yolculuğum","date":"Genel değerlendirme ve uygulama","objective":"Ana kronolojiyi kurar ve öğrendiği bir değeri davranış planına dönüştürür.","hook":{"question":"Bu yolculuğu bir başkasına anlatırken nereden başlamak istersin?","options":["Önce ana zaman çizgisini kurup sonra bir örnek seçmek","Bütün olayları aynı yıl olmuş gibi sıralamak","Yalnız en çok hatırladığım tarihi söylemek"],"note":"Bu bir hız yarışı değildir. Öğrencinin bilgiyle kurduğu bağı görmeye çalışın."},"frames":[{"title":"Mekke yıllarını birleştirelim","kind":"timeline","labels":["Çocukluk","Gençlik","İlk vahiy: 610","Davet"],"narration":"Siyer yolculuğumuz Mekke'deki çocukluk ve gençlik yıllarıyla başladı. Güvenilirlik, emek, aile ve toplumla ilişkiler üzerinde durduk. İlk vahiy 610 yılıyla ilişkilidir; ardından davet dönemi geldi. Bu bölümleri yalnız bağımsız kartlar gibi görmeyelim. İnsanların, şehirlerin ve sorumlulukların zaman içinde nasıl değiştiğini birlikte düşündüğümüzde, hatırladığımız bilgiler anlamlı bir bütün hâline gelir."},{"title":"Hicret ve Medine","kind":"route","labels":["Mekke","Hicret: 622","Medine","Yeni toplum"],"narration":"622 yılındaki hicret, Mekke ile Medine dönemleri arasında önemli bir dönüm noktasıdır. Medine'de mescid, öğrenme, kardeşlik ve birlikte yaşama konularını gördük. Hicreti yalnız haritadaki bir ok olarak bırakmadık; hazırlık ve yeni bir toplumun kurulmasıyla ilişkisini inceledik. Şimdi bu iki şehir arasındaki oku gösterirken bir yer değişikliği ve bir toplumsal değişimi ayrı cümlelerle anlatabilirsin."},{"title":"Son yılları yerleştirelim","kind":"timeline","labels":["Mekke'nin fethi: 630","Heyetler","Veda haccı: 632","Vefat: 632"],"narration":"Son yıllarda Mekke'nin fethi, farklı topluluklarla görüşmeler ve Veda haccı gibi gelişmeleri öğrendik. Peygamber Efendimiz (sallallahü aleyhi ve sellem) 632 yılında Medine'de vefat etti. Aynı yıl içinde birden fazla olay bulunabileceğini artık biliyoruz. Veda haccı ile vefatı aynı tarih kutusuna yazsak da ayrı olaylar olarak açıklamalıyız. Zaman çizgisi bilgiyi düzenler; olayların anlamı ise açıklamalarımızla görünür olur."},{"title":"Bilgiden davranış planına","kind":"agreement","labels":["Bir olay seç","Bir değer belirle","Somut davranış","Geri dönüp değerlendir"],"narration":"Şimdi bir olay ve o olayla ilişkili bir değer seç. Genel bir 'iyi olacağım' sözü yerine, hangi durumda ne yapacağını belirt. Örneğin emanet aldığın kitabın durumunu kontrol edip zamanında geri vermeyi planlayabilirsin. Bu davranış planı, tarihî olayın yerine geçmez; öğrendiğin ilkeyi günlük hayatına bağlar. Bir hafta sonra planına dönerek neyi uyguladığını ve neyi geliştireceğini düşün."}],"game":{"kind":"sequence","title":"Ana zaman çizgimi tamamlıyorum","prompt":"Beş dönüm noktasını eskiden yeniye sırala; aynı yıldaki olayların da sırası vardır.","items":[{"text":"610 — İlk vahiy","explanation":"Mekke dönemindeki davetin başlangıç noktasıdır."},{"text":"622 — Hicret","explanation":"Mekke'den Medine'ye geçişin dönüm noktasıdır."},{"text":"630 — Mekke'nin fethi","explanation":"Hicretten sonraki Medine yıllarındadır."},{"text":"632 — Veda haccı","explanation":"Hayatın son yılında yapılan hacdır."},{"text":"632 — Medine'de vefat","explanation":"Veda haccından sonraki son dönemdedir."}]},"decision":{"question":"Davranış planına hangi cümleyi yazarsan bir hafta sonra ne yaptığını değerlendirebilirsin?","options":["Her zaman çok iyi biri olacağım.","Bu hafta ödünç aldığım kitabı cuma günü durumunu kontrol ederek geri vereceğim.","Siyerdeki bütün değerleri aynı anda eksiksiz uyguladım."],"answer":1,"explanations":["Güzel bir niyet olsa da hangi davranışın ne zaman yapılacağını belirtmiyor.","Davranış ve zaman açık olduğu için uygulanması değerlendirilebilir.","Bu kadar genel ve tamamlanmış bir iddia, öğrenme ve gelişme alanını göstermez."]},"quiz":[{"question":"İlk vahiy, hicret ve Mekke'nin fethi hangi sıradadır?","options":["610 — 622 — 630","622 — 610 — 630","630 — 622 — 610"],"answer":0,"explanation":"Mekke'deki ilk vahiyden sonra hicret, daha sonra fetih gerçekleşti."},{"question":"Veda haccı ile vefat için doğru ifade hangisi?","options":["Aynı olayın iki farklı adıdır.","İkisi de 632 yılındadır; Veda haccı önce gerçekleşti.","Vefat, hicretten önce gerçekleşti."],"answer":1,"explanation":"Aynı yıl, aynı olay anlamına gelmez; sıralamayı koruruz."},{"question":"Siyeri öğrenirken bilgi ve davranış arasındaki bağ nasıl kurulur?","options":["Tarihî bilgiyi değiştirmeden, öğrendiğimiz ilkeye uygun somut bir davranış seçerek","Güzel bir sonuç çıkıyorsa kaynakta olmayan ayrıntılar ekleyerek","Davranış seçince olayın zamanını ve yerini tamamen bırakarak"],"answer":0,"explanation":"Kaynaklı bilgiyi korumak ve örnekliği günlük yaşama taşımak birbirini tamamlar."}],"teacher":{"misconception":"Yıl ezberini bütün öğrenmenin yerine koymayın. Davranış planını kişilik değerlendirmesine veya kusursuzluk vaadine çevirmeyin.","differentiation":"5–6. sınıf üç dönüm noktası ve bir davranış; 7–8. sınıf beş dönüm noktası, bir kaynak ve gerekçeli uygulama planı.","exit":"Hatırladığım olay …; ilişkilendirdiğim değer …; bu hafta uygulayacağım davranış …"},"sources":[{"title":"TDV — Siyer: hayat ve kronoloji","url":"https://islamansiklopedisi.org.tr/muhammed"}]}]};
